import { groups } from './groups';
import { docs } from './docs';
import { services } from './services';
import { filesUpload } from './files-upload';
import { filesDownload } from './files-download';

export default combineReducers({
  auth,
  messages,
  notifications,
  settings,
  ui,
  folders,
  tasks,
  teams,
  user,
  channels,
  chatbot,
  files,
