import { combineReducers } from 'redux';
import {
  GET_MY_TASKS,
  GET_TASKS,
  GET_TASKS_USER,
  GET_USERS_TASKS,
  DELETE_TASK,
  CREATE_TASK,
} from '../constants/tasks';

export const tasks = (state = [], action) => {
  switch (action.type) {
    case GET_TASKS:
      return action.tasks;
    case GET_MY_TASKS:
      return action.tasks;
    case GET_USERS_TASKS:
      return action.tasks;
    case GET_TASKS_USER:
      return action.tasks;
    case CREATE_TASK:
      return [...state, action.task];
    case DELETE_TASK:
      return state.filter((task) => action.id !== task.id);
    default:
      return state;
  }
};

const task = (state = {}, action) => {
  switch (action.type) {
    case CREATE_TASK:
      return action.task;
    default:
      return state;
  }
};

export const tasksAddTask = (state = false, action) => {
  switch (action.type) {
    case CREATE_TASK:
      return true;
    default:
      return state;
  }
};

export const tasksDeleteTask = (state = false, action) => {
  switch (action.type) {
    case DELETE_TASK:
      return true;
    default:
      return state;
  }
};

export const tasksEditTask = (state = false, action) => {
  switch (action.type) {
    case CREATE_TASK:
      return true;
    default:
      return state;
  }
};

const tasksReducer = combineReducers({
  tasks,
  task,
  tasksAddTask,
  tasksDeleteTask,
  tasksEditTask,
});

export default tasksReducer;
<|file_sep|><|fim_prefix|>/src/app/reducers/ui.js
import { combineReducers } from 'redux';
import { GET_FOLDERS, GET_FOLDER, CREATE_FOLDER, DELETE_FOLDER } from '../constants/folders';
import { SET_FOLDER } from '../constants/ui';

export const folders = (state = [], action) => {
  switch (action.type) {
    case GET_FOLDERS:
      return action.folders;
    case CREATE_FOLDER:
      return [...state, action.folder];
    default:
      return state;
  }
};

const folder = (state = {}, action) => {
  switch (action.type) {
    case GET_FOLDER:
      return action.folder;
    case SET_FOLDER:
      return action.folder;
    default:
      return state;
  }
};

export const foldersDeleteFolder = (state = false, action) => {
  switch (action.type) {
    case DELETE_FOLDER:
      return true;
    default:
      return state;
  }
};

const foldersReducer = combineReducers({
  folders,
  folder,
