import { combineReducers } from 'redux';
import {
  GET_USERS,
  GET_USER,
  UPDATE_USER,
  GET_USER_BY_ID,
  DELETE_USER,
  CREATE_USER,
} from '../constants/users';
import { SET_USER } from '../constants/auth';

export const users = (state = [], action) => {
  switch (action.type) {
    case GET_USERS:
      return action.users;
    case GET_USER:
      return action.user;
    default:
      return state;
  }
};

const user = (state = {}, action) => {
  switch (action.type) {
    case GET_USER_BY_ID:
      return action.user;
    case SET_USER:
      return action.user;
    case CREATE_USER:
      return action.user;
    default:
      return state;
  }
};

export const usersUpdateUser = (state = false, action) => {
  switch (action.type) {
    case UPDATE_USER:
      return true;
    default:
      return state;
  }
};

export const usersDeleteUser = (state = false, action) => {
  switch (action.type) {
    case DELETE_USER:
      return true;
    default:
      return state;
  }
};

const usersReducer = combineReducers({
  users,
  user,
  usersUpdateUser,
  usersDeleteUser,
});

export default usersReducer;
