import { combineReducers } from 'redux';
import { GET_MESSAGES, GET_MESSAGE, CREATE_MESSAGE, DELETE_MESSAGE } from '../constants/messages';

export const messages = (state = [], action) => {
  switch (action.type) {
    case GET_MESSAGES:
      return action.messages;
    case CREATE_MESSAGE:
      return [...state, action.message];
    case DELETE_MESSAGE:
      return state.filter((message) => action.id !== message.id);
    default:
      return state;
  }
};

const message = (state = {}, action) => {
  switch (action.type) {
    case GET_MESSAGE:
      return action.message;
    default:
      return state;
  }
};

export const messagesDeleteMessage = (state = false, action) => {
  switch (action.type) {
    case DELETE_MESSAGE:
      return true;
    default:
      return state;
  }
};

const messagesReducer = combineReducers({
  messages,
  message,
  messagesDeleteMessage,
});

export default messages

