openai.organization = os.getenv("OPENAI_ORGANIZATION")

# Function to create a markdown file
def create_markdown_file(filename, content):
    with open(filename, "w", encoding="utf-8") as f:
        f.write(content)

# Function to create a Markdown file with a specific structure
def create_markdown_file_with_structure(filename, title, content, author, date):
    with open(filename, "w", encoding="utf-8") as f:
        f.write(f"# {title}\n")
        f.write(f"Author: {author}\n")
        f.write(f"Date: {date}\n\n")
        f.write(content)

# Function to get the current date in human-readable format
def get_human_readable_date():
    now = datetime.now()
    return now.strftime("%d %B %Y")

# Function to get the date 7 days ago in human-readable format
def get_date_7_days_ago():
    now = datetime.now() - timedelta(days=7)
    return now.strftime("%d %B %Y")

# Function to get the date 30 days ago in human-readable format
def get_date_30_days_ago():
    now = datetime.now() - timedelta(days=30)
    return now.strftime("%d %B %Y")

# Function to check if the file is a Markdown file
def is_markdown_file(filename):
    return filename.endswith(".md")

# Function to count the number of Markdown files in the directory
def count_markdown_files(directory):
    count = 0
    for filename in os.listdir(directory):
        if is_markdown_file(filename):
            count += 1
    return count

# Function to rename a Markdown file
def rename_markdown_file(filename, new_filename):
    os.rename(filename, new_filename)

# Function to convert a Markdown file to HTML
def convert_markdown_to_html(filename):
    subprocess.run(["pandoc", "-s", "-f", "markdown", "-t", "html", "-o", f"{filename[:-3]}.html", filename])

# Function to remove a Markdown file
def remove_markdown_file(filename):
    os.remove(filename)

