public class QwenConsoleException extends RuntimeException implements Serializable {

    private static final long serialVersionUID = 1L;

    private final Response response;

    public QwenConsoleException(Response response) {
        this.response = response;
    }

    public Response getResponse() {
        return response;
    }

    public static QwenConsoleException build(Response response) {
        return new QwenConsoleException(response);
    }

    @Override
    public String getMessage() {
        return response.getMessage();
    }

    @Override
    public String toString() {
        return "[code=" + response.getCode() + ", message=" + response.getMessage() + "]";
    }

