package com.alibaba.ai.qwen.console.common.response;

import java.io.Serializable;

/**
 * @author shicaihao
 * @date 2023/5/30
 */
public class Response implements Serializable {

    private static final long serialVersionUID = 1L;

    private final int code;

    private final String message;

    private final Object data;

    private final String detail;

    private final String requestId;

    private Response(Builder builder) {
        this.code = builder.code;
        this.message = builder.message;
        this.data = builder.data;
        this.detail = builder.detail;
        this.requestId = builder.requestId;
    }

    public static Response build(int code, String message) {
        return new Builder(code, message).build();
    }

    public static Response build(int code, String message, Object data) {
        return new Builder(code, message).setData(data).build();
    }

    public static Response build(int code, String message, Object data, String requestId) {
        return new Builder(code, message).setData(data).setRequestId(requestId).build();
    }

    public static Response build(int code, String message, String requestId) {
        return new Builder(code, message).setRequestId(requestId).build();
    }

    public static Response build(int code, String message, String requestId, String detail) {
        return new Builder(code, message).setRequestId(requestId).setDetail(detail).build();
    }

    public static Response build(int code, String message, Object data, String requestId, String detail) {
        return new Builder(code, message).setData(data).setRequestId(requestId).setDetail(detail).build();
    }

    public static Response buildSuccess() {
        return new Builder(ErrorCode.OK.getCode(), ErrorCode.OK.getMessage()).build();
