package com.alibaba.cloud.api.gateway.service;

import com.alibaba.cloud.api.gateway.dto.ServiceInstanceDTO;
import com.alibaba.cloud.api.gateway.exception.ServiceDiscoveryException;
import com.alibaba.nacos.api.NacosFactory;
import com.alibaba.nacos.api.exception.NacosException;
import com.alibaba.nacos.api.naming.NamingService;
import com.alibaba.nacos.api.naming.listener.EventCallback;
import com.alibaba.nacos.api.naming.listener.NamingEvent;
import com.alibaba.nacos.api.naming.pojo.Instance;
import com.alibaba.nacos.api.naming.pojo.ServiceInfo;
import com.alibaba.nacos.client.naming.NacosNamingService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cache.annotation.CacheConfig;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.CachePut;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * @Author: gaoyu
 * @Date: 2020/11/23 7:45 下午
 */
@Service
@CacheConfig(cacheNames = "service")
public class ServiceDiscovery {
    private static final Logger log = LoggerFactory.getLogger(ServiceDiscovery.class);

    private final NamingService namingService;

    private final Map<String, List<ServiceInstanceDTO>> serviceCache = new HashMap<>();
    private final Map<String, List<ServiceInstanceDTO>> serviceUpCache = new HashMap<>();

    public ServiceDiscovery(@Value("${spring.cloud.nacos.server-addr}") String serverAddr) throws NacosException {
        namingService = NacosFactory.createNamingService(serverAddr);
        namingService.subscribe("gateway", event -> {
            ServiceInfo serviceInfo = (ServiceInfo) event.getData();
            String serviceName = serviceInfo.getName();
            log.info("subscribe service {} changes: {}", serviceName, event);
            List<Instance> instances = serviceInfo.getHosts();
            List<ServiceInstanceDTO> serviceInstanceDTOList = convertInstance(instances);
            serviceCache.put(serviceName, serviceInstanceDTOList);
            if (serviceInfo.getHealth() == 1) {
                serviceUpCache.put(serviceName, serviceInstanceDTOList);
            } else {
                serviceUpCache.remove(serviceName);
            }
        });
    }

    @CacheEvict(value = "service", allEntries = true)
    public void evictCache() {

    }

    @Cacheable(value = "service", key = "'serviceInstanceDTOList' + #name")
    public List<ServiceInstanceDTO> getServiceInstanceDTOList(String name) throws ServiceDiscoveryException {
        List<ServiceInstanceDTO> serviceInstanceDTOList = serviceCache.get(name);
        if (serviceInstanceDTOList == null) {
            throw new ServiceDiscoveryException("service not found");
        }
        return serviceInstanceDTOList;
    }

    @Cacheable(value = "service", key = "'serviceInstanceDTOListUp' + #name")
    public List<ServiceInstanceDTO> getServiceInstanceDTOListUp(String name) throws ServiceDiscoveryException {
        List<ServiceInstanceDTO> serviceInstanceDTOList = serviceUpCache.get(name);
        if (serviceInstanceDTOList == null) {
            throw new ServiceDiscoveryException("service not found");
        }
        return serviceInstanceDTOList;
    }

    private List<ServiceInstanceDTO> convertInstance(List<Instance> instances) {
        List<ServiceInstanceDTO> result = new ArrayList<>();
        for (Instance instance : instances) {
            result.add(ServiceInstanceDTO.builder()
                    .endpoint(instance.getIp() + ":" + instance.getPort())
                    .metadata(instance.getMetadata())
                    .weight(instance.getWeight())
                    .status(instance.isEnabled() ? ServiceInstanceDTO.Status.UP : ServiceInstanceDTO.Status.DOWN)
                    .build());
        }
        return result;
    }

    @Cacheable(value = "service", key = "'serviceInstance' + #instanceId")
    public ServiceInstanceDTO getInstanceById(String instanceId) {
        ServiceInfo serviceInfo;
        try {
            serviceInfo = namingService.getServiceInfo(instanceId);
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("service not found");
        }
        return convertInstance(serviceInfo.getHosts()).get(0);
    }

    @Cacheable(value = "service", key = "'serviceInstance' + #ip + ':' + #port")
    public ServiceInstanceDTO getInstanceByIP(String ip, int port) {
        String serviceName = getServiceName(ip, port);
        ServiceInfo serviceInfo;
        try {
            serviceInfo = namingService.getServiceInfo(serviceName);
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("service not found");
        }
        Instance instance = null;
        for (Instance i : serviceInfo.getHosts()) {
            if (i.getIp().equals(ip) && i.getPort() == port) {
                instance = i;
                break;
            }
        }
        if (instance == null) {
            throw new ServiceDiscoveryException("service instance not found");
        }
        return convertInstance(serviceInfo.getHosts()).get(0);
    }

    private String getServiceName(String ip, int port) {
        String serviceName = null;
        try {
            Map<String, List<String>> serviceNameMap = ((NacosNamingService) namingService).getAllServicesOfServer();
            for (Map.Entry<String, List<String>> entry : serviceNameMap.entrySet()) {
                for (String service : entry.getValue()) {
                    if (service.startsWith(ip + ":" + port)) {
                        serviceName = entry.getKey();
                        break;
                    }
                }
                if (serviceName != null) {
                    break;
                }
            }
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("get service name by ip and port error");
        }
        if (serviceName == null) {
            throw new ServiceDiscoveryException("service not found");
        }
        return serviceName;
    }


    @CachePut(value = "service", key = "'serviceInstance' + #instanceId")
    public void updateInstanceById(String instanceId, String newIp, int newPort, int weight) {
        String serviceName = getServiceName(newIp, newPort);
        String oldServiceName = getServiceName(getInstanceById(instanceId).getEndpoint().split(":")[0], getInstanceById(instanceId).getEndpoint().split(":")[1]);
        if (!serviceName.equals(oldServiceName)) {
            throw new ServiceDiscoveryException("service name not match");
        }
        ServiceInstanceDTO serviceInstanceDTO = getInstanceById(instanceId);
        try {
            namingService.deregisterInstance(serviceName, serviceInstanceDTO.getEndpoint().split(":")[0], Integer.parseInt(serviceInstanceDTO.getEndpoint().split(":")[1]));
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("deregister instance error");
        }
        try {
            namingService.registerInstance(serviceName, newIp, newPort, weight);
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("register instance error");
        }
    }

    public void registerInstance(String serviceName, String ip, int port, int weight) {
        try {
            namingService.registerInstance(serviceName, ip, port, weight);
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("register instance error");
        }
    }

    public void deregisterInstance(String serviceName, String ip, int port) {
        try {
            namingService.deregisterInstance(serviceName, ip, port);
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("deregister instance error");
        }
    }

    @CachePut(value = "service", key = "'serviceInstance' + #instanceId")
    public void updateInstanceById(String instanceId, String newIp, int newPort, int weight, boolean enabled) {
        String serviceName = getServiceName(newIp, newPort);
        String oldServiceName = getServiceName(getInstanceById(instanceId).getEndpoint().split(":")[0], getInstanceById(instanceId).getEndpoint().split(":")[1]);
        if (!serviceName.equals(oldServiceName)) {
