        } catch (NacosException e) {
            throw new ServiceDiscoveryException("deregister instance error");
        }
        try {
            namingService.registerInstance(serviceName, newIp, newPort, weight, enabled);
        } catch (NacosException e) {
            throw new ServiceDiscoveryException("register instance error");
        }
    }

    public void updateInstanceById(String instanceId, String newIp, int newPort, int weight, boolean enabled, Map<String, String> metadata) {
