def create_submission(query, code, lang):
    submission = {
        "lang": lang,
        "query": query,
        "code": code,
    }
    res = requests.post(f"{SERVER_URL}/submission", json=submission).json()
    return res["submission_id"]


def get_submission(submission_id):
    res = requests.get(f"{SERVER_URL}/submission/{submission_id}").json()
    return res


def get_submission_output(submission_id):
    res = requests.get(f"{SERVER_URL}/submission/{submission_id}/output").json()
    return res["output"]


