import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// API URL
const apiUrl = 'https://jsonplaceholder.typicode.com/albums';

// Initial state
const initialState = {
  albums: [],
  status: 'idle',
  error: null,
};

// Create async thunk to fetch albums
export const fetchAlbumsAsync = createAsyncThunk(
  'albums/fetch',
  async () => {
    try {
      const response = await axios.get(apiUrl);
      return response.data;
    } catch (error) {
      throw Error('Failed to fetch albums');
    }
  }
);

// Create albumSlice
const albumSlice = createSlice({
  name: 'albums',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchAlbumsAsync.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchAlbumsAsync.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.albums = action.payload;
      })
      .addCase(fetchAlbumsAsync.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      });
  },
});

export default albumSlice.reducer;

export const selectAlbums = (state) => state.albums.albums;
export const selectAlbumStatus = (state) => state.albums.status;
