import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function AIQwen({ handleModal }) {
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (event) => {
    event.preventDefault();
    if (message.trim() === '') return;

    navigate(`/chat?qwen:${message}`);
    setMessage('');
  };

  const handleInputChange = (event) => {
    setMessage(event.target.value);
  };

  return (
    <div className="ai-qwen">
      <button className="ai-qwen__button" onClick={handleModal}>
        AI Qwen
      </button>
      <form onSubmit={handleSubmit} className="ai-qwen__form">
        <input
          type="text"
          value={message}
          onChange={handleInputChange}
          className="ai-qwen__input"
          placeholder="Ask AI Qwen something..."
        />
        <button type="submit" className="ai-qwen__submit">
          Submit
        </button>
      </form>
    </div>
  );
}

export default AIQwen;
