import React, { useState, useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { selectAlbums, selectAlbumStatus, selectAlbumError } from '../redux/selectors';
import { fetchAlbumsAsync } from '../redux/actions';
import { LazyLoadImage } from 'react-lazy-load-image-component';

function AIChat({ type }) {
  const dispatch = useDispatch();
  const [userMessage, setUserMessage] = useState('');
  const [aiMessage, setAiMessage] = useState('');
  const conversationRef = useRef(null);
  const albumData = useSelector(selectAlbums);
  const albumStatus = useSelector(selectAlbumStatus);
  const albumError = useSelector(selectAlbumError);

  useEffect(() => {
    dispatch(fetchAlbumsAsync());
    const timer = setInterval(() => {
      fetchAnswer();
    }, 1000);

    return () => clearInterval(timer);
  }, [dispatch]);

  useEffect(() => {
    conversationRef.current.scrollTop = conversationRef.current.scrollHeight;
  }, [aiMessage]);

  const fetchAnswer = async () => {
    let userText = userMessage;
    switch (type) {
      case 'qwen':
        userText = 'Qwen: ' + userText;
        break;
      case 'safegpt':
        userText = 'Safegpt: ' + userText;
        break;
      default:
        break;
    }

    const aiResponse = await fetch('/api/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ message: userText }),
    });

    const response = await aiResponse.json();
    setAiMessage(response.message);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    if (userMessage.trim() === '') return;

    setUserMessage('');
    fetchAnswer();
  };

  const handleInputChange = (event) => {
    setUserMessage(event.target.value);
  };

  const handleAutoScroll = () => {
    conversationRef.current.scrollTop = conversationRef.current.scrollHeight;
  };

  useEffect(() => {
    window.addEventListener('load', handleAutoScroll);
    return () => window.removeEventListener('load', handleAutoScroll);
  }, []);

  return (
    <div className="ai-chat">
      <div className="conversation" ref={conversationRef}>
        <div className="conversation__title">
          <h2>Qwen</h2>
          <h2>Safegpt</h2>
        </div>
        <div className="conversation__messages">
          <LazyLoadImage
            src="/assets/qwen.gif"
            alt="Qwen"
            effect="blur"
            className="conversation__qwen"
          />
          <LazyLoadImage
            src="/assets/safegpt.gif"
            alt="Safegpt"
            effect="blur"
            className="conversation__safegpt"
          />
          {albumStatus === 'succeeded' && albumData.map((album) => (
            <div className="conversation__album" key={album.id}>
              <p className="conversation__album-item">{album.title}</p>
              <img
                src={`https://picsum.photos/id/${album.id}/100/100`}
                alt={album.title}
                className="conversation__album-img"
              />
            </div>
          ))}
          {albumStatus === 'failed' && albumError && (
            <p className="conversation__error">{albumError}</p>
          )}
          {aiMessage && (
            <p className="conversation__ai-message">{aiMessage}</p>
          )}
        </div>
      </div>
      <form onSubmit={handleSubmit} className="ai-chat__form">
        <input
          type="text"
          value={userMessage}
          onChange={handleInputChange}
          className="ai-chat__input"
          placeholder="Type your message..."
        />
        <button type="submit" className="ai-chat__submit">
          Send
        </button>
      </form>
    </div>
  );
}

export default AIChat;
