import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.isVisible
import androidx.lifecycle.ViewModelProviders
import androidx.recyclerview.widget.LinearLayoutManager
import com.google.android.material.snackbar.Snackbar
import com.qwen.android.gpt3.chat.R
import com.qwen.android.gpt3.chat.data.model.ChatMessage
import com.qwen.android.gpt3.chat.data.model.ChatResponse
import com.qwen.android.gpt3.chat.data.model.ChatUsage
import com.qwen.android.gpt3.chat.data.model.toChatMessage
import com.qwen.android.gpt3.chat.data.model.toFullChatMessage
import com.qwen.android.gpt3.chat.databinding.ChatActivityBinding
import com.qwen.android.gpt3.chat.databinding.ChatItemBinding
import com.qwen.android.gpt3.chat.ui.adapter.ChatAdapter
import com.qwen.android.gpt3.chat.ui.dialog.DeleteDialog
import com.qwen.android.gpt3.chat.ui.dialog.InputDialog
import com.qwen.android.gpt3.chat.ui.dialog.InputDialogType
import com.qwen.android.gpt3.chat.ui.dialog.LoadDialog
