import com.qwen.android.gpt3.chat.ui.dialog.LogDialogType
import com.qwen.android.gpt3.chat.ui.dialog.MessageDialog
import com.qwen.android.gpt3.chat.ui.dialog.SettingsDialog
import com.qwen.android.gpt3.chat.ui.dialog.SettingsDialogType
import com.qwen.android.gpt3.chat.ui.viewmodel.ChatViewModel
import com.qwen.android.gpt3.chat.ui.viewmodel.ChatViewModelFactory

class ChatActivity : AppCompatActivity(), ChatAdapter.ChatAdapterListener {

    private val chatViewModel: ChatViewModel by lazy {
        ViewModelProviders.of(this, ChatViewModelFactory()).get(ChatViewModel::class.java)
    }

    private val adapter = ChatAdapter(this)

    private val binding by lazy {
        ChatActivityBinding.inflate(layoutInflater)
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(binding.root)
        initViews()
        chatViewModel.chatResponse.observe(this, ::handleChatResponse)
        chatViewModel.chatUsage.observe(this, ::handleChatUsage)
        chatViewModel.lastError.observe(this, ::handleLastErrorMessage)
        chatViewModel.lastDeleteError.observe(this, ::handleLastDeleteErrorMessage)
        chatViewModel.isLoading.observe(this, ::handleLoading)
        chatViewModel.isHistoryVisible.observe(this, ::handleHistoryVisibility)
        chatViewModel.isLogVisible.observe(this, ::handleLogVisibility)
        chatViewModel.isDeleteVisible.observe(this, ::handleDeleteVisibility)
        chatViewModel.isSettingsVisible.observe(this, ::handleSettingsVisibility)
        chatViewModel.isLogDialogVisible.observe(this, ::handleLogDialogVisibility)
        chatViewModel.isDeleteDialogVisible.observe(this, ::handleDeleteDialogVisibility)
        chatViewModel.isSettingsDialogVisible.observe(this, ::handleSettingsDialogVisibility)
        chatViewModel.isLoadDialogVisible.observe(this, ::handleLoadDialogVisibility)
    }

    override fun onCreateOptionsMenu(menu: Menu): Boolean {
        menuInflater.inflate(R.menu.chat_menu, menu)
        return true
    }

    override fun onOptionsItemSelected(item: MenuItem): Boolean {
        return when (item.itemId) {
            R.id.history -> {
                chatViewModel.onHistoryClick()
                true
            }
            R.id.log -> {
                chatViewModel.onLogClick()
                true
            }
            R.id.settings -> {
                chatViewModel.onSettingsClick()
                true
            }
            R.id.delete -> {
                chatViewModel.onDeleteClick()
                true
            }
            else -> super.onOptionsItemSelected(item)
        }
    }

    override fun onUserMessageSent(message: ChatMessage) {
        chatViewModel.onUserMessageSent(message)
    }

    override fun onMessageDelete(message: ChatMessage) {
        chatViewModel.onMessageDelete(message)
    }

    override fun onMessageClicked(message: ChatMessage) {
        chatViewModel.onMessageClicked(message)
    }

    private fun initViews() {
        binding.chatRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@ChatActivity)
            adapter = this@ChatActivity.adapter
        }
        binding.chatInput.setOnSendListener { text ->
            if (text.isEmpty()) {
                Snackbar.make(binding.chatRecyclerView, "Please enter a message", Snackbar.LENGTH_SHORT).show()
            } else {
                chatViewModel.onUserMessageSent(text)
            }
        }
    }

    private fun handleChatResponse(response: ChatResponse) {
        response.choices.forEach {
            it.message?.let {
                adapter.addMessage(it.toFullChatMessage())
            }
        }
    }

    private fun handleChatUsage(usage: ChatUsage) {
        binding.chatUsage.text = getString(R.string.chat_usage, usage.promptTokens, usage.completionTokens, usage.totalTokens)
    }

    private fun handleLastErrorMessage(error: String?) {
        error?.let {
            Snackbar.make(binding.chatRecyclerView, error, Snackbar.LENGTH_SHORT).show()
        }
    }

    private fun handleLastDeleteErrorMessage(error: String?) {
        error?.let {
            Snackbar.make(binding.chatRecyclerView, error, Snackbar.LENGTH_SHORT).show()
        }
    }

    private fun handleLoading(isLoading: Boolean) {
        binding.chatLoading.isVisible = isLoading
    }

    private fun handleHistoryVisibility(isVisible: Boolean) {
        binding.chatHistory.isVisible = isVisible
    }

    private fun handleLogVisibility(isVisible: Boolean) {
        binding.chatLog.isVisible = isVisible
    }

    private fun handleDeleteVisibility(isVisible: Boolean) {
        binding.chatDelete.isVisible = isVisible
    }

    private fun handleSettingsVisibility(isVisible: Boolean) {
        binding.chatSettings.isVisible = isVisible
    }

    private

