void drawAxes(double x, double y, double z)
{
	glColor3f(1, 0, 0);
	glBegin(GL_LINES);
	glVertex3d(0, 0, 0);
	glVertex3d(x, 0, 0);

	glVertex3d(0, 0, 0);
	glVertex3d(0, y, 0);

	glVertex3d(0, 0, 0);
	glVertex3d(0, 0, z);
	glEnd();
}

void drawBox(double x, double y, double z)
{
	glBegin(GL_QUADS);

	glVertex3d(0, 0, z);
	glVertex3d(x, 0, z);
	glVertex3d(x, y, z);
	glVertex3d(0, y, z);

	glVertex3d(0, 0, 0);
	glVertex3d(x, 0, 0);
	glVertex3d(x, y, 0);
	glVertex3d(0, y, 0);

	glVertex3d(0, 0, z);
	glVertex3d(0, 0, 0);
	glVertex3d(0, y, 0);
	glVertex3d(0, y, z);

	glVertex3d(x, 0, z);
	glVertex3d(x, 0, 0);
	glVertex3d(x, y, 0);
	glVertex3d(x, y, z);

	glVertex3d(0, y, z);
	glVertex3d(0, y, 0);
	glVertex3d(x, y, 0);
	glVertex3d(x, y, z);

	glVertex3d(x, 0, z);
	glVertex3d(x, y, z);
	glVertex3d(x, y, 0);
	glVertex3d(x, 0, 0);
	glEnd();
}

void drawObject()
{
	drawAxes(2, 2, 2);
	drawBox(1, 1, 1);
}

void display()
{
	glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
	glLoadIdentity();

	gluLookAt(0, 0, 5, 0, 0, 0, 0, 1, 0);

	drawObject();

	glutSwapBuffers();
}

void reshape(int w, int h)
{
	glViewport(0, 0, (GLsizei)w, (GLsizei)h);
	glMatrixMode(GL_PROJECTION);
	glLoadIdentity();
	gluPerspective(45, (float)w / (float)h, 1.0, 100.0);
	glMatrixMode(GL_MODELVIEW);
}

void keyboard(unsigned char key, int x, int y)
{
	switch (key)
	{
	case 27:
		exit(0);
		break;
	}
}

int main(int argc, char **argv)
{
	glutInit(&argc, argv);
	glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB | GLUT_DEPTH);
	glutInitWindowSize(500, 500);
	glutInitWindowPosition(100, 100);
	glutCreateWindow("Qwen");
