import React, { Component } from 'react';
import ReactDom from 'react-dom';
import $ from 'jquery';
import axios from 'axios';

import './css/App.css';

class App extends Component {
  constructor(props){
    super(props);
    this.state = {
      post: {
        question: 'Who are you?',
        answer: 'I am an AI language model.'
      },
      posts: [],
      input: ''
    };
    this.postSubmit = this.postSubmit.bind(this);
  }

  componentDidMount() {
    axios.get('http://localhost:8000/api/posts', {
      'content-type': 'application/json'
    }).then(res => {
      this.setState({
        posts: res.data
      });
    });
  }

  postSubmit(e){
    this.setState({
      posts: [
        ...this.state.posts,
        {
          question: this.state.input,
          answer: ''
        }
      ]
    });
    axios.post('http://localhost:8000/api/posts', this.state.input, {
      'content-type': 'application/json'
    }).then(res => {
      this.setState({
        posts: res.data
      });
    });
    e.preventDefault();
  }

  render() {
    const { posts } = this.state;
    return (
      <div className="container">
        <div className="py-4">
          <div className="col-md-4">
            <form onSubmit={this.postSubmit}>
              <div className="form-group">
                <input type="text" className="form-control" placeholder="Question" value={this.state.input} onChange={e => this.setState({input: e.target.value})}></input>
              </div>
              <button type="submit" className="btn btn-outline-secondary">Submit</button>
            </form>
            <hr></hr>
            <div className="card card-body">
              {this.state.input &&
                <div>
                  <h3 className="py-1">Question</h3>
                  <p>{this.state.input}</p>
                  <h3 className="py-1">Answer</h3>
                  <p>{this.state.posts[this.state.posts.length-1] && this.state.posts[this.state.posts.length-1].answer}</p>
                </div>
              }
            </div>
          </div>
          <hr></hr>
          <div className="row">
            {posts.map((post, index) => (
              <div className="col-md-4" key={index}>
                <div className="card card-body">
                  <div>
                    <h3 className="py-1">Question</h3>
                    <p>{post.question}</p>
                    <h3 className="py-1">Answer</h3>
                    <p>{post.answer}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }
}

