package com.qa.omniscient.test;

import com.qa.omniscient.model.Model;
import com.qa.omniscient.model.WeiboComment;
import org.junit.Test;
import org.neo4j.graphdb.*;
import org.neo4j.graphdb.factory.GraphDatabaseFactory;

import java.util.ArrayList;
import java.util.List;

/**
 * Created by June on 2016/8/23.
 */
public class WeiboWeiboCommentAllTest {
    @Test
    public void testQuery(){
        List<Model> result = new ArrayList<>();
        GraphDatabaseService graphDb = new GraphDatabaseFactory().newEmbeddedDatabase("/Users/June/Documents/Neo4j/data/db/weiboWeiboCommentAll");
        Transaction tx = graphDb.beginTx();

        try {
            Model model;

            String user = "2858691562";
            String query = "MATCH (a:WeiboComment)-[:WEIBO_COMMENT_ALL]->(b:Weibo) WHERE b.user = '" + user + "' RETURN a";
            ResourceIterator<Node> resultIt = graphDb.execute(query).columnAs("a");
            while (resultIt.hasNext()) {
                Node node = resultIt.next();
                model = new Model();
                model.setCommenterId(node.getProperty("commenterId").toString());
                model.setCommenterName(node.getProperty("commenterName").toString());
                model.setCommentContent(node.getProperty("content").toString());
                model.setImgUrl(node.getProperty("imgUrl").toString());
                model.setTopImgUrl(node.getProperty("topImgUrl").toString());
                model.setCtime(node.getProperty("ctime").toString());
                result.add(model);
            }
            tx.success();
        } finally {
            tx.close();
        }
        graphDb.shutdown();
    }
}
