import "./index.css";

class App extends Component {
  componentDidMount() {
    this._checkUser();
  }

  _checkUser = () => {
    const { user, authActions } = this.props;
    if (user) {
      return;
    }
    authActions.checkUser();
  };

  _checkAdmin = () => {
    const { user, admin, authActions } = this.props;
    if (!user || admin) {
      return;
    }
    authActions.checkAdmin();
  };

  _checkSystem = () => {
    const { system, app, systemActions, appActions } = this.props;
    if (system) {
      return;
    }
    systemActions.getSystem().then(() => {
      // get system value
      const { system } = this.props;
      let api = null;
      if (system && system.value && system.value.api) {
        api = system.value.api;
      }
      appActions.getApp().then(() => {
        // get app value
        const { app } = this.props;
        if (app && app.value && app.value.api) {
          api = app.value.api;
        }
        // check system value if api is not empty
        if (api && api !== "") {
          API.set(api);
        }
      });
    });
  };

  _checkAccount = () => {
    const { user, account, accountActions } = this.props;
    if (!user || account) {
      return;
    }
