import type { AzureCredentials } from '../../types';
import { error } from '../../utils';

const { AZURE_TENANT_ID, AZURE_CLIENT_ID, AZURE_CLIENT_SECRET, AZURE_OPENAI_API_KEY } = process.env;

export const getAzureCredentials = (): AzureCredentials => {
  if (AZURE_TENANT_ID && AZURE_CLIENT_ID && AZURE_CLIENT_SECRET) {
    return {
      AZURE_TENANT_ID,
      AZURE_CLIENT_ID,
      AZURE_CLIENT_SECRET,
    };
  }

  if (AZURE_OPENAI_API_KEY) {
    return {
      AZURE_OPENAI_API_KEY,
    };
  }

  error(
    'You must provide either all of the following environment variables or the Azure OpenAI API key: AZURE_TENANT_ID, AZURE_CLIENT_ID, AZURE_CLIENT_SECRET'
  );
  return {} as never;
};

export const getAzureDeploymentName = (): string | null => {
  const AZURE_OPENAI_DEPLOYMENT_NAME = process.env.AZURE_OPENAI_DEPLOYMENT_NAME;
  if (AZURE_OPENAI_DEPLOYMENT_NAME) {
    return AZURE_OPENAI_DEPLOYMENT_NAME;
  }

  const AZURE_OPENAI_API_INSTANCE_NAME = process.env.AZURE_OPENAI_API_INSTANCE_NAME;
  if (AZURE_OPENAI_API_INSTANCE_NAME) {
    return AZURE_OPENAI_API_INSTANCE_NAME;
  }

  return null;
};

export const getAzureApiVersion = (): string =>
  process.env.AZURE_OPENAI_API_VERSION || '2023-05-15';

export const getAzureOpenAIApiKey = (): string | undefined => {
  const AZURE_OPENAI_API_KEY = process.env.AZURE_OPENAI_API_KEY;
  if (AZURE_OPENAI_API_KEY) {
    return AZURE_OPENAI_API_KEY;
  }

  const AZURE_OPENAI_API_BASE_URL = process.env.AZURE_OPENAI_API_BASE_URL;
  if (AZURE_OPENAI_API_BASE_URL) {
    return '';
  }

  return undefined;
};

export const getAzureOpenAIBaseUrl = (): string => {
  const AZURE_OPENAI_API_BASE_URL = process.env.AZURE_OPENAI_API_BASE_URL;
  const AZURE_OPENAI_API_INSTANCE_NAME = process.env.AZURE_OPENAI_API_INSTANCE_NAME;
  const AZURE_OPENAI_API_DEPLOYMENT_NAME = process.env.AZURE_OPENAI_API_DEPLOYMENT_NAME;

  if (AZURE_OPENAI_API_INSTANCE_NAME && AZURE_OPENAI_API_DEPLOYMENT_NAME) {
    return `https://${AZURE_OPENAI_API_INSTANCE_NAME}.openai.azure.com/openai/deployments/${AZURE_OPENAI_API_DEPLOYMENT_NAME}`;
  }

  if (AZURE_OPENAI_API_BASE_URL) {
    return AZURE_OPENAI_API_BASE_URL;
  }

  throw new Error(
    'You must provide either AZURE_OPENAI_API_BASE_URL or both AZURE_OPENAI_API_INSTANCE_NAME and AZURE_OPENAI_API_DEPLOYMENT_NAME'
  );
};

export const isAzure = (): boolean => {
  const isAzure =
    process.env.AZURE_TENANT_ID &&
    process.env.AZURE_CLIENT_ID &&
    process.env.AZURE_CLIENT_SECRET &&
    process.env<|fim_suffix|>ss.env.AZURE_OPENAI_API_INSTANCE_NAME &&
      process.env.AZURE_OPENAI_API_DEPLOYMENT_NAME;

  return isAzure;
};
