import { execSync } from 'child_process';
import type { PluginConfig } from '../types';

export const isDebug = (config: PluginConfig) =>
  process.env.NODE_ENV === 'development' || config.debug;

export const isTTY = (): boolean => {
  if (process.stdout.isTTY) {
    return true;
  }

  if (process.env.TERM === 'dumb') {
    return false;
  }

  return false;
};

export const getLogLevel = (config: PluginConfig) => {
  if (config.debug) {
    return 'debug';
  }

  if (process.env.NODE_ENV === 'development') {
    return 'silly';
  }

  return 'info';
};

export const getRepoPath = (repo: string) => {
  return execSync('git rev-parse --show-toplevel').toString().trim();
};

export const getRepoName = (repo: string) => {
  return execSync('git config --get remote.origin.url').toString().trim();
};

export const getRepoUrl = (repo: string) => {
  return execSync('git remote get-url origin').toString().trim();
};

export const getPluginName = (repo: string) => {
  return execSync('git remote get-url origin').toString().trim();
};

export const startServer = async (port: number) => {
  return new Promise<void>((resolve) => {
    execSync(`tunnel --port ${port}`);
    resolve();
  });
};

export const runCommand = (command: string): void => {
  execSync(command, {
    stdio: 'inherit',
  });
};
