from django.contrib.auth.decorators import login_required
from django.shortcuts import render
from .models import UserProfile
from django.contrib.auth.models import User
from django.shortcuts import redirect
from django.http import HttpResponse
from django.views.decorators.csrf import csrf_exempt
from django.db.models import Q
from .forms import ProfileForm
import os


@login_required
def profile(request):
    if request.method == 'POST':
        form = ProfileForm(request.POST, instance=request.user.userprofile)
        if form.is_valid():
            form.save()
            return redirect('profile')
    else:
        profile = UserProfile.objects.get(user=request.user)
        form = ProfileForm(instance=profile)
    return render(request, 'ycs/profile.html', {'form': form, 'user': request.user})


@login_required
def dashboard(request):
    user_profile = UserProfile.objects.get(user=request.user)
    channels = Channel.objects.filter(owner=user_profile.user)
    videos = Video.objects.filter(uploader=user_profile.user)
    return render(request, 'ycs/dashboard.html', {'channels': channels, 'videos': videos})


def list_users(request):
    if not request.user.is_superuser:
        return redirect('login')
    users = User.objects.all()
    return render(request, 'ycs/list_users.html', {'users': users})


def create_user(request):
    if not request.user.is_superuser:
        return redirect('login')
    if request.method == 'POST':
        username = request.POST.get('username')
        password = request.POST.get('password')
        email = request.POST.get('email')
        is_superuser = request.POST.get('is_superuser')
        User.objects.create_user(username=username, password=password, email=email, is_superuser=is_superuser)
        return redirect('list_users')
    else:
        return render(request, 'ycs/create_user.html')


def update_user(request, user_id):
    if not request.user.is_superuser:
        return redirect('login')
    user = User.objects.get(id=user_id)
    if request.method == 'POST':
        username = request.POST.get('username')
        password = request.POST.get('password')
        email = request.POST.get('email')
        is_superuser = request.POST.get('is_superuser')
        user.username = username
        user.email = email
        user.is_superuser = is_superuser
        if password:
            user.set_password(password)
        user.save()
        return redirect('list_users')
    else:
        return render(request, 'ycs/update_user.html', {'user': user})


def delete_user(request, user_id):
    if not request.user.is_superuser:
        return redirect('login')
    user = User.objects.get(id=user_id)
    user.delete()
    return redirect('list_users')


def search(request):
    query = request.GET.get('q')
    if query:
        results = Video.objects.filter(Q(name__icontains=query) | Q(description__icontains=query))
    else:
        results = Video.objects.none()
    return render(request, 'ycs/search.html', {'results': results})


def upload_video(request):
    if request.method == 'POST':
        name = request.POST.get('name')
        description = request.POST.get('description')
        file = request.FILES.get('file')
        path = os.path.join('uploads', file.name)
        with open(path, 'wb+') as destination:
            for chunk in file.chunks():
                destination.write(chunk)
        thumbnail = request.FILES.get('thumbnail')
        thumbnail_path = os.path.join('uploads', thumbnail.name)
        with open(thumbnail_path, 'wb+') as destination:
            for chunk in thumbnail.chunks():
                destination.write(chunk)
        duration = request.POST.get('duration')
        views = request.POST.get('views')
        uploader = request.user
        video = Video(name=name, description=description, path=file.name, thumbnail=thumbnail.name,
                      duration=duration, views=views, uploader=uploader)
        video.save()
        return redirect('dashboard')
    else:
        return render(request, 'ycs/upload_video.html')


def create_channel(request):
    if request.method == 'POST':
        name = request.POST.get('name')
        owner = request.user
        channel = Channel(name=name, owner=owner)
        channel.save()
        return redirect('dashboard')
    else:
        return render(request, 'ycs/create_channel.html')


