import os
import zipfile
from typing import List

import requests
from tqdm import tqdm

from DataSet import DataSet


class DatasetDownloader(DataSet):
    def __init__(self, dataset_path: str, url: str):
        super().__init__(dataset_path)
        self.url = url

    def download(self, force: bool = False):
        if os.path.exists(self.dataset_path):
            if force:
                print(f'Dataset already exists in {self.dataset_path}. Downloading again.')
        else:
            os.makedirs(self.dataset_path, exist_ok=True)
            print(f'Downloading dataset to {self.dataset_path}')
            response = requests.get(self.url, stream=True)

            total_size_in_bytes = int(response.headers.get('content-length', 0))
            block_size = 1024  # 1 Kibibyte
            progress_bar = tqdm(total=total_size_in_bytes, unit='iB', unit_scale=True)

            zip_file_path = os.path.join(self.dataset_path, 'dataset.zip')
            with open(zip_file_path, 'wb') as file:
                for data in response.iter_content(block_size):
                    progress_bar.update(len(data))
                    file.write(data)
            progress_bar.close()

            if total_size_in_bytes != 0 and progress_bar.n != total_size_in_bytes:
                print("ERROR, something went wrong")

            print('Extracting dataset...')
            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(self.dataset_path)
            os.remove(zip_file_path)
            print('Dataset downloaded and extracted.')

    def prepare(self):
        super().prepare()
        print('No preparation step for this dataset.')

    def get_all_files(self) -> List[str]:
        path = os.path.join(self.dataset_path, 'dataset')
        return [os.path.join(path, f) for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
        # return glob.glob(os.path.join(self.dataset_path, 'dataset', "*.jpg"))

    def get_item(self, idx: int):
        return super().get_item(idx)

    def __len__(self):
        return super().__len__()


