const fs = require('fs');
const util = require('util');
const path = require('path');

const readline = require('readline');
const {google} = require('googleapis');

let config;
try {
  config = require('./config.js').default;
} catch (e) {
  config = null;
}

// If modifying these scopes, delete token.json.
const SCOPES = ['https://www.googleapis.com/auth/drive.readonly'];
// The file token.json stores the user's access and refresh tokens, and is
// created automatically when the authorization flow completes for the first
// time.
const TOKEN_PATH = 'token.json';

const readFile = util.promisify(fs.readFile);
const writeFile = util.promisify(fs.writeFile);

/**
 * Create an OAuth2 client with the given credentials, and then execute the
 * given callback function.
 * @param {Object} credentials The authorization client credentials.
 * @param {function} callback The callback to call with the authorized client.
 */
async function authorize(credentials) {
  const {client_secret, client_id, redirect_uris} = credentials.installed;
  const oAuth2Client = new google.auth.OAuth2(
      client_id, client_secret, redirect_uris[0]);

  // Check if we have previously stored a token.
  const token = await readFile(TOKEN_PATH, 'utf8');
  oAuth2Client.setCredentials(JSON.parse(token));
  return oAuth2Client;
}

/**
 * Lists the names and IDs of up to 10 files.
 * @param {google.auth.OAuth2} auth An authorized OAuth2 client.
 */
async function listFiles(auth) {
    const drive = google.drive({version: 'v3', auth});
    const files = await drive.files.list({
        pageSize: 10,
        fields: 'nextPageToken, files(id, name)',
    });
    return files.data.files;
}

async function searchFile(auth, term) {
    const drive = google.drive({version: 'v3', auth});
    const res = await drive.files.search({
        q: `name = '${term}'`,
        fields: 'nextPageToken, files(id, name)',
    });
    return res.data?.files ?? [];
}

/**
 * Create a new file
 * @param {google.auth.OAuth2} auth An authorized OAuth2 client.
 * @param {string} fileName The name of the file to create.
 * @param {string} content The content of the file to create.
 */
async function createFile(auth, fileName, content) {
    const drive = google.drive({version: 'v3', auth});
    const fileMetadata = {
        name: fileName,
    };
    const media = {
        mimeType: 'text/plain',
        body: content,
    };
    const file = await drive.files.create({
        resource: fileMetadata,
        media: media,
        fields: 'id',
    });
    return file.data.id;
}

async function readFileById(auth, id) {
    const drive = google.drive({version: 'v3', auth});
    const res = await drive.files.get({
        fileId: id,
        alt: 'media',
    });
    return res.data;
}

async function downloadFileById(auth, id, fileName) {
    const drive = google.drive({version: 'v3', auth});
    const res = await drive.files.get({
        fileId: id,
        alt: 'media',
        responseType: 'stream',
    });
    const dest = fs.createWriteStream(fileName);
    res.data.pipe(dest);

    return new Promise((resolve, reject) => {
        dest.on('finish', resolve);
        dest.on('error', reject);
    });
}

async function uploadFileById(auth, id, fileName) {
    const drive = google.drive({version: 'v3', auth});
    const media = {
        mimeType: 'text/plain',
        body: fs.createReadStream(fileName),
    };
    const res = await drive.files.update({
        fileId: id,
        media: media,
    });
    return res.data;
}

async function uploadFile(auth, fileName, content) {
    const fileId = await createFile(auth, fileName, content);
    const dest = fileName;
    await downloadFileById(auth, fileId, dest);
    return fileId;
}

async function renameFile(auth, fileId, newName) {
    const drive = google.drive({version: 'v3', auth});
    const fileMetadata = {
        name: newName,
    };
    const res = await drive.files.update({
        fileId: fileId,
        resource: fileMetadata,
        fields: 'name',
    });
    return res.data.name;
}

async function deleteFile(auth, fileId) {
    const drive = google.drive({version: 'v3', auth});
    await drive.files.delete({
        fileId: fileId,
    });
}

async function unzipFile(auth, fileId, destDir) {
    const dest = `${destDir}/${fileId}.zip`;
    await downloadFileById(auth, fileId, dest);
    const {default: unzip} = await import('unzipper');
    const unzipped = await unzip.Open.file(dest).promise;
    await unzipped.extract({path: destDir});
    await deleteFile(auth, fileId);
    await fs.promises.unlink(dest);

    return true;
}

async function zipDirectory(auth, dirPath, destPath) {
    const {default: archiver} = await import('archiver');
    // Create a file to stream archive data to.
    const output = fs.createWriteStream(destPath);
    const archive = archiver('zip', {
        zlib: {level: 9}, // Sets the compression level.
    });

    /* eslint-disable-next-line */
    output.on('close', function() {
        // console.log(archive.pointer() + ' total bytes');
        // console.log('archiver has been finalized and the output file descriptor has closed.');
    });

    /* eslint-disable-next-line */
    archive.on('error', function(err) {
        throw err;
    });

    // pipe archive data to the file
    archive.pipe(output);

    // append files from a sub-directory, putting its contents at the root of archive
    archive.directory(dirPath, false);

    // finalize the archive (ie we are done appending files but streams have to finish yet)
    // 'close', 'end' or 'finish' may be fired right after calling this method so register to them beforehand
    await archive.finalize();
    const fileId = await uploadFile(auth, destPath, '');
    // console.log(`Uploaded ${destPath} to ${fileId}`);
    fs.promises.unlink(destPath);

    return fileId;
}

async function uploadDirectory(auth, dirPath, destPath) {
    const dest = `${destPath}/${dirPath}.zip`;
    const fileId = await zipDirectory(auth, dirPath, dest);
    await unzipFile(auth, fileId, destPath);
    return true;
}

async function downloadDirectory(auth, fileId, destPath) {
    const dest = `${destPath}/${fileId}.zip`;
    await downloadFileById(auth, fileId, dest);
