import os
import sys
import json
import requests
import urllib3
import time

from flask import Flask, request, Response
import threading
from datetime import datetime
from flask_cors import CORS
import redis
from pydantic import BaseModel
from qwen_hub import reply as qwen_reply
import qwen_config as config
import webbrowser

app = Flask(__name__)
CORS(app)

redis_client = redis.Redis(host=config.redis_host, port=config.redis_port, db=config.redis_db, decode_responses=True, ssl=config.redis_ssl, ssl_cert_reqs='CERT_NONE')

def user_message_request(user_message, conversation_id=None, context=None):
    if conversation_id is None:
        conversation_id = str(int(time.time())) + "-" + str(int(time.time() * 1000))
    if context is None:
        context = []
    conversation = redis_client.hgetall(f"conversation:{conversation_id}")
    if conversation:
        max_history = config.max_history
        if len(conversation['messages']) > max_history * 2:
            conversation['messages'] = conversation['messages'][-max_history:]
        context = json.loads(conversation['messages'])
    else:
        context = [
            {
                "role": "system",
                "content": config.system_prompt
            }
        ]
    context.append({
        "role": "user",
        "content": user_message
    })
    return redis_client.hset(f"conversation:{conversation_id}", mapping={
        'conversation_id': conversation_id,
        'messages': json.dumps(context)
    }), context

@app.route('/api/v1/chat/completions', methods=['POST'])
def chat():
    try:
        req = request.get_json()
        print(req)
        if 'messages' not in req or len(req['messages']) < 1:
            return Response(
                response=json.dumps({
                    'error': {
                        'message': 'Invalid request: messages field is missing or empty.',
                        'type': 'invalid_request_error',
                        'param': 'messages',
                        'code': 'missing_messages'
                    }
                }),
                status=400,
                mimetype='application/json'
            )

        if 'model' not in req or req['model'] != config.model:
            return Response(
                response=json.dumps({
                    'error': {
                        'message': 'Invalid request: model is not supported.',
                        'type': 'invalid_request_error',
                        'param': 'model',
                        'code': 'model_not_supported'
                    }
                }),
                status=400,
                mimetype='application/json'
            )

        content = req['messages'][-1]['content']
        print(f"Received message: {content}")

        conversation_id = req.get('conversation_id')
        context = req.get('context')
        redis_client.hset(f"conversation:{conversation_id}", mapping={
            'conversation_id': conversation_id,
            'messages': json.dumps(context)
        })

        reply = qwen_reply(content, conversation_id)
        print(f"Sending reply: {reply}")

        response = json.dumps({
            "choices": [{
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": reply
                },
                "finish_reason": "stop"
            }],
            "created": time.time(),
            "model": config.model,
            "object": "chat.completion",
            "usage": {
                "completion_tokens": len(reply),
                "prompt_tokens": len(content),
                "total_tokens": len(reply) + len(content)
            }
        })
        print(response)
        return Response(
            response=response,
            status=200,
            mimetype='application/json'
        )
    except Exception as e:
        print(f"Error: {e}")
        return Response(
            response=json.dumps({
                'error': {
