public class ChatBot {

	private static String apiurl = "http://114.119.139.113:8080/qwen";

	public static void main(String[] args) throws ClientProtocolException,
			IOException {
		Scanner scanner = new Scanner(System.in);
		do {
			System.out.println("Please input your question:");
			String sentence = scanner.nextLine();

			// call the API
			HttpResponse response = callAPI(sentence);
			// print out the response
			String responseBody = EntityUtils.toString(response.getEntity());
			JSONObject responseJson = JSONObject.parseObject(responseBody);
			String botResponse = responseJson.getString("response");
			System.out.println(botResponse);

			// do you want to continue?
			System.out.println("Do you want to continue? (Y/N) ");
			String userInput = scanner.nextLine();
			if (userInput.toLowerCase().equals("n")) {
				break;
			}

		} while (true);

		scanner.close();
	}

	// call the API
	private static HttpResponse callAPI(String sentence)
			throws ClientProtocolException, IOException {
		CloseableHttpClient client = HttpClients.createDefault();
		HttpPost post = new HttpPost(apiurl);
		post.setHeader("Accept", "application/json");
		post.setHeader("Content-Type", "application/json");
		StringEntity input = new StringEntity("{ \"sentence\": \"" + sentence
				+ "\" }");
		input.setContentType("application/json");
		post.setEntity(input);
		HttpResponse response = client.execute(post);
		return response;
	}

