package jd;

import java.io.*;
import java.net.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws IOException {
        String username = "test";
        String password = "test";
        String server = "127.0.0.1";
        int port = 8080;

        try {
            ServerSocket serverSocket = new ServerSocket(port);
            Socket clientSocket = serverSocket.accept();
            DataOutputStream out = new DataOutputStream(clientSocket.getOutputStream());
            DataInputStream in = new DataInputStream(clientSocket.getInputStream());

            // Send the username and password to the server
            out.writeUTF(username);
            out.writeUTF(password);

            // Read the response from the server
            String response = in.readUTF();
            if (response.equals("SUCCESS")) {
                System.out.println("Login successful");
                // Start the chat loop
                chatLoop(clientSocket);
            } else {
                System.out.println("Login failed");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void chatLoop(Socket socket) throws IOException {
        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.print("> ");
            String message = scanner.nextLine();

            // Send the message to the server
            DataOutputStream out = new DataOutputStream(socket.getOutputStream());
            out.writeUTF(message);

            // Read the response from the server
            DataInputStream in = new DataInputStream(socket.getInputStream());
            String response = in.readUTF();
            System.out.println(response);
        }
    }

    private static String generateResponse(String input) {
        Map<String, String> responses = new HashMap<>();
        responses.put("hello", "Hi there!");
        responses.put("how are you", "I'm doing well, thanks!");
        responses.put("bye", "Goodbye!");

        String[] inputWords = input.split(" ");
        for (String word : inputWords) {
            if (responses.containsKey(word)) {
                return responses.get(word);
            }
        }

        return "I'm sorry, I don't understand.";
    }
}

