package api

import (
	"context"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/pkg/errors"
	"google.golang.org/grpc/metadata"

	v1 "github.com/Qwen-Cloud/Qwen-DevOps/api/helloworld/v1"
	"github.com/Qwen-Cloud/Qwen-DevOps/pkg/app"
	"github.com/Qwen-Cloud/Qwen-DevOps/pkg/errno"
	"github.com/Qwen-Cloud/Qwen-DevOps/pkg/log"
)

func (s *Server) sendMessageUser(ctx context.Context, req *v1.SendMessageRequest) error {
	log.Infof("qwen: %s", req)
	_, err := s.SendMessageUser(ctx, req)
	return err
}

func (s *Server) SendMessageUser(c *gin.Context) {
	req := &v1.SendMessageRequest{}
	if err := c.ShouldBindJSON(req); err != nil {
		log.Error(err)
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	log.Infof("req: %v", req)

	// Get token from header
	token := c.GetHeader("token")
	// Get user info from token
	userInfo, err := s.UserManager.GetUserByToken(token)
	if err != nil {
		log.Error(err)
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}
	log.Debugf("User info: %v", userInfo)

	// Get user id
	uid := userInfo.UserID
	// Get user name
	username := userInfo.Username
	// Get user name
	userRole := userInfo.Role
	// get channel id
	channelId := req.ChannelID
	// get message
	message := req.Message
	// get message type
	messageType := req.MessageType
	// get message content
	content := req.Content
	// get message time
	time := req.Time
	// get message id
	messageId := req.MessageID
	// get message received time
	receivedTime := req.ReceivedTime
	// get message status
	status := req.Status
	// get message is read
	isRead := req.IsRead
	// get message read time
	readTime := req.ReadTime
	// get message is deleted
	isDeleted := req.IsDeleted
	// get message deleted time
	deletedTime := req.DeletedTime

	// get channel info
	channelInfo, err := s.ChannelManager.GetChannelInfo(channelId)
	if err != nil {
		log.Error(err)
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}
	log.Debugf("Channel info: %v", channelInfo)

	// Get user id
	channelUid := channelInfo.UserID

	// check if user is in channel
	if channelUid != uid {
		log.Error(errors.New("user is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if user role is in channel
	if channelUid != userRole {
		log.Error(errors.New("user role is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if message is in channel
	if messageId != channelId {
		log.Error(errors.New("message is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if message type is in channel
	if messageId != messageType {
		log.Error(errors.New("message type is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if message content is in channel
	if messageId != content {
		log.Error(errors.New("message content is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if message time is in channel
	if messageId != time {
		log.Error(errors.New("message time is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if message received time is in channel
	if messageId != receivedTime {
		log.Error(errors.New("message received time is not in channel"))
		app.Response(c, errno.ErrInvalidParam, nil)
		return
	}

	// check if message status is in channel
