@app.route("/stream_chat", methods=["POST"])
def stream_chat():
    data = request.get_json()
    print(data)
    if not data or not data.get("prompt"):
        return jsonify({"error": "Missing 'prompt' in the request"}), 400

    prompt = data["prompt"]
    print(f"Received prompt: {prompt}")

    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {API_KEY}"
    }

    data = {
        "prompt": prompt,
        "top_p": 0.7,
        "temperature": 0.95,
        "max_tokens": 20,  # Adjust the stream length as needed
        "stream": True
    }

    stream_response = requests.post("https://api.qwen.alibaba.com/v1/chat/completions", json=data, headers=headers, stream=True)
    if stream_response.status_code != 200:
        return jsonify({"error": f"API error: {stream_response.text}"})

    result = ""
    for line in stream_response.iter_lines():
        if line:
            partial_result = line.decode("utf-8").strip()
            if partial_result.startswith("data:"):
                partial_result = partial_result[6:]
                if partial_result == "[DONE]":
                    break
                try:
                    partial_response = json.loads(partial_result)
                    partial_result = partial_response["result"]
                except json.JSONDecodeError:
                    # Handle malformed JSON here (e.g., partial results)
                    continue
            result += partial_result
            print(f"Partial Qwen response: {partial_result}")

    print(f"Final Qwen response: {result}")
    return jsonify({"result": result})

