/**
 * @api {get} /news/:category get news list
 * @apiDescription get news list
 * @apiGroup news
 * @apiParam {String} category category id
 * @apiSuccessExample {json} Success-Response:
 * {
 *   "status": "OK",
 *   "payload": [
 *     {
 *       "id": 1,
 *       "title": "News Title 1",
 *       "summary": "News Summary 1",
 *       "url": "News URL 1",
 *       "date": "News Date 1"
 *     },
 *     {
 *       "id": 2,
 *       "title": "News Title 2",
 *       "summary": "News Summary 2",
 *       "url": "News URL 2",
 *       "date": "News Date 2"
 *     },
 *     ...
 *   ]
 * }
 * @apiErrorExample {json} Error-Response:
 * {
 *   "status": "ERROR",
 *   "message": "Category not found"
 * }
 */
router.get('/news/:category', function(req, res) {
    var category = req.params.category;
    var cache = path.join(__dirname, 'cache', category + '.json');
    var data = fs.existsSync(cache) ? JSON.parse(fs.readFileSync(cache, 'utf8')) : {};
    if (data.status === 'OK' && data.payload.length > 0) {
        res.json(data);
    } else {
        var url = 'https://www.163.com/special/00804KVA/' + category + '.html';
        request(url, function(error, response, body) {
            if (!error && response.statusCode === 200) {
                var $ = cheerio.load(body);
                var newsList = [];
                $('.time-title').each(function() {
                    var title = $(this).find('a').text();
                    var url = $(this).find('a').attr('href');
                    var date = $(this).find('span').text();
                    var summary = $(this).parent().siblings('.summary').text();
                    newsList.push({
                        title: title,
                        url: url,
                        date: date,
                        summary: summary
                    });
                });
                data = {
                    status: 'OK',
                    payload: newsList
                };
                fs.writeFileSync(cache, JSON.stringify(data));
                res.json(data);
            } else {
                data = {
                    status: 'ERROR',
                    message: 'Category not found'
                }
                res.json(data);
            }
        });
    }
});


/**
 * @api {get} /news/:category/:id get news details
 * @apiDescription get news details
 * @apiGroup news
 * @apiParam {String} category category id
 * @apiParam {String} id news id
 * @apiSuccessExample {json} Success-Response:
 * {
 *   "status": "OK",
 *   "title": "News Title 1",
 *   "summary": "News Summary 1",
 *   "content": "News Content 1",
 *   "date": "News Date 1"
 * }
 * @apiErrorExample {json} Error-Response:
 * {
 *   "status": "ERROR",
 *   "message": "News not found"
 * }
 */
router.get('/news/:category/:id', function(req, res) {
    var category = req.params.category;
    var id = req.params.id;
    var url = 'https://www.163.com/special/00804KVA/' + category + '.html';
    request(url, function(error, response, body) {
        if (!error && response.statusCode === 200) {
            var $ = cheerio.load(body);
            var title = $('#'+id).find('h1').text();
            var date = $('#'+id).find('span').text();
            var summary = $('#'+id).find('.summary').text();
            var content = $('#'+id).find('.content').html();
            var news = {
                status: 'OK',
                title: title,
                summary: summary,
                content: content,
                date: date
            }
            res.json(news);
        } else {
            var news = {
                status: 'ERROR',
                message: 'News not found'
            }
            res.json(news);
        }
    });
});


/**
 * @api {get} /news/:category/:id/comments get news comments
 * @apiDescription get news comments
 * @apiGroup news
 * @apiParam {String} category category id
 * @apiParam {String} id news id
 * @apiSuccessExample {json} Success-Response:
 * {
 *   "status": "OK",
 *   "payload": [
 *     {
 *       "id": 1,
