 * @apiErrorExample {json} Error-Response:
 * {
 *   "status": "ERROR",
 *   "message": "Comments not found"
 * }
 */
router.get('/news/:category/:id/comments', function(req, res) {
    var category = req.params.category;
    var id = req.params.id;
    var cache = path.join(__dirname, 'cache', category + '-' + id + '-comments.json');
    var data = fs.existsSync(cache) ? JSON.parse(fs.readFileSync(cache, 'utf8')) : {};
    if (data.status === 'OK' && data.payload.length > 0) {
        res.json(data);
    } else {
        var url = 'https://www.163.com/special/00804KVA/' + category + '.html';
        request(url, function(error, response, body) {
            if (!error && response.statusCode === 200) {
                var $ = cheerio.load(body);
                var commentsList = [];
                $('div[id^="com-"]').each(function() {
                    var nickname = $(this).find('a').text();
                    var date = $(this).find('.time').text();
                    var content = $(this).find('.dps').text();
                    commentsList.push({
                        nickname: nickname,
                        date: date,
                        content: content
                    });
                });
                data = {
                    status: 'OK',
                    payload: commentsList
                };
                fs.writeFileSync(cache, JSON.stringify(data));
                res.json(data);
            } else {
                data = {
                    status: 'ERROR',
                    message: 'Comments not found'
                }
                res.json(data);
            }
        });
    }
});

