import json
import os
import re
import sys
from json import JSONDecodeError
from typing import Any, Dict, List, Optional, Tuple

import pytest
import requests
from requests import Response

from qwen_cpp.server import server
from tests.utils import get_free_port

try:
    from rich import print
except ImportError:
    pass


def wait_for_server(port: int, timeout: int = 10) -> None:
    """Wait for the server to start."""
    url = f"http://localhost:{port}"
    for _ in range(timeout):
        try:
            requests.get(url)
            return
        except ConnectionError:
            pass
        time.sleep(1)
    raise TimeoutError(f"Server did not start after {timeout} seconds.")


def _print_response(response: Response) -> None:
    print(f"Response status code: {response.status_code}")
    print(f"Response text: {response.text}")


class QwenServer:
    def __init__(self, port: int, model_path: str, max_context_len: int) -> None:
        self.port = port
        self.model_path = model_path
        self.max_context_len = max_context_len

    def start(self) -> None:
        server.run(
            model_path=self.model_path,
            max_context_len=self.max_context_len,
            port=self.port,
        )

    def stop(self) -> None:
        pass


class QwenCppServer(QwenServer):
    def start(self) -> None:
        import subprocess

        cmd = [
            "python",
            "-m",
            "qwen_cpp.server",
            f"--port={self.port}",
            f"--model_path={self.model_path}",
            f"--max_context_len={self.max_context_len}",
        ]

        self.process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Wait for server to start
        wait_for_server(self.port)

    def stop(self) -> None:
        if self.process.poll() is None:
            self.process.terminate()


class MockQwenServer(QwenServer):
    def start(self) -> None:
        self.port = 5000
        self.server = server.MockServer(self.model_path, self.max_context_len)

        wait_for_server(self.port)

    def stop(self) -> None:
        self.server.stop()


@pytest.fixture(scope="session")
def server() -> QwenServer:
    port = get_free_port()
    server = QwenCppServer(port, "./models/qwen-7b", 4096)
    server.start()
    yield server
    server.stop()


@pytest.fixture
def server_mock() -> MockQwenServer:
    port = get_free_port()
    server = MockQwenServer(port, "./models/qwen-7b", 4096)
    server.start()
    yield server
    server.stop()


class QwenClient(requests.Session):
    def __init__(
        self,
        url: str = "http://localhost:8080/v1/completions",
        stream: bool = False,
        timeout: int = 10,
