const prompt = document.querySelector(".prompt");
const response = document.querySelector(".response");
const form = document.querySelector("form");
const sendBtn = document.querySelector(".send");
const clearBtn = document.querySelector(".clear");
const chatContainer = document.querySelector(".chat-container");
const textarea = document.querySelector("textarea");

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const data = new FormData(form);
  prompt.innerHTML = data.get("prompt");
  response.innerHTML = "Thinking...";

  fetch("https://openbuddy.ai/api", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      prompt: data.get("prompt"),
      model: "openbuddy-7b-v1.1",
      temperature: 0.4,
      top_p: 0.7,
      top_k: 50,
      max_new_tokens: 64,
      stop: ["You:"],
    }),
  })
    .then((res) => res.json())
    .then((data) => {
      response.innerHTML = data.data;
      const chat = document.createElement("div");
      chat.classList.add(
        "chat",
        "chat-" + (prompt.innerHTML == data.data ? "prompt" : "response")
      );
      chat.innerHTML = `<p><span>${prompt.innerHTML == data.data ? "You" : "Qwen"}</span>${prompt.innerHTML == data.data ? data.data : prompt.innerHTML}</p>`;
      chatContainer.appendChild(chat);
      chatContainer.scrollTop = chatContainer.scrollHeight;
      textarea.value = "";
    });
});

clearBtn.addEventListener("click", () => {
  prompt.innerHTML = "";
  response.innerHTML = "";
  chatContainer.innerHTML = "";
});

textarea.addEventListener("input", () => {
  const { value } = textarea;
  if (!value) {
    sendBtn.disabled = true;
  } else {
    sendBtn.disabled = false;
  }
});

sendBtn.addEventListener("click", () => {
  if (!sendBtn.disabled) {
    form.submit();
  }
});

