import os
import sys
import json
import openai
from flask import Flask, request, jsonify, abort, make_response

app = Flask(__name__)

QWEN_API_KEY = os.environ.get('QWEN_API_KEY')
QWEN_API_ENDPOINT = os.environ.get('QWEN_API_ENDPOINT', 'https://qwen.alibabacloud.com/api/chat')
QWEN_MAX_TOKENS = int(os.environ.get('QWEN_MAX_TOKENS', 1024))

openai.api_key = QWEN_API_KEY
openai.api_base = QWEN_API_ENDPOINT
openai.Model.list()

@app.route('/api/chat', methods=['POST'])
def chat():
    data = request.get_json()
    if not data or 'prompt' not in data:
        abort(400, 'Missing prompt in request')

    prompt = data['prompt']
    response = openai.Completion.create(
        model="qwen-turbo",
        prompt=prompt,
        max_tokens=QWEN_MAX_TOKENS,
        temperature=0.7,
        n=1,
    )

    if response and response.choices and len(response.choices) > 0:
        reply = response.choices[0].text.strip()
        return make_response(jsonify({
            'reply': reply,
            'status': 'success'
        }), 200)
    else:
        return make_response(jsonify({
            'status': 'error',
            'message': 'Failed to generate a reply'
        }), 500)

@app.route('/api/moderate', methods=['POST'])
def moderate():
    data = request.get_json()
    if not data or 'text' not in data:
        abort(400, 'Missing text in request')

    text = data['text']
    response = openai.Moderation.create(
        input=text,
    )

    if response and response.results and len(response.results) > 0:
        verdict = response.results[0].flagged
        if verdict:
            return make_respo<|fim_suffix|>
        else:
            return make_response(jsonify({
                'verdict': 'ALLOWED',
                'reason': 'Text is safe'
            }), 200)
    else:
        return make_response(jsonify({
            'status': 'error',
            'message': 'Failed to moderate the text'
        }), 500)

if __name__ == '__main__':
    app.run(debug=True)<|fim_middle|>nse(jsonify({
