package com.github.strangemod.item;

import com.github.strangemod.tag.StrangeTags;
import net.minecraft.tags.Tag;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.Enchantment;
import net.minecraft.world.item.enchantment.EnchantmentHelper;
import net.minecraft.world.item.enchantment.Enchantments;
import net.minecraft.world.item.enchantment.FireAspectEnchantment;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;

import java.util.function.Predicate;

public class BowItem extends BowItem {
    private final Predicate<LivingEntity> TARGET_PREDICATE = player -> true;

    public BowItem(Properties pProperties) {
        super(pProperties);
    }

    protected boolean isValidHitResult(BlockState pState, boolean pLiquid, Predicate<LivingEntity> pTarget) {
        return super.isValidHitResult(pState, pLiquid, TARGET_PREDICATE);
    }

    protected int getDefaultProjectileRange(ItemStack pBow) {
        int i = super.getDefaultProjectileRange(pBow);
        return EnchantmentHelper.getItemEnchantmentLevel(Enchantments.POWER_ARROWS, pBow) > 0 ? i * 2 : i;
    }

    protected void onHitEntity(Player pPlayer, LivingEntity pHitEntity, ItemStack pBow, ItemStack pArrow, int pProjectileTime) {
        if (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.POWER_ARROWS, pBow) > 0) {
            int i = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.PUNCH_ARROWS, pBow);
            double d0 = i >= 3 ? 100.0D : (double)(i * 10);
            double d1 = i >= 3 ? 1.5D : (double)i;
            pHitEntity.hurt(pPlayer.damageSources().arrow(pArrow, pPlayer), (float)d0);
            pHitEntity.setArrowCountInEntity(pHitEntity.getArrowCountInEntity() - 1);
            if (pHitEntity.getArrowCountInEntity() <= 0) {
                pHitEntity.removeArrowEffect();
            }

            if (pHitEntity instanceof Player player && player.getAbilities().instabuild) {
                int j = 0;
                if (pArrow.is(Items.FIREWORK_ROCKET)) {
                    j = 10;
                }

                if (pProjectileTime >= 200 - j) {
                    pPlayer.awardStat(Stats.ARROW_HIT_PLAYER);
                }
            }

            pPlayer.awardStat(Stats.ARROW_HIT_PLAYER);
        }

        if (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FLAME_ARROWS, pBow) > 0) {
            pHitEntity.setSecondsOnFire(FireAspectEnchantment.getFireDurationFromItem(pBow));
        }
    }

    public static void fireProjectile(LivingEntity shooter, ItemStack bow, ItemStack arrow, float charge, float velocity, float inaccuracy) {
        Level level = shooter.level();
        if (!level.isClientSide()) {
            double d0 = shooter.getViewVector(1.0F).x;
            double d1 = shooter.getViewVector(1.0F).y;
            double d2 = shooter.getViewVector(1.0F).z;
            double d3 = shooter.getX() + d0 * inaccuracy;
            double d4 = shooter.getY() + (double)shooter.getEyeHeight() + d1 * inaccuracy;
            double d5 = shooter.getZ() + d2 * inaccuracy;
            float f = shooter.getXRot();
            float f1 = shooter.getYRot();
            float f2 = -MathHelper.sin(f1 * ((float)Math.PI / 180F)) * MathHelper.cos(f * ((float)Math.PI / 180F));
            float f3 = -MathHelper.sin(f * ((float)Math.PI / 180F));
            float f4 = MathHelper.cos(f * ((float)Math.PI / 180F)) * MathHelper.cos(f1 * ((float)Math.PI / 180F));
            float f5 = MathHelper.sqrt((f2 * f2) + (f3 * f3) + (f4 * f4));
            float f6 = 3.0F * charge * charge * velocity / f5;
            f2 *= (double)f6;
