from __future__ import print_function
import os
import json

import requests
from requests.auth import HTTPBasicAuth


class Session(object):
    def __init__(self, token=None, mode="online", url=None):
        """
        Init Session.
        """
        self.token = token
        self.url = url
        self.mode = mode

    def _send(self, data, method="GET", api=""):
        if self.token:
            data["token"] = self.token

        headers = {
            "Content-Type": "application/json",
        }
        url = self.url + api if self.url else "https://api.aliyuncs.com" + api
        if method == "GET":
            return requests.get(url, headers=headers, params=data, auth=HTTPBasicAuth("aliyun", "aliyun"))
        elif method == "POST":
            return requests.post(url, headers=headers, json=data, auth=HTTPBasicAuth("aliyun", "aliyun"))

    def _post(self, data, api=""):
        return self._send(data, "POST", api)

    def _get(self, data, api=""):
        return self._send(data, "GET", api)

    def create(self, model, prompt, temperature=0.9, top_p=0.95, top_k=40, max_tokens=512, stream=False):
        """
        Create a completion.
        """
        prompt = "" if not prompt else prompt
        prompt = prompt.strip()
        if not prompt:
            raise ValueError("Prompt cannot be empty.")

        if len(prompt) > 4096:
            raise ValueError("Prompt length must not exceed 4096 characters.")

        if self.mode == "online":
            res = self._post(
                {
                    "model": model,
                    "prompt": prompt,
                    "temperature": temperature,
                    "top_p": top_p,
                    "top_k": top_k,
                    "max_tokens": max_tokens,
                    "stream": stream,
                },
                "/api/chat/completions",
            )
        else:
            res = self._post(
                {
                    "model": model,
                    "prompt": prompt,
                    "temperature": temperature,
                    "top_p": top_p,
                    "top_k": top_k,
                    "max_tokens": max_tokens,
                    "stream": stream,
                },
                "/api/chat/completions",
            )

        res = json.loads(res.content.decode("utf-8"))
        if res.get("code", None) == "200":
            return res.get("data", {}).get("text", "")
        else:
            raise ValueError(res.get("msg", ""))

    def stream(self, model, prompt, temperature=0.9, top_p=0.95, top_k=40, max_tokens=512):
        """
        Create a completion.
        """
        prompt = "" if not prompt else prompt
        prompt = prompt.strip()
        if not prompt:
            raise ValueError("Prompt cannot be empty.")

        if len(prompt) > 4096:
            raise ValueError("Prompt length must not exceed 4096 characters.")

        if self.mode == "online":
            res = self._post(
                {
                    "model": model,
                    "prompt": prompt,
                    "temperature": temperature,
                    "top_p": top_p,
                    "top_k": top_k,
                    "max_tokens": max_tokens,
                    "stream": True,
                },
                "/api/chat/completions",
            )
        else:
            res = self._post(
                {
                    "model": model,
                    "prompt": prompt,
                    "temperature": temperature,
                    "top_p": top_p,
                    "top_k": top_k,
                    "max_tokens": max_tokens,
                    "stream": True,
                },
                "/api/chat/completions",
            )

        return res.content

    def get_models(self):
        """
        Get all models.
        """
        res = self._get({}, "/api/chat/models")
        res = json.loads(res.content.decode("utf-8"))
        if res.get("code", None) == "200":
