from flask import Flask, request, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

@app.route('/api/generate-image', methods=['POST'])
def generate_image():
    try:
        # Retrieve the prompt from the request JSON
        prompt = request.json.get('prompt')
        print("Received prompt:", prompt)

        # Generate the image using the Stable Diffusion process
        # (You would implement this part with your Stable Diffusion model or API)
        # For demonstration purposes, we'll just return a placeholder image
        image = Image.new("RGB", (512, 512), color="blue")

        # Save the image to a file
        image.save("generated_image.png")

        # Return the generated image as a response
        image_file = open("generated_image.png", "rb")
        return send_from_directory(".", "generated_image.png", mimetype="image/png")
        #return jsonify({'status': 'success', 'message': 'Image generated successfully.'})
    except Exception as e:
        print("Error:", e)
        return jsonify({'status': 'error', 'message': 'Failed to generate image.'})

@app.route('/')
def index():
    return app.send_static_file('index.html')

@app.route('/api/ping', methods=['POST'])
def ping():
    return jsonify({'status': 'success'})

@app.route('/api/upload_image', methods=['POST'])
def upload_image():
    try:
        # Retrieve the uploaded image from the request
        file = request.files['file']
        print("Received image file:", file)

        # Save the uploaded image to a file
        image_path = 'uploaded_image.png'
        file.save(image_path)

        # Open the image using PIL
        image = Image.open(image_path)

        # Convert the image to bytes
        image_bytes = BytesIO()
        image.save(image_bytes, format="PNG")
        image_bytes.seek(0)

        # Send the image bytes as a response
        return Response(image_bytes, mimetype='image/png')
        #return jsonify({'status': 'success', 'message': 'Image uploaded successfully.'})
    except Exception as e:
        print("Error:", e)
        return jsonify({'status': 'error', 'message': 'Failed to upload image.'})

