@PIPELINES.register_module(
    Tasks.face_detection, module_name=Pipelines.face_detection)
class FaceDetectionPipeline(Pipeline):

    def __init__(self, model: str, **kwargs):
        """
        use `model` to create a face detection pipeline for prediction
        Args:
            model: model id on modelscope hub.
        """
        super().__init__(model, **kwargs)

    def preprocess(self, input: Input) -> Dict[str, Any]:
        inputs = dict()
        if isinstance(input, str):
            inputs['img'] = input
        else:
            raise TypeError(
                f'The input should be type of str, but got {type(input)}')
        return inputs

    def forward(self, input: Dict[str, Any]) -> Dict[str, Any]:
        return self.model(**input)

    def postprocess(self, inputs: Dict[str, Any]) -> Dict[str, Any]:
        faces = tensor_to_list(inputs[OutputKeys.KEYPOINTS])
        faces = [dict(zip(['x', 'y'], face)) for face in faces]
        return {OutputKeys.OUTPUT: faces}


