from flask import Blueprint, send_file, request, jsonify, render_template
from flask_restful import Resource
from werkzeug.utils import secure_filename

from llmstudio import app, utils, config
from llmstudio.model import Model
from llmstudio.models import Models
from llmstudio.sse import sse
from llmstudio.utils import data_from_json, data_to_json
from llmstudio.schema import SchemaModel

bp = Blueprint('api', __name__)
models = Models()

@bp.route('/')
def index():
    return render_template('index.html')


class NewModel(Resource):
    def post(self):
        data = data_from_json(request.data)
        model = Model(**data)
        if not model.validate():
            return jsonify({'message': 'Bad request'}), 400

        model_path = os.path.join(config.get('models_dir'), secure_filename(model.name))
        if not os.path.exists(model_path):
            os.makedirs(model_path)
        schema_path = os.path.join(model_path, 'schema.json')
        data_to_json(schema_path, Model.schema())

        models.update(model)
        config.update({'models': models.list()})
        return jsonify({'message': 'OK', 'model': model}), 201

class ModelResource(Resource):
    def get(self, name):
        model = models.find(name)
        if model is None:
            return jsonify({'message': 'Model not found'}), 404
        return jsonify({'message': 'OK', 'model': model}), 200

    def put(self, name):
        data = data_from_json(request.data)
        model = models.find(name)
        if model is None:
            return jsonify({'message': 'Model not found'}), 404
        if not Model.validate(data):
            return jsonify({'message': 'Bad request'}), 400

        model.update(data)
        models.update(model)
        config.update({'models': models.list()})
        return jsonify({'message': 'OK', 'model': model}), 200

    def delete(self, name):
        model = models.find(name)
        if model is None:
            return jsonify({'message': 'Model not found'}), 404
        model.delete()
        models.update(model)
        config.update({'models': models.list()})
        return jsonify({'message': 'OK'}), 200

