import axios from 'axios';
import {
  EmailCronJob,
  EmailCronJobType,
  FetchHealthwiseSitesDataCronJob,
} from './models';
import {
  getBlogs,
  getHealthSites,
  getHealthwiseSites,
  getRecommendation,
} from '@/services';
import { apiConfig } from '@/constants/api.config';
import { db } from '@/services/db';
import { cronjobConfig } from '@/constants/cronjob.config';

export class FetchHealthwiseSitesCronJob extends EmailCronJob {
  constructor() {
    super(cronjobConfig.healthwiseSites.name);
  }

  async fetchHealthwiseSites(keyword: string): Promise<any[]> {
    const data = await getHealthwiseSites(keyword);
    return data;
  }

  async fetchAndSaveHealthwiseSites(keyword: string) {
    const fetchedData = await this.fetchHealthwiseSites(keyword);
    const savedData = await this.saveHealthwiseSitesToDB(fetchedData);
    return savedData;
  }

  async saveHealthwiseSitesToDB(data: any[]) {
    try {
      await db.saveHealthwiseSites(data);
      return data;
    } catch (error) {
      console.error('Error saving healthwise sites to DB:', error);
      throw error;
    }
  }

  async fetchAndSendEmailToUser(): Promise<void> {
    try {
      const fetchedData = await this.fetchAndSaveHealthwiseSites(
        cronjobConfig.healthwiseSites.keyword,
      );
      const emailBody = this.createEmailBody(fetchedData);
      await this.sendEmailToUser(emailBody);
    } catch (error) {
      console.error('Error fetching and sending emails:', error);
    }
  }

  createEmailBody(data: any[]): string {
    const emailBody = data
      .map((item) => {
        return `
          <h2>${item.title}</h2>
          <p>${item.content}</p>
          <a href="${item.url}">${item.url}</a>
        `;
      })
      .join(`\n\n`);
    return emailBody;
  }

  async sendEmailToUser(emailBody: string) {
    try {
      await axios.post(apiConfig.sendEmail, {
        type: EmailCronJobType.FETCH_HEALTHWISE_SITES,
        emailBody,
      });
    } catch (error) {
      console.error('Error sending email to user:', error);
      throw error;
    }
  }
}

