def get_model_args(model_name):
    model_path = Path(Path.cwd(), "models", model_name)
    if not model_path.exists():
        return None
    model_args = {}
    model_args_file = model_path / "model_args.json"
    if model_args_file.exists():
        model_args = json.load(model_args_file.open("r", encoding="utf-8"))
    return model_args

def get_model_name(model_args, model_path):
    if "model_name" in model_args:
        return model_args["model_name"].replace("-", "_")
    model_name = model_path.name
    return model_name.replace("-", "_")

def get_model_version(model_args):
    if "model_version" in model_args:
        return model_args["model_version"]
    return None

def get_model_path(model_name):
    model_path = Path(Path.cwd(), "models", model_name)
    if not model_path.exists():
        return None
    return model_path

