        self.max_context_length = max_context_length

        self.init_model()

    def init_model(self):
        self.model = QwenCppHttpModel(self.model_path, self.model_version, self.max_context_length)

    def generate(self, prompt, max_length, temperature, top_p):
        if not self.model:
            return ""
        return self.model.generate(prompt, max_length, temperature, top_p)

