namespace qwen_cpp {

template <typename T>
class Uniform {
 public:
  Uniform(T min, T max) : dis_(min, max) {}

  Tensor<T> Sample(size_t size) {
    Tensor<T> tensor(size);
    for (size_t i = 0; i < size; ++i) {
      tensor[i] = dis_(generator_);
    }
    return tensor;
  }

 private:
  std::mt19937 generator_;
  std::uniform_real_distribution<T> dis_;
};

template <>
class Uniform<float> {
 public:
  Uniform(float min, float max) : dis_(static_cast<double>(min),
                                       static_cast<double>(max)) {}

  Tensor<float> Sample(size_t size) {
    Tensor<float> tensor(size);
    for (size_t i = 0; i < size; ++i) {
      tensor[i] = static_cast<float>(dis_(generator_));
    }
    return tensor;
  }

 private:
  std::mt19937 generator_;
  std::uniform_real_distribution<double> dis_;
};

template <>
class Uniform<double> {
 public:
  Uniform(double min, double max) : dis_(min, max) {}

  Tensor<double> Sample(size_t size) {
    Tensor<double> tensor(size);
    for (size_t i = 0; i < size; ++i) {
      tensor[i] = dis_(generator_);
    }
    return tensor;
  }

 private:
  std::mt19937 generator_;
  std::uniform_real_distribution<double> dis_;
};

