from typing import Dict, List

import numpy as np
import torch
from torch import nn

from modelscope.metainfo import Pipelines
from modelscope.models import TorchModel
from modelscope.outputs import OutputKeys
from modelscope.pipelines.base import Pipeline
from modelscope.pipelines.builder import PIPELINES
from modelscope.utils.constant import ModelFile, Tasks


@PIPELINES.register_module(
    Tasks.text_classification, module_name=Pipelines.ocnli)
class OcnliPipeline(Pipeline):

    def __init__(self, model: str, **kwargs):
        """
        use `model` to create a ocnli pipeline for prediction
        Args:
            model: model id on modelscope hub.
        """
        super().__init__(model, **kwargs)

        self.model = TorchModel.from_pretrained(model, **kwargs)
        self.model.eval()

    def preprocess(self, input: Dict[str, str]) -> Dict[str, torch.Tensor]:
        inputs = self.tokenizer(
            input['sentence1'],
            input['sentence2'],
            max_length=512,
            return_tensors='pt',
            padding=True)
        inputs = {k: v.to(self.device) for k, v in inputs.items()}
        return inputs

    def _collate_batch(self, batch: List) -> Dict[str, torch.Tensor]:
        return {
            k: torch.stack([d[k] for d in batch])
            for k in batch[0].keys()
        }

    def forward(self, input: Dict[str, torch.Tensor]) -> Dict[str, torch.Tensor]:
        with torch.no_grad():
            input = self._collate_batch(input)
            output = self.model(**input)

        return output

    def postprocess(self, inputs: Dict[str, torch.Tensor]) -> Dict[str, List[str]]:
        logits = inputs[OutputKeys.LOGITS]
        label_id = torch.argmax(logits, dim=-1).cpu().numpy().astype(np.long)
        labels = []
        for label in label_id:
            if label == 0:
                labels.append('contradiction')
            elif label == 1:
                labels.append('entailment')
            elif label == 2:
                labels.append('neutral')
            else:
                labels.append('unknow')
        results = {OutputKeys.LABELS: labels}
        return results


