const express = require('express');
const router = express.Router();
const User = require('../user');
const Chat = require('../chat');


// Get all chats
router.get('/', async (req, res) => {
    try {
        const chats = await Chat.find();
        res.json(chats);
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
});

// Get a single chat
router.get('/:id', getChat, (req, res) => {
    res.json(res.chat);
});

// Create a new chat
router.post('/', async (req, res) => {
    const chat = new Chat({
        title: req.body.title,
        participants: req.body.participants,
        messages: req.body.messages,
    });

    try {
        const newChat = await chat.save();
        res.status(201).json(newChat);
    } catch (err) {
        res.status(400).json({ message: err.message });
    }
});

// Update a chat
router.patch('/:id', getChat, async (req, res) => {
    if (req.body.title != null) {
        res.chat.title = req.body.title;
    }
    if (req.body.participants != null) {
        res.chat.participants = req.body.participants;
    }
    if (req.body.messages != null) {
        res.chat.messages = req.body.messages;
    }

    try {
        const updatedChat = await res.chat.save();
        res.json(updatedChat);
    } catch (err) {
        res.status(400).json({ message: err.message });
    }
});

// Add a user to a chat
router.post('/:chatId/addUser/:userId', async (req, res) => {
    try {
        const chat = await Chat.findById(req.params.chatId);
        const user = await User.findById(req.params.userId);

        if (!chat || !user) {
            return res.status(404).json({ message: 'Chat or user not found' });
        }

        if (chat.participants.includes(user._id)) {
            return res.status(400).json({ message: 'User is already in the chat' });
        }

        chat.participants.push(user._id);
        await chat.save();

        res.status(201).json({ message: 'User added to chat successfully' });
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
});

// Remove a user from a chat
router.delete('/:chatId/removeUser/:userId', async (req, res) => {
    try {
        const chat = await Chat.findById(req.params.chatId);
        const user = await User.findById(req.params.userId);

        if (!chat || !user) {
            return res.status(404).json({ message: 'Chat or user not found' });
        }

        const participantIndex = chat.participants.indexOf(user._id);

        if (participantIndex === -1) {
            return res.status(400).json({ message: 'User is not in the chat' });
        }

        chat.participants.splice(participantIndex, 1);
        await chat.save();

        res.json({ message: 'User removed from chat successfully' });
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
});

// Add a message to a chat
router.post('/:chatId/addMessage', async (req, res) => {
    try {
        const chat = await Chat.findById(req.params.chatId);

        if (!chat) {
            return res.status(404).json({ message: 'Chat not found' });
        }

        chat.messages.push(req.body.message);
        await chat.save();

        res.status(201).json({ message: 'Message added to chat successfully' });
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
});

// Delete a chat
router.delete('/:id', getChat, async (req, res) => {
    try {
        await res.chat.remove();
        res.json({ message: 'Chat deleted successfully' });
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
});

// Middleware function to get a chat by ID
async function getChat(req, res, next) {
    try {
        const chat = await Chat.findById(req.params.id);
        if (!chat) {
            return res.status(404).json({ message: 'Chat not found' });
        }
        res.chat = chat;
        next();
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
}

