package com.qwenielee.qwenielee.controller.admin;

import com.qwenielee.qwenielee.model.Book;
import com.qwenielee.qwenielee.service.BookService;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.context.junit4.SpringRunner;
import org.springframework.test.web.servlet.MockMvc;

import java.util.ArrayList;
import java.util.List;

import static org.hamcrest.CoreMatchers.is;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@RunWith(SpringRunner.class)
@WebMvcTest(BookController.class)
public class BookControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private BookService bookService;

    @Test
    public void testGetAllBooks() throws Exception {
        Book book1 = new Book();
        book1.setTitle("Book 1");
        book1.setAuthor("Author 1");
        book1.setIsbn("ISBN1");
        book1.setSummary("Summary 1");

        Book book2 = new Book();
        book2.setTitle("Book 2");
        book2.setAuthor("Author 2");
        book2.setIsbn("ISBN2");
        book2.setSummary("Summary 2");

        List<Book> bookList = new ArrayList<>();
        bookList.add(book1);
        bookList.add(book2);

        when(bookService.getAllBooks()).thenReturn(bookList);

        mockMvc.perform(get("/api/admin/books").accept(MediaType.APPLICATION_JSON))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()", is(2)))
                .andExpect(jsonPath("$[0].title", is("Book 1")))
                .andExpect(jsonPath("$[0].author", is("Author 1")))
                .andExpect(jsonPath("$[0].isbn", is("ISBN1")))
                .andExpect(jsonPath("$[0].summary", is("Summary 1")))
                .andExpect(jsonPath("$[1].title", is("Book 2")))
                .andExpect(jsonPath("$[1].author", is("Author 2")))
                .andExpect(jsonPath("$[1].isbn", is("ISBN2")))
                .andExpect(jsonPath("$[1].summary", is("Summary 2")));
    }

    @Test
    public void testGetBookById() throws Exception {
        Book book = new Book();
        book.setId(1L);
        book.setTitle("Book 1");
        book.setAuthor("Author 1");
        book.setIsbn("ISBN1");
        book.setSummary("Summary 1");

        when(bookService.getBookById(1L)).thenReturn(book);

        mockMvc.perform(get("/api/admin/books/1").accept(MediaType.APPLICATION_JSON))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id", is(1)))
                .andExpect(jsonPath("$.title", is("Book 1")))
                .andExpect(jsonPath("$.author", is("Author 1")))
                .andExpect(jsonPath("$.isbn", is("ISBN1")))
                .andExpect(jsonPath("$.summary", is("Summary 1")));
    }

    @Test
    public void testCreateBook() throws Exception {
        Book book = new Book();
        book.setTitle("Book 1");
        book.setAuthor("Author 1");
        book.setIsbn("ISBN1");
        book.setSummary("Summary 1");

        when(bookService.createBook(book)).thenReturn(book);

        mockMvc.perform(post("/api/admin/books").contentType(MediaType.APPLICATION_JSON)
                .content("{\"title\":\"Book 1\",\"author\":\"Author 1\",\"isbn\":\"ISBN1\",\"summary\":\"Summary 1\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.title", is("Book 1")))
                .andExpect(jsonPath("$.author", is("Author 1")))
                .andExpect(jsonPath("$.isbn", is("ISBN1")))
                .andExpect(jsonPath("$.summary", is("Summary 1")));
    }

    @Test
    public void testUpdateBook() throws Exception {
        Book book = new Book();
        book.setId(1L);
        book.setTitle("Updated Book");
        book.setAuthor("Updated Author");
        book.setIsbn("Updated ISBN");
        book.setSummary("Updated Summary");

        when(bookService.updateBook(book)).thenReturn(book);

        mockMvc.perform(put("/api/admin/books/1").contentType(MediaType.APPLICATION_JSON)
                .content("{\"title\":\"Updated Book\",\"author\":\"Updated Author\",\"isbn\":\"Updated ISBN\",\"summary\":\"Updated Summary\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.title", is("Updated Book")))
                .andExpect(jsonPath("$.author", is("Updated Author")))
                .andExpect(jsonPath("$.isbn", is("Updated ISBN")))
                .andExpect(jsonPath("$.summary", is("Updated Summary")));
    }

    @Test
    public void testDeleteBook() throws Exception {
        when(bookService.getBookById(1L)).thenReturn(new Book());
        mockMvc.perform(delete("/api/admin/books/1").accept(MediaType.APPLICATION_JSON))
                .andExpect(status().isOk());
    }

    // Add more tests for getAllBooks, getBookById, createBook, updateBook, and deleteBook methods
}
