import json
import os
import subprocess
import warnings
from pathlib import Path
from typing import Any, Dict, Optional, Union

import requests

from qwen_v2.utils import get_config_dir, get_user_agent


def get_app_token() -> str:
    """Get the app token from the environment or config file."""
    try:
        from qwen_v2 import __version__
    except ImportError:
        # If the package is not installed, use the version from the config file.
        __version__ = get_config_dir("app_token.json").read_text()
    return __version__


def get_token() -> str:
    """Return the token from the environment variable."""
    return os.environ.get("QWENV2_TOKEN")


def get_client_id() -> str:
    """Return the client_id from the environment variable."""
    return os.environ.get("QWENV2_CLIENT_ID")


def get_client_secret() -> str:
    """Return the client_secret from the environment variable."""
    return os.environ.get("QWENV2_CLIENT_SECRET")


def get_base_url() -> str:
    """Get the base url from the environment variable."""
    return os.environ.get("QWENV2_BASE_URL", "https://qwen-v2-api.qwen.tech")


def get_app_token_path() -> Path:
    """Return the path to the app token file."""
    return get_config_dir("app_token.json")


def get_config_path() -> Path:
    """Return the path to the config file."""
    return get_config_dir("config.json")


def get_cookies_path() -> Path:
    """Return the path to the cookies file."""
    return get_config_dir("cookies.json")


def get_token_path() -> Path:
    """Return the path to the token file."""
    return get_config_dir("token.json")


def get_access_token() -> str:
    """Return the access token from the token file."""
    try:
        return get_token_path().read_text()
    except FileNotFoundError:
        return ""


def read_config() -> Dict[str, Any]:
    """Read the config file."""
    try:
        return json.loads(get_config_path().read_text())
    except FileNotFoundError:
        return {}


def write_config(config: Dict[str, Any]) -> None:
    """Write the config file."""
    get_config_path().write_text(json.dumps(config))


def request(
    method: str,
    path: str,
    params: Optional[Dict[str, Any]] = None,
    data: Optional[Dict[str, Any]] = None,
    json: Optional[Dict[str, Any]] = None,
    headers: Optional[Dict[str, Any]] = None,
    timeout: int = 60,
) -> requests.Response:
    """Make a request to the API."""
    base_url = get_base_url()
    url = f"{base_url}{path}"
    headers = {
        "Content-Type": "application/json",
        "User-Agent": get_user_agent(),
    }
    if headers:
        headers.update(headers)
    return requests.request(
        method,
        url,
        params=params,
        data=data,
        json=json,
        headers=headers,
        timeout=timeout,
    )


def get_access_token_from_refresh_token(refresh_token: str) -> str:
    """Get the access token from the refresh token."""
    token_path = get_token_path()
    if token_path.exists():
        token_path.unlink()
    token_path.write_text(refresh_token)
    return refresh_token


def qwen_user_login(
    app_token: Optional[str] = None,
    client_id: Optional[str] = None,
    client_secret: Optional[str] = None,
) -> None:
    """Login with qwen user and save the refresh token to the token file."""
    if not app_token:
        app_token = get_app_token()
    if not client_id:
        client_id = get_client_id()
    if not client_secret:
        client_secret = get_client_secret()
    if not (client_id and client_secret):
        raise ValueError(
            "Please set QWENV2_CLIENT_ID and QWENV2_CLIENT_SECRET environment variables."
        )

    response = request(
        "POST",
        "/v1/login",
        json={
            "app_key": app_token,
            "client_id": client_id,
            "client_secret": client_secret,
        },
    )
    response.raise_for_status()
    response_json = response.json()
    if "refresh_token" not in response_json:
        raise ValueError(f"Login failed: {response_json}")
    refresh_token = response_json["refresh_token"]
    get_token_path().write_text(refresh_token)
    return refresh_token


def qwen_user_logout() -> None:
    """Logout from the qwen user.

    This will remove the refresh token from the token file.
    """
    os.remove(get_token_path())


def qwen_user_refresh_token() -> None:
    """Refresh the access token."""
    token_path = get_token_path()
    if not token_path.exists():
        raise ValueError("No refresh token found.")
    refresh_token = token_path.read_text()
    response = request(
        "POST",
        "/v1/refresh_token",
        data={
            "refresh_token": refresh_token,
        },
    )
    response.raise_for_status()
    response_json = response.json()
    if "access_token" not in response_json:
        raise ValueError(f"Refresh failed: {response_json}")
    access_token = response_json["access_token"]
    get_access_token_path().write_text(access_token)
    return access_token


def qwen_user_whoami() -> Dict[str, Any]:
    """Get the user information."""
    response = request("GET", "/v1/whoami")
    response.raise_for_status()
    return response.json()


def qwen_user_info() -> Dict[str, Any]:
    """Get the user information."""
    response = request("GET", "/v1/user_info")
    response.raise_for_status()
    return response.json()


def get_cookies() -> Dict[str, str]:
    """Read the cookies from the cookie file."""
    if not get_cookies_path().exists():
        return {}
    return json.loads(get_cookies_path().read_text())


def save_cookies(cookies: Dict[str, str]) -> None:
    """Save the cookies to the cookie file."""
    get_cookies_path().write_text(json.dumps(cookies))


def qwen_dingtalk_bind(
    dingtalk_token: str,
    app_token: Optional[str] = None,
) -> None:
    """Bind the qwen user with dingtalk."""
    if not app_token:
        app_token = get_app_token()
    response = request(
        "POST",
        "/v1/dingtalk/bind",
        json={
            "dingtalk_token": dingtalk_token,
            "app_token": app_token,
        },
    )
    response.raise_for_status()
    response_json = response.json()
    if "cookies" not in response_json:
        raise ValueError(f"Bind failed: {response_json}")
    cookies = response_json["cookies"]
    save_cookies(cookies)


def qwen_dingtalk_unbind(
    app_token: Optional[str] = None,
) -> None:
    """Unbind the qwen user with dingtalk."""
    if not app_token:
        app_token = get_app_token()
    response = request(
        "POST",
        "/v1/dingtalk/unbind",
        json={
            "app_token": app_token,
        },
    )
    response.raise_for_json()
    response_json = response.json()
    if "cookies" not in response_json:
        raise ValueError(f"Unbind failed: {response_json}")
    cookies = response_json["cookies"]
    save_cookies(cookies)


def qwen_dingtalk_logout() -> None:
    """Logout from the qwen dingtalk.

    This will remove the cookies from the cookie file.
    """
    os.remove(get_cookies_path())
    os.remove(get_token_path())


def qwen_dingtalk_info() -> Dict[str, Any]:
    """Get the dingtalk information."""
    response = request("GET", "/v1/dingtalk/info")
    response.raise_for_status()
    response_json = response.json()
    if "dingtalk_info" not in response_json:
        raise ValueError(f"Info failed: {response_json}")
    dingtalk_info = response_json["dingtalk_info"]
    return dingtalk_info


def qwen_dingtalk_start_conversation() -> Dict[str, Any]:
    """Start dingtalk conversation."""
    response = request("GET", "/v1/dingtalk/start_conversation")
    response.raise_for_status()
    return response.json()


def qwen_dingtalk_chat_message(
    conversation_id: str, message

