from transformers import AutoTokenizer, AutoModelForCausalLM, BertTokenizer
import torch
from transformers import AutoModelForSequenceClassification, AutoModelForCausalLM, AutoTokenizer


class model:
    def __init__(self, model_name: str, model_path: str):
        # self.tokenizer = BertTokenizer.from_pretrained('bert-base-uncased')
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.model = AutoModelForCausalLM.from_pretrained(model_path)

    def generate(self, text, max_length, do_sample=False):
        inputs = self.tokenizer(text, return_tensors='pt')
        input_ids = inputs['input_ids'].to(self.model.device)
        with torch.no_grad():
            outputs = self.model.generate(
                input_ids,
                max_length=max_length,
                pad_token_id=self.tokenizer.eos_token_id,
                do_sample=do_sample,
                top_p=0.95,
                top_k=50,
                num_return_sequences=1
            )

        return self.tokenizer.decode(outputs[0], skip_special_tokens=True)

    def finish_prompt(self, text, max_length, do_sample=False):
        inputs = self.tokenizer(text, return_tensors='pt')
        input_ids = inputs['input_ids'].to(self.model.device)
        with torch.no_grad():
            outputs = self.model(input_ids,
                                 max_length=max_length,
                                 pad_token_id=self.tokenizer.eos_token_id,
                                 do_sample=do_sample,
                                 top_p=0.95,
                                 top_k=50,
                                 num_return_sequences=1
                                 )

        return self.tokenizer.decode(outputs[0], skip_special_tokens=True)

    def forward(self, text, do_sample=False):
        inputs = self.tokenizer.encode(text, return_tensors="pt")
        inputs = inputs.to(self.model.device)
        with torch.no_grad():
            outputs = self.model(inputs, labels=inputs)
        return outputs

    def eval(self):
        self.model.eval()

    def cuda(self):
        self.model.cuda()

    def cpu(self):
        self.model.cpu()

    def save_pretrained(self, path):
        self.tokenizer.save_pretrained(path)
        self.model.save_pretrained(path)

    def load(self, path):
        self.tokenizer = AutoTokenizer.from_pretrained(path)
        self.model = AutoModelForCausalLM.from_pretrained(path)

    def get_tokenizer(self):
        return self.tokenizer

    def get_model(self):
        return self.model


