from tkinter import *
from tkinter import ttk
from PIL import ImageTk, Image

# Function to read the images in the image folder
def read_images():
    images = []
    for i in range(1, 16):
        img = Image.open("image/{}.png".format(i))
        img = img.resize((40, 40), Image.ANTIALIAS)  # resize the image to fit the labels
        img = ImageTk.PhotoImage(img)
        images.append(img)
    return images

# Function to display the images in the GUI
def display_images():
    global images
    global image_labels
    global current_img
    global current_img_label
    images = read_images()
    image_labels = []
    j = 0
    for i in range(5):
        for k in range(3):
            img_label = Label(root, image=images[j])
            img_label.grid(row=i, column=k)
            j += 1
            image_labels.append(img_label)
    current_img = 0
    current_img_label = image_labels[current_img]

# Function to change the displayed image
def change_image(direction):
    global current_img
    global current_img_label
    if direction == "next":
        current_img += 1
        if current_img >= len(image_labels):
            current_img = 0
    elif direction == "prev":
        current_img -= 1
        if current_img < 0:
            current_img = len(image_labels) - 1
    current_img_label = image_labels[current_img]
    current_img_label.grid(row=current_img // 3, column=current_img % 3)

# Create the main window
root = Tk()
root.title("Image Viewer")

# Create labels for the buttons
next_button = Button(root, text="Next", command=lambda: change_image("next"))
next_button.grid(row=5, column=2)

prev_button = Button(root, text="Previous", command=lambda: change_image("prev"))
prev_button.grid(row=5, column=0)

# Display the images in the GUI
display_images()

# Start the GUI event loop
root.mainloop()<|file_sep|><|fim_prefix|>/0097.py
class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        res = 0
        l = 0
        for r in range(len(nums)):
            if nums[r] == 0:
                k -= 1
            if k < 0:
                if nums[l] == 0:
                    k += 1
                l += 1
            res = max(res, r - l + 1)
        return res

