"""Utilities for managing PyTorch checkpoints."""
import contextlib
import fnmatch
import os
from typing import TYPE_CHECKING, Callable, Dict, Iterator, Optional, Tuple, TypeVar, Union

import torch
from torch import nn

from .configuration_utils import PretrainedConfig


if TYPE_CHECKING:
    import bitsandbytes as bnb


def _is_float_tensor(x):
    return isinstance(x, torch.Tensor) and x.dtype in (torch.float32, torch.float16, torch.bfloat16)


def _is_model_parallel(tensor):
    return isinstance(tensor, list) or isinstance(tensor, tuple)


def _is_bnb_8bit(tensor):
    return isinstance(tensor, bnb.nn.modules.linear.BnbLinear4bitLt)


def _is_bnb_4bit(tensor):
    return isinstance(tensor, bnb.nn.modules.linear.BnbLinear4bit)


def _get_bnb_4bit_quantile(tensor):
    assert _is_bnb_4bit(tensor)
    return tensor.quantiles


def _dispatch_8bit_tensor(tensor, params):
    if _is_bnb_8bit(tensor):
        tensor.dispatch(params["quantile"])
        return True
    return False


def _dispatch_quantized_4bit_tensor(tensor, params):
    if _is_bnb_4bit(tensor):
        tensor.dispatch(params["quantile"])
        return True
    return False


def _dispatch_tensor(tensor, params):
    if _is_model_parallel(tensor):
        return True
    if _is_float_tensor(tensor):
        tensor.dispatch(params["device"])
        return True
    return False


def _is_in_dispatch_queue(tensor):
    return tensor.dispatch is not None and tensor.dispatch.device is not None


@contextlib.contextmanager
def _clear_torch_modules(module):
    try:
        for attr in dir(module):
            value = getattr(module, attr)
            if isinstance(value, torch.nn.Module):
                setattr(module, attr, None)
        yield
    finally:
        for attr in dir(module):
            value = getattr(module, attr)
            if isinstance(value, torch.nn.Module):
                setattr(module, attr, value)


T = TypeVar("T")


def _retrieve_from_checkpoint(
    checkpoint_file: str, pattern: str, device: torch.device, convert_to_half: bool, model_class: Optional[Callable] = None
) -> Dict[str, T]:
    if model_class is not None:
        with _clear_torch_modules(model_class):
            return _retrieve_from_checkpoint(
                checkpoint_file, pattern, device, convert_to_half, model_class=model_class
            )
