from typing import Union

from fastapi import HTTPException
from pydantic import BaseModel, Field
from starlette.status import HTTP_400_BAD_REQUEST

from app import crud as crud
from app import schemas
from app.api import deps
from app.core.logger import TimedRoute
from app.core.security import get_password_hash
from app.utils import generate_password
from app.utils import send_email
from app.utils.user import get_user_model
from fastapi import APIRouter, Depends

router = APIRouter(route_class=TimedRoute)


class UserCreateModel(BaseModel):
    username: str = Field(..., min_length=3, max_length=32)
    email: str = Field(..., min_length=5, max_length=128)
    password: str = Field(..., min_length=8, max_length=128)

    class Config:
        orm_mode = True


class UserUpdateModel(BaseModel):
    username: Union[str, None] = Field(None, min_length=3, max_length=32)
    email: Union[str, None] = Field(None, min_length=5, max_length=128)
    password: Union[str, None] = Field(None, min_length=8, max_length=128)

    class Config:
        orm_mode = True


class UserPasswordResetModel(BaseModel):
    email: str = Field(..., min_length=5, max_length=128)

    class Config:
        orm_mode = True


@router.post("/users/", response_model=schemas.User, status_code=201)
def create_user(*, user_in: UserCreateModel, current_user: schemas.User = Depends(deps.get_current_user)) -> schemas.User:
    if crud.user.get_by_email(db=current_user.db, email=user_in.email):
        raise HTTPException(status_code=400, detail=f"Email already registered")
    created_user = crud.user.create(db=current_user.db, obj_in=user_in)
    try:
        send_email(
            email_to=user_in.email, subject=f"Welcome to Qwen {user_in.username}", email_template="email/welcome.html",
            username=user_in.username, password=user_in.password
        )
    except Exception as e:
        print(e)
    return created_user


@router.post("/users/reset-password", status_code=204)
def reset_user_password(*, user_in: UserPasswordResetModel) -> None:
    user = crud.user.get_by_email(db=deps.get_db(), email=user_in.email)
    if not user:
        raise HTTPException(status_code=400, detail=f"Email not registered")
    password = generate_password()
    hashed_password = get_password_hash(password)
    crud.user.update(db=deps.get_db(), db_obj=user, obj_in={"password": hashed_password})
    try:
        send_email(
            email_to=user_in.email, subject=f"Reset your password for Qwen", email_template="email/reset-password.html",
            username=user.username, password=password
        )
    except Exception as e:
        print(e)


@router.get("/users/", response_model=list[schemas.User])
def read_users(current_user: schemas.User = Depends(deps.get_current_user)):
    return current_user.db.query(get_user_model()).all()


@router.get("/users/me", response_model=schemas.User)
def read_current_user(current_user: schemas.User = Depends(deps.get_current_user)):
    return current_user


@router.get("/users/{user_id}", response_model=schemas.User)
def read_user(*, user_id: int, current_user: schemas.User = Depends(deps.get_current_user)):
    user = crud.user.get(db=current_user.db, id=user_id)
    if not user:
        raise HTTPException(status_code=404, detail=f"User {user_id} not found")
    return user


@router.patch("/users/{user_id}", response_model=schemas.User)
def update_user(
        *, user_id: int, user_in: UserUpdateModel, current_user: schemas.User = Depends(deps.get_current_user)
) -> schemas.User:
    user = crud.user.get(db=current_user.db, id=user_id)
    if not user:
        raise HTTPException(status_code=404, detail=f"User {user_id} not found")
    if crud.user.is_superuser(user) and not crud.user.is_superuser(current_user):
        raise HTTPException(
            status_code=400,
            detail="Only admin users can change other admin users",
        )
    if not crud.user.is_superuser(current_user) and user_in.username:
        if user.username != current_user.username:
            raise HTTPException(
                status_code=400,
                detail="Only admin users can change other users' usernames",
            )
    if user_in.password:
        if not user_in.password.startswith("$2y$"):
            user_in.password = get_password_hash(user_in.password)
    return crud.user.update(db=current_user.db, db_obj=user, obj_in=user_in)


@router.delete("/users/{user_id}", response_model=schemas.User)
def delete_user(
        *, user_id: int, current_user: schemas.User = Depends(deps.get_current_user)
) -> schemas.User:
    user = crud.user.get(db=current_user.db, id=user_id)
    if not user:
        raise HTTPException(status_code=404, detail=f"User {user_id} not found")
    if crud.user.is_superuser(user) and not crud.user.is_superuser(current_user):
        raise HTTPException(
            status_code=400,
            detail="Only admin users can delete other admin users",
        )
    return crud.user.remove(db=current_user.db, id=user_id)


