class WizardLocal(Wizard):
    def __init__(self, group_size=1, wizard_num=1):
        super().__init__(group_size, wizard_num)
        self.wizards = self.init_wizards()
        self.proxy = None

    def init_wizards(self):
        wizards = []
        for i in range(self.wizard_num):
            wizards.append(WizardLocal(i + 1, proxy=self.proxy))
        return wizards

