        if prefix is None:
            prefix = self.question_prefix
        question = prefix + question
        response = None
        try:
            response = requests.post(
                "http://127.0.0.1:8080/",
                json={"question": question, "answer": response},
                timeout=500,
                proxies=self.proxy,
            ).json()
