import React, {useEffect, useState} from 'react';
import {Modal, message} from 'antd';
import {useDispatch, useSelector} from 'react-redux';
import {getCampusCard} from "../../api/campus_card/getCampusCard";
import {setCampusCard} from "../../redux/action";

const CampusCard = () => {
  const dispatch = useDispatch();
  const campusCardInfo = useSelector(state => state.app.campus_card_info);
  const [campusCard, setCampusCard] = useState(null);

  useEffect(() => {
    if (campusCardInfo && campusCardInfo.card_id !== '') {
      setCampusCard(campusCardInfo);
    } else {
      getCampusCard().then((res) => {
        if (res.status === 200 && res.data.card_id !== '') {
          dispatch(setCampusCard(res.data));
          setCampusCard(res.data);
        }
      }).catch((err) => {
        message.error("校园卡信息获取失败");
        setCampusCard(null);
      });
    }
  }, []);

  const handleDelete = () => {
    Modal.confirm({
      title: '确认删除校园卡吗？',
      content: '删除校园卡后，将无法使用校园卡功能',
      okText: '确认',
      okType: 'danger',
      cancelText: '取消',
      onOk: () => {
        setCampusCard(null);
        dispatch(setCampusCard(null));
      }
    });
  };

  if (campusCard === null) {
    return <div className={'campus-card'}>
      <div className={'campus-card-title'}>校园卡</div>
      <div className={'campus-card-content'}>
        <div className={'campus-card-info'}>
          <div className={'campus-card-info-title'}>校园卡</div>
          <div className={'campus-card-info-content'}>校园卡未绑定</div>
        </div>
        <div className={'campus-card-action'}>
          <button className={'campus-card-action-button'} onClick={getCampusCard}>绑定校园卡</button>
        </div>
      </div>
    </div>;
  } else {
    const campusCardInfo = campusCard;
    return <div className={'campus-card'}>
      <div className={'campus-card-title'}>校园卡</div>
      <div className={'campus-card-content'}>
        <div className={'campus-card-info'}>
          <div className={'campus-card-info-title'}>校园卡</div>
          <div className={'campus-card-info-content'}>
            <div className={'campus-card-info-item'}>
              <div className={'campus-card-info-item-title'}>卡号</div>
              <div className={'campus-card-info-item-content'}>{campusCardInfo.card_id}</div>
            </div>
            <div className={'campus-card-info-item'}>
              <div className={'campus-card-info-item-title'}>余额</div>
              <div className={'campus-card-info-item-content'}>{campusCardInfo.balance}</div>
            </div>
          </div>
        </div>
        <div className={'campus-card-action'}>
          <button className={'campus-card-action-button'} onClick={handleDelete}>解绑校园卡</button>
        </div>
      </div>
    </div>;
  }
};

