import { ContractTerm } from '@app/models/contract';
import { Contract } from '@app/models/contract';
import { User } from '@app/models/user';
import { getTenantId } from '@app/utils/get-tenant-id';
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';

@Injectable()
export class ContractTermsService {
  constructor(
    @InjectModel('ContractTerm')
    private readonly contractTermModel: Model<ContractTerm>,
    @InjectModel('Contract')
    private readonly contractModel: Model<Contract>,
    @InjectModel('User')
    private readonly userModel: Model<User>,
  ) {}

  public async getContractTermById(id: string, user: User) {
    const tenantId = getTenantId(user);

    const contractTerm = await this.contractTermModel
      .findOne({ id, tenantId })
      .sort({ createdAt: -1 })
      .exec();

    const contract = await this.contractModel
      .findOne({ id: contractTerm.contractId, tenantId })
      .exec();

    const author = await this.userModel
      .findOne({ id: contractTerm.author, tenantId })
      .exec();

    const editor = await this.userModel
      .findOne({ id: contractTerm.editor, tenantId })
      .exec();

    if (!contractTerm) {
      throw new InternalServerErrorException(
        `Contract term with id ${id} not found`,
        'NOT_FOUND',
      );
    }

    return {
      ...contractTerm.toJSON(),
      contract,
      author,
      editor,
    };
  }

  public async getContractTermsByIds(
    contractId: string,
    user: User,
  ): Promise<ContractTerm[]> {
    const tenantId = getTenantId(user);

    const contractTerms = await this.contractTermModel
      .find({ contractId, tenantId })
      .sort({ createdAt: -1 })
      .exec();

    const contract = await this.contractModel
      .findOne({ id: contractId, tenantId })
      .exec();

    const author = await this.userModel
      .findOne({ id: contract.author, tenantId })
      .exec();

    const editor = await this.userModel
      .findOne({ id: contract.editor, tenantId })
      .exec();

    if (!contractTerms) {
      throw new InternalServerErrorException(
        `Contract terms with contractId ${contractId} not found`,
        'NOT_FOUND',
      );
    }

    return contractTerms.map((term) => ({
      ...term.toJSON(),
      contract,
      author,
      editor,
    }));
  }

  public async createContractTerm(
    contractId: string,
    text: string,
    user: User,
  ): Promise<ContractTerm> {
    const tenantId = getTenantId(user);

    const contractTerm = new this.contractTermModel({
      id: v4(),
      userId: user.id,
      contractId,
      text,
      author: user.id,
      editor: user.id,
    });

    const contract = await this.contractModel
      .findOne({ id: contractId, tenantId })
      .exec();

    const author = await this.userModel
      .findOne({ id: contract.author, tenantId })
      .exec();

    const editor = await this.userModel
      .findOne({ id: contract.editor, tenantId })
      .exec();

    if (!contract) {
      throw new InternalServerErrorException(
        `Contract with id ${contractId} not found`,
        'NOT_FOUND',
      );
    }

    await contractTerm.save();

    return {
      ...contractTerm.toJSON(),
      contract,
      author,
      editor,
    };
  }

  public async updateContractTerm(
    id: string,
    text: string,
    user: User,
  ): Promise<ContractTerm> {
    const tenantId = getTenantId(user);

    const contractTerm = await this.contractTermModel
      .findOne({ id, tenantId })
      .exec();

    const contract = await this.contractModel
      .findOne({ id: contractTerm.contractId, tenantId })
      .exec();

    const author = await this.userModel
      .findOne({ id: contract.author, tenantId })
      .exec();

    const editor = await this.userModel
      .findOne({ id: contract.editor, tenantId })
      .exec();

    if (!contractTerm) {
      throw new InternalServerErrorException(
        `Term with id ${id} not found`,
        'NOT_FOUND',
      );
    }

    contractTerm.text = text;
    contractTerm.editor = user.id;

    await contractTerm.save();

    return {
      ...contractTerm.toJSON(),
      contract,
      author,
      editor,
    };
  }

  public async deleteContractTerm(id: string, user: User): Promise<void> {
    const tenantId = getTenantId(user);

    const contractTerm = await this.contractTermModel
      .findOne({ id, tenantId })
      .exec();

    const contract = await this.contractModel
      .findOne({ id: contractTerm.contractId, tenantId })
      .exec();

    const author = await this.userModel
      .findOne({ id: contract.author, tenantId })
      .exec();

    const editor = await this.userModel
      .findOne({ id: contract.editor, tenantId })
      .exec();

    if (!contractTerm) {
      throw new InternalServerErrorException(
        `Contract term with id ${id} not found`,
        'NOT_FOUND',
      );
    }

    await this.contractTermModel.deleteOne({ id, tenantId }).exec();
  }
