#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// 用户结构体
typedef struct User {
    char username[50];
    char password[50];
} User;

// 用户登录函数
int loginUser(User *loggedInUser) {
    char inputUsername[50];
    char inputPassword[50];

    printf("请输入用户名：");
    scanf("%s", inputUsername);

    printf("请输入密码：");
    scanf("%s", inputPassword);

    // 模拟用户数据（实际应用中应从数据库中获取）
    User users[3] = {
        {"user1", "password1"},
        {"user2", "password2"},
        {"user3", "password3"}
    };

    for (int i = 0; i < 3; i++) {
        if (strcmp(users[i].username, inputUsername) == 0 &&
            strcmp(users[i].password, inputPassword) == 0) {
            printf("登录成功！\n");
            strcpy(loggedInUser->username, users[i].username);
            strcpy(loggedInUser->password, users[i].password);
            return 1; // 登录成功
        }
    }

    printf("用户名或密码错误，请重新登录。\n");
    return 0; // 登录失败
}

// 用户注册函数
int registerUser(User *loggedInUser) {
    char username[50];
    char password[50];

    printf("请输入用户名：");
    scanf("%s", username);

    printf("请输入密码：");
    scanf("%s", password);

    // 模拟用户数据（实际应用中应将新用户添加到数据库中）
    User newUser = {
        .username = username,
        .password = password
    };

    printf("恭喜您，注册成功！\n");
    strcpy(loggedInUser->username, newUser.username);
    strcpy(loggedInUser->password, newUser.password);
    return 1; // 注册成功
}

// 主函数
int main() {
    User loggedInUser = {"", ""};
    char choice;

    while (1) {
        printf("请选择操作：\n");
        printf("1. 登录\n");
        printf("2. 注册\n");
        printf("3. 退出\n");
        scanf(" %c", &choice);

        switch (choice) {
            case '1':
                if (loginUser(&loggedInUser)) {
                    // 登录成功后执行其他操作
                    printf("欢迎，%s！\n", loggedInUser.username);
                    // 在这里添加其他功能
                }
                break;
            case '2':
                if (registerUser(&loggedInUser)) {
                    // 注册成功后执行其他操作
                    printf("欢迎，%s！\n", loggedInUser.username);
                    // 在这里添加其他功能
                }
                break;
            case '3':
                printf("退出程序。\n");
                exit(0); // 退出程序
            default:
                printf("无效的选择，请重新选择。\n");
        }
    }

    return 0;
}







