// 发布帖子结构体
typedef struct Post {
    char title[100];
    char content[500];
    time_t timestamp;
} Post;

// 发布帖子函数
void publishPost(Post *posts, int *numPosts) {
    char title[100];
    char content[500];

    printf("请输入帖子标题：");
    scanf(" %[^\n]", title);

    printf("请输入帖子内容：");
    scanf(" %[^\n]", content);

    // 获取当前时间戳
    time_t currentTime = time(NULL);

    // 添加新帖子到数组中
    Post newPost = {
        .title = title,
        .content = content,
        .timestamp = currentTime
    };

    posts[*numPosts] = newPost;
    (*numPosts)++;

    printf("帖子发布成功！\n");
}

// 显示帖子列表函数
void displayPosts(Post *posts, int numPosts) {
    for (int i = numPosts - 1; i >= 0; i--) {
        printf("标题：%s\n", posts[i].title);
        printf("时间：%s", ctime(&posts[i].timestamp));
        printf("内容：%s\n", posts[i].content);
        printf("-----------------------------\n");
    }
}

// 主函数
int main() {
    User loggedInUser = {"", ""};
    Post posts[100];
    int numPosts = 0;

    char choice;

    while (1) {
        printf("请选择操作：\n");
        printf("1. 登录\n");
        printf("2. 注册\n");
        printf("3. 发布帖子\n");
        printf("4. 显示所有帖子\n");
        printf("5. 退出\n");
        scanf(" %c", &choice);

        switch (choice) {
            case '1':
                if (loginUser(&loggedInUser)) {
                    // 登录成功后执行其他操作
                    printf("欢迎，%s！\n", loggedInUser.username);
                    // 在这里添加其他功能
                }
                break;
            case '2':
                if (registerUser(&loggedInUser)) {
                    // 注册成功后执行其他操作
                    printf("欢迎，%s！\n", loggedInUser.username);
                    // 在这里添加其他功能
                }
                break;
            case '3':
                publishPost(posts, &numPosts);
                break;
            case '4':
                displayPosts(posts, numPosts);
                break;
            case '5':
                printf("退出程序。\n");
                exit(0); // 退出程序
            default:
                printf("无效的选择，请重新选择。\n");
        }
    }

    return 0;
}







