namespace ov = openvino;
namespace {

void WriteImages(const std::vector<std::vector<uint8_t>>& images,
                 const std::string& output_dir) {
  std::filesystem::path output_dir_path(output_dir);
  std::filesystem::create_directories(output_dir_path);

  const std::vector<std::string> image_names = {
      "qwen_7b_base.png", "qwen_7b_ref.png", "qwen_7b_diff.png"};

  CHECK_EQ(images.size(), image_names.size());

  for (size_t i = 0; i < images.size(); ++i) {
    const std::string image_name = image_names[i];
    const std::filesystem::path image_path = output_dir_path / image_name;
    std::ofstream image_file(image_path, std::ios::out | std::ios::binary);
    CHECK(image_file.is_open()) << "Failed to open image file: " << image_path;

    image_file.write(reinterpret_cast<const char*>(images[i].data()),
                     images[i].size());
    image_file.close();
  }
}

void WriteTexts(const std::vector<std::string>& texts,
                const std::string& output_dir) {
  const std::string text_file_path = output_dir + "/texts.txt";
  std::ofstream text_file(text_file_path);
  CHECK(text_file.is_open()) << "Failed to open text file: " << text_file_path;

  text_file << absl::StrJoin(texts, "\n");
  text_file.close();
}

std::unique_ptr<qwen::qwen_7b::Qwen7b> CreateModel(
    const std::string& model_path, const ov::AnyMap& config) {
  if (FLAGS_use_gpu) {
    return std::make_unique<qwen::qwen_7b::Qwen7bGpu>(
        model_path, FLAGS_max_batch_size, FLAGS_max_input_length,
        FLAGS_max_output_length, FLAGS_gpu_id, FLAGS_num_threads, config);
  } else {
    return std::make_unique<qwen::qwen_7b::Qwen7bCpu>(
        model_path, FLAGS_max_batch_size, FLAGS_max_input_length,
        FLAGS_max_output_length, FLAGS_num_threads, config);
  }
}

void LoadInputs(const std::string& input_txt, const std::string& input_json,
                std::vector<std::string>& prompts) {
  std::ifstream input_txt_file(input_txt);
  std::ifstream input_json_file(input_json);

  if (input_txt_file.is_open()) {
    std::string line;
    while (std::getline(input_txt_file, line)) {
      prompts.push_back(line);
    }
    input_txt_file.close();
  }

  if (input_json_file.is_open()) {
    std::string line;
    while (std::getline(input_json_file, line)) {
      std::string prompt;
      try {
        auto prompt_json = nlohmann::json::parse(line);
        prompt = prompt_json["prompt"];
      } catch (const nlohmann::json::exception& e) {
        LOG(ERROR) << "Failed to parse JSON line: " << line << " Error: "
                   << e.what();
        continue;
      }

      prompts.push_back(prompt);
    }
    input_json_file.close();
  }
}

void RunBenchmark(std::unique_ptr<qwen::qwen_7b::Qwen7b>& model) {
  const int num_iterations = 10;
  const std::string prompt = "Hello, world!";

  const auto start_time = std::chrono::high_resolution_clock::now();

  for (int i = 0; i < num_iterations; ++i) {
    model->Generate(prompt);
  }

  const auto end_time = std::chrono::high_resolution_clock::now();

  const auto duration =
      std::chrono::duration_cast<std::chrono::microseconds>(end_time -
                                                            start_time);

  const auto average_time =
      static_cast<float>(duration.count()) / num_iterations /

