import React, { useState } from 'react';
import { Button, Modal, Form, Input } from 'antd';

const PostForm = ({ visible, onClose, onCreate }) => {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);

  const handleCreate = () => {
    form
      .validateFields()
      .then((values) => {
        setLoading(true);
        onCreate(values, () => {
          form.resetFields();
          onClose();
          setLoading(false);
        });
      })
      .catch((error) => {
        console.error(error);
        setLoading(false);
      });
  };

  return (
    <Modal
      title="Create Post"
      visible={visible}
      onOk={handleCreate}
      onCancel={onClose}
      confirmLoading={loading}
    >
      <Form form={form} layout="vertical">
        <Form.Item
          label="Title"
          name="title"
          rules={[{ required: true, message: 'Please enter a title' }]}
        >
          <Input />
        </Form.Item>
        <Form.Item
          label="Content"
          name="content"
          rules={[{ required: true, message: 'Please enter content' }]}
        >
          <Input.TextArea rows={4} />
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default PostForm;<|file_sep|>/app/components/PageHeader.js
