import React from 'react'
import { Link, Route } from 'react-router-dom'
import { Button, Icon } from 'antd'
import UserList from './userManage/UserList'
import InviteUser from './userManage/InviteUser'
import RoleList from './userManage/RoleList'
import UserStateList from './userManage/UserStateList'
import '../../common/common.scss'
import styles from './styles/index.scss'
import './styles/index.scss'
import { routes } from '../../../config/routeConfig'
import { menu } from '../../../config/menuConfig'
import {
  getRoleList,
  getUserList,
  inviteUser,
  getToken,
  updateUserState,
} from '../../../api/admin'
import { MESSAGE } from '../../../utils/constant'

export default class UserManage extends React.Component {
  constructor(props) {
    super(props)
  }

  state = {
    roleList: [],
    userList: [],
    userTotal: 0,
    roleTotal: 0,
    userPage: 1,
    rolePage: 1,
    userPageSize: 10,
    rolePageSize: 10,
    loading: false,
  }

  componentDidMount() {
    this.getRoleList()
    this.getUserList()
  }

  getRoleList = () => {
    const { rolePageSize, rolePage } = this.state
    const params = { pageSize: rolePageSize, pageNum: rolePage }
    getRoleList(params).then((res) => {
      if (res.code === 200) {
        const list = res.data.list.map((item) => {
          if (item.id === 1) {
            item.name = '超级管理员'
          }
          return item
        })
        this.setState({
          roleList: list,
          roleTotal: res.data.total,
        })
      } else {
        this.setState({
          roleList: [],
          roleTotal: 0,
        })
      }
    })
  }

  getUserList = () => {
    const { userPageSize, userPage } = this.state
    const params = { pageSize: userPageSize, pageNum: userPage }
    getUserList(params).then((res) => {
      if (res.code === 200) {
        this.setState({
          userList: res.data.list,
          userTotal: res.data.total,
        })
      } else {
        this.setState({
          userList: [],
          userTotal: 0,
        })
      }
    })
  }

  handleInvite = (values) => {
    const params = {
      name: values.name,
      email: values.email,
      role: values.role,
      token: getToken(),
    }
    inviteUser(params).then((res) => {
      if (res.code === 200) {
        this.getUserList()
      } else {
        this.setState({ loading: false })
        this.props.showNotification({
          type: MESSAGE.ERROR,
          message: res.msg,
        })
      }
    })
  }

  handleUpdateUserState = (values, id) => {
    const params = {
      id: id,
      status: values.status,
    }
    updateUserState(params).then((res) => {
      if (res.code === 200) {
        this.getUserList()
      } else {
        this.props.showNotification({
          type: MESSAGE.ERROR,
          message: res.msg,
        })
      }
    })
  }

  render() {
    const {
      roleList,
      userList,
      roleTotal,
      userTotal,
      userPage,
      rolePage,
      userPageSize,
      rolePageSize,
      loading,
    } = this.state
    return (
      <div className={styles['body-container']}>
        <div className={styles['nav-container']}>
          {menu.map((item) => {
            return (
              <div
                className={styles['nav-item']}
                key={item.title}
                onClick={() => this.props.history.push(item.url)}
              >
                <Icon
                  className={styles['nav-item-icon']}
                  type={item.icon}
                  style={item.url === this.props.location.pathname ? { color: '#fff' } : {}}
                />
                <span className={styles['nav-item-text']}>{item.title}</span>
              </div>
            )
          })}
        </div>
        <div className={styles['main-container']}>
          <div className={styles['main-header']}>
            <div className={styles['main-title']}>用户管理</div>
            <div className={styles['nav-container']}>
              <Button
                type="primary"
                style={{ marginRight: 8 }}
                onClick={() => this.props.history.push(routes.userInvite.url)}
              >
                邀请用户
              </Button>
              <Button
                type="primary"
                onClick={() => this.props.history.push(routes.userRole.url)}
              >
                添加角色
              </Button>
            </div>
          </div>
          <div className={styles['main-content']}>
            <div className={styles['main-nav']}>
              <div
                className={styles['nav-item'] + ' ' + styles['nav-item-active']}
                onClick={() => this.props.history.push(routes.userManage.url)}
              >
                用户列表
              </div>
              <div
                className={styles['nav-item']}
                onClick={() => this.props.history.push(routes.userRole.url)}
              >
                角色列表
              </div>
              <div
                className={styles['nav-item']}
                onClick={() => this.props.history.push(routes.userState.url)}
              >
                用户状态
              </div>
            </div>
            <div className={styles['content-body']}>
              <div className={styles['tab-item'] + ' ' + styles['tab-item-active']}>
                用户列表
                <Link
                  to={routes.userInvite.url}
                  style={{ marginLeft: 20, fontSize: 14, color: '#2F54EB' }}
                >
                  邀请用户
                </Link>
              </div>
              <div className={styles['tab-item']}>
                <Link
                  to={routes.userRole.url}
                  style={{ marginLeft: 20, fontSize: 14, color: '#2F54EB' }}
                >
                  角色列表
                </Link>
                <Button type="primary" style={{ marginLeft: 20 }}>
                  添加角色
                </Button>
              </div>
              <div className={styles['tab-item']}>
                <Link
                  to={routes.userState.url}
                  style={{ marginLeft: 20, fontSize: 14, color: '#2F54EB' }}
                >
                  用户状态
                </Link>
              </div>
            </div>
            <div className={styles['user-list']}>
              <Route
                path={routes.userInvite.url}
                render={(props) => <InviteUser {...props} onSubmit={this.handleInvite} />}
              />
              <Route
                path={routes.userManage.url}
                render={(props) => (
                  <UserList
                    {...props}
                    userList={userList}
                    userTotal={userTotal}
                    userPage={userPage}
                    loading={loading}
                    roleList={roleList}
                    userPageSize={userPageSize}
                    rolePageSize={rolePageSize}
                    roleTotal={roleTotal}
                    userPageChange={(page) => {
                      this.setState({
                        userPage: page,
                      })
                      this.getUserList()
                    }}
                    userPageSizeChange={(pageSize) => {
                      this.setState({
                        userPageSize: pageSize,
                      })
                      this.getUserList()
                    }}
                    rolePageChange={(page) => {
                      this.setState({
                        rolePage: page,
                      })
                      this.getRoleList()
                    }}
                    rolePageSizeChange={(pageSize) => {
                      this.setState({
                        rolePageSize: pageSize,
                      })
                      this.getRoleList()
                    }}
                    roleList={roleList}
                    getUserList={this.getUserList}
                    roleList={roleList}
                    getRoleList={this.getRoleList}
                    updateUserState={this.handleUpdateUserState}
                  />
                )}
              />
              <Route
                path={routes.userRole.url}
                render={(props) => (
                  <RoleList {...props} roleList={roleList} getRoleList={this.getRoleList} />
                )}
              />
              <Route
                path={routes.userState.url}
                render={(props) => (
                  <UserStateList
                    {...props}
                    getUserList={this.getUserList}
                    userTotal={userTotal}
                    userPage={userPage}
                    userPageSize={userPageSize}
                    userPageChange={(page) => {
                      this.setState({
                        userPage: page,
                      })
                      this.getUserList()
                    }}
                    userPageSizeChange={(pageSize) => {
                      this.setState({
                        userPageSize: pageSize,
                      })
                      this.getUserList()
                    }}
                  />
                )}
              />
            </div>
          </div>
        </div>
      </div>
    )
  }
}

