package com.esoft.esoftservice.service.impl;

import com.esoft.esoftservice.entity.Tutor;
import com.esoft.esoftservice.mapper.TutorMapper;
import com.esoft.esoftservice.service.TutorService;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.esoft.esoftservice.util.MailUtil;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class TutorServiceImp extends ServiceImpl<TutorMapper, Tutor> implements TutorService {
    @Autowired
    private TutorMapper tutorMapper;
    @Autowired
    private MailUtil mailUtil;

    @Override
    public int add(Tutor tutor) {
        return tutorMapper.insert(tutor);
    }

    @Override
    public String verifyCode(String email, String code) {
        int result = tutorMapper.updateById(new Tutor().setEmail(email).setCode(code));
        if (result > 0) {
            return "注册成功！";
        } else {
            return "注册失败！";
        }
    }

    @Override
    public String send(String email) {
        String code = mailUtil.send(email, "软考认证服务注册", "您本次的验证码为：" + mailUtil.generateCode());
        tutorMapper.updateById(new Tutor().setEmail(email).setCode(code));
        return "发送成功！";
    }

    @Override
    public String login(String email, String password) {
        Tutor tutor = tutorMapper.selectOne(new Tutor().setEmail(email).setPassword(password));
        if (tutor != null) {
            return "登录成功！";
        } else {
            return "登录失败！";
        }
    }

