import os
import json
import pandas as pd
from django.shortcuts import render
from django.contrib.auth.decorators import login_required
from qa_bot_app.utils import (
    fetch_qa_data,
    filter_questions_by_answer_length,
    get_sorted_questions,
    generate_question_html,
    get_question_url,
    get_answer_url,
    get_random_question,
)
from qa_bot_app.models import Question, Answer


@login_required
def index(request):
    if request.method == "POST":
        data = json.loads(request.body)
        user_input = data.get("user_input", "").strip()
        user_input = user_input.strip('"')
        if not user_input:
            return render(request, "qa_bot_app/index.html")

        # Fetch questions and answers from the database
        questions = Question.objects.all()
        answers = Answer.objects.all()

        # Filter questions by answer length
        questions = filter_questions_by_answer_length(questions, answers, 500)

        # Generate question HTML
        question_html = generate_question_html(questions, answers)

        # Get the URL of the random question
        random_question = get_random_question(questions)
        random_question_url = get_question_url(random_question.id)

        # Get the URL of the first answer
        first_answer = get_sorted_questions(questions, random_question.id)[0]
        first_answer_url = get_answer_url(first_answer.id)

        context = {
            "question_html": question_html,
            "random_question_url": random_question_url,
            "first_answer_url": first_answer_url,
        }
        return render(request, "qa_bot_app/index.html", context)

    return render(request, "qa_bot_app/index.html")


