def sort_answers(question_id):
    try:
        question = Question.objects.get(id=question_id)
    except Question.DoesNotExist:
        return render(request, "qa_bot_app/question_not_found.html")

    answer_data = fetch_qa_data(question, question_id)
    if answer_data is None:
        return render(request, "qa_bot_app/question_not_found.html")

    # Sort answers by score or date, depending on the user's choice
    sorted_answers = get_sorted_questions(answer_data["questions"], question_id)
    sorted_answers = filter_questions_by_answer_length(
        sorted_answers, answer_data["answers"], 500
    )

    context = {"question": question, "answers": sorted_answers}

    return render(request, "qa_bot_app/sorted_answers_page.html", context)


@login_required
def sort_answers_page(request, question_id):
    if request.method == "POST":
        sort_by = request.POST.get("sort_by", "score")

        # Sort answers by score or date
        sorted_answers = sort_answers(question_id)

        context = {"question": sorted_answers["question"], "answers": sorted_answers["answers"]}
        return render(request, "qa_bot_app/sorted_answers_page.html", context)

    return render(request, "qa_bot_app/sorted_answers_page.html", {"question_id": question_id})


@login_required
def search(request):
    if request.method == "POST":
        search_query = request.POST.get("search_query", "").strip()
        if not search_query:
            return render(request, "qa_bot_app/index.html")

        # Fetch questions with the search query in their titles
        search_query = search_query.lower()
        questions = Question.objects.filter(title__icontains=search_query)
        if not questions:
            return render(request, "qa_bot_app/search_results.html", {"search_query": search_query})

        # Generate question HTML
        question_html = generate_question_html(questions, [])

        # Get the URL of the random question
        random_question = get_random_question(questions)
        random_question_url = get_question_url(random_question.id)

        # Get the URL of the first answer
        first_answer = get_sorted_questions(questions, random_question.id)[0]
        first_answer_url = get_answer_url(first_answer.id)

        context = {
            "question_html": question_html,
            "search_query": search_query,
            "random_question_url": random_question_url,
            "first_answer_url": first_answer_url,
        }
        return render(request, "qa_bot_app/search_results.html", context)

    return render(request, "qa_bot_app/search_results.html")


