const mutations = {
  SET_TOKEN: (state, token) => {
    state.token = token
  },
  SET_NAME: (state, name) => {
    state.name = name
  },
  SET_AVATAR: (state, avatar) => {
    state.avatar = avatar
  },
  SET_ROLES: (state, roles) => {
    state.roles = roles
  },
  SET_USER_INFO: (state, userInfo) => {
    state.userInfo = userInfo
    state.username = userInfo.username
    state.gender = userInfo.gender
    state.birthday = userInfo.birthday
    state.phone = userInfo.phone
    state.email = userInfo.email
    state.departmentId = userInfo.departmentId
    state.departmentName = userInfo.departmentName
    state.createTime = userInfo.createTime
    state.lastLoginIp = userInfo.lastLoginIp
    state.lastLoginTime = userInfo.lastLoginTime
    state.roleId = userInfo.roleId
    state.roleName = userInfo.roleName
    state.userId = userInfo.userId
    state.userStatus = userInfo.userStatus
    state.accessToken = userInfo.accessToken
  }
}

const actions = {
  // 登录
  login({commit}, userInfo) {
    const {username, password} = userInfo
    return new Promise((resolve, reject) => {
      login({username: username.trim(), password: password}).then(response => {
        const data = response.data
        const accessToken = data.token
        const refreshToken = data.refreshToken
        setToken(accessToken)
        commit('SET_TOKEN', accessToken)
        commit('SET_USER_INFO', data)
        resolve()
      }).catch(error => {
        reject(error)
      })
    })
  },

  // 获取用户信息

  // 获取用户信息
  getInfo({commit, state}) {
    return new Promise((resolve, reject) => {
      getInfo(state.token).then(response => {
        const data = response.data
        if (!data) {
          reject('Verification failed, please Login again.')
        }
        const {roles} = data

        // roles must be a non-empty array
        if (!roles || roles.length <= 0) {
          reject('getInfo: roles must be a non-empty array!')
        }
        const {name, avatar, roles} = data
        commit('SET_NAME', name)
        commit('SET_AVATAR', avatar)
        commit('SET_ROLES', roles)
        resolve(data)
      }).catch(error => {
        reject(error)
      })
    })
  },

  // 用户登出
  logout({commit, state}) {
    return new Promise((resolve, reject) => {
      removeToken() // must remove  token  first
      commit('SET_TOKEN', '')
      commit('SET_ROLES', [])
      resolve()
    })
  },
