package com.qwen.engine.service.impl;

import cn.hutool.core.util.StrUtil;
import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;
import com.qwen.engine.config.QwenConfig;
import com.qwen.engine.dto.QwenRequest;
import com.qwen.engine.dto.QwenResponse;
import com.qwen.engine.dto.QwenResponseContent;
import com.qwen.engine.model.Message;
import com.qwen.engine.service.QwenService;
import com.qwen.engine.service.UserService;
import com.qwen.engine.utils.HttpHelper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.URISyntaxException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@Service
@Slf4j
public class QwenServiceImpl implements QwenService {
    private final static String API_CHAT_URL = "https://api.qwen.chat/v1/chat";
    private final static String API_MODELS_URL = "https://api.qwen.chat/v1/models";

    @Autowired
    private UserService userService;

    @Autowired
    private QwenConfig qwenConfig;

    @Override
    public QwenResponseResponse chat(QwenRequest request) {
        JSONObject json = new JSONObject();
        json.put("model", request.getModel());
        json.put("messages", request.getMessages());
        json.put("stream", "true");
        json.put("top_p", request.getTop_p());

        JSONObject result = HttpHelper.post(API_CHAT_URL, json);
        QwenResponseContent content = new QwenResponseContent();
        content.setChoices(new ArrayList<>());
        Message message = new Message();
        message.setContent(result.getString("text"));
        message.setRole(Message.Role.ASSISTANT);
        content.getChoices().add(message);
        QwenResponseResponse response = new QwenResponseResponse();
        response.setResponse(content);
        return response;
    }

    @Override
    public List<String> listModels() {
        JSONObject json = HttpHelper.post(API_MODELS_URL, null);
        return json.getList("models", String.class);
    }

    @Override
    public QwenResponse chatWithUser(QwenRequest request) {
        JSONObject json = new JSONObject();
        json.put("model", request.getModel());
        json.put("messages", request.getMessages());
        json.put("stream", "false");
        json.put("top_p", request.getTop_p());

        JSONObject result = HttpHelper.post(API_CHAT_URL, json);
        QwenResponseContent content = new QwenResponseContent();
        content.setChoices(new ArrayList<>());
        Message message = new Message();
        message.setContent(result.getString("text"));
        message.setRole(Message.Role.ASSISTANT);
        content.getChoices().add(message);
        QwenResponse response = new QwenResponse();
        response.setResponse(content);
        return response;
    }

    @Override
    public String getRole(QwenRequest request) {
        Map<String, Object> map = userService.getUserInfo(request.getUserName());
        if (map == null || map.isEmpty()) {
            return "user";
        }
        String userRole = String.valueOf(map.get("role"));
        if (StrUtil.isEmpty(userRole)) {
            return "user";
        }
        return userRole;
    }

    @Override
    public JSONObject sendMessageToQwenEngine(QwenRequest request) {
        JSONObject json = new JSONObject();
        json.put("model", request.getModel());
        json.put("messages", request.getMessages());
        json.put("stream", "false");
        json.put("top_p", request.getTop_p());

        String userRole = getRole(request);
        if ("admin".equals(userRole)) {
            json.put("userRole", userRole);
        }

        JSONObject result = HttpHelper.post(API_CHAT_URL, json);
        return result;
    }

    @Override
    public String getResponseFromQwenEngine(QwenRequest request) {
        JSONObject json = new JSONObject();
        json.put("model", request.getModel());
        json.put("messages", request.getMessages());
        json.put("stream", "false");
        json.put("top_p", request.getTop_p());

        String userRole = getRole(request);
        if ("admin".equals(userRole)) {
            json.put("userRole", userRole);
        }

        JSONObject result = HttpHelper.post(API_CHAT_URL, json);
        return result.getString("text");
    }

    @Override
    public JSONObject getModels() {
        JSONObject json = HttpHelper.post(API_MODELS_URL, null);
        return json;
    }

    @Override
    public void setModels(List<String> models) {
        JSONObject json = new JSONObject();
        json.put("models", models);

        JSONObject result = HttpHelper.post(API_MODELS_URL, json);
    }

    @Override
    public void deleteModel(String model) {
        JSONObject json = new JSONObject();
        json.put("model", model);

        JSONObject result = HttpHelper.delete(API_MODELS_URL, json);
    }

    @Override
    public JSONObject getSingleModel(String model) {
        JSONObject json = new JSONObject();
        json.put("model", model);

        JSONObject result = HttpHelper.post(API_MODELS_URL, json);
        return result;
    }

    @Override
    public void deleteSingleModel(String model) {
        JSONObject json = new JSONObject();
        json.put("model", model);

