    encounters_user = EncountersUser.query.filter_by(user_id=user_id).all()
    for encounter_user in encounters_user:
        encounter_id = encounter_user.encounter_id
        encounter = Encounter.query.get(encounter_id)
        if encounter:
            category_encounters = CategoryEncounter.query.all()
            for category_encounter in category_encounters:
                category_id = category_encounter.category_id
                category = Category.query.get(category_id)
                if category and category.question_id == encounter.question_id:
                    score = category_encounter.score
                    total_score += score

    return total_score

