import { OpenAIStream, StreamingTextResponse } from 'ai'
import { Configuration, OpenAIApi } from 'openai-edge'
import { OpenAIStreamOptions } from 'openai-streams'
import { OpenAIModel } from '../../types/openai'

import { OPENAI_API_KEY, OPENAI_API_ORG, OPENAI_API_BASE_URL } from '@/env'
import { getChatMessage, logChatMessage } from '@/utils/chat'

export const runtime = 'edge'

export async function POST(request: Request) {
  try {
    const { model, messages, stop, temperature } = await request.json()

    if (!messages) {
      return new Response('No messages provided', { status: 400 })
    }

    const configuration = new Configuration({
      apiKey: OPENAI_API_KEY,
      organization: OPENAI_API_ORG,
      basePath: OPENAI_API_BASE_URL,
    })

    const openai = new OpenAIApi(configuration)

    const response = await openai.createChatCompletion({
      model: model.id as OpenAIModel,
      messages: messages.map((m) => getChatMessage(m)),
      stop,
      temperature,
    })

    if (!response.ok) {
      return new Response(
        `OpenAI API error: ${response.status} ${response.statusText}`,
        {
          status: 500,
        },
      )
    }

    const stream = OpenAIStream(response, {
      async onToken(token) {
        logChatMessage({
          token,
          role: 'assistant',
          model,
          messages,
          stop,
          temperature,
        })
      },
    } as OpenAIStreamOptions)

    return new StreamingTextResponse(stream)
  } catch (error) {
    console.error(error)
    return new Response('Internal Server Error', { status: 500 })
  }
}

export async function OPTIONS() {
  return new Response(null, {
    status: 204,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
    },
  })
}

// This handler is needed to avoid a Cloudflare bug that causes the serverless function to timeout
// when the user hits the back button after navigating to a page that uses this function.
// See https://github.com/vercel/next.js/issues/37838
export async function GET() {
  return new Response(null, {
    status: 204,
    headers: {
      'Access-Control-Al<|fim_suffix|>OPTIONS',
    },
  })
}
