import { OpenAIModel } from '@/types/openai'
import { ChatCompletionMessage } from 'openai-edge/dist/src/api/ChatCompletionMessage'
import { StreamingTextResponse } from 'ai'
import { OpenAIStream, OpenAIStreamOptions, OpenAIStreamResult } from 'openai-streams'

export async function getChatStream(
  model: OpenAIModel,
  messages: ChatCompletionMessage[],
  stop?: string | string[],
  temperature = 1,
): Promise<StreamingTextResponse> {
  const stream = OpenAIStream({
    model: model.id,
    messages,
    stop,
    temperature,
  } as OpenAIStreamOptions)

  const chunks = [] as Array<ChatCompletionMessage & { token: string }>

  for await (const result of stream) {
    if (typeof result === 'string') {
      chunks.push({ token: result, role: 'assistant', content: '' })
    } else if (result.status === 0) {
      chunks.push({
        token: result.choices[0].delta.content || '',
        role: 'assistant',
        content: '',
      })
    } else if (result.status === 1) {
      const chunk = result.choices[0].delta as OpenAIStreamResult
      const text = chunk.content || ''

      chunks.push({
        token: text,
        role: 'assistant',
        content: '',
      })
    }

    yield chunks.map((c) => ({ ...c, content: c.token })).join('')
  }
}
