import { OpenAIModel } from '@/types/openai'
import { useRouter } from 'next/router'
import { useState } from 'react'
import { useToast } from '../use-toast'

const useChat = () => {
  const router = useRouter()
  const { showToast } = useToast()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [messages, setMessages] = useState<ChatCompletionMessage[] | null>(null)

  const generate = async (
    model: OpenAIModel,
    prompt: string,
    options = {
      stop: '',
      temperature: 1,
    },
  ) => {
    setIsLoading(true)

    try {
      const response = await fetch('/api/chat/stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model,
          messages: [
            {
              role: 'system',
              content:
                'You are a helpful assistant. Answer as concisely as possible.',
            },
            {
              role: 'user',
              content: prompt,
            },
          ],
          ...options,
        }),
      })

      if (!response.ok) {
        throw new Error(`${response.status} ${response.statusText}`)
      }

      let data = ''
      const reader = response.body?.getReader()
      if (!reader) {
        throw new Error('No reader')
      }
      const decoder = new TextDecoder()

      while (true) {
        const { done, value } = await reader.read() // read() returns a promise
        if (done) {
          break
        }
        data += decoder.decode(value)
        setMessages((prev) => {
          if (!prev) {
            return null
          }
          return [...prev, { role: 'assistant', content: data }]
        })
        showToast({
          message: 'Response received',
          variant: 'success',
        })
      }
    } catch (error) {
      if (error instanceof Error) {
        setError(error.message)
        showToast({
          message: error.message,
          variant: 'error',
        })
      } else {
        setError('Unknown error')
        showToast({
          message: 'Unknown error',
          variant: 'error',
        })
      }
    } finally {
      setIsLoading(false)
    }
  }

  const getChat = async (
    model: OpenAIModel,
    messages: ChatCompletionMessage[],
    options = {
      stop: '',
      temperature: 1,
    },
  ) => {
    setIsLoading(true)

    try {
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model,
          messages,
          ...options,
        }),
      })

      if (!response.ok) {
        throw new Error(`${response.status} ${response.statusText}`)
      }

      const data = await response.json()
      setMessages((prev) => {
        if (!prev) {
          return null
        }
        return [...prev, ...data]
      })
      showToast({
        message: 'Response received',
        variant: 'success',
      })
    } catch (error) {
      if (error instanceof Error) {
        setError(error.message)
        showToast({
          message: error.message,
          variant: 'error',
        })
      } else {
        setError('Unknown error')
        showToast({
          message: 'Unknown error',
          variant: 'error',
        })
      }
    } finally {
      setIsLoading(false)
    }
  }

  return { isLoading, error, messages, generate, getChat }
}

export default useChat
