// The GarReaderBuilder is a builder class to build GarReader
class GarReaderBuilder {
 public:
  GarReaderBuilder() {}

  ~GarReaderBuilder() {}

  // Set the file system to read data from. If not set, the default file system
  // will be used.
  GarReaderBuilder& file_system(std::shared_ptr<io::FileSystem> file_system);

  // Set the file paths to read data from. If not set, the default file path
  // will be used.
  GarReaderBuilder& file_paths(std::vector<std::string> file_paths);

  // Build the GarReader with the given reader builder.
  Status Build(std::shared_ptr<reader::PropertyGraphReader>& reader);

 private:
  std::shared_ptr<io::FileSystem> file_system_;
  std::vector<std::string> file_paths_;
};

// The GarBuilder is a builder class to build Gar
class GarBuilder {
 public:
  GarBuilder() {}

  ~GarBuilder() {}

  // Set the schema of the graph to build. If not set, the default schema will
  // be used.
  GarBuilder& schema(std::shared_ptr<arrow::Schema> schema);

  // Set the property interface to the graph to build. If not set, the default
  // property interface will be used.
  GarBuilder& property_interface(
      std::shared_ptr<PropertyInterface> property_interface);

  // Set the file system to write data to. If not set, the default file system
  // will be used.
  GarBuilder& file_system(std::shared_ptr<io::FileSystem> file_system);

  // Set the file paths to write data to. If not set, the default file path
  // will be used.
  GarBuilder& file_paths(std::vector<std::string> file_paths);

  // Build the Gar with the given reader builder.
  Status Build(std::shared_ptr<PropertyGraph>& graph);

 private:
  std::shared_ptr<arrow::Schema> schema_;
  std::shared_ptr<PropertyInterface> property_interface_;
  std::shared_ptr<io::FileSystem> file_system_;
  std::vector<std::string> file_paths_;
};

// The PropertyGraph is a wrapper of a graph, which includes the schema, the
// property interface and the property graph.
class PropertyGraph {
 public:
  PropertyGraph() {}

  ~PropertyGraph() {}

  // Get the schema of the graph.
  std::shared_ptr<arrow::Schema> schema() const;

  // Get the property interface of the graph.
  std::shared_ptr<PropertyInterface> property_interface() const;

  // Get the property graph of the graph.
  std::shared_ptr<PropertyGraph> property_graph() const;

  // Get the file system to read data from.
  std::shared_ptr<io::FileSystem> file_system() const;

 private:
  friend class PropertyGraphBuilder;

  std::shared_ptr<arrow::Schema> schema_;
  std::shared_ptr<PropertyInterface> property_interface_;
  std::shared_ptr<PropertyGraph> property_graph_;
  std::shared_ptr<io::FileSystem> file_system_;
};

// The GarReader is a reader class to read Gar from file.
class PropertyGraphReader {
 public:
  PropertyGraphReader() {}

  ~PropertyGraphReader() {}

  // Read the schema of the graph.
  Status ReadSchema(std::shared_ptr<arrow::Schema>& schema);

  // Read the property interface of the graph. If not set, the default property
  // interface will be used.
  Status ReadPropertyInterface(std::shared_ptr<PropertyInterface>&
                                   property_interface);

  // Read the property graph of the graph.
  Status ReadPropertyGraph(std::shared_ptr<PropertyGraph>& property_graph);

  // Read the record batch by given schema and property interface.
  Status ReadRecordBatch(
      std::shared_ptr<arrow::Schema> schema,
      std::shared_ptr<PropertyInterface> property_interface,
      std::shared_ptr<arrow::RecordBatch>& record_batch);

  // Read the record batch by given schema and property interface.
  Status ReadRecordBatch(
      std::shared_ptr<arrow::Schema> schema,
      std::shared_ptr<PropertyInterface> property_interface,
      std::shared_ptr<reader::RecordBatchReader>& record_batch_reader);

  // Read the table by given schema and property interface.
  Status ReadTable(std::shared_ptr<arrow::Schema> schema,
                   std::shared_ptr<PropertyInterface> property_interface,
                   std::shared_ptr<arrow::Table>& table);

 private:
  friend class PropertyGraph;

  std::shared_ptr<connector::Connector> connector_;
};

// The GarBuilder is a builder class to build Gar
class PropertyGraphBuilder {
 public:
  PropertyGraphBuilder() {}

  ~PropertyGraphBuilder() {}

  // Set the page size of the graph to build. If not set, the default page size
  // will be used.
  PropertyGraphBuilder& page_size(int32_t page_size);

  // Set the page size of the graph to build. If not set, the default page size
  // will be used.
  PropertyGraphBuilder& append_mode(bool append_mode);

  // Set the file system to write data to. If not set, the default file system
  // will be used.
  PropertyGraphBuilder& file_system(std::shared_ptr<io::FileSystem> file_system);

  // Set the file paths to write data to. If not set, the default file path
  // will be used.
  PropertyGraphBuilder& file_paths(std::vector<std::string> file_paths);

  // Build the Gar with the given reader builder.
  Status Build(std::shared_ptr<PropertyGraph>& graph);

 private:
  std::shared_ptr<connector::Connector> connector_;
  int32_t page_size_ = 100000;
  bool append_mode_ = false;
  std::shared_ptr<io::FileSystem> file_system_;
  std::vector<std::string> file_paths_;
};

