import openai
import json
import os

openai.api_key = os.environ.get("OPENAI_API_KEY")

def is_hate_speech(text):
    response = openai.Completion.create(
        engine="text-davinci-002",
        prompt=f"Is the following text hate speech? If so, return the text that is hate speech. If not, return 'No hate speech': {text}",
        max_tokens=1024,
    )
    return response.choices[0].text.strip() != "No hate speech"

def censor(text):
    response = openai.Completion.create(
        engine="text-davinci-002",
        prompt=f"Redact any hate speech in the following text: {text}",
        max_tokens=1024,
    )
    return response.choices[0].text.strip()

def censor_text(text):
    # First, we check the text to ensure it does not violate our policy.
    if not is_hate_speech(text):
        return text

    # If it does violate our policy, we redact the hate speech.
    return censor(text)

def censor_if_necessary(text):
    # We start by checking the text to ensure it does not violate our policy.
    if not is_hate_speech(text):
        return text

    # If it does violate our policy, we redact the hate speech.
    return censor(text)

