#include <iostream>
#include <ctime>
#include <chrono>
#include <thread>
#include <fstream>
#include <string>
#include <cstring>
#include <cstdlib>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080

using namespace std;

void handle_client(int client_sock);
void parse_input(string input, string& action, string& dir);
void interpret_input(string action, string dir, int& x, int& y, int& z);
void validate_input(string action, string dir, int x, int y, int z);
void execute_move(int& x, int& y, int& z, string action, int& valid_moves);
void print_board(int x, int y, int z);
void save_board(int x, int y, int z);
void load_board(int& x, int y, int z);

int main() {
    // Initialize the socket
    int server_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (server_sock == -1) {
        cerr << "Error creating socket" << endl;
        return 1;
    }

    // Bind the socket to the specified port
    sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);
    if (bind(server_sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        cerr << "Error binding socket" << endl;
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_sock, 5) == -1) {
        cerr << "Error listening for connections" << endl;
        return 1;
    }

    cout << "Server listening on port " << PORT << endl;

    while (true) {
        // Accept incoming connections
        sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(server_sock, (struct sockaddr*)&client_addr, &client_len);
        if (client_sock == -1) {
            cerr << "Error accepting connection" << endl;
            continue;
        }

        cout << "Client connected" << endl;

        // Spawn a new thread to handle the client
        thread client_thread(handle_client, client_sock);
        client_thread.detach();
    }

    // Clean up
    close(server_sock);
    return 0;
}

void handle_client(int client_sock) {
    // Send a welcome message to the client
    string welcome_msg = "Welcome to the game!\n";
    send(client_sock, welcome_msg.c_str(), welcome_msg.size(), 0);

    // Set up the game board
    int x = 5;
    int y = 5;
    int z = 5;
    int valid_moves = 20;
    load_board(x, y, z);

    // Start the game loop
    string input;
    while (valid_moves > 0) {
        // Send the current state of the game to the client
        string board_state = "Current state of the game:\n";
        print_board(x, y, z);
        board_state += "Valid moves left: " + to_string(valid_moves) + "\n";
        send(client_sock, board_state.c_str(), board_state.size(), 0);

        // Receive input from the client
        char buf[1024];
        memset(buf, 0, sizeof(buf));
        int num_bytes = recv(client_sock, buf, sizeof(buf), 0);
        if (num_bytes == -1) {
            cerr << "Error receiving input from client" << endl;
            break;
        }
        input = buf;

        // Parse the input from the client
        string action, dir;
        parse_input(input, action, dir);

        // Interpret the input from the client
        int x_move, y_move, z_move;
        interpret_input(action, dir, x_move, y_move, z_move);

        // Validate the input from the client
        validate_input(action, dir, x_move, y_move, z_move);

        // Execute the move on the game board
        execute_move(x, y, z, action, valid_moves);

        // Save the current state of the game
        save_board(x, y, z);
    }

    // Send a final message to the client
    string end_msg = "Game over!\n";
    send(client_sock, end_msg.c_str(), end_msg.size(), 0);

    // Close the client socket
    close(client_sock);
}

void parse_input(string input, string& action, string& dir) {
    // Split the input string into an action and a direction
    size_t delim_pos = input.find(' ');
    if (delim_pos == string::npos) {
        action = input;
        dir = "";
    } else {
        action = input.substr(0, delim_pos);
        dir = input.substr(delim_pos+1);
    }
}

void interpret_input(string action, string dir, int& x, int& y, int& z) {
    // Interpret the direction based on the action
    if (action == "move") {
        if (dir == "up") {
            x++;
        } else if (dir == "down") {
            x--;
        } else if (dir == "left") {
            y--;
        } else if (dir == "right") {
            y++;
        } else if (dir == "in") {
            z++;
        } else if (dir == "out") {
            z--;
        }
    }
}

