 *         salary: 50000
 */

connect();

// Home routes
api.use('/home', home);

// swagger
api.use('/swagger', swaggerUi.serve, swaggerUi.setup(swaggerDocument));

// 404
api.use((_, res) => {
  res.status(404).send('The requested route does not exist');
});

// Error handling
api.use((err, _, res) => {
  const { message, code } = err;
  const status = code || 500;
  const messageToSend = message || 'Internal server error';
  res.status(status).json({ message: messageToSend });
});

