    public class ChatController : ControllerBase
    {
        private readonly ILogger<ChatController> _logger;
        private readonly IConfiguration _configuration;
        private readonly ChatHistoryContext _context;
        private bool _isRunning;
        private bool _isStopped;

        private Task _chatTask;
        private CancellationTokenSource _cancellationTokenSource;
        private CancellationToken _cancellationToken;

        private string _lastUserMessage;
        private bool _isCurrentUserMessage;
        private int _replyTime;
        private string _historyId;

        private bool _isGenerating;

        public ChatController(ILogger<ChatController> logger, IConfiguration configuration, ChatHistoryContext context)
        {
            _logger = logger;
            _configuration = configuration;
            _context = context;
        }

        [HttpPost("start")]
        public async Task<IActionResult> StartChat([FromBody] StartChatRequest request)
        {
            if (_isRunning)
            {
                return BadRequest("Chat is already running.");
            }

            _lastUserMessage = request.LastUserMessage;
            _isCurrentUserMessage = false;
            _replyTime = request.ReplyTime;
            _historyId = request.HistoryId;
            _isCurrentUserMessage = request.IsCurrentUserMessage;
            _cancellationTokenSource = new CancellationTokenSource();
            _cancellationToken = _cancellationTokenSource.Token;
            _isRunning = true;
            _isStopped = false;

            AddChatHistory(request.HistoryId, request.LastUserMessage, request.Prompt, "", DateTime.UtcNow, false, request.ReplyTime, "", true, null);

            _chatTask = Task.Run(async () =>
            {
                try
                {
                    await ChatAsync();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error in chat task.");
                    _isRunning = false;
                    _isStopped = false;
                }
            }, _cancellationToken);

            return Ok();
        }

        [HttpPost("stop")]
        public async Task<IActionResult> StopChat()
        {
            if (!_isRunning)
            {
                return BadRequest("Chat is not running.");
            }

            _cancellationTokenSource.Cancel();

            while (!_isStopped)
            {
                await Task.Delay(100);
            }

            _isRunning = false;

            return Ok();
        }

        private async Task ChatAsync()
        {
            try
            {
                while (true)
                {
                    _isStopped = false;

                    // Check if the user has stopped the chat
                    if (_cancellationToken.IsCancellationRequested)
