// 从指定的路径加载模型文件
void loadModel(const std::string& model_path, llama_context* ctx) {
    // 读取模型文件，并将其加载到内存中
    std::ifstream fin(model_path, std::ios::binary);

    // 判断是否成功打开文件
    if (!fin.is_open()) {
        throw std::runtime_error("Failed to open model file: " + model_path);
    }

    // 获取模型文件的大小
    fin.seekg(0, std::ios::end);
    size_t model_size = fin.tellg();
    fin.seekg(0, std::ios::beg);

    // 分配内存空间来存储模型数据
    std::vector<char> model_data(model_size);

    // 读取模型数据
    fin.read(model_data.data(), model_size);
    fin.close();

    // 将模型数据加载到模型上下文中
    llama_model_load_from_file(model_data.data(), model_data.size(), ctx);
}

// 创建一个用于生成文本的会话
llama_context* createSession(const std::string& model_path, int n_ctx, int n_threads) {
    // 创建一个上下文配置对象
    llama_context_params params;
    params.n_ctx = n_ctx;               // 设置上下文大小
    params.n_threads = n_threads;       // 设置多线程数

    // 创建上下文对象，用于处理模型和生成任务
    llama_context* ctx = llama_new_context_with_model_file(model_path.c_str(), params);

    // 检查上下文是否创建成功
    if (ctx == nullptr) {
        throw std::runtime_error("Failed to create llama context");
    }

    // 返回创建的上下文对象
    return ctx;
}

// 根据输入的上下文、模型和输入文本生成输出文本
std::string generateText(llama_context* ctx, const std::string& model_path, const std::string& input_text, int n_tokens) {
