void saveModel(const std::string& model_path, const std::string& model_data) {
    // 打开模型文件，以二进制写入模式
    std::ofstream fout(model_path, std::ios::binary);

    // 检查文件是否成功打开
    if (!fout.is_open()) {
        throw std::runtime_error("Failed to open model file: " + model_path);
    }

    // 将模型数据写入文件
    fout.write(model_data.c_str(), model_data.size());

    // 关闭文件
    fout.close();
}

