import { Tabs } from "antd";
import { CssBaseline } from "@mui/material";
import React from "react";
import ReactDOM from "react-dom";
import { app, AppContext } from "./context";
import { navbar } from "./navbar";
import { validateGenerationParameters, GenerationParameters } from "./components/Tab";
import { ImageGeneration } from "./components/ImageGeneration";
import { ModelCard } from "./components/ModelCard";

export type Tab = {
  title: string;
  subtitle: string;
  component: React.ReactElement;
};

export function registerTab(tab: Tab) {
  app.tabs.push(tab);
}

export function registerModelCard(modelCard: ModelCard) {
  app.modelCards.push(modelCard);
}

type Props = {
  title: string;
  subtitle: string;
  defaultOpen?: boolean;
};

export class Tab {
  title: string;
  subtitle: string;
  component: React.ReactElement;
  defaultOpen: boolean;
  key: string;

  constructor(tab: Props) {
    this.title = tab.title;
    this.subtitle = tab.subtitle;
    this.component = tab.component;
    this.defaultOpen = tab.defaultOpen || false;
    this.key = this.title.toLowerCase().replace(/\s+/g, "-");
  }

  open() {
    app.setState("tab", this.key);
  }
}

// A list of all the tabs that are currently registered.
export const tabs: Tab[] = [];

// A list of all the model cards that are currently registered.
export const modelCards: ModelCard[] = [];

export class ModelCard {
  title: string;
  subtitle: string;
  component: React.ReactElement;
  key: string;

  constructor(tab: Props) {
    this.title = tab.title;
    this.subtitle = tab.subtitle;
    this.component = tab.component;
    this.key = this.title.toLowerCase().replace(/\s+/g, "-");
  }
}

// A dictionary of all the tabs that are currently registered.
export const tabMap: { [key: string]: Tab } = {};

// A dictionary of all the model cards that are currently registered.
export const modelCardMap: { [key: string]: ModelCard } = {};

// A list of all the tabs that are currently open.
export const openTabs: Tab[] = [];

// A list of all the model cards that are currently open.
export const openModelCards: ModelCard[] = [];

// A dictionary of all the tabs that are currently open.
