# -*- coding: utf-8 -*-
from __future__ import absolute_import, print_function

import os
import re
import sys
import traceback
import logging
import json
import requests
import hashlib
from datetime import datetime
from multiprocessing import Process

from . import logger
from . import config
from . import compose
from . import utils
from . import agent
from . import handler


def main():
    agent.main()


def main_loop():
    from . import agent
    agent.main()


def thread_main_loop():
    p = Process(target=main_loop)
    p.start()
    p.join()


def thread_main():
    p = Process(target=main)
    p.start()
    p.join()


def generate_token():
    return hashlib.sha1(datetime.now().isoformat().encode()).hexdigest()


def touch():
    agent.touch()


def restart():
    import subprocess
    subprocess.call(["python", "-m", "qwen_agent.agent"])


def update():
    pass


def restart_handler():
    global handler
    handler = None
    thread_main_loop()


def update_handler():
    global handler
    thread_main()
    handler = None


def restart():
    thread_main_loop()


def update():
    thread_main()


def _check():
    logger.info("Check for update...")
    try:
        from . import package
        package.check_for_update()
    except:
        traceback.print_exc()


def check():
    _check()


def _check_loop():
    while True:
        try:
            logger.info("Check for update...")
            from . import package
            package.check_for_update()
            logger.info("Check for update... Done.")
        except:
            traceback.print_exc()

        logger.info("Sleep for 1 hour.")
        import time
        time.sleep(60 * 60)


def check_loop():
    while True:
        try:
            logger.info("Check for update...")
            from . import package
            package.check_for_update()
            logger.info("Check for update... Done.")
        except:
            traceback.print_exc()

        logger.info("Sleep for 1 hour.")
        import time
        time.sleep(60 * 60)


def _check_loop_thread():
    p = Process(target=check_loop)
    p.start()
    p.join()


def check_loop_thread():
    p = Process(target=_check_loop)
    p.start()
    p.join()


if __name__ == "__main__":
    sys.exit(main())
