def signal_handler(signum, frame):
    logger.info("Stop Qwen Agent...")
    logger.info("Exiting...")
    sys.exit(0)


def sigterm_handler(signum, frame):
    logger.info("Stop Qwen Agent (SIGTERM)...")
    logger.info("Exiting...")
    sys.exit(0)


def read_config():
    config_path = os.path.join(os.path.expanduser("~"), ".qwen_agent", "config.json")
    if os.path.exists(config_path):
        with open(config_path, "r", encoding="utf-8") as f:
            config_data = json.load(f)
            config_data = {k: v for k, v in config_data.items() if k in config.CONFIG}
            config.update(config_data)
    return config_path


def write_config(config_path):
    with open(config_path, "w", encoding="utf-8") as f:
        json.dump(config.CONFIG, f, indent=2, ensure_ascii=False)


def read_token():
    token_path = os.path.join(os.path.expanduser("~"), ".qwen_agent", "token.json")
    if os.path.exists(token_path):
        with open(token_path, "r", encoding="utf-8") as f:
            token_data = json.load(f)
            config.update(token_data)
    return token_path


def write_token(token_path):
    with open(token_path, "w", encoding="utf-8") as f:
        json.dump(config.CONFIG, f, indent=2, ensure_ascii=False)


def read_agent():
    agent_path = os.path.join(os.path.expanduser("~"), ".qwen_agent", "agent.json")
    if os.path.exists(agent_path):
        with open(agent_path, "r", encoding="utf-8") as f:
            agent_data = json.load(f)
            config.update(agent_data)
    return agent_path


def write_agent(agent_path):
    with open(agent_path, "w", encoding="utf-8") as f:
        json.dump(config.CONFIG, f, indent=2, ensure_ascii=False)


def read_handler():
    handler_path = os.path.join(os.path.expanduser("~"), ".qwen_agent", "handler.json")
    if os.path.exists(handler_path):
        with open(handler_path, "r", encoding="utf-8") as f:
            handler_data = json.load(f)
            config.update(handler_data)
    return handler_path


def write_handler(handler_path):
    with open(handler_path, "w", encoding="utf-8") as f:
        json.dump(config.CONFIG, f, indent=2, ensure_ascii=False)


def touch():
    logger.info("Touch %s" % config.CONFIG["agent_path"])
    try:
        if os.path.exists(config.CONFIG["agent_path"]):
            utils.touch(config.CONFIG["agent_path"])
        else:
            logger.info("Agent path not exists: %s" % config.CONFIG["agent_path"])
    except:
        logger.info("Touch failed.")


def update():
    logger.info("Update agent...")
    try:
        if os.path.exists(config.CONFIG["agent_path"]):
            utils.update_agent(config.CONFIG["agent_path"], config.CONFIG["qwen_url"])
        else:
            logger.info("Agent path not exists: %s" % config.CONFIG["agent_path"])
    except:
        logger.info("Update failed.")


def main():
    logger.info("Qwen Agent v%s" % __version__)
    package.check_for_update()

    signal.signal(signal.SIGTERM, sigterm_handler)
    signal.signal(signal.SIGINT, signal_handler)

    config_path = read_config()
    token_path = read_token()
    agent_path = read_agent()
    handler_path = read_handler()

    if config.CONFIG["debug"]:
        logger.setLevel(logging.DEBUG)

    logger.info("Config path: %s" % config_path)
    logger.info("Token path: %s" % token_path)
    logger.info("Agent path: %s" % agent_path)
    logger.info("Handler path: %s" % handler_path)

    if not os.path.exists(config.CONFIG["agent_path"]):
        logger.info("Agent path not exists: %s" % config.CONFIG["agent_path"])
        logger.info("Please run qwen_agent setup first.")
        sys.exit(1)

    if not os.path.exists(config.CONFIG["handler_path"]):
        logger.info("Handler path not exists: %s" % config.CONFIG["handler_path"])
        logger.info("Please run qwen_agent setup first.")
        sys.exit(1)

    # logger.info("Check for update...")
    # from . import package
    # package.check_for_update()

    # logger.info("Start agent...")
    # agent.main()

    logger.info("Start handler...")
    handler.main()


