package com.dustdawn.leetcode.medium.Graph;

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;

/**
 * @author dustdawn
 * @date 2019/10/18
 */
public class FindRedundantConnection {

    public static int[] findRedundantConnection(int[][] edges) {
        int[] parent = new int[edges.length + 1];
        Arrays.fill(parent, -1);

        for (int[] edge : edges) {
            int n1 = find(edge[0], parent);
            int n2 = find(edge[1], parent);

            if (n1 == n2) {
                return edge;
            } else {
                parent[n1] = n2;
            }
        }
        return null;
    }

    private static int find(int n, int[] parent) {
        if (parent[n] == -1) {
            return n;
        }
        return find(parent[n], parent);
    }

    public static void main(String[] args) {
        int[][] edges = new int[][]{
                {1, 2},
                {1, 3},
                {2, 3}
        };
    <|fim_suffix|>tem.out.println(Arrays.toString(findRedundantConnection(edges)));
    }
}
