public class NumWays {
    public int numWays(int n, int[] boards) {
        if (n == 0) {
            return 1;
        }
        Map<Integer, Integer> memo = new HashMap<>();
        memo.put(0, 1);
        for (int i = 0; i < n; i++) {
            Map<Integer, Integer> nextMemo = new HashMap<>();
            for (Integer target : memo.keySet()) {
                if (target + 1 >= 0 && target + 1 < boards.length) {
                    nextMemo.put(target + 1, memo.get(target));
                }
                if (target + boards[i] >= 0 && target + boards[i] < boards.length) {
                    nextMemo.put(target + boards[i], memo.get(target));
                }
            }
            memo = nextMemo;
        }
        return memo.get(boards.length - 1);
    }

    static class Solution {
        public int numWays(int target, int[] boards) {
            Map<Integer, Integer> memo = new HashMap<>();
            memo.put(0, 1);
            for (int i = 0; i < boards.length; i++) {
                for (Integer key : memo.keySet()) {
                    if (key + boards[i] >= 0 && key + boards[i] <= target) {
                        memo.put(key + boards[i], memo.get(key) + 1);
                    }
                }
            }
            return memo.get(target);
        }
