package com.alibaba.qiuzhi.util;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;

/**
 * @author Qwen
 * @date 2022/10/13 14:35
 */
public class DateUtil {
    public static String getNowDateStr() {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        return simpleDateFormat.format(new Date());
    }

    public static String getNowDateStr(String format) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        return simpleDateFormat.format(new Date());
    }

    public static long diff(String start, String end, String format) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        try {
            Date startTime = simpleDateFormat.parse(start);
            Date endTime = simpleDateFormat.parse(end);
            return endTime.getTime() - startTime.getTime();
        } catch (ParseException e) {
            e.printStackTrace();
        }
        return -1;
    }

    public static String dateToString(Date date, String format) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        return simpleDateFormat.format(date);
    }

    public static Date addDate(Date date, int type, int amount) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        calendar.add(type, amount);
        return calendar.getTime();
    }

    public static boolean pastDue(String dueDateStr, String format) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        try {
            Date nowDate = simpleDateFormat.parse(getNowDateStr(format));
            Date dueDate = simpleDateFormat.parse(dueDateStr);
            return nowDate.after(dueDate);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        return false;
    }

    public static long diff(String start, String end, String format, int type) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        try {
            Date startTime = simpleDateFormat.parse(start);
            Date endTime = simpleDateFormat.parse(end);
            if (type == Calendar.DAY_OF_YEAR) {
                return (endTime.getTime() - startTime.getTime()) / (1000 * 60 * 60 * 24);
            } else if (type == Calendar.MONTH) {
                return (endTime.getTime() - startTime.getTime()) / (1000 * 60 * 60 * 24 * 30);
            } else if (type == Calendar.YEAR) {
                return (endTime.getTime() - startTime.getTime()) / (1000 * 60 * 60 * 24 * 365);
            }
        } catch (ParseException e) {
            e.printStackTrace();
        }
        return -1;
    }

    public static String getBeforeOrAfterDateStr(String dateStr, int type, int amount, String format) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        try {
            Date date = simpleDateFormat.parse(dateStr);
            return dateToString(DateUtil.addDate(date, type, amount), format);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        return null;
    }

    public static int getBeforeOrAfterDateStr(String dateStr, String format, int type) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        try {
            Date date = simpleDateFormat.parse(dateStr);
            return (int) (DateUtil.getBeforeOrAfterDateStr(simpleDateFormat.format(date), type, 1, format).length() - 1);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        return -1;
    }

    public static boolean validate(String dateStr, String format) {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(format);
        try {
            simpleDateFormat.parse(dateStr);
