import Vue from 'vue'
import Router from 'vue-router'
// import store from '@/store'
import { getToken } from '@/utils/auth'
import { Message } from 'element-ui'
import { getRoutes } from '@/api/permission'
Vue.use(Router)

const router = new Router({
  mode: 'history',
  base: process.env.BASE_URL,
  routes: [
    {
      path: '/login',
      name: 'Login',
      component: () => import('@/views/sys/login/login')
    },
    {
      path: '/404',
      component: () => import('@/views/sys/errorpage/404')
    },
    {
      path: '/401',
      component: () => import('@/views/sys/errorpage/401')
    },
    {
      path: '/',
      component: () => import('@/views/layout/Layout'),
      redirect: '/dashboard',
      children: [
        {
          path: 'dashboard',
          name: 'Dashboard',
          component: () => import('@/views/sys/dashboard/index')
        }
      ]
    },
    {
      path: '/404',
      component: () => import('@/views/sys/errorpage/404')
    }
  ],
  scrollBehavior: () => ({ y: 0 })
})

router.beforeEach((to, from, next) => {
  // 获取token
  const token = getToken()
  if (token) {
    // 用户已经登录
    if (to.path === '/login') {
      next({ path: '/' })
    } else {
      // 判断是否获取菜单
      if (store.getters.menus.length === 0) {
        getRoutes().then(res => {
          if (res && res.code === 200) {
            const routes = res.data.routes
            // 生成菜单
            store.dispatch('permission/generateRoutes', routes).then(() => {
              router.addRoutes(routes)
              next({ ...to, replace: true })
            })
          } else {
            Message.error(res.msg || '服务器错误')
            store.dispatch('user/logout')
            next('/login')
          }
        })
      } else {
        next()
      }
    }
  } else {
    // 用户未登录
    if (to.path === '/login') {
      next()
    } else {
      next('/login')
    }
  }
})

router.afterEach(() => {
  // router.push({ path: to.fullPath })
})

export default router

