class ThreadManager():
    def __init__(self):
        self.queue = queue.Queue()
        self.pool = multiprocessing.Pool(2)
        self.results = {}

    def add_task(self, url, token):
        self.queue.put((url, token))

    def run(self):
        def worker():
            while True:
                url, token = self.queue.get()
                try:
                    img = requests.get(url, headers={'Authorization': token}).content
                    self.results[url] = img
                except Exception as e:
                    logger.error(e)
                    self.results[url] = None
                finally:
                    self.queue.task_done()

        for _ in range(2):
            self.pool.apply_async(worker)

        self.queue.join()


thread_manager = ThreadManager()


def get_img(url, token):
    if url not in thread_manager.results:
        thread_manager.add_task(url, token)
    return thread_manager.results.get(url, None)


def get(img):
    if img:
        return {'img': img}
    return {'img': None}


