﻿using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Threading.Tasks;
using ChatGPT.Models;
using ChatGPT.Models.Request;
using Newtonsoft.Json;

namespace ChatGPT
{
    public class ChatGPTModel
    {
        private readonly string _apiKey;
        private readonly string _host;
        private readonly string _model;

        public ChatGPTModel(string apiKey, string host, string model)
        {
            _apiKey = apiKey;
            _host = host;
            _model = model;
        }

        public async Task<string> GetChatResponse(ChatGPTRequest request)
        {
            string response;
            try
            {
                using (var client = new HttpClient())
                {
                    client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);

                    request.Model = _model;

                    var content = new StringContent(JsonConvert.SerializeObject(request), Encoding.UTF8, "application/json");
                    var responseMessage = await client.PostAsync($"{_host}/v1/chat/completions", content);

                    if (responseMessage.IsSuccessStatusCode)
                    {
                        var responseString = await responseMessage.Content.ReadAsStringAsync();
                        response = responseString;
                    }
                    else
                    {
                        response = await responseMessage.Content.ReadAsStringAsync();
                    }
                }
            }
            catch (Exception ex)
            {
                response = ex.Message;
            }

            return response;
        }
    }

    public class ChatGPTModelSingleton
    {
        private static readonly Lazy<ChatGPTModel> _instance = new Lazy<ChatGPTModel>(() =>
        {
            var apiKey = Environment.GetEnvironmentVariable("CHATGPT_API_KEY");
            var host = Environment.GetEnvironmentVariable("CHATGPT_HOST");
            var model = Environment.GetEnvironmentVariable("CHATGPT_MODEL");
            return new ChatGPTModel(apiKey, host, model);
        });

        public static ChatGPTModel Instance => _instance.Value;
    }

    public class ChatGPTClient
    {
        public async Task<string> GetChatResponse(ChatGPTRequest request)
        {
            return await ChatGPTModelSingleton.Instance.GetChatResponse(request);
        }
    }
}
