import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { setCourse } from "../../redux/courseSlice";
import { setStudentId } from "../../redux/studentIdSlice";

const CourseSelection = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const courseId = useSelector((state) => state.course.courseId);
  const studentId = useSelector((state) => state.studentId.studentId);
  const [courseData, setCourseData] = useState([]);

  useEffect(() => {
    const fetchCourseData = async () => {
      try {
        const response = await axios.get("https://www.satisy.com/api/course");

        setCourseData(response.data);
      } catch (error) {
        console.error("Error fetching course data:", error);
      }
    };

    fetchCourseData();
  }, []);

  const handleRegistration = (courseId) => {
    // send a POST request to the server to register the student for the selected course
    axios
      .post("https://www.satisy.com/api/course/register", {
        courseId,
        studentId,
      })
      .then((response) => {
        // update the course state with the selected course data
        dispatch(setCourse(response.data));

        // redirect the student to the course page
        navigate(`/course/${courseId}`);
      })
      .catch((error) => {
        console.error(error);
      });
  };

  return (
    <div className="course-selection">
      <h1>Select a Course</h1>
      <ul>
        {courseData.map((course) => (
          <li key={course.id}>
            <button onClick={() => handleRegistration(course.id)}>
              {course.description}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default CourseSelection;
