import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { setStudentId } from "../../redux/studentIdSlice";

const CourseRegistration = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const studentId = useSelector((state) => state.studentId.studentId);
  const [courseId, setCourseId] = useState("");

  const handleRegistration = () => {
    // send a POST request to the server to register the student for the selected course
    axios
      .post("https://www.satisy.com/api/course/register", {
        courseId,
        studentId,
      })
      .then((response) => {
        // redirect the student to the course page
        navigate(`/course/${courseId}`);
      })
      .catch((error) => {
        console.error(error);
      });
  };

  return (
    <div className="course-registration">
      <h1>Course Registration</h1>
      <input
        type="text"
        placeholder="Enter course ID"
        value={courseId}
        onChange={(event) => setCourseId(event.target.value)}
      />
      <button onClick={handleRegistration}>Register</button>
    </div>
  );
};

export default CourseRegistration;
