#!/bin/bash

export PATH=$(pwd):${PATH}

function check_env {
    env_file=".env"
    if [ -f "$env_file" ]; then
        echo "Loading environment variables from $env_file"
        export $(cat $env_file | grep -v '^#' | xargs)
    else
        echo "No $env_file found. Please set the following environment variables:"
        echo "OPENAI_API_KEY, OPENAI_API_BASE, QWEN_API_KEY, QWEN_API_BASE"
        exit 1
    fi
}

function check_python_version {
    python_version=$(python3 --version 2>&1 || python --version 2>&1)
    if [[ $python_version == *"Python 3"* ]]; then
        echo "Python 3 is installed"
    else
        echo "Python 3 is not installed. Please install Python 3."
        exit 1
    fi
}

function check_python_packages {
    echo "Checking Python packages..."
    python3 -m pip install -r requirements.txt
}

function get_script_dir {
    SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
    SCRIPT_DIR=$(readlink -f "$SCRIPT_DIR")
    echo $SCRIPT_DIR
}

function set_faiss_path {
    FAISS_PATH=$(which faiss)
    if [ -z "$FAISS_PATH" ]; then
        FAISS_PATH=$(which libfaiss.so)
    fi
    if [ -z "$FAISS_PATH" ]; then
        echo "Faiss not found. Please install faiss."
        exit 1
    fi
    export FAISS_PATH
}

