"""This is a script for training on Qwen pretrain task."""
import os
import torch
from vega.core.common import hyper_parameter
from vega.modules.common import ClassFactory, ClassType
from vega.modules.operators import *
from vega.modules.module import Module
from vega.models.qwen_config import QwenConfig
from vega.core.pipeline.hyper_parameter import HyperParameter
from vega.search_space.common import Parameter
from vega.search_space.networks import Network
from vega.search_space.networks.mutables import MutableScope
from vega.common import ClassFactory, ClassType
from vega.common.class_factory import ClassType, ClassFactory
from vega.common import Config

# import model
from vega.models.qwen7b import Qwen7B
from vega.models.qwen7b import Qwen7BForCausalLM
from vega.models.qwen7b import QwenModel


@ClassFactory.register(ClassType.NETWORK)
class QwenPretrain(MutableScope, Module):
    """QwenPretrain class."""

    def __init__(self, search_space, **kwargs):
        """Initialize QwenPretrain class."""
        super(QwenPretrain, self).__init__(search_space, **kwargs)
        self.qwen_config = QwenConfig.from_pretrained('qwen-7b')
        self.qwen = Qwen7BForCausalLM(self.qwen_config)

    def forward(self, input_ids, attention_mask, labels=None, **kwargs):
        """Forward function of QwenPretrain."""
        if labels is not None:
            # shift logits and labels to the right so that the logits at position i are
            # computing for the token at position i + 1, which is the left context for
            # position i.
            shift_logits = self.qwen(input_ids, attention_mask)[0].contiguous().float()
            shift_labels = labels[..., 1:].contiguous()
            loss = torch.nn.functional.cross_entropy(
                shift_logits.view(-1, shift_logits.size(-1)), shift_labels.view(-1), ignore_index=self.qwen.config.pad_token_id
            )
            return loss
        else:
            return self.qwen(input_ids, attention_mask)[0]

    def get_search_space(self, **kwargs):
        """Get search space for QwenPretrain."""
        return self.qwen.get_search_space()

    def get_config(self):
