namespace {
bool use_unbuffered_io = false;
#ifdef _WIN32
#include <windows.h>
void set_unbuffered_io(bool enable) {
    if (enable) {
        // Set stdout to binary mode
        HANDLE hstdout = GetStdHandle(STD_OUTPUT_HANDLE);
        DWORD mode = 0;
        if (!GetConsoleMode(hstdout, &mode)) {
            return;
        }
        SetConsoleMode(hstdout, mode & (~ENABLE_PROCESSED_OUTPUT));
    } else {
        // Set stdout to cooked mode
        HANDLE hstdout = GetStdHandle(STD_OUTPUT_HANDLE);
        DWORD mode = 0;
        if (!GetConsoleMode(hstdout, &mode)) {
            return;
        }
        SetConsoleMode(hstdout, mode | ENABLE_PROCESSED_OUTPUT);
    }
}
#else
#include <fcntl.h>
#include <unistd.h>
void set_unbuffered_io(bool enable) {
    if (enable) {
        // Set stdout to binary mode
        int flags = fcntl(STDOUT_FILENO, F_GETFL, 0);
        if (!(flags & O_BINARY)) {
            fcntl(STDOUT_FILENO, F_SETFL, flags | O_BINARY);
        }
    } else {
        // Set stdout to cooked mode
        int flags = fcntl(STDOUT_FILENO, F_GETFL, 0);
        if (flags & O_BINARY) {
            fcntl(STDOUT_FILENO, F_SETFL, flags & (~O_BINARY));
        }
    }
}
#endif
}

