import torch
import torch.nn as nn

from ...generation import GenerationMixin
from ...models import BaseTransformerModel
from ...utils import LazyImporter


class LlamaModel(BaseTransformerModel, GenerationMixin):
    def __init__(self, config, model):
        super().__init__(config)
        self.model = model

    def forward(self, input_ids, attention_mask=None, **kwargs):
        outputs = self.model(input_ids, attention_mask=attention_mask, **kwargs)
        return outputs.logits

    def generate(self, input_ids, attention_mask=None, **kwargs):
        return self.model.generate(input_ids, attention_mask=attention_mask, **kwargs)


class LlamaForCausalLM(LlamaModel, nn.Module):
    @staticmethod
    def from_pretrained(pretrained_model_name_or_path, *model_args, **kwargs):
        tokenizer = LazyImporter("transformers", "LlamaTokenizer").from_pretrained(
            pretrained_model_name_or_path, *model_args, **kwargs
        )
        model = LazyImporter("transformers", "LlamaForCausalLM").from_pretrained(
            pretrained_model_name_or_path, *model_args, **kwargs
        )
        return LlamaForCausalLM(model.config, model=model)

    @staticmethod
    def from_config(config):
        tokenizer = LazyImporter("transformers", "LlamaTokenizer").from_pretrained(
            "decapoda-research/llama-7b-hf"
        )
        model = LazyImporter("transformers", "LlamaForCausalLM").from_config(
            config, model_type="LlamaForCausalLM"
        )
        return LlamaForCausalLM(model.config, model=model)

    def get_decoder(self):
        return self.model.get_decoder()

    def prepare_inputs_for_generation(self, input_ids, **kwargs):
        return self.model._prepare_decoder_inputs(input_ids, **kwargs)

    def _prepare_decoder_inputs(self, input_ids, **kwargs):
        if "attention_mask" in kwargs:
            return self.model._prepare_decoder_inputs(
                input_ids=input_ids, attention_mask=kwargs["attention_mask"]
            )
        return self.model._prepare_decoder_inputs(input_ids=input_ids)

    def _reorder_cache(self, cache, beam_idx):
        return self.model._reorder_cache(cache, beam_idx)

    def _reorder_cache_for_beam(self, cache, beam_idx):
        return self.model._reorder_cache(cache, beam_idx)

    def _reorder_cache_for_sampling(self, cache, beam_idx):
        return self.model._reorder_cache(cache, beam_idx)

    def _prepare_attention_mask(self, attention_mask):
        return self.model._prepare_decoder_attention_mask(attention_mask)


