import json
import re
from functools import lru_cache
from pathlib import Path
from typing import Optional, Tuple, Union
from urllib.request import urlopen

import torch
import torch.nn.functional as F
import transformers
from torch import nn


def token_logits_to_logprobs(token_logits: torch.Tensor, tokenizer: transformers.PreTrainedTokenizer) -> torch.Tensor:
    logits = torch.zeros_like(token_logits)
    for j in range(token_logits.shape[1]):
        logits[:, j] = F.log_softmax(token_logits[:, j], dim=-1)
    return logits


class VllmTransformerModel(nn.Module):
    def __init__(self, config, model):
        super().__init__()
        self.config = config
        self.model = model

    def forward(self, input_ids: torch.Tensor, attention_mask: Optional[torch.Tensor] = None, **kwargs):
        if attention_mask is None:
            attention_mask = torch.ones_like(input_ids, dtype=torch.int32)
        transformer_outputs = self.model(
            input_ids=input_ids, attention_mask=attention_mask, return_dict=True, **kwargs
        )
        return transformer_outputs.logits


class VllmModel(VllmTransformerModel):
    def __init__(self, config, model):
        super().__init__(config, model)

    def forward(self, input_ids: torch.Tensor, attention_mask: Optional[torch.Tensor] = None, **kwargs):
        return super().forward(input_ids, attention_mask, **kwargs)


class VllmForCausalLM(VllmTransformerModel):
    @staticmethod
    def from_pretrained(
        pretrained_model_name_or_path: Union[str, Path], cache_dir: Optional[Union[str, Path]] = None, **kwargs
    ):
        if "model_name_or_path" in kwargs:
            model_name_or_path = kwargs.pop("model_name_or_path")
        else:
            model_name_or_path = pretrained_model_name_or_path

        if isinstance(model_name_or_path, Path):
            model_name_or_path = str(model_name_or_path.absolute())

        if isinstance(model_name_or_path, str):
            model_name_or_path = model_name_or_path.strip()

        if not model_name_or_path.startswith("http"):
            model_name_or_path = Path(model_name_or_path).absolute()

        model_config = VllmModelConfig.from_pretrained(model_name_or_path, cache_dir=cache_dir, **kwargs)
        tokenizer = VllmTokenizer.from_pretrained(model_name_or_path, cache_dir=cache_dir, **kwargs)

        return VllmForCausalLM.from_config(model_config, tokenizer=tokenizer)

    @classmethod
    def from_config(cls, config: "VllmModelConfig", **kwargs) -> "VllmForCausalLM":
        transformers_model_name = config.model_name
        if transformers_model_name not in ["gpt2", "gpt2-medium", "gpt2-large", "gpt2-xl", "opt-125m"]:
            raise ValueError(
                f"Currently, only GPT2 and OPT models are supported, but got {transformers_model_name}. "
                "You can set `model_name_or_path` to `gpt2`, `gpt2-medium`, `gpt2-large`, `gpt2-xl`, or `opt-125m`."
            )

        if transformers_model_name in ["gpt2", "gpt2-medium", "gpt2-large", "gpt2-xl"]:
            transformer_model_name = "gpt2"
        else:
            transformer_model_name = "opt"

        tokenizer = transformers.AutoTokenizer.from_pretrained(transformer_model_name, use_fast=True)
        model = transformers.AutoModelForCausalLM.from_pretrained(transformer_model_name)
        model.resize_token_embeddings(len(tokenizer))

        for name, param in model.named_parameters():
            if "layers" in name:
                param.requires_grad = False

        return cls(config, model)

    def generate(
        self, input_ids: torch.Tensor, attention_mask: Union[torch.Tensor, None] = None, **kwargs
    ) -> torch.Tensor:
        if attention_mask is None:
            attention_mask = torch.ones_like(input_ids, dtype=torch.int32)
        return self.model.generate(input_ids=input_ids, attention_mask=attention_mask, **kwargs)

    def get_decoder(self):
        return self.model.get_decoder()

    def prepare_inputs_for_generation(
        self, input_ids: torch.Tensor, attention_mask: Union[torch.Tensor, None] = None, **kwargs
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        if attention_mask is None:
            attention_mask = torch.ones_like(input_ids, dtype=torch.int32)
        return input_ids, attention_mask

    def _reorder_cache(self, cache, beam_idx):
        return self.model._reorder_cache(cache, beam_idx)


