#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import os
from flask import Flask, render_template, request, jsonify
from flask_cors import CORS
from qwen import Qwen
from prompt_templates import QwenPromptTemplates

qwen = Qwen()

app = Flask(__name__)
app.config['debug'] = True
CORS(app)

@app.route('/')
def index():
    return render_template('index.html')


@app.route('/chat', methods=['POST'])
def chat():
    data = request.get_json()
    prompt = data.get('prompt')
    if not prompt:
        return jsonify({'error': 'Missing prompt'}), 400

    if prompt in QwenPromptTemplates:
        prompt = QwenPromptTemplates[prompt]

    response = qwen.generate(prompt)
    return jsonify({'response': response})


@app.route('/ask', methods=['POST'])
def ask():
    data = request.get_json()
    prompt = data.get('prompt')
    if not prompt:
        return jsonify({'error': 'Missing prompt'}), 400

    if prompt in QwenPromptTemplates:
        prompt = QwenPromptTemplates[prompt]

    response = qwen.generate(prompt)
    return jsonify({'response': response})


@app.route('/completion', methods=['POST'])
def completion():
    data = request.get_json()
    prompt = data.get('prompt')
    if not prompt:
        return jsonify({'error': 'Missing prompt'}), 400

    if prompt in QwenPromptTemplates:
        prompt = QwenPromptTemplates[prompt]

    response = qwen.generate(prompt)
    return jsonify({'response': response})


@app.route('/generate', methods=['POST'])
def generate():
    data = request.get_json()
    prompt = data.get('prompt')
    if not prompt:
        return jsonify({'error': 'Missing prompt'}), 400

    if prompt in QwenPromptTemplates:
        prompt = QwenPromptTemplates[prompt]

    response = qwen.generate(prompt)
    return jsonify({'response': response})


@app.route('/model/ping', methods=['GET'])
def model_ping():
    return jsonify({'status': 'OK'})


@app.route('/model/generation/submit', methods=['POST'])
def submit():
    data = request.get_json()
    prompt = data.get('prompt')
    if not prompt:
        return jsonify({'error': 'Missing prompt'}), 400

    if prompt in QwenPromptTemplates:
        prompt = QwenPromptTemplates[prompt]

    response = qwen.generate(prompt)
    return jsonify({'response': response})


@app.route('/model/generation/continue', methods=['POST'])
def continue_generation():
    data = request.get_json()
    prompt = data.get('prompt')
    if not prompt:
        return jsonify({'error': 'Missing prompt'}), 400

    if prompt in QwenPromptTemplates:
        prompt = QwenPromptTemplates[prompt]

    response = qwen.generate(prompt)
    return jsonify({'response': response})


@app.route('/model/generation/query', methods=['GET'])
def query():
    return jsonify({'status': 'OK'})


@app.route('/model/generation/stop', methods=['GET'])
def stop():
    return jsonify({'status': 'OK'})


@app.route('/model/generation/cancel', methods=['GET'])
def cancel():
    return jsonify({'status': 'OK'})


@app.route('/model/generation/finish', methods=['GET'])
def finish():
