namespace qwen {

    template<typename T>
    class Serializer {
    public:
        Serializer() = default;
        virtual ~Serializer() = default;

        virtual void serialize(const std::vector<T>& vec, const std::string& filename) = 0;
        virtual void deserialize(std::vector<T>& vec, const std::string& filename) = 0;
    };

    template<typename T>
    class BinarySerializer : public Serializer<T> {
    public:
        BinarySerializer() = default;
        ~BinarySerializer() override = default;

        void serialize(const std::vector<T>& vec, const std::string& filename) override {
            std::ofstream file(filename, std::ios::binary);
            if (!file.is_open()) {
                throw std::runtime_error("Could not open file for writing.");
            }

            size_t size = vec.size();
            file.write(reinterpret_cast<const char*>(&size), sizeof(size_t));

            for (const T& element : vec) {
                file.write(reinterpret_cast<const char*>(&element), sizeof(T));
            }

            file.close();
        }

        void deserialize(std::vector<T>& vec, const std::string& filename) override {
            std::ifstream file(filename, std::ios::binary);
            if (!file.is_open()) {
                throw std::runtime_error("Could not open file for reading.");
            }

            size_t size;
            file.read(reinterpret_cast<char*>(&size), sizeof(size_t));

            vec.resize(size);

