    Server::Server(Config&& config) : config(std::move(config)) {
        io_context = std::make_unique<boost::asio::io_context>();
        acceptor = std::make_unique<boost::asio::ip::tcp::acceptor>(*io_context);
        endpoint = boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), config.port);
        acceptor->open(endpoint.protocol());
        acceptor->set_option(boost::asio::ip::tcp::acceptor::reuse_address(true));
        acceptor->bind(endpoint);
        acceptor->listen();

        std::cout << "Server listening on port " << config.port << std::endl;

        boost::asio::post(*io_context, [this]() { accept_connections(); });
        io_context->run();
    }

    Server::~Server() {
        io_context->stop();
    }

    void Server::serve_file(const std::string& filename, boost::asio::ip::tcp::socket& socket) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Could not open file for reading.");
        }

        std::vector<char> buffer(std::istreambuf_iterator<char>(file), {});
        file.close();

        boost::asio::write(socket, boost::asio::buffer(buffer));
    }

    void Server::serve_directory(const std::string& directory_name, boost::asio::ip::tcp::socket& socket) {
        std::vector<std::string> file_names;
        boost::filesystem::path directory_path(directory_name);

        if (!boost::filesystem::exists(directory_path)) {
            throw std::runtime_error("Directory does not exist.");
        }

        if (!boost::filesystem::is_directory(directory_path)) {
            throw std::runtime_error("Path is not a directory.");
        }

        for (const auto& entry : boost::filesystem::directory_iterator(directory_path)) {
            if (boost::filesystem::is_regular_file(entry)) {
                file_names.push_back(entry.path().string());
            }
        }

        for (const auto& filename : file_names) {
            std::ifstream file(filename, std::ios::binary);
            if (!file.is_open()) {
                throw std::runtime_error("Could not open file for reading.");
            }

            std::vector<char> buffer(std::istreambuf_iterator<char>(file), {});
            file.close();

            boost::asio::write(socket, boost::asio::buffer(buffer));
        }
    }

