$(function(){
    var doctor = new Vue({
        el:'#doctor',
        data:{
            result:[]
        },
        methods:{
            getArticle:function(){
                var _this = this;
				axios({
					method:'get',
					url:'doctor/getArticle.do',
					headers:{'Authorization':localStorage.getItem('Authorization')}
				}).then(function(res){
					_this.result = res.data.data;
				}).catch(function(err){
					console.log(err);
				})
            },
            showArticle:function(id){
                location.href = 'showArticle.do?id='+id;
            }
        },
        mounted:function(){
            this.getArticle();
        }
    })

    var article = new Vue({
        el:'#article',
        data:{
            article:[],
            comment:[],
            commentFlag:true,
            page:1,
            size:5
        },
        methods:{
            showArticle:function(id){
                location.href = 'article.do?id='+id;
            },
            addComment:function(){
                var _this = this;
                var content = document.getElementById('content').value;
                var articleid = document.getElementById('articleId').value;
                var doctorid = document.getElementById('doctorId').value;
                if(content == ''){
                    alert('请输入评论内容！');
                    return;
                }
				axios({
					method:'post',
					url:'comment/add.do',
					headers:{'Authorization':localStorage.getItem('Authorization')},
					data:{
						content:content,
						articleid:articleid,
						doctorid:doctorid
					}
				}).then(function(res){
					if(res.data.code == 1){
						_this.comment = res.data.data;
						_this.commentFlag = false;
					}else{
						alert(res.data.msg);
					}
				}).catch(function(err){
					console.log(err);
				})
            },
            getComment:function(){
                var _this = this;
				axios({
					method:'get',
					url:'comment/getComment.do',
					headers:{'Authorization':localStorage.getItem('Authorization')},
					params:{
						articleid:this.article.id,
						page:this.page,
						size:this.size
					}
				}).then(function(res){
					_this.comment = res.data.data;
					_this.commentFlag = false;
				}).catch(function(err){
					console.log(err);
				})
            },
            addMark:function(){
                var _this = this;
				axios({
					method:'get',
					url:'comment/addMark.do',
					headers:{'Authorization':localStorage.getItem('Authorization')},
					params:{
						articleid:this.article.id
					}
				}).then(function(res){
					if(res.data.code == 1){
						_this.article.mark = res.data.data;
					}else{
						alert(res.data.msg);
					}
				}).catch(function(err){
					console.log(err);
				})
            },
            loadMore:function(){
                var _this = this;
                _this.page = Number(_this.page)+1;
				axios({
					method:'get',
					url:'comment/getComment.do',
					headers:{'Authorization':localStorage.getItem('Authorization')},
					params:{
						articleid:this.article.id,
						page:this.page,
						size:this.size
					}
				}).then(function(res){
					if(res.data.code == 1){
						var oldData = [];
						oldData = res.data.data;
						_this.commentFlag = true;
						res.data.data.forEach(function(item){
							_this.comment.push(item);
						})
					}
				}).catch(function(err){
					console.log(err);
				})
            }
        },
        mounted:function(){
            var id = document.getElementById('id').value;
			axios({
				method:'get',
				url:'article/getArticle.do',
				headers:{'Authorization':localStorage.getItem('Authorization')},
				params:{
					id:id
				}
			}).then(function(res){
				if(res.data.code == 1){
					article.article = res.data.data;
					article.addMark();
					article.getComment();
					if(localStorage.getItem('Authorization')){
						article.commentFlag = false;
					}
				}else{
					alert(res.data.msg);
				}
			}).catch(function(err){
				console.log(err);
			})
        }
    })

