# -*- coding: utf-8 -*-
import logging
import re
from time import sleep
import requests

logging.basicConfig(
    format="%(asctime)s - %(levelname)s - %(name)s - %(message)s",
    datefmt="%m/%d/%Y %H:%M:%S",
    level=logging.INFO
)
logger = logging.getLogger(__name__)


class ChatGPT():
    def __init__(self, config):
        self.config = config
        self.headers = {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + self.config.get('OPENAI_API_KEY', '')
        }

    def get_chatgpt(self):
        end_point = 'https://api.openai.com/v1/chat/completions'
        while True:
            logger.info('Sending a GET request')
            try:
                response = requests.get(
                    url=end_point,
                    headers=self.headers,
                    params=self.get_params(),
                    timeout=60,
                )
                break
            except Exception as e:
                logger.error(f"Error: {e}")
                if e.response.status_code == 429:
                    logger.info("Rate limit exceeded, waiting for 5 seconds")
                    sleep(5)
                    continue
                raise
        logger.info(f"Status code: {response.status_code}")
        logger.info(f"Status content: {response.content}")
        if response.status_code == 200:
            return response.json()
        else:
            logger.error(f"Error: {response.json()}")
            raise Exception(response.json())

    def get_chatgpt_stream(self):
        end_point = 'https://api.openai.com/v1/chat/completions'
        while True:
            logger.info('Sending a POST request')
            try:
                response = requests.post(
                    url=end_point,
                    headers=self.headers,
                    json=self.get_params(),
                    timeout=60,
                )
                break
            except Exception as e:
                logger.error(f"Error: {e}")
                if e.response.status_code == 429:
                    logger.info("Rate limit exceeded, waiting for 5 seconds")
                    sleep(5)
                    continue
                raise
        logger.info(f"Status code: {response.status_code}")
        logger.info(f"Status content: {response.content}")
        if response.status_code == 200:
            return response.json()
        else:
            logger.error(f"Error: {response.json()}")
            raise Exception(response.json())

    def get_chatgpt_stream_iter(self):
        return self.get_chatgpt_stream()

    def get_params(self):
        return {
            "model": "gpt-3.5-turbo",
            "messages": [
                {"role": "system", "content": self.config.get(
                    'SYSTEM_PROMPT', '')},
                {"role": "user", "content": self.config.get(
                    'USER_PROMPT', '')}
            ],
            "max_tokens": int(self.config.get('MAX_TOKENS', 200)),
            "temperature": float(self.config.get('TEMPERATURE', 0.5)),
            "stream": True if self.config.get('STREAM', False) else False,
            "n": int(self.config.get('N', 1)),
            "stop": self.config.get('STOP', None),
            "top_p": float(self.config.get('TOP_P', 1)),
            "frequency_penalty": float(self.config.get('FREQUENCY_PENALTY', 0)),
            "presence_penalty": float(self.config.get('PRESENCE_PENALTY', 0))
        }


class ChatGPTAssistant(ChatGPT):
    def __init__(self, config):
        super().__init__(config)
        self.config = config

    def run(self):
        return self.get_chatgpt()

    def run_stream(self):
        return self.get_chatgpt_stream()


class ChatGPTStreamAssistant(ChatGPT):
    def __init__(self, config):
        super().__init__(config)

    def run(self):
        return self.get_chatgpt_stream_iter()

    def run_stream(self):
        return self.get_chatgpt_stream_iter()


