from app import app
from flask import request, render_template, jsonify
from functools import wraps
import json
import os
from flask import send_file

app.config['JSON_AS_ASCII'] = False


@app.route('/')
def index():
    return render_template('index.html')


@app.route('/check.txt')
def check():
    return send_file('check.txt')


def allow_only_type(allow_type='jpg'):
    def allow_only_type_decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            file = request.files.get('file')
            if file is None:
                return jsonify({'status': -1, 'message': '请上传文件'})
            file_type = os.path.splitext(file.filename)[-1][1:].lower()
            if file_type not in allow_type.split(','):
                return jsonify({'status': -1, 'message': '不支持的格式'})
            return func(file, *args, **kwargs)

        return wrapper

    return allow_only_type_decorator


def allow_only_mimetype(allow_mimetype='image/jpeg'):
    def allow_only_mimetype_decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            file = request.files.get('file')
            if file is None:
                return jsonify({'status': -1, 'message': '请上传文件'})
            if file.mimetype not in allow_mimetype.split(','):
                return jsonify({'status': -1, 'message': '不支持的格式'})
            return func(file, *args, **kwargs)

        return wrapper

    return allow_only_mimetype_decorator
