from app import app
from flask import request, jsonify
from model.recon import recon
from model.check import check
from model.face import face
from model.face import search
import json
import logging
import time
import os
from lib import uploader
from lib import logger


@app.route('/face/recon', methods=['POST'])
@allow_only_mimetype('image/jpeg')
def face_recon(file):
    logger.info('face recon start')
    try:
        recon_id = recon(file)
        if recon_id is None:
            logger.info('face recon end')
            return jsonify({'status': -1, 'message': '未知错误'})
        recon_path = os.path.join(app.config['RECON_DIR'], recon_id)
        recon_url = uploader.upload(recon_path, 'recon')
        logger.info('face recon end')
        return jsonify({'status': 0, 'url': recon_url})
    except Exception as e:
        logger.error(e)
        return jsonify({'status': -1, 'message': '未知错误'})


@app.route('/face/check', methods=['POST'])
@allow_only_mimetype('image/jpeg')
def face_check(file):
    logger.info('face check start')
    try:
        recon_id = recon(file)
        if recon_id is None:
            logger.info('face check end')
            return jsonify({'status': -1, 'message': '未知错误'})
        recon_path = os.path.join(app.config['RECON_DIR'], recon_id)
        recon_url = uploader.upload(recon_path, 'recon')
        check_result = check(file)
        if check_result is None:
            logger.info('face check end')
            return jsonify({'status': -1, 'message': '未知错误'})
        logger.info('face check end')
        return jsonify({'status': 0, 'url': recon_url, 'data': check_result})
    except Exception as e:
        logger.error(e)
        return jsonify({'status': -1, 'message': '未知错误'})


@app.route('/face/search', methods=['POST'])
@allow_only_mimetype('image/jpeg')
def face_search(file):
    logger.info('face search start')
    try:
        recon_id = recon(file)
        if recon_id is None:
            logger.info('face search end')
            return jsonify({'status': -1, 'message': '未知错误'})
        recon_path = os.path.join(app.config['RECON_DIR'], recon_id)
        recon_url = uploader.upload(recon_path, 'recon')
        search_result = search(file)
        if search_result is None:
            logger.info('face search end')
            return jsonify({'status': -1, 'message': '未知错误'})
        logger.info('face search end')
        return jsonify({'status': 0, 'url': recon_url, 'data': search_result})
    except Exception as e:
        logger.error(e)
