void Log::log(const char* format, ...) {
	va_list args;
	va_start(args, format);
	vfprintf(stderr, format, args);
	va_end(args);
}

void Log::log_to_file(string& log_path, const char* format, ...) {
	va_list args;
	va_start(args, format);
	string str;
	str.reserve(1024);
	{
		lock_guard<mutex> lock(mtx);
		str.clear();

		va_list args_copy;
		va_copy(args_copy, args);
		int len = vsnprintf(NULL, 0, format, args_copy);
		va_end(args_copy);
		str.resize(len);

		vsnprintf((char*)str.data(), len + 1, format, args);
	}
	va_end(args);

	ofstream outfile;
	outfile.open(log_path, ios::app);
	if (!outfile.is_open()) {
		return;
	}
	outfile << str << "\n";
	outfile.close();
}

