import { useReducer, useMemo, Dispatch } from 'react';
import { Reducer, ReducerActionType } from './types';

/**
 * Use reducer with options to expose state, dispatch, and memoized selector
 * @param reducer Reducer function
 * @param initialState Initial state
 * @param options Options
 */
export default function useReducerWithSelector<S, A extends ReducerActionType, R>(
  reducer: Reducer<S, A>,
  initialState: S,
  options?: {
    selector?: (state: S) => R;
    init?: (state: S) => S;
    debug?: boolean;
  }
): [S, Dispatch<A>, () => R] {
  const { selector = (state: S) => state as unknown as R, init = (state: S) => state } = options || {};
  const [state, dispatch] = useReducer(reducer, initialState, <any>init);
  const selectorFn = useMemo(() => selector, []);
  const memoizedSelector = useMemo(() => selectorFn(state), [state, selectorFn]);
  return [state, dispatch, () => memoizedSelector];
}
