package com.qwenet.controller;

import com.qwenet.model.ChatMessage;
import com.qwenet.model.GPTModel;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
public class ChatController {
    private GPTModel gptModel;

    public ChatController(GPTModel gptModel) {
        this.gptModel = gptModel;
    }

    @RequestMapping(value = "/chat", method = RequestMethod.POST)
    public ChatMessage chat(@RequestBody ChatMessage chatMessage) {
        String conversation = chatMessage.getConversation();
        List<ChatMessage> chatHistory = chatMessage.getChatHistory();

        String response = gptModel.generateResponse(conversation, chatHistory);

        ChatMessage chatResponse = new ChatMessage();
        chatResponse.setConversation(conversation);
        chatResponse.setChatHistory(chatHistory);
        chatResponse.setResponse(response);

        return chatResponse;
    }
}
