ChatRoom::ChatRoom(QWidget *parent) : QWidget(parent)
{
    // 调整窗口大小
    resize(800, 600);
    // 创建控件
    // 创建聊天输入框和发送按钮
    chatInput = new QLineEdit(this);
    chatInput->setPlaceholderText("输入消息");
    sendButton = new QPushButton("发送", this);
    // 创建聊天记录列表
    chatLog = new QListWidget(this);
    chatLog->setEditTriggers(QAbstractItemView::NoEditTriggers);
    // 创建日志文件按钮
    logButton = new QPushButton("打开日志文件", this);
    // 创建菜单栏
    menuBar = new QMenuBar(this);
    fileMenu = menuBar->addMenu("文件");
    exitAction = fileMenu->addAction("退出");
    // 创建工具栏
    toolBar = new QToolBar(this);
    addToolBar(Qt::TopToolBarArea, toolBar);
    toolBar->addWidget(sendButton);
    toolBar->addWidget(logButton);
    // 设置布局
    QVBoxLayout *layout = new QVBoxLayout();
    layout->addWidget(chatInput);
    layout->addWidget(chatLog);
    setLayout(layout);
    // 信号与槽连接
    connect(sendButton, &QPushButton::clicked, this, &ChatRoom::sendMessage);
    connect(chatInput, &QLineEdit::returnPressed, this, &ChatRoom::sendMessage);
    connect(logButton, &QPushButton::clicked, this, &ChatRoom::openLogFile);
    connect(exitAction, &QAction::triggered, this, &QWidget::close);
    // 加载日志文件
    loadLog();
    // 加载模型
    QJsonObject config = QJsonObject();
    config.insert("model_name", "qwen");
    config.insert("model_path", "/Users/zhaozhenyu/Downloads/llama-2-7b-chat-hf");
    config.insert("model_type", "qwen");
    config.insert("max_context_length", 1024);
    config.insert("max_len", 256);
    model = new QwenModel(this, config);
    // 创建并显示窗口
    // ChatRoom chatRoom;
    // chatRoom.show();
}

void ChatRoom::sendMessage()
{
    QJsonObject message = QJsonObject();
    message.insert("role", "user");
    message.insert("content", chatInput->text());
    QJsonValue content = QJsonValue(message);
    chatLog->addItem("User: " + message["content"].toString());
    chatInput->clear();
    sendMessageToLLM(content);
}

void ChatRoom::openLogFile()
{
    QString logPath = QFileDialog::getOpenFileName(this, "打开日志文件", "", "Text Files (*.txt)");
    if (!logPath.isEmpty())
    {
        QFile file(logPath);
        if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
        {
            QMessageBox::critical(this, "错误", "无法打开文件");
            return;
        }
        QTextStream in(&file);
        while (!in.atEnd())
        {
            QString line = in.readLine();
            QJsonObject message = QJsonObject();
            message.insert("role", "assistant");
            message.insert("content", line);
            chatLog->addItem("Assistant: " + line);
        }
        file.close();
    }
}

