void ChatRoom::sendMessageToLLM(QJsonValue message)
{
    QJsonObject request = QJsonObject();
    request.insert("messages", QJsonArray() << message);
    QJsonValue requestValue = QJsonValue(request);
    model->sendMessage(requestValue);
    QObject::connect(model, &QwenModel::responseReceived, this, [=](QJsonValue responseValue) {
        QJsonObject response = responseValue.toObject();
        QJsonValue content = response["choices"][0]["message"]["content"];
        chatLog->addItem("Assistant: " + content.toString());
        QJsonObject message = QJsonObject();
        message.insert("role", "assistant");
        message.insert("content", content.toString());
        chatLog->addItem("Assistant: " + content.toString());
    });
}

