public class MathTools extends AbstractTools {

    public static final String NAME = "math";

    public static final String DESCRIPTION = "A tool which can help you to solve math questions";

    public static final String INPUT_KEY = "question";

    @Override
    public String getName() {
        return NAME;
    }

    @Override
    public String getDescription() {
        return DESCRIPTION;
    }

    @Override
    public Map<String, Object> call(Map<String, Object> input) {
        String question = input.get(INPUT_KEY).toString();
        question = CommonUtils.cleanStr(question);
        String[] split = question.split("=");
        if (split.length == 1) {
            return handleError("Number of equations is less than 1");
        } else {
            if (!question.contains("x")) {
                CommonUtils.logInfo("No x in math question, return null");
                return handleError("No x in math question");
            }
            String finalQuestion = question;
            split = question.split("=");
            boolean containsEqual = false;
            for (String s : split) {
                if (s.contains("=")) {
                    containsEqual = true;
                    break;
                }
            }
            if (containsEqual) {
                return handleError("Equations contains multiple equal signs");
            }
            List<MathExpression> expressions = parseMathExpression(split);
            if (expressions.size() == 0) {
                return handleError("No valid math expression found");
            }

            int x = getX(split);
            if (x == -1) {
                return handleError("No x in math question");
            }
            if (x != -1 && expressions.size() == 1) {
                return handleError("No multiple equations found");
            }
            String variable = getXVariable(split);
            if (variable == null) {
                return handleError("No variable found in math question");
            }
            if (variable.equals("x") && expressions.size() == 1) {
                expressions.get(0).x = -1;
                expressions.get(0).variable = "x";
            }
            String solution = solveMathExpressions(expressions);
            return new HashMap<>() {{
                put(Constants.TOOL_RESULT_KEY, solution);
            }};
        }
    }

    private String solveMathExpressions(List<MathExpression> expressions) {
        try {
            Map<String, Integer> variableMap = new HashMap<>();
            for (MathExpression expression : expressions) {
                if (expression.variable != null && expression.variable.equals("x") && expression.x == -1) {
                    return "No solution found";
                }
                if (expression.x == -1) {
                    variableMap.put(expression.variable, expression.value);
                }
            }
            for (MathExpression expression : expressions) {
                if (expression.x != -1) {
                    for (String key : variableMap.keySet()) {
                        expression.value = expression.value.replace(key, String.valueOf(variableMap.get(key)));
                    }
                    expression.value = expression.value.replace(expression.variable, String.valueOf(expression.x));
