from collections import defaultdict
import torch
from torch import nn
from torch.nn import functional as F
from typing import Optional, Tuple, Union, List
from functools import partial

from easy_transformer.model import EasyTransformer
from easy_transformer.model.layer import FeedForward, AttentionLayer, LayerNorm, MLPHead
from easy_transformer.modules import linear, register

class TransformerBlock(nn.Module):
    def __init__(self, config, layer_idx=None):
        super().__init__()
        self.config = config
        self.inner_dim = config.inner_dim
        self.n_heads = config.n_heads
        self.layer_idx = layer_idx
        self.scale = config.scale
        self.use_float16 = config.use_float16
        self.attn = AttentionLayer(config)
        self.attn_norm = LayerNorm(self.inner_dim)
        self.ff = FeedForward(config)
        self.ff_norm = LayerNorm(self.inner_dim)

    def forward(self, x, mask=None, token=None, block_layer=None):
        if self.use_float16:
            x = x.half()
        h = self.attn_norm(x)
        a = self.attn(h, mask=mask)
        x = x + a
        h = self.ff_norm(x)
        x = x + self.ff(h)
        return x

class GPT2LMHead(MLPHead):
    def __init__(self, config):
        self.inner_dim = config.inner_dim
        self.vocab_size = config.vocab_size
        super().__init__(config)
        self.decoder = nn.Linear(config.inner_dim, config.vocab_size, bias=False)
        self.decoder.weight = self.transform.weight

    def forward(self, x):
        x = self.transform(x) # [b, t, e]
        x = self.decoder(x)
        return x

class GPT2(EasyTransformer):
    def __init__(self, config):
        super().__init__(config)
        self.config = config
        self.inner_dim = config.inner_dim
        self.n_layers = config.n_layers
        self.n_heads = config.n_heads
        self.vocab_size = config.vocab_size
        self.dim_head = config.dim_head
        self.scale = config.scale
        self.use_float16 = config.use_float16
        self.block_fn = partial(TransformerBlock, config)
        self.embed_tokens = nn.Embedding(config.vocab_size, config.inner_dim)
        self.lm_head = GPT2LMHead(config)
        self.blocks = nn.ModuleList([self.block_fn(layer_idx=i) for i in range(config.n_layers)])
        self.proj_head = nn.Linear(config.inner_dim, config.inner_dim, bias=False)
        self.proj_head.weight = self.lm_head.transform.weight

    def forward(self, token, use_cache=False, cache=None):
        x = self.embed_tokens(token)
        for block in self.blocks:
            x = block(x)
        x = self.proj_head(x)
        x = self.lm_head(x)
        return x



