#!/usr/bin/env node

const { program } = require('commander')
const { createClient } = require('redis')
const { createServer } = require('http')
const { createProxyService } = require('./proxy')
const { createWebsocketServer } = require('./server')
const { createWebSocketProxyService } = require('./proxy-ws')

const server = createServer()

const createResolver = ctx => ({
    async resolve (name) {
        return ctx.client.hget(`server:${name}`, 'host')
    }
})

program
    .option('--port <port>', 'port to listen on', 8080)
    .option('--redis-host <host>', 'redis host', '127.0.0.1')
    .option('--redis-port <port>', 'redis port', 6379)
    .option('--redis-password <password>', 'redis password', '')
    .option('--redis-db <db>', 'redis db', 0)
    .option('--redis-prefix <prefix>', 'redis prefix', '')
    .option('--secret <secret>', 'secret key', 'secret')
    .option('--debug', 'debug mode', false)
    .option('--private', 'private mode', false)
    .option('--allow-cors', 'allow CORS', false)
    .option('--cors-origin <origin>', 'CORS origin', '*')
    .option('--cors-allow-methods <methods>', 'CORS allow methods', 'GET,POST,PUT,DELETE,CONNECT,OPTIONS,PATCH')
    .option('--cors-allow-headers <headers>', 'CORS allow headers', 'X-Requested-With,Content-Type,Accept')
    .option('--cors-expose-headers <headers>', 'CORS expose headers', 'X-Requested-With,Content-Type,Accept')
    .option('--cors-max-age <age>', 'CORS max age', 86400)
    .option('--cors-allow-credentials', 'CORS allow credentials', false)
    .option('--websocket-path <path>', 'websocket path', '/ws')
    .option('--websocket-port <port>', 'websocket port', 8081)
    .option('--websocket-proxy-path <path>', 'websocket proxy path', '/ws')
    .option('--websocket-proxy-port <port>', 'websocket proxy port', 8082)

program.parse(process.argv)

const options = program.opts()

const client = createClient({
    url: `redis://${options.redisHost}:${options.redisPort}`,
    password: options.redisPassword,
    db: options.redisDb
})

const resolver = createResolver({ client, prefix: options.redisPrefix })

const proxy = createProxyService({
    server,
    client,
    resolver,
    secret: options.secret,
    private: options.private,
    debug: options.debug,
    allowCors: options.allowCors,
    corsOrigin: options.corsOrigin,
    corsAllowMethods: options.corsAllowMethods.split(','),
    corsAllowHeaders: options.corsAllowHeaders.split(','),
    corsExposeHeaders: options.corsExposeHeaders.split(','),
    corsMaxAge: parseInt(options.corsMaxAge),
    corsAllowCredentials: options.corsAllowCredentials
})

if (options.debug) {
    proxy.on('error', err => {
        console.error(err)
    })
}

proxy.listen(options.port, () => {
    console.log(`Server listening on port ${options.port}`)
})

const wss = createWebSocketServer({
    server,
    client,
    resolver,
    secret: options.secret,
    debug: options.debug,
    allowCors: options.allowCors,
    corsOrigin: options.corsOrigin,
    corsAllowMethods: options.corsAllowMethods.split(','),
    corsAllowHeaders: options.corsAllowHeaders.split(','),
    corsExposeHeaders: options.corsExposeHeaders.split(','),
    corsMaxAge: parseInt(options.corsMaxAge),
    corsAllowCredentials: options.corsAllowCredentials
})

wss.on('connection', async (ws, req) => {
    const name = req.url.slice(1)
    const host = await resolver.resolve(name)
    if (!host) {
        ws.close(4000, 'Server not found')
        return
    }
    createWebSocketProxyService({
        ws,
        host,
        name,
        secret: options.secret,
        debug: options.debug,
        allowCors: options.allowCors,
        corsOrigin: options.corsOrigin,
        corsAllowMethods: options.corsAllowMethods.split(','),
        corsAllowHeaders: options.corsAllowHeaders.split(','),
        corsExposeHeaders: options.corsExposeHeaders.split(','),
        corsMaxAge: parseInt(options.corsMaxAge),
        corsAllowCredentials: options.corsAllowCredentials
    })
})

wss.listen(options.websocketPort, () => {
    console.log(`WebSocket server listening on port ${options.websocketPort}`)
})

server.listen(options.websocketProxyPort, () => {
    console.log(`WebSocket proxy server listening on port ${opt<|fim_suffix|>.options)
<|fim_middle|>ions.websocketProxyPort}`)
})

server.on('error', err => {
    console.error(err)
})

