import { createProxyService } from './proxy'
import { createResolver } from './resolver'
import { createWebSocketProxyService } from './proxy-ws'
import { createWsServer } from './ws'

const server = createServer()
const resolver = createResolver({ client: createClient() })

const proxy = createProxyService({
    server,
    client: createClient(),
    resolver,
    secret: 'secret',
    debug: false,
    allowCors: false,
    corsOrigin: '*',
    corsAllowMethods: ['GET', 'POST', 'PUT', 'DELETE', 'CONNECT', 'OPTIONS', 'PATCH'],
    corsAllowHeaders: ['X-Requested-With', 'Content-Type', 'Accept'],
