import {
  ChatCompletionRequestMessageRoleEnum,
  ChatCompletionResponseMessageRoleEnum,
  Configuration,
  OpenAIApi,
} from 'openai'
import { config } from '../config'
import { getQwenChatMessageRole } from './message'

const configuration = new Configuration({
  apiKey: config.openaiKey,
  basePath: config.openaiApiHost,
})

const openai = new OpenAIApi(configuration)

export const getChatCompletion = async (messages: any[], apiModel: string) => {
  try {
    const output = await openai.createChatCompletion({
      model: apiModel,
      messages,
      temperature: 0.7,
      top_p: 1,
      frequency_penalty: 0,
      presence_penalty: 0,
      max_tokens: 2048,
      stream: true,
    })
    return output
  } catch (error: any) {
    console.error(error)
    throw error
  }
}

export const getChatCompletionMessage = async (
  messages: any[],
  apiModel: string
) => {
  try {
    const output = await openai.createChatCompletion({
      model: apiModel,
      messages,
    })
    return output.data.choices[0].message
  } catch (error: any) {
    console.error(error)
    throw error
  }
}

const convertChatMessageRole = (role: string) => {
  switch (role) {
    case ChatCompletionRequestMessageRoleEnum.System:
      return ChatCompletionResponseMessageRoleEnum.System
    case ChatCompletionRequestMessageRoleEnum.User:
      return ChatCompletionResponseMessageRoleEnum.User
    case ChatCompletionRequestMessageRoleEnum.Assistant:
      return ChatCompletionResponseMessageRoleEnum.Assistant
    case ChatCompletionRequestMessageRoleEnum.Function:
      return ChatCompletionResponseMessageRoleEnum.Function
    default:
      throw new Error(`Invalid role: ${role}`)
  }
}

