import { config } from '@/config'
import type { ChatMessage, UserSettings } from '@/types'
import { getChatCompletion, getChatCompletionStream } from './request'
import { getChatCompletionMessage } from './response'

export const QWEN_API_KEY = config.qwenApiKey

export const QWEN_API_HOST = config.qwenApiHost

export const QWEN_API_MODEL = config.qwenApiModel

export const QWEN_MAX_TOKENS = config.qwenMaxTokens

export const fetchChatGptStream = async (
  messages: ChatMessage[],
  settings: UserSettings
) => {
  const { QWEN_API_KEY, QWEN_API_HOST } = config
  const role = 'User'
  const userMessage = messages.find((message) => message.role === role)
  messages.unshift({
    role: 'System',
    content: 'You are Qwen, an Open-Source AI chatbot.',
  })
  const { response, stream } = await getChatCompletionStream(
    messages,
    QWEN_API_MODEL
  )
  return { response, stream }
}

export const fetchChatGpt = async (
  messages: ChatMessage[],
  settings: UserSettings
) => {
  const { QWEN_API_KEY, QWEN_API_HOST } = config
  const role = 'User'
  const userMessage = messages.find((message) => message.role === role)
  messages.unshift({
    role: 'System',
    content: 'You are Qwen, an Open-源 AI chatbot.',
  })
  const response = await getChatCompletionMessage(messages, QWEN_API_MODEL)
  return { response }
}
