using namespace std;

// ChatGPT client constructor
ChatGPT::ChatGPT(const char* host, int port) : mSocket(-1), mHost(host), mPort(port), mIsRunning(false) {
}

// ChatGPT client destructor
ChatGPT::~ChatGPT() {
    if (mSocket != -1) {
        close(mSocket);
    }
}

// Start the ChatGPT client
void ChatGPT::start() {
    if (!mIsRunning) {
        mIsRunning = true;
        thread t(&ChatGPT::run, this);
        t.detach();
    }
}

// Stop the ChatGPT client
void ChatGPT::stop() {
    if (mIsRunning) {
        mIsRunning = false;
        shutdown(mSocket, SHUT_RDWR);
        close(mSocket);
        mSocket = -1;
    }
}

// Run the ChatGPT client
void ChatGPT::run() {
    if (!connectToServer()) {
        return;
    }

    while (mIsRunning) {
        char buffer[1024];
        int bytesRead = recv(mSocket, buffer, sizeof(buffer), 0);
        if (bytesRead <= 0) {
            break;
        }

        buffer[bytesRead] = '\0';
        string receivedMessage(buffer);

        // Process the received message
        processReceivedMessage(receivedMessage);
    }
}

// Connect to the ChatGPT server
bool ChatGPT::connectToServer() {
    if (mSocket != -1) {
        close(mSocket);
    }

    mSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (mSocket == -1) {
        cerr << "Failed to create socket" << endl;
        return false;
    }

