import json
import os
import datetime
import time
from abc import ABC, abstractmethod
from collections import deque
from typing import Any, Dict, List, Optional, Union

import numpy as np

from ..common import get_current_time
from .model import Model


class BaseTask(ABC):
    """
    Base class for all tasks.
    """

    def __init__(self, user_id, model: Model):
        self.user_id = user_id
        self.model = model
        self._generate_time = None
        self._generate_timestamp = None
        self._generate_history = None
        self._generate_info = None
        self._generate_output = None
        self._generate_status = None
        self._generate_request = None

    def _parse_request(self, request: dict) -> None:
        self._generate_request = request
        self._generate_info = request.get("generate_info", {})

    @abstractmethod
    def _generate(self, request: dict) -> Any:
        """
        Perform the task generation, return the result.
        """
        pass

    def generate(self, request: dict = None) -> dict:
        self._parse_request(request)
        self._generate_time = get_current_time()
        self._generate_timestamp = int(time.time())
        self._generate_output = self._generate(request)
        self._generate_status = "success"
        return self.to_dict()

    def to_dict(self):
        return {
            "generate_info": self._generate_info,
            "generate_time": self._generate_time,
            "generate_timestamp": self._generate_timestamp,
            "generate_history": self._generate_history,
            "generate_output": self._generate_output,
            "generate_status": self._generate_status,
        }

    @abstractmethod
    def get_status(self):
        pass


class BaseTranslationTask(BaseTask):
    def __init__(self, user_id, model):
        super().__init__(user_id, model)
        self._generate_history = deque(
            maxlen=self.model.config.get("max_history", 1)
        )

    def _parse_request(self, request) -> None:
        super()._parse_request(request)
        self._generate_lang = request.get("generate_lang")
        self._generate_history.clear()
        self._generate_history.append(request.get("prompt", []))
        self._generate_source = request.get("generate_source")
        self._generate_target = request.get("generate_target")

    def _generate(self, request):
        self._generate_history.append(request.get("prompt"))
        self._generate_source = request.get("generate_source", self._generate_source)
        self._generate_target = request.get("generate_target", self._generate_target)
        if not self._generate_source and not self._generate_target:
            raise ValueError("source and target language not specified")
        if not self._generate_source:
            self._generate_source = self._generate_lang
        if not self._generate_target:
            self._generate_target = self._generate_lang

        translations = self.model.translate(
            request.get("prompt"),
            source=self._generate_source,
            target=self._generate_target,
        )
        return translations

    def get_status(self):
        return {
            "source": self._generate_source,
            "target": self._generate_target,
        }


class BaseChatTask(BaseTask):
    def __init__(self, user_id, model):
        super().__init__(user_id, model)
        self._generate_history = deque(
            maxlen=self.model.config.get("max_history", 1)
        )
        self._generate_role = None

    def _parse_request(self, request) -> None:
        super()._parse_request(request)
        self._generate_history.clear()
        self._generate_history.append(request.get("prompt", []))
        self._generate_role = request.get("generate_role")

    def _generate(self, request):
        self._generate_history.append(request.get("prompt"))
        response = self.model.chat(
            request.get("prompt"), role=self._generate_role, history=self._generate_history
        )
        return response

    def get_status(self):
        return {
            "role": self._generate_role,
        }


