import {
  Context,
  OpenAIStream,
  StreamingTextResponse,
} from 'ai'
import { Configuration, OpenAIApi } from 'openai-edge'
import { nanoid } from 'nanoid'
import {
  OpenAIModelId,
  OpenAIModels,
} from '../../constants'
import {
  ChatMessage,
  ChatMessageRole,
} from '../../types'
import { upsertConversation } from '../../utils/conversation'
import { getEnvironmentVariable } from '../../utils/environment'
import { getOpenAIApiKey } from '../../utils/openai'

const OPENAI_API_KEY = getOpenAIApiKey()
const OPENAI_API_BASE_URL = getEnvironmentVariable('NEXT_PUBLIC_OPENAI_API_BASE_URL')
const OPENAI_API_VERSION = getEnvironmentVariable('NEXT_PUBLIC_OPENAI_API_VERSION')

const configuration = new Configuration({
  apiKey: OPENAI_API_KEY,
  basePath: OPENAI_API_BASE_URL,
  baseOptions: {
    headers: {
      'Api-Version': OPENAI_API_VERSION,
    },
  },
})

const openai = new OpenAIApi(configuration)

export const run = async (
  messages: ChatMessage[],
  model: OpenAIModelId = OpenAIModels.GPT4,
  context?: Context,
) => {
  const conversationId = nanoid()

  const messageHistory: ChatMessage[] = [
    {
      role: ChatMessageRole.System,
      content: 'You are a helpful assistant.',
    },
    ...messages,
  ]

  const prompt = 'You are a helpful assistant.'

  try {
    const response = await openai.createChatCompletion(
      {
        model,
        messages: [
          {
            role: 'system',
            content: prompt,
          },
          ...messageHistory,
        ],
        stream: true,
      },
      {
        signal: context?.signal,
      },
    )

    const stream = OpenAIStream(response)

    if (context) {
      upsertConversation(conversationId, messageHistory, stream)
    }

    return new StreamingTextResponse(stream)
  } catch (error) {
    console.error('Error generating response:', error)

    return new Response(JSON.stringify({ error: 'Error generating response' }))
  }
