"""Class of BaseMetric."""
import os
from collections import OrderedDict
from collections.abc import Iterable
from functools import partial
import numpy as np
import torch
import torch.nn.functional as F

from vega.common import ClassFactory, ClassType
from .metric import Metric


@ClassFactory.register(ClassType.METRIC)
class MultiTaskMetric(Metric):
    """MultiTaskMetric class."""

    def __init__(self, metric_type=None, metric_args=None):
        """Construct the MultiTaskMetric class."""
        super(MultiTaskMetric, self).__init__()
        self.metric_type = metric_type
        self.metric_args = metric_args
        self.metric_func = ClassFactory.get_cls(ClassType.METRIC, self.metric_type)
        self.metric_func = partial(self.metric_func, **self.metric_args)
        self.metric_funcs = {}
        self.reset()

    def reset(self):
        """Reset the state of the metric to initial conditions."""
        self.metric_funcs.clear()

    def update(self, outputs, targets):
        """Update the internal evaluation result."""
        if isinstance(outputs, torch.Tensor):
            outputs = [outputs]
        if isinstance(targets, torch.Tensor):
            targets = [targets]
        assert len(outputs) == len(targets), "outputs and targets must have the same length"
        for output, target in zip(outputs, targets):
            if output.device != torch.device('cpu'):
                output = output.cpu()
            if target.device != torch.device('cpu'):
                target = target.cpu()
            if isinstance(output, torch.Tensor):
                output = output.numpy()
            if isinstance(target, torch.Tensor):
                target = target.numpy()
            if isinstance(target, (list, tuple)):
                target = np.array(target)
            target = target.reshape(-1)
            output = output.reshape(-1)
            if not self.metric_funcs:
                self.metric_funcs['all'] = self.metric_func(output, target)
            if target.shape[0] > 1:
                for idx in range(target.shape[0]):
                    task_name = str(idx)
                    if task_name not in self.metric_funcs:
                        self.metric_funcs[task_name] = self.metric_func(output[idx], target[idx])
            if len(set(target)) == 1:  # for all same value
                for idx in range(target.shape[0]):
                    task_name = str(idx)
                    if task_name not in self.metric_funcs:
                        self.metric_funcs[task_name] = self.metric_func(output[idx], target[idx])
        return self.metric_funcs

    def result(self):
        """Get the current evaluation result."""
        if not self.metric_funcs:
            return OrderedDict()
        return OrderedDict(zip(self.metric_funcs.keys(), [self.metric_funcs[key].result() for key in self.metric_funcs.keys()]))

    def check(self, outputs, targets):
        """Check the outputs and targets, raise error if any."""
        if isinstance(outputs, torch.Tensor):
            outputs = [outputs]
        if isinstance(targets, torch.Tensor):
            targets = [targets]
        assert len(outputs) == len(targets), "outputs and targets must have the same length"
        for output, target in zip(outputs, targets):
            if isinstance(output, torch.Tensor):
                output = output.numpy()
            if isinstance(target, torch.Tensor):
                target = target.numpy()
            assert output.shape == target.shape, "output and target must have the same shape"

    def __call__(self, outputs, targets):
        """Calculate metric."""
        self.check(outputs, targets)
        return self.update(outputs, targets)
        # return self.metric_func(output, target)

    @staticmethod
    def _get_class_name(cls):
        if cls.__name__ == 'MultiTaskMetric':
            raise ValueError("The class name of MultiTaskMetric is not allowed.")
        if hasattr(cls, '_name'):
            return cls._name
        if cls.__name__.startswith('MultiTask'):
            cls._name = cls.__name__[9:]
        return cls.__name__

    @staticmethod
    def _parse_metric_type(metric_type):
        if isinstance(metric_type, str):
            metric_type = [metric_type]
        elif isinstance(metric_type, ClassFactory):
            metric_type = [metric_type.__name__]
        if isinstance(metric_type, Iterable):
            return metric_type
        raise TypeError("metric_type must be a string or a list of string")

    def serialize(self):
        """Serialize the metric metrics."""
        try:
            metric_args = self.metric_args.copy()
        except AttributeError:
            metric_args = {}
        metric_type = self.metric_type
        if isinstance(metric_type, ClassFactory):
            metric_type = metric_type.__name__
        metric_args['metric_type'] = metric_type
        metric_args['metric_args'] = self.metric_args
        return metric_args

    @classmethod
    def convert(cls, metric_args):
        """Convert the metric metrics."""
        try:
            metric_type = metric_args['metric_type']
        except KeyError:
            raise ValueError("metric_type must be provided.")
        metric_args = metric_args['metric_args']
        metric_type = ClassFactory.get_cls(ClassType.METRIC, metric_type)
        metric = metric_type(**metric_args)
        return metric


@ClassFactory.register(ClassType.METRIC)
class AccuracyMetric(Metric):
    """Accuracy metric class."""

    def __init__(self, topk=(1,), class_num=None):
        """Initialize Accuracy metric."""
        super(AccuracyMetric, self).__init__()
        self.topk = topk
        self.class_num = class_num
        self.reset()

    def reset(self):
        """Reset the metric."""
        self.correct = [0 for _ in range(len(self.topk))]
        self.total = 0

    def update(self, outputs, targets):
        """Update the metric.

        :param outputs: Tensor generated by model forwarding
        :param targets: The ground truth tensor
        """
        if isinstance(outputs, torch.Tensor):
            outputs = outputs.cpu().numpy()
        if isinstance(targets, torch.Tensor):
            targets = targets.cpu().numpy()
        if isinstance(targets, (list, tuple)):
            targets = np.array(targets)
        assert outputs.shape[0] == targets.shape[0], "outputs and targets must have the same batch size"
        if self.class_num is not None:
            outputs = F.softmax(outputs, dim=1)
        for i in range(len(self.topk)):
            k = self.topk[i]
            topk_outputs = np.argsort(-outputs, axis=1)[:, :k]
            correct = sum([1 for i in range(outputs.shape[0]) if targets[i] in topk_outputs[i]])
            self.correct[i] += correct
        self.total += outputs.shape[0]
        return self.result()

    def result(self):
        """Return the result of the metric calculation."""
        return OrderedDict(zip(['top%d' % i for i in self.topk], [1.0 * self.correct[i] / self.total for i in range(len(self.topk))]))

    def check(self, outputs, targets):
        """Check the outputs and targets, raise error if any."""
        assert len(outputs) == len(targets), "outputs and targets must have the same length"
        assert outputs.shape[0] == targets.shape[0], "outputs and targets must have the same batch size"
        assert outputs.shape[1] == self.class_num, "outputs and class_num must have the same class number"
        assert outputs.shape[0] == targets.shape[0], "outputs and targets must have the same batch size"

    @staticmethod
    def _parse_topk(topk):
        if isinstance(topk, int):
            topk = (topk, )
        elif isinstance(topk, tuple):
            topk = topk
        elif isinstance(topk, list):
            topk = tuple(topk)
        return topk


