function getFileSize(file) {
    const fileSize = file.size / 1024 / 1024;
    if (fileSize > 100) {
        return 100;
    }
    return fileSize;
}

function uploadFile(file, fileInput) {
    const form = new FormData();
    form.append('file', file);
    form.append('file_name', file.name);
    form.append('file_size', fileInput.files[0].size);
    form.append('file_type', file.type);
    const fileSize = getFileSize(fileInput.files[0]);
    if (fileSize > 100) {
        return Promise.reject('File size is too large');
    }
    const fileInputId = fileInput.id;
    const progressBar = document.querySelector(`#${fileInputId} .progress-bar`);
    const progressText = document.querySelector(`#${fileInputId} .progress-text`);
    progressBar.style.width = '0%';
    progressText.textContent = '0%';
    const promise = new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open('POST', '/file/upload');
        xhr.upload.addEventListener('progress', function (event) {
            const percentComplete = Math.round((event.loaded / event.total) * 100);
            progressBar.style.width = `${percentComplete}%`;
            progressText.textContent = `${percentComplete}%`;
        });
        xhr.onload = function () {
            if (xhr.status === 200) {
                const response = xhr.response;
                const fileID = response.id;
                resolve(fileID);
            } else {
                reject(new Error(`Upload failed with status ${xhr.status}`));
            }
        };
        xhr.send(form);
    });
    return promise;
}

function sendEvent(fileID, event) {
    const xhr = new XMLHttpRequest();
    xhr.open('POST', '/file/event');
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.send(JSON.stringify({file_id: fileID, event: event}));
    return new Promise((resolve, reject) => {
        xhr.onload = function () {
            if (xhr.status === 200) {
                resolve(xhr.response);
            } else {
                reject(new Error(`Event send failed with status ${xhr.status}`));
            }
        };
    });
}

function deleteRow(fileID) {
    const xhr = new XMLHttpRequest();
    xhr.open('DELETE', `/file/${fileID}`);
    xhr.onload = function () {
        if (xhr.status === 200) {
            const row = document.querySelector(`#file-row-${fileID}`);
            row.parentNode.removeChild(row);
        } else {
            console.error(`Delete failed with status ${xhr.status}`);
        }
    };
    xhr.send();
}

function handleFileInput() {
    const fileInput = document.querySelector('#file-input');
    const fileSelectButton = document.querySelector('#file-select-button');
    const fileRemoveButton = document.querySelector('#file-remove-button');
    const fileUploadButton = document.querySelector('#file-upload-button');
    const fileProgressContainer = document.querySelector('#file-progress-container');
    const fileProgressText = document.querySelector('#file-progress-text');

    fileSelectButton.addEventListener('click', function () {
        fileInput.click();
    });

    fileInput.addEventListener('change', function () {
        const fileName = fileInput.value.split('\\').pop();
        fileSelectButton.textContent = fileName;
        fileRemoveButton.style.display = 'inline-block';
        fileUploadButton.style.display = 'inline-block';
        fileProgressContainer.style.display = 'block';
        fileProgressText.textContent = '';
    });

    fileRemoveButton.addEventListener('click', function () {
        fileInput.value = '';
        fileSelectButton.textContent = 'Select a file';
        fileRemoveButton.style.display = 'none';
        fileUploadButton.style.display = 'none';
        fileProgressContainer.style.display = 'none';
    });

    fileUploadButton.addEventListener('click', function () {
        const file = fileInput.files[0];
        if (!file) {
            console.error('No file selected');
            return;
        }
        const fileID = Math.floor(Math.random() * 100000);
        const fileRow = document.createElement('div');
        fileRow.id = `file-row-${fileID}`;
        fileRow.innerHTML = `
            <div class="file-row">
                <div class="file-name">${file.name}</div>
                <div class="file-progress">
                    <div class="progress-bar"></div>
                </div>
                <div class="file-actions">
                    <button class="file-stop-button" id="file-stop-button-${fileID}">Stop</button>
                    <button class="file-delete-button" id="file-delete-button-${fileID}">Delete</button>
                </div>
            </div>
        `;
        const fileDeleteButton = document.createElement('button');
        fileDeleteButton.id = `file-delete-button-${fileID}`;
        fileDeleteButton.textContent = 'Delete';
        fileDeleteButton.addEventListener('click', function () {
            deleteRow(fileID);
        });
        const fileStopButton = document.createElement('button');
        fileStopButton.id = `file-stop-button-${fileID}`;
        fileStopButton.textContent = 'Stop';
        fileStopButton.addEventListener('click', function () {
            sendEvent(fileID, 'stop');
            fileStopButton.style.display = 'none';
            fileDeleteButton.style.display = 'inline-block';
        });
        const fileActions = fileRow.querySelector('.file-actions');
        fileActions.appendChild(fileStopButton);
        fileActions.appendChild(fileDeleteButton);
        const fileProgressContainer = document.querySelector('#file-progress-container');
        fileProgressContainer.appendChild(fileRow);
        uploadFile(file, fileInput)
            .then(function (fileID) {
                sendEvent(fileID, 'upload');
            })
            .catch(function (error) {
                console.error(error);
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                fileRow.parentNode.removeChild(fileRow);
            });
    });
}

function handleFileDelete() {
    const fileDeleteButtons = document.querySelectorAll('.file-delete-button');
    fileDeleteButtons.forEach(function (fileDeleteButton) {
        fileDeleteButton.addEventListener('click', function () {
            const fileID = fileDeleteButton.id.split('-')[3];
            deleteRow(fileID);
        });
    });
}

function handleFileStop() {
    const fileStopButtons = document.querySelectorAll('.file-stop-button');
    fileStopButtons.forEach(function (fileStopButton) {
        fileStopButton.addEventListener('click', function () {
            const fileID = fileStopButton.id.split('-')[3];
            sendEvent(fileID, 'stop');
        });
    });
}

function handleFileEvents() {
    const fileEvents = ['upload', 'processing', 'text', 'video', 'audio', 'error'];
    fileEvents.forEach(function (event) {
        window.addEventListener(event, function (e) {
            const fileID = e.detail.file_id;
            const message = e.detail.message;

            if (event === 'upload') {
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                const fileActions = fileRow.querySelector('.file-actions');
                fileActions.style.display = 'flex';
                const fileStopButton = fileRow.querySelector('.file-stop-button');
                fileStopButton.style.display = 'inline-block';
            }

            if (event === 'processing') {
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                const fileActions = fileRow.querySelector('.file-actions');
                fileActions.style.display = 'none';
                const fileProgressText = fileRow.querySelector('.file-progress-text');
                fileProgressText.textContent = message;
            }

            if (event === 'text') {
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                const fileActions = fileRow.querySelector('.file-actions');
                fileActions.style.display = 'none';
                const fileText = document.querySelector(`#file-text-${fileID}`);
                fileText.textContent = message;
            }

            if (event === 'video') {
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                const fileActions = fileRow.querySelector('.file-actions');
                fileActions.style.display = 'none';
                const fileVideo = document.querySelector(`#file-video-${fileID}`);
                fileVideo.src = message;
                fileVideo.controls = true;
                fileVideo.play();
            }

            if (event === 'audio') {
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                const fileActions = fileRow.querySelector('.file-actions');
                fileActions.style.display = 'none';
                const fileAudio = document.querySelector(`#file-audio-${fileID}`);
                fileAudio.src = message;
                fileAudio.controls = true;
                fileAudio.play();
            }

            if (event === 'error') {
                const fileRow = document.querySelector(`#file-row-${fileID}`);
                const fileActions = fileRow.querySelector('.file-actions');
                fileActions.style.display = 'none';
                const fileError = document.querySelector(`#file-error-${fileID}`);
                fileError.textContent = message;
            }
        });
    });
}

