import { readFileSync } from 'fs';
import { join } from 'path';
import { program } from 'commander';
import { fetch } from 'undici';
import { sortBy, uniqBy } from 'lodash';
import { makeChangelog } from './utils';

interface ICompareOptions {
    version?: string;
    since?: string;
    preview?: boolean;
    force?: boolean;
}

const compareOptions = {
    version: 'v1.8.0',
    since: 'v1.7.0',
    preview: false,
    force: false,
};

program
    .option('-v, --version <version>', 'current version', compareOptions.version)
    .option('-s, --since <since>', 'since version', compareOptions.since)
    .option('--preview', 'generate preview changelog', compareOptions.preview)
    .option('--force', 'force generate changelog', compareOptions.force)
    .parse(process.argv);

interface ICompareItem {
    version: string;
    [key: string]: any;
}

const changelogData = JSON.parse(
    readFileSync(join(__dirname, 'CHANGELOG.json'), 'utf8'),
) as ICompareItem[];

const compareData = JSON.parse(
    readFileSync(join(__dirname, 'CHANGELOG_COMPARE.json'), 'utf8'),
) as ICompareItem[];

const currentVersion = program.opts().version;
const sinceVersion = program.opts().since;
const preview = program.opts().preview;
const force = program.opts().force;

const compareList = sortBy(
    compareData.filter((item) => item.version >= sinceVersion),
    'version',
);
const changelogList = sortBy(
    changelogData.filter((item) => item.version >= sinceVersion),
    'version',
);

const versionList = uniqBy(
    compareList.concat(changelogList),
    'version',
);

const compareItem = versionList.find((item) => item.version === currentVersion);
const changelogItem = versionList.find((item) => item.version === currentVersion);

if (!compareItem && !changelogItem) {
    console.log(`[ERROR] Version ${currentVersion} not found.`);
    process.exit(1);
}

let compareTemplate = '';
let changelogTemplate = '';
let changelogDetail = '';

(async function () {
    const { version, changelog, compare } = compareItem || changelogItem;

    const prefix = preview ? '# ' : '';

    compareTemplate = `${prefix}## ${version}\n`;
    changelogTemplate = `${prefix}## ${version}\n`;

    if (compare && compare.length) {
        compareTemplate += compare.join('\n');
    }

    if (changelog && changelog.length) {
        changelogTemplate += changelog.join('\n');
    }

    if (!changelogItem) {
        changelogDetail = await fetchChangelogDetail(version);
    }
})();

async function fetchChangelogDetail(version: string) {
    let changelogDetail = '';

    try {
        const { body } = await fetch(`https://api.github.com/repos/alibaba/Qwen/releases/tags/${version}`);

        const release = await body.json();

        changelogDetail += `**${version}**\n`;
        changelogDetail += `发布日期：${release.published_at}\n\n`;
        changelogDetail += release.body;
    } catch (error) {
        console.log(`[ERROR] Fetch changelog detail failed: ${error}`);
    }

    return changelogDetail;
}

const changelogTemplatePath = join(__dirname, 'CHANGELOG.md');
const changelogDetailPath = join(__dirname, 'CHANGELOG_DETAIL.md');

function writeChangelog() {
    let changelog = '';
    let changelogDetail = '';

    if (compareTemplate) {
        changelog += compareTemplate;
    }

    changelog += '\n';

    if (changelogTemplate) {
        changelog += changelogTemplate;
    }

    if (changelogItem) {
        changelogDetail += changelogDetail || changelogItem.changelogDetail || '';
    }

    changelogDetail = changelogDetail.replace(/#\s/g, '## ');

    const currentChangeLog = readFileSync(changelogTemplatePath, 'utf8');
    const currentChangeLogDetail = readFileSync(changelogDetailPath, 'utf8');

    changelog += currentChangeLog;
    changelogDetail += currentChangeLogDetail;

