import { createSlice } from '@reduxjs/toolkit';
import { API_URL } from '../constant';

const initialState = {
  messages: [],
  isLoading: false,
  error: null,
};

const chatSlice = createSlice({
  name: 'chat',
  initialState,
  reducers: {
    startLoading: (state) => {
      state.isLoading = true;
    },
    stopLoading: (state) => {
      state.isLoading = false;
    },
    setMessages: (state, action) => {
      state.messages = action.payload;
    },
    addMessage: (state, action) => {
      state.messages = [...state.messages, action.payload];
    },
    setError: (state, action) => {
      state.error = action.payload;
    },
  },
});

export const { startLoading, stopLoading, setMessages, addMessage, setError } =
  chatSlice.actions;

export const chatReducer = chatSlice.reducer;

export const sendMessage = (messageData) => async (dispatch) => {
  try {
    dispatch(startLoading());
    const response = await fetch(`${API_URL}/send_message`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(messageData),
    });
    const data = await response.json();

    if (!response.ok) {
      dispatch(setError(data.message));
      return;
    }

    dispatch(addMessage(data.message));
    dispatch(stopLoading());
  } catch (error) {
    dispatch(setError('An error occurred while sending the message.'));
  }
};

export const fetchMessages = (conversationId) => async (dispatch) => {
  try {
    dispatch(startLoading());
    const response = await fetch(`${API_URL}/fetch_messages/${conversationId}`);
    const data = await response.json();

    if (!response.ok) {
      dispatch(setError(data.message));
      return;
    }

    dispatch(setMessages(data.messages));
    dispatch(stopLoading());
  } catch (error) {
    dispatch(setError('An error occurred while fetching messages.'));
  }
};

export const addMessage = (message) => async (dispatch) => {
  try {
    const response = await fetch(`${API_URL}/add_message`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(message),
    });
    const data = await response.json();

    if (!response.ok) {
      dispatch(setError(data.message));
      return;
    }

    dispatch(addMessage(data.message));
  } catch (error) {
    dispatch(setError('An error occurred while adding the message.'));
  }
};

export const editMessage = (messageId, updatedMessage) => async (dispatch) => {
  try {
    const response = await fetch(`${API_URL}/edit_message/${messageId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(updatedMessage),
    });
    const data = await response.json();

    if (!response.ok) {
      dispatch(setError(data.message));
      return;
    }

    dispatch(addMessage(data.message));
  } catch (error) {
    dispatch(setError('An error occurred while editing the message.'));
  }
};

export const deleteMessage = (messageId) => async (dispatch) => {
  try {
    const response = await fetch(`${API_URL}/delete_message/${messageId}`, {
      method: 'DELETE',
    });
    const data = await response.json();

    if (!response.ok) {
      dispatch(setError(data.message));
      return;
    }

    dispatch(addMessage(data.message));
  } catch (error) {
    dispatch(setError('An error occurred while deleting the message.'));
  }
};

