const getFiles = async function (dir) {
  const files = await readdir(dir)
  const paths = files.map(function (file) {
    return path.resolve(dir, file)
  })

  const stats = await Promise.all(paths.map(stat))

  return paths
    .filter(function (path, index) {
      return stats[index].isFile()
    })
    .map(function (path) {
      return path.slice(dir.length + 1)
    })
}

