class DataObject(Schema):
    def __init__(self, values: Optional[Dict[str, Any]] = None, **kwargs):
        self._values = values or {}
        self._fields = self._get_fields()
        self._process_fields(kwargs)
        self._validate_values()

    def _validate_values(self) -> None:
        if self._values is None:
            return
        for field, value in self._values.items():
            if field not in self._fields:
                raise ValueError(f"Invalid field '{field}' in DataObject")
            field_info = self._fields[field]
            if field_info["required"] and value is None:
                raise ValueError(f"Field '{field}' is required but not provided in DataObject")
            if value is not None:
                self._validate_value(field, value)

    def _validate_value(self, field: str, value: Any) -> None:
        field_info = self._fields[field]
        if "type" in field_info:
            value_type = field_info["type"]
            if isinstance(value_type, list):
                if not isinstance(value, value_type):
                    raise ValueError(f"Invalid type for field '{field}'. Expected one of {value_type}, got {type(value)}")
            else:
                if not isinstance(value, value_type):
                    raise ValueError(f"Invalid type for field '{field}'. Expected {value_type}, got {type(value)}")
        if "schema" in field_info:
            if not isinstance(value, dict):
                raise ValueError(f"Invalid type for field '{field}'. Expected dict, got {type(value)}")
            schema = field_info["schema"]
            schema.validate(value)

    def _get_fields(self, obj: Optional[Any] = None, prefix: str = "") -> Dict[str, Any]:
        if obj is None:
            obj = self.__class__
        fields = {}
        for field_name, field_info in obj.__dict__.items():
            if isinstance(field_info, PropertyType):
                full_field_name = prefix + field_name
                if field_info.type is None:
                    fields[full_field_name] = {
                        "required": field_info.required,
                        "description": field_info.description,
                        "schema": field_info.schema,
                    }
                else:
                    fields[full_field_name] = {
                        "required": field_info.required,
                        "description": field_info.description,
                        "type": field_info.type,
                    }
                fields.update(self._get_fields(field_info.type, prefix=full_field_name + "."))
        return fields

    def _process_fields(self, kwargs: Dict[str, Any]) -> None:
        for field_name, field_info in self._fields.items():
            if "schema" in field_info and field_name in kwargs:
                field_info["schema"].validate(kwargs[field_name])

