#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>

#define PORT 8080
#define MAX_BUFFER_SIZE 1024
#define MAX_URL_SIZE 256
#define MAX_RESPONSE_SIZE 4096

struct Url {
    char url[MAX_URL_SIZE];
};

struct Url urls[10];

void init_urls() {
    strcpy(urls[0].url, "https://www.youtube.com/watch?v=dQw4w9WgXcQ");
    strcpy(urls[1].url, "https://www.youtube.com/watch?v=4eX8kXl40bA");
    strcpy(urls[2].url, "https://www.youtube.com/watch?v=7P6sO791x4A");
    strcpy(urls[3].url, "https://www.youtube.com/watch?v=y4fKxZ8V35A");
    strcpy(urls[4].url, "https://www.youtube.com/watch?v=6Jt5C6i5OaQ");
    strcpy(urls[5].url, "https://www.youtube.com/watch?v=QoYRd6iG1Co");
    strcpy(urls[6].url, "https://www.youtube.com/watch?v=7p5nDyP5sOQ");
    strcpy(urls[7].url, "https://www.youtube.com/watch?v=1UjA3d2lN5g");
    strcpy(urls[8].url, "https://www.youtube.com/watch?v=7Uz3t6mGQhA");
    strcpy(urls[9].url, "https://www.youtube.com/watch?v=4L5A3d2lN5g");
}

void generate_urls() {
    srand(time(NULL));
    int i;
    int num_urls = 5;
    printf("Generating %d random URLs:\n", num_urls);
    for (i = 0; i < num_urls; i++) {
        int index = rand() % 10;
        char url[MAX_URL_SIZE];
        strcpy(url, "https://www.youtube.com/watch?v=");
        strcat(url, urls[index].url);
        printf("%s\n", url);
    }
}

int main() {
    int server_fd, new_socket, valread;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[MAX_BUFFER_SIZE] = {0};

    init_urls();

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt failed");
        exit(EXIT_FAILURE);
    }

    // Bind socket to port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            exit(EXIT_FAILURE);
        }

        valread = read(new_socket, buffer, MAX_BUFFER_SIZE);
        printf("%s\n", buffer);

        int num_urls = 5;
        char urls[5][MAX_URL_SIZE];
        int i, j;
        int index[num_urls];
        for (i = 0; i < num_urls; i++) {
            index[i] = rand() % 10;
            strcpy(urls[i], "https://www.youtube.com/watch?v=");
            strcat(urls[i], urls[index[i]].url);
        }

        // Send generated URLs to client
        for (i = 0; i < num_urls; i++) {
            send(new_socket, urls[i], strlen(urls[i]), 0);
        }

        // Close the socket
        close(new_socket);
    }

    // Close the server socket
    close(server_fd);

    return 0;
}


