}

int rsa_decrypt(const char *private_key, int private_key_len, const char *encrypted_data, int encrypted_data_len,
                char *decrypted_data) {
    BIO *keybio = BIO_new_mem_buf(private_key, private_key_len);
    if (!keybio) {
        LOG_ERROR("BIO_new_mem_buf failed.");
        return -1;
    }

    EVP_PKEY *privkey = PEM_read_bio_RSAPrivateKey(keybio, NULL, NULL, NULL);
    if (!privkey) {
        LOG_ERROR("PEM_read_bio_RSAPrivateKey failed.");
        return -2;
    }

    RSA *rsa = EVP_PKEY_get1_RSA(privkey);
    int decrypted_len = RSA_private_decrypt(encrypted_data_len, (const unsigned char *)encrypted_data, (unsigned char *)decrypted_data,
                                            rsa, RSA_PKCS1_PADDING);
    if (decrypted_len < 0) {
        LOG_ERROR("RSA_private_decrypt failed.");
        return -3;
    }

    BIO_free(keybio);
    EVP_PKEY_free(privkey);
    RSA_free(rsa);
    return 0;
}

int rsa_encrypt(const char *public_key, int public_key_len, const char *data, int data_len, char *encrypted_data) {
    BIO *keybio = BIO_new_mem_buf(public_key, public_key_len);
    if (!keybio) {
        LOG_ERROR("BIO_new_mem_buf failed.");
        return -1;
    }

    EVP_PKEY *pubkey = PEM_read_bio_RSA_PUBKEY(keybio, NULL, NULL, NULL);
    if (!pubkey) {
        LOG_ERROR("PEM_read_bio_RSA_PUBKEY failed.");
        return -2;
    }

    RSA *rsa = EVP_PKEY_get1_RSA(pubkey);
    int encrypted_len = RSA_public_encrypt(data_len, (const unsigned char *)data, (unsigned char *)encrypted_data,
                                           rsa, RSA_PKCS1_PADDING);
    if (encrypted_len < 0) {
        LOG_ERROR("RSA_public_encrypt failed.");
        return -3;
    }

    BIO_free(keybio);
    EVP_PKEY_free(pubkey);
    RSA_free(rsa);
    return 0;
}

int base64_encode(const char *input, int input_len, char *output, int output_len) {
    BIO *bmem, *b64;
    BUF_MEM *bptr;

    b64 = BIO_new(BIO_f_base64());
    if (b64 == NULL) {
        LOG_ERROR("BIO_new failed.");
        return -1;
    }

    bmem = BIO_new(BIO_s_mem());
    if (bmem == NULL) {
        LOG_ERROR("BIO_new failed.");
        BIO_free(b64);
        return -2;
    }

    BIO_push(b64, bmem);
    BIO_write(b64, input, input_len);
    BIO_flush(b64);
    BIO_get_mem_ptr(b64, &bptr);

    if (bptr == NULL || bptr->length > output_len) {
        LOG_ERROR("BIO_get_mem_ptr failed.");
        BIO_free_all(b64);
        return -3;
    }

    memcpy(output, bptr->data, bptr->length);
    output[bptr->length] = '\0';

    BIO_free_all(b64);
    return bptr->length;
}

int base64_decode(const char *input, int input_len, char *output, int output_len) {
    BIO *b64, *bmem;

    b64 = BIO_new(BIO_f_base64());
    if (b64 == NULL) {
        LOG_ERROR("BIO_new failed.");
        return -1;
    }

    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
