    BIO_free_all(bmem);
    return 0;
}

int hex_encode(const char *input, int input_len, char *output, int output_len) {
    if (output_len < input_len * 2) {
        LOG_ERROR("hex_encode output buffer is too small.");
        return -1;
    }

    for (int i = 0; i < input_len; i++) {
        int c = input[i];
        output[i * 2] = "0123456789abcdef"[(c >> 4) & 0xf];
        output[i * 2 + 1] = "0123456789abcdef"[c & 0xf];
    }

    return input_len * 2;
}

