    # eg: 'train/000000000008.jpg' -> 'train/000000000008.txt'
    label_name = label_name.strip()
    if label_name.endswith('.jpg') or label_name.endswith('.png'):
        label_name = label_name.replace('.jpg', '.txt').replace('.png', '.txt')
    return label_name


def load_label(label_name, label_dir=None):
    # load label from label_name
    if label_dir is not None:
        label_name = label_name.replace(label_dir, '')
    label_name = load_label_from_name(label_name)
    label_name = Path(label_name)
    label_path = get_label_file(label_name)
    if label_path.is_file():
        with open(label_path, 'r') as f:
            label = f.read()
        if label == '':
            return []
        label = label.strip().split('\n')
        label = [line.split(' ') for line in label]
        label = [line for line in label if len(line) == 5]
        label = [[float(x) for x in line] for line in label]
        return label
    else:
        return []


