const { v4: uuidv4 } = require('uuid');
const { Location } = require('../models');

async function validateLocation(location) {
  if (!location || typeof location !== 'object') {
    throw new Error(`Invalid location: ${location}`);
  }

  if (!location.hasOwnProperty('name')) {
    throw new Error('Location missing required name property');
  }

  if (!location.hasOwnProperty('address')) {
    throw new Error('Location missing required address property');
  }

  if (!location.hasOwnProperty('phone')) {
    throw new Error('Location missing required phone property');
  }

  if (!location.hasOwnProperty('location')) {
    throw new Error('Location missing required location property');
  }

  if (
    !location.location.hasOwnProperty('lat') ||
    !location.location.hasOwnProperty('long')
  ) {
    throw new Error('Location missing required lat/long properties');
  }

  if (!location.hasOwnProperty('id')) {
    location.id = uuidv4();
  }

  location.createdAt = new Date();
  location.updatedAt = new Date();

  const existingLocation = await Location.findOne({
    where: {
      id: location.id,
    },
  });

  if (existingLocation) {
    throw new Error('Location ID already exists');
  }

  return location;
}

async function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new Error(`Invalid user: ${user}`);
  }

  if (!user.hasOwnProperty('name')) {
    throw new Error('User missing required name property');
  }

  if (!user.hasOwnProperty('email')) {
    throw new Error('User missing required email property');
  }

  if (!user.hasOwnProperty('phone')) {
    throw new Error('User missing required phone property');
  }

  if (!user.hasOwnProperty('location')) {
    throw new Error('User missing required location property');
  }

  if (
    !user.location.hasOwnProperty('lat') ||
    !user.location.hasOwnProperty('long')
  ) {
    throw new Error('User missing required lat/long properties');
  }

  if (!user.hasOwnProperty('id')) {
    user.id = uuidv4();
  }

  user.createdAt = new Date();
  user.updatedAt = new Date();

  const existingUser = await User.findOne({
    where: {
      id: user.id,
    },
  });

  if (existingUser) {
    throw new Error('User ID already exists');
  }

  return user;
}

async function validateFavorites(favorites) {
  if (!favorites || typeof favorites !== 'object') {
    throw new Error(`Invalid favorites: ${favorites}`);
  }

  if (!favorites.hasOwnProperty('users')) {
    throw new Error('Favorites missing required users property');
  }

  if (!favorites.hasOwnProperty('locations')) {
    throw new Error('Favorites missing required locations property');
  }

  if (!Array.isArray(favorites.users)) {
    throw new Error('Favorites users property must be an array');
  }

  if (!Array.isArray(favorites.locations)) {
    throw new Error('Favorites locations property must be an array');
  }

  for (const user of favorites.users) {
    await validateUser(user);
  }

  for (const location of favorites.locations) {
    await validateLocation(location);
  }

  return favorites;
}

