ChatMessage::ChatMessage(QJsonObject messageObject)
{
    messageId = messageObject.value("messageId").toString();
    role = messageObject.value("role").toString();
    content = messageObject.value("content").toString();
    parentMessageId = messageObject.value("parentMessageId").toString();
    type = messageObject.value("type").toInt();
    createTimestamp = messageObject.value("createTimestamp").toInt();
    updateTimestamp = messageObject.value("updateTimestamp").toInt();
}

ChatMessage::ChatMessage(QChatSession *session)
{
    if (session == nullptr) {
        return;
    }

    this->session = session;

    ChatbotMessage *chatbotMessage = session->getChatbotMessage();
    auto chatbotMessageObject = chatbotMessage->toJsonObject();
    messageId = chatbotMessageObject.value("messageId").toString();
    role = chatbotMessageObject.value("role").toString();
    content = chatbotMessageObject.value("content").toString();
    parentMessageId = chatbotMessageObject.value("parentMessageId").toString();
    type = chatbotMessageObject.value("type").toInt();
    createTimestamp = chatbotMessageObject.value("createTimestamp").toInt();
    updateTimestamp = chatbotMessageObject.value("updateTimestamp").toInt();
}

ChatMessage::ChatMessage(QChatSession *session, QString messageId)
{
    if (session == nullptr) {
        return;
    }

    this->session = session;

    ChatbotMessage *chatbotMessage = session->getChatbotMessage(messageId);
    auto chatbotMessageObject = chatbotMessage->toJsonObject();
    this->messageId = messageId;
    role = chatbotMessageObject.value("role").toString();
    content = chatbotMessageObject.value("content").toString();
    parentMessageId = chatbotMessageObject.value("parentMessageId").toString();
    type = chatbotMessageObject.value("type").toInt();
    createTimestamp = chatbotMessageObject.value("createTimestamp").toInt();
    updateTimestamp = chatbotMessageObject.value("updateTimestamp").toInt();
}

