QChatMessage::ChatMessageType ChatMessage::getChatMessageType()
{
    if (type == QChatSession::UserMessage) {
        return QChatMessage::User;
    }
    if (type == QChatSession::ChatbotMessage) {
        return QChatMessage::Chatbot;
    }
    if (type == QChatSession::ImageChatbotMessage) {
        return QChatMessage::ImageChatbot;
    }
    return QChatMessage::Unknown;
}

QString ChatMessage::toText()
{
    QString message;
    auto chatMessageType = getChatMessageType();
    if (chatMessageType == QChatMessage::User) {
        message.append("User: ");
    } else if (chatMessageType == QChatMessage::Chatbot) {
        message.append("Qwen: ");
    } else if (chatMessageType == QChatMessage::ImageChatbot) {
        message.append("Qwen: ");
    }

    message.append(content);

    return message;
}

QJsonObject ChatMessage::toJsonObject()
{
    QJsonObject chatMessageObject;
    chatMessageObject.insert("messageId", messageId);
    chatMessageObject.insert("role", role);
    chatMessageObject.insert("content", content);
    chatMessageObject.insert("parentMessageId", parentMessageId);
    chatMessageObject.insert("type", type);
    chatMessageObject.insert("createTimestamp", createTimestamp);
    chatMessageObject.insert("updateTimestamp", updateTimestamp);
    return chatMessageObject;
}
