#pragma once

#include "QwenChatGlobal.h"
#include "ChatMessage.h"

#include <QObject>
#include <QJsonObject>

class QChatSession;
class QChatMessage;

class QChatSessionPrivate;
class QWENCHATSHARED_EXPORT QChatSession : public QObject
{
    Q_OBJECT

    friend class QChatSessionPrivate;

public:
    enum ChatMessageType {
        Unknown = 0,
        UserMessage = 1,
        ChatbotMessage = 2,
        ImageChatbotMessage = 3
    };

    static const QString USER_MESSAGE;
    static const QString CHATBOT_MESSAGE;
    static const QString IMAGE_CHATBOT_MESSAGE;

    explicit QChatSession(const QString &sessionToken, QObject *parent = nullptr);
    ~QChatSession();

    QString getSessionToken() const;
    void setSessionToken(const QString &sessionToken);

    QString getChatbotReply() const;
    void setChatbotReply(const QString &chatbotReply);

    QString getRequestId() const;
    void setRequestId(const QString &requestId);

    QString getQuestion() const;
    void setQuestion(const QString &question);

    QJsonObject getUserMessageObject() const;
    QJsonObject getChatbotMessageObject() const;

    QJsonObject getUserMessageObject(const QString &messageId) const;
    QJsonObject getChatbotMessageObject(const QString &messageId) const;

    ChatMessage *getUserMessage() const;
    ChatMessage *getChatbotMessage() const;

    ChatMessage *getUserMessage(const QString &messageId) const;
    ChatMessage *getChatbotMessage(const QString &messageId) const;

    void addQuestion(const QString &question);
    void addAnswer(const QString &answer);
    void addImage(const QString &imageBase64);

    void clear();

    void save();

signals:
    void requestMessage(QJsonObject &requestMessage);
    void replyMessage(QJsonObject &replyMessage);

public slots:
    bool request(const QString &sessionToken, const QJsonObject &requestMessage);

private slots:
    void onRequestMessage(QJsonObject &requestMessage);
    void onReplyMessage(QJsonObject &replyMessage);

private:
    QChatSessionPrivate *d;
};

Q_DECLARE_METATYPE(QChatSession *)
Q_DECLARE_METATYPE(QChatSession::ChatMessageType)
Q_DECLARE_METATYPE(QJsonObject)
Q_DECLARE_METATYPE(QChatMessage *)
Q_DECLARE_METATYPE(QChatMessage::ChatMessageType)

inline QJsonObject QChatSession::getUserMessageObject() const
{
    return getUserMessageObject(getRequestId());
}

inline QJsonObject QChatSession::getChatbotMessageObject() const
{
    return getChatbotMessageObject(getRequestId());
}

inline ChatMessage *QChatSession::getUserMessage() const
{
    return getUserMessage(getRequestId());
}

inline ChatMessage *QChatSession::getChatbotMessage() const
{
    return getChatbotMessage(getRequestId());
}

inline void QChatSession::addQuestion(const QString &question)
{
    QJsonObject userMessageObject = getUserMessageObject();
    userMessageObject.insert("question", question);
    setUserMessageObject(userMessageObject);
}

inline void QChatSession::addAnswer(const QString &answer)
{
    QJsonObject chatbotMessageObject = getChatbotMessageObject();
    chatbotMessageObject.insert("answer", answer);
    setChatbotMessageObject(chatbotMessageObject);
}

inline void QChatSession::addImage(const QString &imageBase64)
{
    QJsonObject chatbotMessageObject = getChatbotMessageObject();
    chatbotMessageObject.insert("image", imageBase64);
    setChatbotMessageObject(chatbotMessageObject);
}

inline void QChatSession::clear()
{
    setQuestion("");
    setChatbotReply("");
    setUserMessageObject(QJsonObject());
    setChatbotMessageObject(QJsonObject());
}

inline void QChatSession::save()
{
    clear();

    QJsonObject userMessageObject = getUserMessageObject();
    userMessageObject.insert("question", getQuestion());
    QJsonObject chatbotMessageObject = getChatbotMessageObject();

