package com.qwenlp.chatgpt.api;

import com.qwenlp.chatgpt.config.Config;
import com.qwenlp.chatgpt.chat.ChatRequest;
import com.qwenlp.chatgpt.chat.ChatResponse;
import com.qwenlp.chatgpt.chat.Message;
import com.qwenlp.chatgpt.chat.Message.Role;
import com.qwenlp.chatgpt.common.ErrorResponse;
import com.qwenlp.chatgpt.common.HttpResponse;
import com.qwenlp.chatgpt.common.ParameterMap;
import com.qwenlp.chatgpt.common.RequestException;
import com.qwenlp.chatgpt.utils.HttpUtils;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.apache.http.HttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.client.methods.HttpRequestBase;
import org.apache.http.util.EntityUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * ChatGPT API
 *
 * @author zhanghao
 */
@Slf4j
public class ChatGPT {

    static final Logger logger = LoggerFactory.getLogger(ChatGPT.class);

    // API KEY
    private final String apiKey;

    // MODEL
    private final String model;

    // BLOCKING
    private final Boolean blocking;

    // ENDPOINT URL
    private final String url;

    // Chat History
    private final List<Message> chatHistory;

    // CONSTRUCTOR
    public ChatGPT(String apiKey, String model) {
        this(apiKey, model, false);
    }

    public ChatGPT(String apiKey, String model, Boolean blocking) {
        this(apiKey, model, blocking, Config.getDefaultURL());
    }

    public ChatGPT(String apiKey, String model, Boolean blocking, String url) {
        this.apiKey = apiKey;
        this.model = model;
        this.blocking = blocking;
        this.url = url;
        this.chatHistory = new ArrayList<>();
    }

    public ChatResponse chat(String prompt, String id) {
        return chat(prompt, id, 3000);
    }

    public ChatResponse chat(String prompt, String id, int timeout) {
        return chat(prompt, id, timeout, false);
    }

    public ChatResponse chat(String prompt, String id, Boolean stream) {
        return chat(prompt, id, 3000, stream);
    }

    public ChatResponse chat(String prompt, String id, int timeout, Boolean stream) {
        // Create a new chat request
        ChatRequest request = ChatRequest.builder()
            .id(id)
            .model(model)
            .timeout(timeout)
            .stream(stream)
            .prompt(prompt)
            .build();

        // Notify the user about the request
        logger.info("Sending request. Prompt: {}", prompt);
        logger.info("Request: {}", request);

        // Send the request and get the response
        HttpResponse response = sendRequest(request);

        // Parse the response
        ChatResponse chatResponse = parseResponse(response);

        // Notify the user about the response
        if (chatResponse != null) {
            logger.info("Response: {}", chatResponse);
        } else {
            logger.error("Response parsing error");
        }

        // Return the response
        return chatResponse;
    }

    /**
     * Sends a request to the ChatGPT API and returns the response.
     *
     * @param request the request to send
     * @return the response from the API
     */
    private HttpResponse sendRequest(ChatRequest request) {
        try {
            // Create a POST request with the appropriate headers and body
            HttpPost requestBase = new HttpPost(url);
            requestBase.setHeader("Content-Type", "application/json");
            requestBase.setHeader("Authorization", "Bearer " + apiKey);
            requestBase.setHeader("User-Agent", "Qwen");
            requestBase.setHeader("X-User-Agent", "Qwen");
            requestBase.setEntity(request.toEntity());

            // Execute the request and get the response
            HttpResponse response = HttpUtils.executeRequest(requestBase, blocking);

            // Log the response
            logger.info("Response: {}", response);

            // Return the response
            return response;
        } catch (Exception e) {
            // Log the error
            logger.error("Error sending request", e);

            // Throw an exception indicating that the request failed
            throw new RequestException(e);
        }
    }

    /**
     * Parses the response from the ChatGPT API and returns the ChatResponse object.
     *
     * @param response the response to parse
     * @return the ChatResponse object
     */
    private ChatResponse parseResponse(HttpResponse response) {
        // Create a new ChatResponse object with default values
        ChatResponse chatResponse = ChatResponse.builder().build();

        try {
            // If the response is successful (status code 200)
            if (response.getStatusCode() == 200) {
                // Create a new Message object with the assistant's role and the generated text
                Message message = Message.builder()
                    .role(Role.ASSISTANT)
                    .content(getGeneratedText(response))
                    .build();
                // Add the message to the chat history
                chatHistory.add(message);
                // Set the ChatResponse object to the message
                chatResponse.setMessage(message);
            } else {
                // Create a new ErrorResponse object with the error message from the response
                ErrorResponse errorResponse = ErrorResponse.fromJSON(EntityUtils.toString(response.getEntity()));
                // Set the ChatResponse object to the error response
                chatResponse = ChatResponse.builder()
                    .status(response.getStatusCode())
                    .errorMessage(errorResponse.getMessage())
                    .build();
            }
        } catch (Exception e) {
            // Log the error
            logger.error("Error parsing response", e);
        }

        // Return the ChatResponse object
        return chatResponse;
    }

    /**
     * Retrieves the generated text from the response.
     *
     * @param response the response to parse
     * @return the generated text
     */
    private String getGeneratedText(HttpResponse response) {
        try {
            // Parse the response as a JSON object and get the "choices" array
            ParameterMap<String, Object> responseJson = ParameterMap.fromJSON(EntityUtils.toString(response.getEntity()));
            List<ParameterMap<String, Object>> choices = responseJson.getList("choices");

            // If there are no choices, return the text from the first message in the history
            if (choices == null || choices.isEmpty()) {
                if (chatHistory.isEmpty()) {
                    return null;
                } else {
                    return chatHistory.get(0).getContent();
                }
            }

            // Get the text from the first choice's "text" field
            String generatedText = choices.get(0).getString("message.content");

            // If the text is empty, return the text from the first message in the history
            if (StringUtils.isEmpty(generatedText)) {
                if (chatHistory.isEmpty()) {
                    return null;
                } else {
                    return chatHistory.get(0).getContent();
                }
            }

            // Return the generated text
            return generatedText;
        } catch (Exception e) {
            // Log the error
            logger.error("Error getting generated text", e);

            // Throw an exception indicating that the generated text could not be retrieved
            throw new RequestException("Failed to get generated text");
        }
    }

    @Override
    public String toString() {
        return "ChatGPT{" +
            "apiKey='" + apiKey + '\'' +
            ", model='" + model + '\'' +
            ", blocking=" + blocking +
            ", url='" + url + '\'' +
            ", chatHistory=" + chatHistory +
            '}';
    }

    public static void main(String[] args) {
        // Get the API key and model from the command-line arguments
        String apiKey = args[0];
        String model = args[1];

        // Create a new ChatGPT object with the API key and model
        ChatGPT chatGPT = new ChatGPT(apiKey, model);

        // Create a new message with the user's name and a prompt
        Message message = Message.builder()
            .role(Role.USER)
            .content("Yo, Qwen. What's up?")
            .build();

        // Add the message to the chat history
        chatGPT.chatHistory.add(message);

        // Chat with the user and print the response
        ChatResponse chatResponse = chatGPT.chat(message.getContent(), UUID.randomUUID().toString(), true);
        System.out.println(chatResponse.getMessage().getContent());
    }
}
