package com.alibaba.search.ai.demo.qa;

import com.alibaba.search.ai.demo.qa.model.QuestionAnsweringRequest;
import com.alibaba.search.ai.demo.qa.model.QuestionAnsweringResponse;
import com.alibaba.search.ai.demo.qa.model.QuestionAnsweringResult;
import org.apache.http.HttpEntity;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class QaDemo {

    private static final String QA_URL = "http://your_service_url";

    private static final String QUESTION = "What is the capital of France?";

    public static void main(String[] args) {
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            // Prepare the request payload
            List<String> contexts = Arrays.asList(
                    "The capital of France is Paris.",
                    "The capital of Spain is Madrid.",
                    "The capital of Italy is Rome."
            );
            QuestionAnsweringRequest request = new QuestionAnsweringRequest(QUESTION, contexts);

            // Execute the request and get the response
            HttpPost httpPost = new HttpPost(QA_URL);
            httpPost.setHeader("Content-Type", "application/json");
            httpPost.setEntity(new StringEntity(request.toJson()));

            try (CloseableHttpResponse response = httpClient.execute(httpPost)) {
                HttpEntity entity = response.getEntity();
                String responseBody = EntityUtils.toString(entity);

                // Convert the response to a QuestionAnsweringResponse object
                QuestionAnsweringResponse responseObj = QuestionAnsweringResponse.fromJson(responseBody);

                // Extract the question answering results from the response
                List<QuestionAnsweringResult> results = responseObj.getResults();

                // Process the question answering results
                for (QuestionAnsweringResult result : results) {
                    System.out.println("Answer: " + result.getText());
                    System.out.println("Confidence: " + result.getConfidence());
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
