import { OpenAI, QwenConfig } from "./openai";
import { QwenMessage, QwenMessageError } from "./llm-qwen-message";
import { QwenHistory } from "./llm-qwen-history";

export interface QwenResponse {
  choices: QwenChoice[];
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface QwenChoice {
  index: number;
  message: {
    role: string;
    content: string;
  };
  finish_reason: string;
}

export class QwenError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "QwenError";
  }
}

export class Qwen extends OpenAI {
  config: QwenConfig;

  constructor(config: QwenConfig) {
    super(config.apiHost, config.apiKey);
    this.config = config;
  }

  async message(content: string, history: QwenHistory) {
    try {
      const messages = history.search(content);
      const messagesContent = messages.map((m) => m.content).join("\n");
      const messagesRole = messages.map((m) => m.role).join("\n");

      const result = await this.completion({
        model: this.config.model,
        messages: [
          {
            role: "system",
            content: messagesContent,
          },
          {
            role: "user",
            content,
          },
        ],
        temperature: this.config.temperature,
        top_p: this.config.top_p,
        top_k: this.config.top_k,
        max_tokens: this.config.max_tokens,
      });

      this.log(result);

      return {
        content: result.choices[0].message.content,
        history: messagesRole + result.choices[0].message.content,
      };

