<?php

declare(strict_types=1);

namespace Qwen\Qwen\Kernel;

use Qwen\Qwen\Contracts\QwenClientInterface;
use Qwen\Qwen\Contracts\QwenKernelInterface;
use Qwen\Qwen\Enums\Model;
use Qwen\Qwen\Exceptions\QwenException;
use Qwen\Qwen\Request\ChatRequest;
use Qwen\Qwen\Response\ChatResponse;
use Qwen\Qwen\Response\ChatStreamResponse;

class ChatStreamKernel extends StreamKernel implements QwenKernelInterface
{
    protected string $streamUrl = 'https://api.qwen.tech/api/chat-stream';

    public function __construct(QwenClientInterface $client, string $model = Model::QWEN_1B)
    {
        parent::__construct($client, $model);
    }

    public function ask(array $messages, array $options = []): ChatStreamResponse
    {
        $request = new ChatRequest($messages, $options);
        $this->validateRequest($request);

        $requestParams = $this->getRequestParams();

        $options = array_merge($request->toChatCompletionRequestOptions(), $requestParams);

        $response = $this->client->post($this->streamUrl, $options);

        if ($response->getStatusCode() !== 200) {
            throw new QwenException($response->getBody()->getContents());
        }

        return new ChatStreamResponse($response->getBody());
    }

    private function getRequestParams(): array
    {
        $params = [
            'raw' => true,
            'model' => $this->model,
        ];

        if ($this->temperature) {
            $params['temperature'] = $this->temperature;
        }

        if ($this->topP) {
            $params['top_p'] = $this->topP;
        }

        if ($this->maxTokens) {
            $params['max_tokens'] = $this->maxTokens;
        }

        if ($this->presencePenalty) {
            $params['presence_penalty'] = $this->presencePenalty;
        }

        if ($this->frequencyPenalty) {
            $params['frequency_penalty'] = $this->frequencyPenalty;
        }

        if ($this->stop) {
            $params['stop'] = $this->stop;
        }

        if ($this->user) {
            $params['user'] = $this->user;
        }

        if ($this->logitBias) {
            $params['logit_bias'] = $this->logitBias;
        }

        if ($this->stream) {
            $params['stream'] = $this->stream;
        }

        return $params;
    }

    protected function validateRequest(ChatRequest $request): void
    {
        $model = $request->model();

        if ($model !== Model::QWEN_1B) {
            throw new QwenException(sprintf('Model "%s" is not supported for chat stream kernel', $model));
        }

        parent::validateRequest($request);
    }

    public function message(string $content, string $role = 'user'): Message
    {
        return new Message($content, $role);
    }

    public function user(string $content): Message
    {
        return new Message($content, 'user');
    }

    public function system(string $content): Message
    {
        return new Message($content, 'system');
    }

    public function assistant(string $content): Message
    {
        return new Message($content, 'assistant');
    }

    public function functionCall(string $name, array $arguments = []): Message
    {
        return new Message(['name' => $name, 'arguments' => json_encode($arguments)], 'function_call');
    }

    public function isStreaming(): bool
    {
        return true;
    }

    public function streamUrl(): string
    {
        return $this->streamUrl;
    }

    public function stream(): QwenKernelInterface
    {
        return $this;
    }

    public function stop(array|string $sequence): self
    {
        if (is_array($sequence)) {
            $sequence = implode(',', $sequence);
        }

        $this->stop = $sequence;

        return $this;
    }

    public function maxTokens(int $maxTokens): self
    {
        $this->maxTokens = $maxTokens;

        return $this;
    }

    public function temperature(float $temperature): self
    {
        $this->validateTemperature($temperature);

        $this->temperature = $temperature;

        return $this;
    }

    public function topP(float $topP): self
    {
        $this->validateTopP($topP);

        $this->topP = $topP;

        return $this;
    }

    public function presencePenalty(float $presencePenalty): self
    {
        $this->validatePresencePenalty($presencePenalty);

        $this->presencePenalty = $presencePenalty;

        return $this;
    }

    public function frequencyPenalty(float $frequencyPenalty): self
    {
        $this->validateFrequencyPenalty($frequencyPenalty);

        $this->frequencyPenalty = $frequencyPenalty;

        return $this;
    }

    public function logitBias(array $logitBias): self
    {
        $this->validateLogitBias($logitBias);

        $this->logitBias = $logitBias;

        return $this;
    }

    public function stream(string $url): self
    {
        $this->streamUrl = $url;

        return $this;
    }

    public function user(string $user): self
    {
        $this->user = $user;

        return $this;
    }

    public function reset(): self
    {
        parent::reset();

        $this->stream = true;

        return $this;
    }

    protected function canReset(): bool
    {
        return true;
    }
}
