  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleTyping = () => {
    if (!isTyping) {
      setIsTyping(true);
    } else {
      setIsTyping(false);
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    const emitTypingEvent = () => {
      if (isTyping) {
        socket.emit("typing", true);
      } else {
        socket.emit("typing", false);
      }
    };

    const handleTypingEvent = (data) => {
      setStatus(data ? "User is typing..." : "");
    };

    socket.on("typing", handleTypingEvent);

    return () => {
      socket.off("typing", handleTypingEvent);
    };
  }, [isTyping]);

  useEffect(() => {
    if (messages.length > 0) {
      scrollToBottom();
    }
  }, [messages]);

  useEffect(() => {
    if (currentMsg && assistantMsgs.length > 0) {
      const index = assistantMsgs.length - 1;
      const lastAssistantMessage = assistantMsgs[index];

      if (index > 0) {
        const prevAssistantMessage = assistantMsgs[index - 1];
        if (prevAssistantMessage.content !== lastAssistantMessage.content) {
          setAssistantMsgs(assistantMsgs.slice(0, index));
          setCurrentMsg(lastAssistantMessage.content);
        }
      }
    }
  }, [currentMsg, assistantMsgs]);

  useEffect(() => {
    if (currentMsg) {
      const timeout = setTimeout(() => {
        setAssistantMsgs([...assistantMsgs, { content: currentMsg }]);
        setCurrentMsg("");
      }, 1000); // Adjust the delay as needed

      return () => clearTimeout(timeout);
    }
  }, [currentMsg, assistantMsgs]);

  useEffect(() => {
    const updateAssistantMsgs = (data) => {
      const assistantMessage = data.choices[0]?.message;
      if (assistantMessage) {
        const content = assistantMessage.content;
        if (content.startsWith("```")) {
          const lines = content.split("\n");
          const codeLines = lines.slice(1, lines.length - 1);
          const code = codeLines.join("\n");
          const formattedContent = `\`\`\`${assistantMessage.content.split("```")[1]}\n${code}\n\`\`\``;
          setCurrentMsg(formattedContent);
        } else {
          setCurrentMsg(content);
        }
      }
    };

    socket.on("assistantMessage", updateAssistantMsgs);

    return () => {
      socket.off("assistantMessage", updateAssistantMsgs);
    };
  }, [currentMsg]);

  return (
    <div className="container">
      <div className="main">
        <Sidebar activeRoute={activeRoute} />
        <div className="main-content">
          <div className="chat-box">
            {messages.map((message, index) => (
              <Chat
                key={index}
                message={message}
                showUser={message.role === "user"}
                showAssistant={message.role === "assistant"}
                status={status}
                currentMsg={currentMsg}
              />
            ))}
          </div>
          <div className="input-box">
            <textarea
              ref={inputRef}
              value={inputValue}
              onChange={handleInputChange}
              onKeyDown={handleKeyDown}
              placeholder="Type a message..."
            />
            <div className="input-buttons">
              <Button
                id="send-button"
                variant="contained"
                color="primary"
                onClick={handleSendMessage}
                disabled={loading}
              >
                Send
              </Button>
              <Button
                id="typing-button"
                variant="outlined"
                color="primary"
                onClick={handleTyping}
              >
                {isTyping ? "Stop Typing" : "Start Typing"}
              </Button>
              <div ref={messagesEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Qwen;
