import { useLocation } from "react-router-dom";
import { Settings } from "./Settings";
import "./App.css";

export const App = () => {
  const location = useLocation();
  return (
    <div className="app">
      {location.pathname === "/" ? (
        <div className="content">
          <h1>Welcome to Qwen</h1>
          <p>Qwen is an innovative AI chatbot that provides intelligent and helpful responses to your queries.</p>
          <p>Feel free to ask Qwen anything you'd like!</p>
        </div>
      ) : location.pathname === "/settings" ? (
        <Settings />
      ) : (
        <div className="content">
          <h1>Oops! Page Not Found</h1>
          <p>The page you're looking for might have been moved or deleted.</p>
          <p>Please check the URL and try again.</p>
        </div>
      )}
    </div>
  );
};

