st.table(pos_table)

def ner(nlp, sentence):
    doc = nlp(sentence)
    return [(ent.text, ent.label_) for ent in doc.ents]

st.subheader("Named Entity Recognition")
sentence = st.text_input("Enter a sentence", "This is not a threat")
ner_table = pd.DataFrame(ner(nlp, sentence), columns=['Word', 'NER'])
st.table(ner_table)

def threat_detection(sentence):
    doc = nlp(sentence)
    threat = False
    for ent in doc.ents:
        if ent.label_ == "THREAT":
            threat = True
    return threat

