use crate::lib::*;

pub trait Tokenizer: Send + Sync {
    fn tokenize(&self, text: &str) -> Vec<u64>;
    fn detokenize(&self, tokens: &[u64]) -> String;
}

pub fn get_tokenizer(kind: TokenizerKind, model: &Model) -> Result<Box<dyn Tokenizer>> {
    match kind {
        TokenizerKind::Mecab => MecabTokenizer::new(model),
        TokenizerKind::SpaCy => SpaCyTokenizer::new(model),
        TokenizerKind::SentencePiece => SentencePieceTokenizer::new(model),
        TokenizerKind::Simple => SimpleTokenizer::new(model),
        TokenizerKind::GPT2 => GPT2Tokenizer::new(model),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TokenizerKind {
    Mecab,
    SpaCy,
    SentencePiece,
    Simple,
    GPT2,
}

pub struct MecabTokenizer {
    model: Model,
}

impl MecabTokenizer {
    pub fn new(model: &Model) -> Result<Box<Self>> {
        Ok(Box::new(Self { model: model.clone() }))
    }
}

impl Tokenizer for MecabTokenizer {
    fn tokenize(&self, text: &str) -> Vec<u64> {
        let mecab = match self.model {
            Model::Japanese => mecab::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = mecab.tokenize(text);
        tokens
            .into_iter()
            .map(|token| self.model.token2id(token))
            .collect()
    }

    fn detokenize(&self, tokens: &[u64]) -> String {
        let tokens = tokens.iter().map(|token| self.model.id2token(*token)).collect::<Vec<String>>();
        let mecab = match self.model {
            Model::Japanese => mecab::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = mecab.detokenize(tokens);
        tokens
    }
}

pub struct SpaCyTokenizer {
    model: Model,
}

impl SpaCyTokenizer {
    pub fn new(model: &Model) -> Result<Box<Self>> {
        Ok(Box::new(Self { model: model.clone() }))
    }
}

impl Tokenizer for SpaCyTokenizer {
    fn tokenize(&self, text: &str) -> Vec<u64> {
        let spacy = match self.model {
            Model::English => spacy::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = spacy.tokenize(text);
        tokens
            .into_iter()
            .map(|token| self.model.token2id(token))
            .collect()
    }

    fn detokenize(&self, tokens: &[u64]) -> String {
        let tokens = tokens.iter().map(|token| self.model.id2token(*token)).collect::<Vec<String>>();
        let spacy = match self.model {
            Model::English => spacy::Model::new(),
            _ => panic!("Tokenizer not支持"),
        };
        let tokens = spacy.detokenize(tokens);
        tokens
    }
}

pub struct SentencePieceTokenizer {
    model: Model,
}

impl SentencePieceTokenizer {
    pub fn new(model: &Model) -> Result<Box<Self>> {
        Ok(Box::new(Self { model: model.clone() }))
    }
}

impl Tokenizer for SentencePieceTokenizer {
    fn tokenize(&self, text: &str) -> Vec<u64> {
        let sp = match self.model {
            Model::Chinese => sentencepiece::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = sp.tokenize(text);
        let tokens = tokens.iter().map(|token| token.piece).collect::<Vec<String>>();
        tokens
            .into_iter()
            .map(|token| self.model.token2id(token))
            .collect()
    }

    fn detokenize(&self, tokens: &[u64]) -> String {
        let tokens = tokens.iter().map(|token| self.model.id2token(*token)).collect::<Vec<String>>();
        let sp = match self.model {
            Model::Chinese => sentencepiece::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = sp.detokenize(tokens);
        tokens
    }
}

pub struct GPT2Tokenizer {
    model: Model,
}

impl GPT2Tokenizer {
    pub fn new(model: &Model) -> Result<Box<Self>> {
        Ok(Box::new(Self { model: model.clone() }))
    }
