impl Tokenizer for GPT2Tokenizer {
    fn tokenize(&self, text: &str) -> Vec<u64> {
        let tokenizer = match self.model {
            Model::English => gpt2_tokenizer::Model::new(),
            Model::Japanese => gpt2_tokenizer::Model::new(),
            Model::Chinese => gpt2_tokenizer::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = tokenizer.tokenize(text);
        tokens
    }

    fn detokenize(&self, tokens: &[u64]) -> String {
        let tokenizer = match self.model {
            Model::English => gpt2_tokenizer::Model::new(),
            Model::Japanese => gpt2_tokenizer::Model::new(),
            Model::Chinese => gpt2_tokenizer::Model::new(),
            _ => panic!("Tokenizer not supported"),
        };
        let tokens = tokens.iter().map(|token| self.model.id2token(*token)).collect::<Vec<String>>();
        let tokens = tokenizer.detokenize(tokens);
        tokens
    }
}

