import bcrypt from 'bcryptjs'

export const hash = (value, saltRounds) => {
  const passwordHash = bcrypt.hashSync(value, saltRounds)
  return passwordHash
}

export const compare = function (value, hash) {
  const isMatch = bcrypt.compareSync(value, hash)
  return isMatch
}

export const genSalt = async () => {
  const saltRounds = 10
  const salt = await bcrypt.genSalt(saltRounds)
  return salt
}

export const getHashPassword = async (password) => {
  const salt = await genSalt()
  const hash = await hash(password, salt)
  return hash
