import { Collection, Db, ObjectId, IndexDescription } from 'mongodb';
import { CommonRepository } from './common_repository';
import { Document, Filter } from 'mongodb';
import { LocalCache } from './local_cache';
import { Logger } from './logger';
import { emit } from './event';
import { App } from '../app';

export abstract class Repository<T extends Document> extends CommonRepository<T> {
  protected _collection: Collection<T>;
  private readonly _name: string;
  protected _cache: LocalCache<T>;
  protected _logger: Logger;

  constructor(db: Db, name: string, indexes: IndexDescription[]) {
    super();
    this._name = name;
    this._collection = db.collection(name);
    this._cache = LocalCache.getInstance();
    this._logger = Logger.getInstance();
    this._logger.notice(`Init ${name} Collection`);

    if (process.env.NODE_ENV === 'development') {
      for (const idx of indexes) {
        this._logger.notice(`Init ${name} Index ${JSON.stringify(idx)}`);
        this._collection.createIndex(idx);
      }
    }
    emit('db.initialized');
  }

  protected abstract toData(doc: T): T;

  init(app: App) {
    this._cache.init(app.getCache());
  }

  async find(filter: Filter<T>) {
    const rs = await this._collection.find(filter);
    const res = await rs.toArray();
    if (!res) return;
    const data = res.map((doc) => this.toData(doc));
    await this._cache.setMany(data);
    return data;
  }

  async upsert(id: ObjectId, data: Partial<T>) {
    const res = await this._collection.updateOne(
      { _id: id },
      { $set: data },
      { upsert: true }
    );
    if (res.upsertedCount > 0) {
      const doc = await this._collection.findOne({ _id: id });
      await this._cache.set(this.toData(doc));
      return this.toData(doc);
    }
    return this.toData(await this._collection.findOne({ _id: id }));
  }

  async findAndRemove(filter: Filter<T>) {
    const res = await this._collection.findOneAndDelete(filter);
    if (!res) return;
    await this._cache.deleteOne(res._id);
    return this.toData(res);
  }

  async deleteOne(id: ObjectId) {
    const res = await this._collection.deleteOne({ _id: id });
    if (!res) return;
    await this._cache.deleteOne(id);
    return res;
  }

  async deleteMany(filter: Filter<T>) {
    const res = await this._collection.deleteMany(filter);
    if (!res) return;
    const deleted = this._cache.getMany(filter as Filter<T>);
    await this._cache.deleteMany(deleted.map((doc) => doc._id));
    return res;
  }

  async findMany(filter: Filter<T>) {
    const rs = await this._collection.find(filter);
    const res = await rs.toArray();
    if (!res) return;
    const data = res.map((doc) => this.toData(doc));
    await this._cache.setMany(data);
    return data;
  }

  async findAndUpdate(filter: Filter<T>, update: Document) {
    const res = await this._collection.findOneAndUpdate(filter, update);
    if (!res) return;
    await this._cache.set(res);
    return res;
  }

  async findById(id: ObjectId) {
    const res = await this._collection.findOne({ _id: id });
    if (!res) return;
    const data = this.toData(res);
    await this._cache.set(data);
    return data;
  }
}
