import { getAuthSelector } from 'app/redux/auth';
import { TextButton } from 'app/components';
import { getMyCitiesSelector, deleteCity } from '../../../redux/my';
import { cities } from '../../../data';
import { Colors } from '../../../config';
import CityItem from './CityItem';

class MyCitiesScreen extends Component {
  static navigationOptions = {
    title: 'My cities',
  };

  onAddCityPress() {
    this.props.navigation.navigate('AddCity');
  }

  onCityPress(item) {
    this.props.navigation.navigate('City', { city: item });
  }

  render() {
    const { myCities, auth } = this.props;
    return (
      <View style={styles.wrapper}>
        <View style={styles.container}>
          <FlatList
            data={myCities}
            renderItem={({ item }) => (
              <TouchableWithoutFeedback onPress={() => this.onCityPress(item)}>
                <View style={styles.cityItem}>
                  <Text style={styles.cityName}>{item.name}</Text>
                </View>
              </TouchableWithoutFeedback>
            )}
            keyExtractor={item => item.name}
          />
          <TextButton
            text="Add city"
            onPress={() => this.onAddCityPress()}
            disabled={!auth.isLoggedIn}
          />
        </View>
      </View>
    );
  }
}

const styles = StyleSheet.create({
  wrapper: {
    flex: 1,
    backgroundColor: Colors.white,
  },
  container: {
    flex: 1,
    paddingHorizontal: 16,
  },
  cityItem: {
    paddingVertical: 16,
  },
  cityName: {
    fontSize: 16,
    color: Colors.black,
  },
});

const mapStateToProps = state => ({
  myCities: getMyCitiesSelector(state),
  auth: getAuthSelector(state),
});

const mapDispatchToProps = dispatch => ({
  deleteCity: city => dispatch(deleteCity(city)),
});

export default connect(mapStateToProps, mapDispatchToProps)(MyCitiesScreen);
export { MyCitiesScreen };
export type { Props as MyCitiesScreenProps, State as MyCitiesScreenState };
