import logging
import traceback
from concurrent.futures import ThreadPoolExecutor
from time import sleep

from flask import Flask, request

from qwen_remote_api import config as remote_config
from qwen_remote_api.model import ModelSpec
from qwen_remote_api.plugins.plugin import Plugin
from qwen_remote_api.plugins.qwen_remote_server import QwenRemoteServerPlugin

logger = logging.getLogger(__name__)


class QwenRemoteServerPluginManager:
    def __init__(self):
        self.plugins: list[QwenRemoteServerPlugin] = []
        self.executor = ThreadPoolExecutor(max_workers=100)
        self._thread_running = False
        self._thread = None

    def load_qwen_remote_server_plugin(self, plugin: QwenRemoteServerPlugin):
        if plugin in self.plugins:
            return
        self.plugins.append(plugin)
        self.executor.submit(plugin.load)

    def unload_qwen_remote_server_plugin(self, plugin: QwenRemoteServerPlugin):
        if plugin not in self.plugins:
            return
        self.plugins.remove(plugin)
        self.executor.submit(plugin.unload)

    def get_plugins(self):
        return self.plugins

    def get_plugin(self, name: str) -> Optional[QwenRemoteServerPlugin]:
        for plugin in self.plugins:
            if plugin.name == name:
                return plugin
        return None

    def get_all_model_names(self) -> list[str]:
        model_names = []
        for plugin in self.plugins:
            model_names.extend(plugin.get_model_names())
        return model_names

    def get_model_spec(self, plugin_name: str, model_name: str) -> Optional[ModelSpec]:
        for plugin in self.plugins:
            if plugin.name == plugin_name:
                return plugin.get_model_spec(model_name)
        return None

    def get_model_endpoint(self, plugin_name: str, model_name: str) -> Optional[str]:
        for plugin in self.plugins:
            if plugin.name == plugin_name:
                return plugin.get_model_endpoint(model_name)
        return None

    def get_model_port(self, plugin_name: str, model_name: str) -> Optional[int]:
        for plugin in self.plugins:
            if plugin.name == plugin_name:
                return plugin.get_model_port(model_name)
        return None

    def get_model_path(self, plugin_name: str, model_name: str) -> Optional[str]:
        for plugin in self.plugins:
            if plugin.name == plugin_name:
                return plugin.get_model_path(model_name)
        return None

    def _run(self):
        while True:
            try:
                if self.plugins:
                    if not self._thread_running:
                        self._thread_running = True
                        self._thread = self.executor.submit(self._run_model_server)
                        self._thread.result()
                        self._thread_running = False
                else:
                    # sleep 1 sec
                    sleep(1)
            except Exception as e:
                logger.error(f"Error in QwenRemoteServerPluginManager: {e}")
                logger.error(traceback.format_exc())

    def _run_model_server(self):
        # wait for all plugins to load
        while not self.plugins:
            sleep(1)

        model_names = self.get_all_model_names()
        if not model_names:
            logger.warning("No models are loaded.")
            return

        logger.info(f"Loading {len(model_names)} models: {model_names}")

        app = Flask(__name__)

