import csv
import json
from io import StringIO

# Define the function to load the text file with the list of banned words
def load_banned_words(text_file_path):
    with open(text_file_path, 'r') as file:
        return file.read().splitlines()

# Define the function to load the JSON file with the list of banned words
def load_json_banned_words(json_file_path):
    with open(json_file_path, 'r') as file:
        return json.loads(file.read())

# Define the function to load the CSV file with the list of banned words
def load_csv_banned_words(csv_file_path):
    with open(csv_file_path, 'r') as file:
        reader = csv.reader(file)
        return [row[0] for row in reader]

# Define the function to check if a string contains any banned word
def contains_banned_word(string, banned_words):
    for word in banned_words:
        if word in string:
            return True
    return False

# Define the function to check if a string contains any banned word from a text file
def contains_banned_word_from_text_file(string, text_file_path):
    banned_words = load_banned_words(text_file_path)
    return contains_banned_word(string, banned_words)

# Define the function to check if a string contains any banned word from a JSON file
def contains_banned_word_from_json_file(string, json_file_path):
    banned_words = load_json_banned_words(json_file_path)
    return contains_banned_word(string, banned_words)

# Define the function to check if a string contains any banned word from a CSV file
def contains_banned_word_from_csv_file(string, csv_file_path):
    banned_words = load_csv_banned_words(csv_file_path)
    return contains_banned_word(string, banned_words)

# Define the function to check if a string contains any banned word from a list of banned words
def contains_banned_word_from_list(string, banned_words):
    return contains_banned_word(string, banned_words)

# Define the function to filter a list of strings and remove any string that contains a banned word
def filter_strings(string_list, banned_words):
    valid_strings = []
    for string in string_list:
        if not contains_banned_word(string, banned_words):
            valid_strings.append(string)
    return valid_strings

# Define the function to filter a list of strings and remove any string that contains a banned word from a text file
def filter_strings_from_text_file(string_list, text_file_path):
    banned_words = load_banned_words(text_file_path)
    return filter_strings(string_list, banned_words)

# Define the function to filter a list of strings and remove any string that contains a banned word from a JSON file
def filter_strings_from_json_file(string_list, json_file_path):
    banned_words = load_json_banned_words(json_file_path)
    return filter_strings(string_list, banned_words)

# Define the function to filter a list of strings and remove any string that contains a banned word from a CSV file
def filter_strings_from_csv_file(string_list, csv_file_path):
    banned_words = load_csv_banned_words(csv_file_path)
    return filter_strings(string_list, banned_words)

# Define the function to filter a list of strings and remove any string that contains a banned word from a list of banned words
def filter_strings_from_list(string_list, banned_words_list):
    banned_words = []
    for banned_words_file_path in banned_words_list:
        if banned_words_file_path.endswith('.txt'):
            banned_words.extend(load_banned_words(banned_words_file_path))
        elif banned_words_file_path.endswith('.json'):
            banned_words.extend(load_json_banned_words(banned_words_file_path))
        elif banned_words_file_path.endswith('.csv'):
            banned_words.extend(load_csv_banned_words(banned_words_file_path))
        else:
            raise ValueError('Invalid file format for banned words list: {}'.format(banned_words_file_path))
    return filter_strings(string_list, banned_words)

# Define the function to filter a list of strings and remove any string that contains a banned word from a list of banned words
def filter_strings_from_list_of_lists(string_list, banned_words_list_of_lists):
    banned_words = []
    for banned_words_list in banned_words_list_of_lists:
        if isinstance(banned_words_list, list):
            banned_words.extend(banned_words_list)
        elif isinstance(banned_words_list, str):
            if banned_words_list.endswith('.txt'):
                banned_words.extend(load_banned_words(banned_words_list))
            elif banned_words_list.endswith('.json'):
                banned_words.extend(load_json_banned_words(banned_words_list))
            elif banned_words_list.endswith('.csv'):
                banned_words.extend(load_csv_banned_words(banned_words_list))
            else:
                raise ValueError('Invalid file format for banned words list of lists: {}'.format(banned_words_list))
        else:
            raise ValueError('Invalid type for banned words list of lists: {}'.format(banned_words_list))
    return filter_strings(string_list, banned_words)

