            } catch (Exception e) {
                e.printStackTrace();
            }
            return byteArray;
        }

        /**
         * @param file
         * @return
         * @throws IOException
         */
        public static byte[] readFileByBytes(File file) {
            byte[] byteArray = null;
            try {
                InputStream in = new FileInputStream(file);
                byteArray = new byte[(int) file.length()];
                int length = 0;
                while ((length = in.read(byteArray)) != -1) {
                }
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return byteArray;
        }
    }

    public static class PrintJson {

        public static String toJson(Object object) {
            String jsonString = null;
            try {
                jsonString = JacksonUtils.toJson(object);
            } catch (JsonProcessingException e) {
                e.printStackTrace();
            }
            return jsonString;
        }
    }

    public static class JacksonUtils {
        private static final ObjectMapper objectMapper = new ObjectMapper();

        static {
            // Use Jackson's default settings
            objectMapper.configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false);
        }

        /**
         * Convert an object to a JSON string
         *
         * @param object The object to be converted
         * @return JSON string or null if an error occurs
         */
        public static String toJson(Object object) throws JsonProcessingException {
            return objectMapper.writeValueAsString(object);
        }

        /**
         * Convert JSON string to object
         *
         * @param json   JSON string
         * @param clazz  Type of the object to be converted
         * @param <T>    Type parameter
         * @return Object of type T or null if an error occurs
         */
        public static <T> T fromJson(String json, Class<T> clazz) throws IOException {
            return objectMapper.readValue(json, clazz);
        }
    }
}
