import { PdfViewerModule } from 'ng2-pdf-viewer';

import { AppComponent } from './app.component';
import { HomeComponent } from './home/home.component';
import { AboutComponent } from './about/about.component';
import { ChatComponent } from './chat/chat.component';
import { ChatInputComponent } from './chat/chat-input/chat-input.component';
import { ChatMessageComponent } from './chat/chat-message/chat-message.component';
import { ChatStatusComponent } from './chat/chat-status/chat-status.component';

import { ScrollToBottomDirective } from './chat/directives/scroll-to-bottom.directive';
import { ConversationsService } from './chat/services/conversations.service';

const routes: Routes = [
  { path: '', component: HomeComponent },
  { path: 'about', component: AboutComponent },
  { path: 'chat/:id', component: ChatComponent },
  { path: '**', redirectTo: '/' }
];

@NgModule({
  imports: [
    CommonModule,
    FormsModule,
    HttpClientModule,
    PdfViewerModule,
    RouterModule.forRoot(routes)
  ],
  declarations: [
    AppComponent,
    HomeComponent,
    AboutComponent,
    ChatComponent,
    ChatInputComponent,
    ChatMessageComponent,
    ChatStatusComponent,
    ScrollToBottomDirective
  ],
  providers: [ConversationsService],
  bootstrap: [AppComponent]
})
export class AppModule {}
