import { Component, OnInit } from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';

import { ConversationsService } from '../services/conversations.service';
import { Conversation, Message } from '../models/conversation';

@Component({
  selector: 'app-chat',
  templateUrl: './chat.component.html',
  styleUrls: ['./chat.component.css']
})
export class ChatComponent implements OnInit {
  conversationId: string;
  conversation: Conversation;

  constructor(private conversationsService: ConversationsService,
              private router: Router,
              private route: ActivatedRoute) { }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.conversationId = params['id'];
      this.conversationsService.getConversation(this.conversationId)
        .subscribe(conversation => this.conversation = conversation);
    });
  }

  sendMessage(message: string) {
    this.conversationsService.sendMessage(this.conversationId, message).subscribe(() => {
      this.conversationsService.getConversation(this.conversationId)
        .subscribe(conversation => this.conversation = conversation);
    });
  }

  sendFile(file: File) {
    const formData = new FormData();
    formData.append('file', file);

    this.conversationsService.sendFile(this.conversationId, formData).subscribe(() => {
      this.conversationsService.getConversation(this.conversationId)
        .subscribe(conversation => this.conversation = conversation);
    });
  }

  deleteConversation() {
    this.conversationsService.deleteConversation(this.conversationId)
      .subscribe(() => { this.router.navigate(['/']); });
  }

  deleteMessage(messageId: string) {
    this.conversationsService.deleteMessage(this.conversationId, messageId)
      .subscribe(() => {
        this.conversationsService.getConversation(this.conversationId)
          .subscribe(conversation => this.conversation = conversation);
      });
  }
}

