class Solution:
    def canPartition(self, nums):
        sum_nums = sum(nums)
        if sum_nums & 1:
            return False
        sum_nums //= 2
        dp = [True] + [False] * sum_nums
        for num in nums:
            for j in range(sum_nums, num - 1, -1):
                dp[j] |= dp[j - num]
        return dp[sum_nums]


