package com.qwen.ai.gpt.controller;

import com.qwen.ai.gpt.model.ChoiceModel;
import com.qwen.ai.gpt.model.ResponseModel;
import com.qwen.ai.gpt.service.TextService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.Arrays;
import java.util.List;

@RestController
@RequestMapping(value = "/api/v1/text")
public class TextController {
    @Autowired
    private TextService textService;

    @PostMapping(value = "/chat", produces = "application/json;charset=UTF-8")
    public ResponseModel create(@RequestBody TextChatBody body) {
        List<String> names = Arrays.stream(body.getNames()).map(String::trim).toList();
        String prompt = body.getMessages().get(0).getContent();
        ResponseModel responseModel = textService.chat(prompt, body.getTemperature(), names);
        return responseModel;
    }

    @PostMapping(value = "/completions", produces = "application/json;charset=UTF-8")
    public ResponseModel completions(@RequestBody CompletionBody body) {
        ResponseModel responseModel = textService.completions(body.getPrompt(), body.getTemperature());
        return responseModel;
    }

    @PostMapping(value = "/edit", produces = "application/json;charset=UTF-8")
    public ResponseModel edit(@RequestBody TextEditBody body) {
        ResponseModel responseModel = textService.edit(body.getPrompt(), body.getTemperature(), body.getInstruction());
        return responseModel;
    }

    @PostMapping(value = "/embedding", produces = "application/json;charset=UTF-8")
    public ResponseModel embedding(@RequestBody TextEmbeddingBody body) {
        List<String> names = Arrays.stream(body.getNames()).map(String::trim).toList();
        String prompt = body.getMessages().get(0).getContent();
        ResponseModel responseModel = textService.embedding(prompt, names);
        return responseModel;
    }

    @PostMapping(value = "/davinci", produces = "application/json;charset=UTF-8")
    public ResponseModel davinci(@RequestBody TextDavinciBody body) {
        ResponseModel responseModel = textService.davinci(body.getPrompt(), body.getTemperature());
        return responseModel;
    }

    @Data
    public static class TextEditBody {
        private String prompt;
        private String instruction;
        private float temperature = 1.0f;
        private String[] names;
    }

    @Data
    public static class TextEmbeddingBody {
    <|fim_suffix|>ing[] names;
    }

    @Data
    public static class TextDavinciBody {
        private String prompt;
