import Foundation

class Message {
    var id: Int
    var uuid: String
    var message: String
    var type: String
    var sender: String
    var createdAt: Date
    var updatedAt: Date
    var synced: Bool = false
    var deletedAt: Date?
    var resendCount: Int = 0
    var resend: Bool = false
    var resendTimestamp: Date?
    var senderDisplayName: String?
    var senderId: String?
    var senderAvatar: String?
    var senderCountry: Bool?
    var senderLanguage: String?
    var senderGender: String?

    var isRead: Bool = false
    var isDeleted: Bool = false

    var isTyping: Bool = false
    var isSeen: Bool = false
    var isDelivered: Bool = false

    init(from json: [String: Any]) {
        let now = Date()
        id = json["id"] as? Int ?? 0
        uuid = json["uuid"] as? String ?? ""
        message = json["message"] as? String ?? ""
        type = json["type"] as? String ?? ""
        sender = json["sender"] as? String ?? ""
        createdAt = json["createdAt"] as? Date ?? now
        updatedAt = json["updatedAt"] as? Date ?? now
        synced = json["synced"] as? Bool ?? false
        deletedAt = json["deletedAt"] as? Date
        resendCount = json["resendCount"] as? Int ?? 0
        resend = json["resend"] as? Bool ?? false
        resendTimestamp = json["resendTimestamp"] as? Date
        senderDisplayName = json["senderDisplayName"] as? String
        senderId = json["senderId"] as? String
        senderAvatar = json["senderAvatar"] as? String
        senderCountry = json["senderCountry"] as? Bool
        senderLanguage = json["senderLanguage"] as? String
        senderGender = json["senderGender"] as? String

        isRead = json["isRead"] as? Bool ?? false
        isDeleted = json["isDeleted"] as? Bool ?? false

        isTyping = json["isTyping"] as? Bool ?? false
        isSeen = json["isSeen"] as? Bool ?? false
        isDelivered = json["isDelivered"] as? Bool ?? false
    }

    func toDictionary() -> [String: Any] {
        var dict = [String: Any]()
        dict["id"] = id
        dict["uuid"] = uuid
        dict["message"] = message
        dict["type"] = type
        dict["sender"] = sender
        dict["createdAt"] = createdAt
        dict["updatedAt"] = updatedAt
        dict["synced"] = synced
        dict["deletedAt"] = deletedAt
        dict["resendCount"] = resendCount
        dict["resend"] = resend
        dict["resendTimestamp"] = resendTimestamp
        dict["senderDisplayName"] = senderDisplayName
        dict["senderId"] = senderId
        dict["senderAvatar"] = senderAvatar
        dict["senderCountry"] = senderCountry
        dict["senderLanguage"] = senderLanguage
        dict["senderGender"] = senderGender

        dict["isRead"] = isRead
        dict["isDeleted"] = isDeleted

        dict["isTyping"] = isTyping
        dict["isSeen"] = isSeen
        dict["isDelivered"] = isDelivered
        return dict
    }

