    @Test
    @WithMockUser(username = "testuser", password = "password")
    public void testRegister() {
        // 注册一个新的用户
        RegisterRequest registerRequest = new RegisterRequest();
        registerRequest.setUsername("newuser");
        registerRequest.setPassword("newpassword");
        registerRequest.setAge(21);
        registerRequest.setGender("M");
        registerRequest.setAvatarUrl("avatar_url");
        registerRequest.setAddress("address");
        registerRequest.setPhone("phone");

        RegisterResponse response = userService.register(registerRequest);
        System.out.println(response);
    }

    @Test
    @WithMockUser(username = "testuser", password = "password")
    public void testLogin() {
        // 登录一个已有的用户
        LoginRequest loginRequest = new LoginRequest();
        loginRequest.setUsername("existinguser");
        loginRequest.setPassword("existingpassword");

        LoginResponse response = userService.login(loginRequest);
        System.out.println(response);
    }

    @Test
    @WithMockUser(username = "testuser", password = "password")
    public void testGetUser() {
        // 获取用户信息
