package com.qwen.chat.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Lazy;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.ModelAndView;

import com.qwen.chat.common.Const;
import com.qwen.chat.common.ErrorCode;
import com.qwen.chat.exception.BusinessException;
import com.qwen.chat.model.entity.User;
import com.qwen.chat.model.request.RegisterRequest;
import com.qwen.chat.model.response.LoginResponse;
import com.qwen.chat.model.response.RegisterResponse;
import com.qwen.chat.service.UserService;
import com.qwen.chat.util.JwtUtil;
import com.qwen.chat.util.UserHolder;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import org.springframework.stereotype.Controller;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static com.qwen.chat.common.Const.USER_LOGIN_STATE;

@RestController
public class UserController {
    @Autowired
    private UserService userService;
    @Autowired
    private UserHolder userHolder;
    @Autowired
    private JwtUtil jwtUtil;

    @PostMapping("/register")
    public RegisterResponse register(@RequestBody RegisterRequest request, HttpServletResponse response) {
        if (request.getUserType() == null || (request.getUserType() != 0 && request.getUserType() != 1)) {
            throw new BusinessException(ErrorCode.PARAMS_ERROR, "用户类型错误");
        }
        RegisterResponse registerResponse = userService.register(request);
        String token = jwtUtil.generateToken(registerResponse.getUid());
        response.setHeader(Const.AUTHORIZATION, token);
        return registerResponse;
    }

    @PostMapping("/login")
    public LoginResponse login(@RequestBody LoginRequest request, HttpServletResponse response) {
        LoginResponse loginResponse = userService.login(request);
        String token = jwtUtil.generateToken(loginResponse.getUid());
        response.setHeader(Const.AUTHORIZATION, token);
        return loginResponse;
    }

    @GetMapping("/user")
    public User getUser() {
        return userHolder.getUser();
    }

    @GetMapping("/user/{username}")
    public User getUser(@PathVariable String username) {
        return userService.getUser(username);
    }

    @GetMapping("/users")
    public List<User> getUsers() {
        return userService.getUsers();
    }

    @GetMapping("/user/search")
    public List<User> searchUser(@RequestParam("keyword") String keyword) {
        return userService.searchUser(keyword);
    }

    @PostMapping("/user/follow")
    public Map<String, Object> follow(@RequestParam("username") String username) {
        return userService.follow(userHolder.getUser().getUsername(), username);
    }

    @PostMapping("/user/unfollow")
    public Map<String, Object> unFollow(@RequestParam("username") String username) {
        return userService.unfollow(userHolder.getUser().getUsername(), username);
    }

    @PostMapping("/user/status")
    public Map<String, Object> changeUserStatus(@RequestParam("status") boolean status) {
        return userService.changeUserStatus(userHolder.getUser().getUsername(), status);
    }

    @GetMapping("/user/followers")
    public List<User> getFollowers() {
        return userService.getFollowers(userHolder.getUser().getUsername());
    }

    @GetMapping("/user/following")
    public List<User> getFollowing() {
        return userService.getFollowing(userHolder.getUser().getUsername());
    }

    @GetMapping("/user/following/search")
    public List<User> getFollowingSearch(@RequestParam("keyword") String keyword) {
        return userService.getFollowingSearch(userHolder.getUser().getUsername(), keyword);
    }

    @GetMapping("/user/followers/search")
    public List<User> getFollowersSearch(@RequestParam("keyword") String keyword) {
        return userService.getFollowersSearch(userHolder.getUser().getUsername(), keyword);
    }

    @PostMapping("/user/password")
    public String changePassword(@RequestParam("oldPassword") String oldPassword, @RequestParam("newPassword") String newPassword) {
        return userService.changePassword(userHolder.getUser().getUsername(), oldPassword, newPassword);
    }

    @GetMapping("/user/{username}/chat")
    public ModelAndView getChatPage(@PathVariable("username") String username, HttpServletRequest request, HttpServletResponse response) {
        return userService.getChatPage(username, request, response);
    }

    @PostMapping("/user/{username}/add")
    public String addFriend(@PathVariable("username") String username, HttpSession session) {
        return userService.addFriend(username, session);
    }

    @PostMapping("/user/{username}/remove")
    public String removeFriend(@PathVariable("username") String username) {
        return userService.removeFriend(username);
    }

    @GetMapping("/user/{username}/block")
    public String blockUser(@PathVariable("username") String username) {
        return userService.blockUser(username);
    }

    @GetMapping("/user/{username}/unblock")
    public String unblockUser(@PathVariable("username") String username) {
        return userService.unblockUser(username);
    }

    @GetMapping("/user/{username}/status")
    public boolean getUserStatus(@PathVariable("username") String username) {
        return userService.getUserStatus(username);
    }

    @GetMapping("/user/{username}/friends")
    public List<User> getFriends(@PathVariable("username") String username) {
        return userService.getFriends(username);
    }

    @GetMapping("/user/{username}/friendRequests")
    public List<User> getFriendRequests(@PathVariable("username") String username) {
        return userService.getFriendRequests(username);
    }

    @GetMapping("/user/{username}/chatRecords")
    public List<Map<String, Object>> getChatRecords(@PathVariable("username") String username) {
        return userService.getChatRecords(username);
    }

