import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

export const supabase = createClient(supabaseUrl, supabaseKey);
export const {
    auth: { onAuthStateChange: supabaseOnAuthStateChange },
} = supabase;

const points = [
    [60, 80],
    [55, 85],
    [60, 90],
    [65, 95],
    [70, 100],
];

const initialState = {
    state: 'idle',
    error: null,
    result: null,
    points,
};

const reducer = (state, action) => {
    switch (action.type) {
        case 'loading':
            return { ...state, state: 'loading' };
        case 'success':
            return { ...state, state: 'success', result: action.result };
        case 'failure':
            return { ...state, state: 'error', error: action.error };
        case 'reset':
            return initialState;
        default:
            return state;
    }
};

const useData = (initialState, reducer, fetcher) => {
    const [state, dispatch] = React.useReducer(reducer, initialState);

    React.useEffect(() => {
        dispatch({ type: 'loading' });
        fetcher().then(
            (result) => dispatch({ type: 'success', result }),
            (error) => dispatch({ type: 'failure', error })
        );
    }, []);

    const reset = () => dispatch({ type: 'reset' });

    return [state, reset];
};

const fetcher = () => Promise.resolve(points);

const data = useData(initialState, reducer, fetcher);

export default function App() {
    const { points } = data[0];
    const [selectedPoints, setSelectedPoints] = React.useState(points);

    const handleSelect = (event) => {
        const index = points.findIndex(
            (point) => point.join() === event.target.value
        );
        const newPoints = [...points];
        newPoints[index] = event.target.checked
            ? newPoints[index]
            : selectedPoints[index];
        setSelectedPoints(newPoints);
    };

    return (
        <div>
            <h1>Supabase + React + React-Redux + React-Router</h1>
            <ul>
                {points.map((point) => (
                    <li key={point.join()}>
                        <input
                            type="checkbox"
                            value={point.join()}
                            checked={selectedPoints.includes(point)}
                            onChange={handleSelect}
                        />
                        {point.join()}
                    </li>
                ))}
            </ul>
            <button onClick={data[1]}>Reset</button>
        </div>
    );
}

