import json
import requests

from config import params
from tool import Tool
from util import Util


class Agent:
    def __init__(self, name, token=""):
        self.name = name
        self.token = token
        self.get_token()

    def get_token(self):
        if not self.token:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 6.1; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/55.0.2883.87 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'}
            params = {
                'username': params['username'],
                'password': params['password']
            }
            ret = requests.post('https://www.qwen.tech/api/auth/login', params=params, headers=headers)
            data = json.loads(ret.text)
            if data["code"] == 200:
                self.token = data["data"]["token"]
            else:
                print('获取token失败')

    def ask(self, sentence):
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 6.1; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/55.0.2883.87 Safari/537.36',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
            'Authorization': 'qwen_token {}'.format(self.token)}
        params = {
            'sentence': sentence
        }
        ret = requests.post("https://www.qwen.tech/api/chatbot/ask", params=params, headers=headers)
        data = json.loads(ret.text)
        if data["code"] == 200:
            return data["data"]
        else:
            return []

    def get_response(self, sentence):
        data = self.ask(sentence)
        if len(data) > 0:
            return data[0]['answer']
        else:
            return ''

    def get_response_json(self, sentence):
        data = self.ask(sentence)
        if len(data) > 0:
            return data
        else:
            return []

    def get_response_list(self, sentence):
        data = self.ask(sentence)
        if len(data) > 0:
            return data[0]['text']
        else:
            return []

    def update(self, question, answer):
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 6.1; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/55.0.2883.87 Safari/537.36',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
            'Authorization': 'qwen_token {}'.format(self.token)}
        params = {
            'question': question,
            'answer': answer
        }
        ret = requests.post("https://www.qwen.tech/api/chatbot/update", params=params, headers=headers)
        data = json.loads(ret.text)
        print(data)

    def answer(self, sentence):
        response = self.get_response(sentence)
        self.update(sentence, response)
        return response

    def answer_json(self, sentence):
        response = self.get_response_json(sentence)
        self.update(sentence, response)
        return response

    def answer_list(self, sentence):
        response = self.get_response_list(sentence)
        self.update(sentence, response)
        return response

    def talk(self, sentence):
        response = self.get_response(sentence)
        return response

    def talk_json(self, sentence):
