import { createSlice } from '@reduxjs/toolkit';

export interface RealTimeChatState {
  messages: string[];
  history: string[];
  currentMessage: string;
  currentMessageUser: string;
}

const initialState: RealTimeChatState = {
  messages: [],
  history: [],
  currentMessage: '',
  currentMessageUser: '',
};

export const realTimeChatSlice = createSlice({
  name: 'realTimeChat',
  initialState,
  reducers: {
    addMessage: (state, action) => {
      state.messages.push(action.payload);
    },
    addMessageToHistory: (state, action) => {
      state.history.push(action.payload);
    },
    updateCurrentMessage: (state, action) => {
      state.currentMessage = action.payload;
    },
    updateCurrentMessageUser: (state, action) => {
      state.currentMessageUser = action.payload;
    },
  },
});

export const {
  addMessage,
  addMessageToHistory,
  updateCurrentMessage,
  updateCurrentMessageUser,
} = realTimeChatSlice.actions;

export default realTimeChatSlice.reducer;

