const { MessageEmbed } = require("discord.js");
const { Command } = require("../../core");
const { getAnime } = require("../../utils");
const { PREFIX } = require("../../config");

module.exports = class Anime extends Command {
  constructor(client) {
    super(client, {
      name: "anime",
      aliases: ["anime-info"],
      description: "Get Anime Info",
      usage: `${PREFIX}anime [anime-name]`,
    });
  }

  async run(message, args) {
    const anime = args.join(" ");

    if (anime) {
      const data = await getAnime(anime);

      if (data.error) {
        message.reply("No Anime found with the given name.");
        return;
      }

      const embed = new MessageEmbed();
      embed.setTitle("Anime Info");
      embed.setDescription(data.synopsis);
      embed.setImage(data.image_url);
      embed.setThumbnail(data.image_url);
      embed.setColor("#ffffff");
      embed.setFooter({
        text: `MAL ID: ${data.mal_id}`,
        iconURL: "https://cdn.discordapp.com/attachments/1027450484462791834/1027450516961802557/unknown.png",
      });
      embed.setAuthor({
        name: "Anime Info",
        iconURL: "https://cdn.discordapp.com/attachments/1027450484462791834/1027450516961802557/unknown.png",
      });
      embed.setTimestamp();
      message.reply({ embeds: [embed] });
    } else {
      message.reply("Please provide an anime name.");
    }
  }
};

