const { MessageEmbed } = require("discord.js");
const { Command } = require("../../core");
const fs = require("fs");

module.exports = class Audio extends Command {
  constructor(client) {
    super(client, {
      name: "audio",
      aliases: [],
      description: "Play audio from a file",
      usage: `${PREFIX}audio <file>`,
    });
  }

  async run(message, args) {
    const file = args[0];

    if (!file) {
      message.reply("Please provide a file to play.");
      return;
    }

    const filePath = `./audio/${file}`;

    if (!fs.existsSync(filePath)) {
      message.reply("File not found.");
      return;
    }

    const connection = await message.member.voice.channel.join();
    const dispatcher = connection.play(filePath);

    dispatcher.on("finish", () => {
      message.reply("Audio finished playing.");
      connection.disconnect();
    });

    dispatcher.on("error", (error) => {
      message.reply("Error occurred while playing audio.");
      console.error(error);
      connection.disconnect();
    });

    message.reply("Playing audio...");
  }
};

