```rust
use reqwest;
use serde_json::{json, Value};

fn generate(text: &str, max_tokens: usize, top_p: f64, top_k: usize, temperature: f64) -> String {
    let client = reqwest::blocking::Client::new();
    let url = "http://0.0.0.0:8080/generate";
    let response = client.post(url)
        .json(&json!({
            "text": text,
            "max_tokens": max_tokens,
            "top_p": top_p,
            "top_k": top_k,
            "temperature": temperature,
        }))
        .send()
        .unwrap()
        .text()
        .unwrap();
    let value: Value = serde_json::from_str(&response).unwrap();
    value["text"].as_str().unwrap().to_string()
}

fn main() {
    println!("{}", generate("Once upon a time,", 100, 0.9, 0, 0.8));
}
