### Go
```go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

func generate(text string, maxTokens int, topP float64, topK int, temperature float64) string {
	client := &http.Client{}
	url := "http://0.0.0.0:8080/generate"
	data := []byte(fmt.Sprintf(`{"text": "%s", "max_tokens": %d, "top_p": %f, "top_k": %d, "temperature": %f}`, text, maxTokens, topP, topK, temperature))
	req, err := http.NewRequest("POST", url, bytes.NewBuffer(data))
	if err != nil {
		panic(err)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	var response map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&response); err != nil {
		panic(err)
	}
	return response["text"]
}

func main() {
	fmt.Println(generate("Once upon a time,", 100, 0.9, 0, 0.8))
}
