 * @date 2020/04/13
 */
public class SqlBuilderContext {

    private final Map<String, Object> context;
    private final Map<String, String> colTypes;
    private final JSONObject sqlBuilder;

    public SqlBuilderContext(String sqlBuilderParam, JSONObject sqlBuilder) {
        this.sqlBuilder = sqlBuilder;
        this.context = ELUtils.createContext(sqlBuilderParam);
        this.colTypes = ELUtils.createColTypesMap(sqlBuilderParam);
    }

    public Map<String, Object> getContext() {
        return context;
    }

    public String getParam(String param) {
        Object value = context.get(param);
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    public String getParam(String param, String def) {
        Object value = context.get(param);
        if (value == null) {
            return def;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    public String getParam(String param, Object defaultValue) {
        Object value = context.get(param);
        if (value == null) {
            return defaultValue.toString();
        }
        if (value instanceof String) {
            return (String) value;
        }
        return value.toString();
    }


    public String getParamPadding(String param) {
        Object value = context.get(param);
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    public String getParamPadding(String param, String def) {
        Object value = context.get(param);
        if (value == null) {
            return def;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    public JSONObject getSqlBuilder() {
        return sqlBuilder;
    }

    public String getSQL() {
        return getParam(Config.SQL_KEY);
    }

    public String getSQLPadding() {
        return getParamPadding(Config.SQL_KEY);
    }

    public String getTableName() {
        return getParam(Config.TABLE_KEY);
    }

    public String getTableNamePadding() {
        return getParamPadding(Config.TABLE_KEY);
    }

    public String getColTypes(String colName) {
        return colTypes.get(colName);
    }

    public String getColTypesPadding(String colName) {
        String type = colTypes.get(colName);
        if (StringUtils.isEmpty(type)) {
            return null;
        }
        return type.trim();
    }
}
