package com.alibaba.dubbo;

import org.apache.dubbo.rpc.Invocation;
import org.apache.dubbo.rpc.Invoker;
import org.apache.dubbo.rpc.Result;
import org.apache.dubbo.rpc.RpcException;
import org.apache.dubbo.rpc.cluster.LoadBalance;
import org.apache.dubbo.rpc.cluster.loadbalance.RandomLoadBalance;

import java.util.List;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

/**
 * @author zk
 * @date 2023/5/20 18:27
 */
public class RoundRobinLoadBalance implements LoadBalance {
    private static final Lock LOCK = new ReentrantLock();

    @Override
    public <T> Invoker<T> select(List<Invoker<T>> invokers, Invocation invocation) throws RpcException {
        int length = invokers.size();
        if (length == 1) {
            return invokers.get(0);
        }

        LOCK.lock();
        try {
            int index = index.getAndIncrement() % length;
            return invokers.get(index);
        } finally {
            LOCK.unlock();
        }
    }

    private static class InstanceHolder {
        public static final RoundRobinLoadBalance INSTANCE = new RoundRobinLoadBalance();
    }

    public static RoundRobinLoadBalance getInstance() {
        return InstanceHolder.INSTANCE;
    }

    private volatile int index = 0;

    @Override
    public <T> Invoker<T> select(List<Invoker<T>> invokers, String invoker, Invocation invocation) throws RpcException {
        int length = invokers.size();
        if (length == 1) {
            return invokers.get(0);
        }

        LOCK.lock();
        try {
            int index = this.index.getAndIncrement() % length;
            return invokers.get(index);
        } finally {
            LOCK.unlock();
        }
    }

    @Override
    public <T> Invoker<T> select(List<Invoker<T>> invokers, String method, Invocation invocation) throws RpcException {
        int length = invokers.size();
        if (length == 1) {
            return invokers.get(0);
        }

        LOCK.lock();
        try {
            int index = this.index.getAndIncrement() % length;
            return invokers.get(index);
        } finally {
            LOCK.unlock();
        }
    }

    @Override
    public <T> Invoker<T> select(List<Invoker<T>> invokers, String group, String version, Invocation invocation) throws RpcException {
        int length = invokers.size();
        if (length == 1) {
            return invokers.get(0);
        }

        LOCK.lock();
        try {
            int index = this.index.getAndIncrement() % length;
            return invokers.get(index);
        } finally {
            LOCK.unlock();
        }
    }
}

