	@Test
	public void testSynthesizer() throws IOException, InterruptedException,
			TimeoutException {
		NlsClient client = new NlsClient(appId, token);
		RequestConfig config = new RequestConfig();
		config.setSampleRate(SAMPLE_RATE);
		config.setFormat("wav");
		config.setChannel(CHANNEL);
		config.setAppId(appId);
		config.setToken(token);
		config.setCustomVoice("customVoiceId");
		config.setAudioFormat("pcm");
		SpeechSynthesizerResponseMessage response = client.synthesizer(
				new ByteArrayInputStream(getBytes(audioFile)),
				new ByteArrayOutputStream(), config, TIME_OUT);
		assertNull(response.getErrorMessage());
		assertEquals(TtsResponseType.SUCCESS, response.getResponseType());
		assertEquals("tts response", getBytes(audioFileResponse),
				response.getAudio());
	}

	@Test
	public void testTts() throws IOException, InterruptedException,
			TimeoutException {
		NlsClient client = new NlsClient(appId, token);
		RequestConfig config = new RequestConfig();
		config.setSampleRate(SAMPLE_RATE);
		config.setFormat("wav");
		config.setChannel(CHANNEL);
		config.setAppId(appId);
		config.setToken(token);
		config.setCustomVoice("customVoiceId");
		config.setAudioFormat("pcm");
		config.setMessageFormat(MessageFormatType.JSON);
		TtsResponseMessage response = client.tts(
				new ByteArrayInputStream(getBytes(audioFile)),
				new ByteArrayOutputStream(), config, TIME_OUT);
		assertNull(response.getErrorMessage());
		assertEquals(TtsResponseType.SUCCESS, response.getResponseType());
		assertEquals("tts response", getBytes(audioFileResponse),
				response.getAudio());
	}

