		this.code = code;
	}

	public int getCode() {
		return code;
	}

	public static TtsResponseType valueOf(int code) {
		switch (code) {
		case 0:
			return SUCCESS;
		case 1:
			return FAILED;
		case 2:
			return EXCEPTION;
		case 3:
			return TIME_OUT;
		default:
			return null;
		}
	}

