from agent.context import ContextNodeManager

class Agent:
    def __init__(self, id, ctx):
        self.id = id
        self.ctx = ctx
        self.ctx_mgr = ContextNodeManager()
        self.node = None
        self.parent = None
        self.children = []
        self.state = "INITIAL"
        self.expired = False

    def set_root(self, parent_id):
        self.parent = None
        self.node = self.ctx_mgr.add_node(self.id, parent_id)

    def set_parent(self, parent_node):
        self.parent = parent_node
        self.node = self.ctx_mgr.add_node(self.id, parent_node.id)

    def add_child(self, child):
        self.children.append(child)

    def update(self, ctx):
        if self.state == "INITIAL":
            if self.parent is None:
                self.state = "FINALIZE"
            else:
                self.state = "WAITING"
        elif self.state == "WAITING":
            if self.parent.expired:
                self.state = "ERROR"
            else:
                self.state = "FINALIZE"
        elif self.state == "FINALIZE":
            if self.parent is not None:
                self.parent.add_child(self)
            self.state = "FINALIZED"
            self.expired = True
        elif self.state == "ERROR":
            self.expired = True

    def reset(self):
        self.ctx_mgr.reset()
        self.node = None
        self.parent = None
        self.children = []
        self.state = "INITIAL"
        self.expired = False

