from common import *

class ContextNode:
    def __init__(self, id, parent_id):
        self.id = id
        self.parent_id = parent_id
        self.children = []
        self.state = "INITIAL"
        self.expired = False

    def update(self):
        if self.state == "INITIAL":
            self.state = "FINALIZED"
            self.expired = True
        elif self.state == "FINALIZED":
            self.expired = True

    def reset(self):
        self.children = []
        self.state = "INITIAL"
        self.expired = False

class ContextNodeManager:
    def __init__(self):
        self.nodes = []

    def add_node(self, id, parent_id):
        node = ContextNode(id, parent_id)
        self.nodes.append(node)
        return node

    def get_node(self, id):
        for node in self.nodes:
            if node.id == id:
                return node
