#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include "simplefs.h"
#include "simplefs_internals.h"
#include "simplefs_internalfs.h"

/* Debug macros */
#ifdef DEBUG
#define dbgprintf(...) fprintf(stderr, __VA_ARGS__)
#else
#define dbgprintf(...)
#endif

/* Helper functions */
static int is_directory(simplefs_handle *fh, int ino);
static int get_inode(simplefs_handle *fh, int ino, inode_t **inode);
static int add_new_inode(simplefs_handle *fh, int ino, int type, int size);
static int add_new_dentry(simplefs_handle *fh, char *name, int name_len,
                          int ino, int parent_ino);
static int get_dentry(simplefs_handle *fh, int ino, char *name, int name_len,
                      dentry_t **dentry);
static int get_parent(simplefs_handle *fh, int ino, dentry_t **dentry);
static int get_parent_inode(simplefs_handle *fh, int ino, inode_t **inode);
static int set_inode(simplefs_handle *fh, int ino, inode_t *inode);
static int set_dentry(simplefs_handle *fh, int ino, dentry_t *dentry);
static int remove_dentry(simplefs_handle *fh, int ino, int pino, char *name,
                         int name_len);

/* Filesystem initialization */
int simplefs_init(simplefs_handle *fh, char *diskname) {
    int rc;
    struct stat st;
    size_t len;

    /* Check if the disk exists */
    rc = stat(diskname, &st);
    if (rc == -1) {
        /* Disk does not exist, create a new one */
        rc = open(diskname, O_CREAT | O_RDWR | O_EXCL, 0666);
        if (rc == -1) {
            dbgprintf("simplefs_init: stat(%s): %s\n", diskname, strerror(errno));
            return -1;
        }
        close(rc);
    } else {
        /* Disk exists, check its size */
        len = st.st_size;
        if (len != DISK_SIZE) {
            dbgprintf("simplefs_init: disk size incorrect (%ld != %d)\n",
                      len, DISK_SIZE);
            return -1;
        }
    }

    /* Open the disk */
    fh->fd = open(diskname, O_RDWR);
    if (fh->fd == -1) {
        dbgprintf("simplefs_init: open(%s): %s\n", diskname, strerror(errno));
        return -1;
    }

    /* Read the superblock */
    rc = pread(fh->fd, &fh->sb, sizeof(fh->sb), 0);
    if (rc != sizeof(fh->sb)) {
        dbgprintf("simplefs_init: pread: %s\n", strerror(errno));
        return -1;
    }

    /* Check magic number */
    if (fh->sb.magic != SIMPLEFS_MAGIC) {
        dbgprintf("simplefs_init: magic number incorrect (%x != %x)\n",
                  fh->sb.magic, SIMPLEFS_MAGIC);
        return -1;
    }

    /* Initialize the free list */
    fh->free_list = fh->sb.free_list;
    fh->free_inode_list = fh->sb.inode_free_list;
    return 0;
}

int simplefs_destroy(simplefs_handle *fh) {
    /* Write the superblock */
    ssize_t rc = pwrite(fh->fd, &fh->sb, sizeof(fh->sb), 0);
    if (rc != sizeof(fh->sb)) {
        dbgprintf("simplefs_destroy: pwrite: %s\n", strerror(errno));
        return -1;
    }

    /* Close the disk */
    close(fh->fd);
    return 0;
}

/* Directory entry functions */
int simplefs_getattr(simplefs_handle *fh, char *path, simplefs_stat_t *st) {
    int ino;
    inode_t *inode;
    dentry_t *dentry;
    int rc;

    /* Check if the path is valid */
    if ((path == NULL) || (st == NULL)) {
        return -1;
    }

    /* Get the inode number */
    ino = simplefs_lookup(fh, path);
    if (ino == -1) {
        return -1;
    }

    /* Get the inode */
    rc = get_inode(fh, ino, &inode);
    if (rc == -1) {
        return -1;
    }

    /* Set the stat structure */
    st->ino = inode->ino;
    st->size = inode->size;
    st->mode = inode->mode;
    st->ctime = inode->ctime;
    st->mtime = inode->mtime;
    st->atime = inode->atime;
    return 0;
}

int simplefs_link(simplefs_handle *fh, char *path1, char *path2) {
    int ino, pino;
    dentry_t *dentry;
    int rc;

    /* Check if the paths are valid */
    if ((path1 == NULL) || (path2 == NULL)) {
        return -1;
    }

    /* Get the inode number */
    ino = simplefs_lookup(fh, path1);
    if (ino == -1) {
        return -1;
    }

    /* Get the parent inode number */
    pino = simplefs_lookup(fh, path2);
    if (pino == -1) {
        return -1;
    }

    /* Get the parent inode */
    rc = get_inode(fh, pino, &inode);
    if (rc == -1) {
        return -1;
    }

    /* Check if the parent is a directory */
    if (!is_directory(fh, pino)) {
        return -1;
    }

    /* Add a new dentry to the parent */
    rc = add_new_dentry(fh, path1, strlen(path1), ino, pino);
    if (rc == -1) {
        return -1;
    }

    /* Link the dentry */
    dentry = malloc(sizeof(dentry_t));
    if (dentry == NULL) {
        dbgprintf("simplefs_link: malloc: %s\n", strerror(errno));
        return -1;
    }
    dentry->ino = ino;
    rc = set_dentry(fh, pino, dentry);
    if (rc == -1) {
        free(dentry);
        return -1;
    }
    return 0;
}

int simplefs_unlink(simplefs_handle *fh, char *path) {
    int ino, pino;
    dentry_t *dentry;
    int rc;

    /* Check if the path is valid */
    if (path == NULL) {
        return -1;
    }

    /* Get the inode number */
    ino = simplefs_lookup(fh, path);
    if (ino == -1) {
        return -1;
    }

    /* Get the parent inode number */
    pino = simplefs_lookup(fh, path);
    if (pino == -1) {
        return -1;
    }

    /* Get the parent inode */
    rc = get_inode(fh, pino, &inode);
    if (rc == -1) {
        return -1;
    }

    /* Check if the parent is a directory */
    if (!is_directory(fh, pino)) {
        return -1;
    }

    /* Remove the dentry */
    rc = remove_dentry(fh, ino, pino, path, strlen(path));
    if (rc == -1) {
        return -1;
    }

    /* Unlink the dentry */
    rc = get_parent(fh, ino, &dentry);
    if (rc == -1) {
        return -1;
    }
    free(dentry);
    return 0;
}

