package org.algorithm.center.service;

import lombok.extern.slf4j.Slf4j;
import org.algorithm.center.controller.KafkaController;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Service;

/**
 * @author Jason Ding
 * @date 2022/11/17 17:13
 */
@Slf4j
@Service
public class KafkaConsumerService {

    @KafkaListener(topics = {"request.topic"})
    public void consumer(ConsumerRecord<?, ?> record) {
        log.info("received kafka message: {}", record.value());
        String key = (String) record.key();
        String value = (String) record.value();
        log.info("key: {}, value: {}", key, value);
        KafkaController.executeRequest(key, value);
    }
}
