import { Schema, Document, model } from 'mongoose';
import { IProductDocument } from './product';

export interface ITagDocument extends Document {
  name: string;
  products: IProductDocument[];
}

const productSchema = new Schema<IProductDocument>({
  name: { type: String, required: true },
  price: { type: Number, required: true }
}, { _id: false });

const tagSchema = new Schema<ITagDocument>({
  name: { type: String, required: true },
  products: [productSchema]
}, { collection: 'tags' });

export const Tag = model<ITagDocument>('Tag', tagSchema);

export const TagService = {
  /**
   * Get all tags
   * @param query
   * @returns
   */
  async findAll(query?: object) {
    return Tag.find(query);
  },

  /**
   * Create a new tag
   * @param tag
   * @returns
   */
  async create(tag) {
    return Tag.create(tag);
  },

  /**
   * Find a tag by name
   * @param name
   * @returns
   */
  async findByName(name) {
    return Tag.findOne({ name });
  },

  /**
   * Add product to tag
   * @param name
   * @param product
   * @returns
   */
  async addToTag(name: string, product: IProductDocument) {
    const tag = await Tag.findOne({ name });
    if (!tag) {
      return Tag.create({ name, products: [product] });
    }
    return Tag.findOneAndUpdate({ name }, { $addToSet: { products: product } }, { new: true });
  },

  /**
   * Get products by tag name
   * @param name
   * @returns
   */
  async getProductsByTagName(name) {
    const tag = await Tag.findOne({ name });
    return tag?.products || [];
  },

  /**
   * Get tag by id
   * @param id
   * @returns
   */
  async findById(id) {
    return Tag.findById(id);
  },

  /**
   * Update tag by id
   * @param id
   * @param tag
   * @returns
   */
  async updateById(id, tag) {
    return Tag.findByIdAndUpdate(id, tag, { new: true });
  },

  /**
   * Delete tag by id
   * @param id
   * @returns
   */
  async deleteById(id) {
    return Tag.findByIdAndDelete(id);
  },

  /**
   * Find tags by name
   * @param name
   * @returns
   */
  async findByNames(names: string[]) {
    return Tag.find({ name: { $in: names } });
  },

  /**
   * Search tags by name
   * @param name
   * @returns
   */
  async searchByName(name) {
    return Tag.find({ name: { $regex: name, $options: 'i' } });
  },

  /**
