import { OpenAI } from "langchain/llms/openai";
import { RetrievalQAChain } from "langchain/chains";
import { HNSWLibrary } from "langchain/vectorstores/hnswlib";
import { OpenAIEmbeddings } from "langchain/embeddings/openai";
import { RecursiveCharacterTextSplitter } from "langchain/text_splitter";
import { TextLoader } from "langchain/document_loaders/fs/text";
import { basename } from "path";

const loader = new TextLoader("src/data/20231118.md");
const docs = await loader.load();
const textSplitter = new RecursiveCharacterTextSplitter({
  chunkSize: 1000,
});
const docsSplitted = await textSplitter.splitDocuments(docs);

// Create a vector store from the documents.
const vectorStore = await HNSWLibrary.fromDocuments(
  docsSplitted,
  new OpenAIEmbeddings(),
  {
    space: "cosine",
  },
);

// Create a chain that uses a map-reduce chain to answer questions.
const chain = RetrievalQAChain.fromLLM(
  new OpenAI({ temperature: 0 }),
  vectorStore.asRetriever(),
  {
    retriever: vectorStore.asRetriever(),
    returnSourceDocuments: true,
  },
);
const res = await chain.call({
  query: "How did the AI create this data?",
});

console.log(res);

