package com.alibaba.cloud.utils;

import java.io.IOException;
import java.util.concurrent.TimeUnit;

import static com.alibaba.cloud.utils.Constants.*;

import com.alibaba.cloud.utils.http.HttpRequest;
import com.alibaba.cloud.utils.http.HttpResponse;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;

public class AccessTokenUtil {
    private static final Logger LOG = LoggerFactory.getLogger(AccessTokenUtil.class);
    public static final long EXPIRE_TIME = 3600L;

    private AccessTokenUtil() {
    }

    public static AccessToken getAccessToken(AccessTokenRequest request) {
        String token = null;
        try {
            HttpRequest httpRequest = new HttpRequest(GET, TOKEN_API);
            httpRequest.addParam("app_id", request.getAppId());
            httpRequest.addParam("app_secret", request.getAppSecret());
            httpRequest.addParam("grant_type", request.getGrantType());
            if (request.getGrantType().equals("refresh_token")) {
                httpRequest.addParam("refresh_token", request.getRefreshToken());
            }
            HttpResponse response = httpRequest.timeout(3, TimeUnit.SECONDS).send();
            if (response.isSuccess()) {
                JSONObject json = JSON.parseObject(response.getBody());
                token = json.getString("access_token");
            } else {
                LOG.error("get access token failed: {}", response.getBody());
            }
        } catch (IOException e) {
            LOG.error("get access token failed", e);
        }
        return new AccessToken(token, System.currentTimeMillis() + EXPIRE_TIME * 1000);
    }

    public static String refreshToken(AccessTokenRequest request) {
        String token = null;
        try {
            HttpRequest httpRequest = new HttpRequest(GET, TOKEN_API);
            httpRequest.addParam("appid", request.getAppId());
            httpRequest.addParam("appsecret", request.getAppSecret());
            httpRequest.addParam("grant_type", request.getGrantType());
            httpRequest.addParam("refresh_token", request.getRefreshToken());
            HttpResponse response = httpRequest.timeout(3, TimeUnit.SECONDS).send();
            if (response.isSuccess()) {
                JSONObject json = JSON.parseObject(response.getBody());
                token = json.getString("refresh_token");
            } else {
                LOG.error("refresh access token failed: {}", response.getBody());
            }
        } catch (IOException e) {
            LOG.error("refresh access token failed", e);
        }
        return token;
    }

    public static AccessTokenRequest convertCredentialsToAccessTokenRequest(AlibabaCloudCredentials credentials) {
        return new AccessTokenRequest(credentials.getAppId(), credentials.getAppSecret(),
                "refresh_token", credentials.getRefreshToken());
    }

    public static AccessTokenRequest convertCredentialsToAccessTokenRequest(String appId, String appSecret, String refreshToken) {
        return new AccessTokenRequest(appId, appSecret, "refresh_token", refreshToken);
    }

    public static boolean isAccessTokenExpired(AccessToken accessToken) {
        return accessToken == null || accessToken.getExpireAt() < System.currentTimeMillis();
    }

    public static boolean isAccessTokenExpired(AccessTokenRequest accessTokenRequest) {
        return accessTokenRequest == null || accessTokenRequest.getRefreshToken() == null;
    }

    public static class AccessToken {
        private String token;
        private long expireAt;

        public AccessToken() {
        }

        public AccessToken(String token, long expireAt) {
            this.token = token;
            this.expireAt = expireAt;
        }

        public String getToken() {
            return token;
        }

        public void setToken(String token) {
            this.token = token;
        }

        public long getExpireAt() {
            return expireAt;
        }

        public void setExpireAt(long expireAt) {
            this.expireAt = expireAt;
        }
    }

    public static class AccessTokenRequest {
        private String appId;
        private String appSecret;
        private String grantType;
        private String refreshToken;

        public AccessTokenRequest() {
        }

        public AccessTokenRequest(String appId, String appSecret, String grantType, String refreshToken) {
            this.appId = appId;
            this.appSecret = appSecret;
            this.grantType = grantType;
            this.refreshToken = refreshToken;
        }

        public String getAppId() {
            return appId;
        }

        public void setAppId(String appId) {
            this.appId = appId;
        }

        public String getAppSecret() {
            return appSecret;
        }

        public void setAppSecret(String appSecret) {
            this.appSecret = appSecret;
        }

        public String getGrantType() {
            return grantType;
        }

        public void setGrantType(String grantType) {
            this.grantType = grantType;
        }

        public String getRefreshToken() {
            return refreshToken;
        }

        public void setRefreshToken(String refreshToken) {
            this.refreshToken = refreshToken;
        }
    }
}
