import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

import org.springframework.boot.context.properties.ConfigurationProperties;

import com.alibaba.cloud.model.AccessTokenRequest;
import com.alibaba.cloud.model.AlibabaCloudCredentials;

import org.springframework.http.HttpMethod;

@ConfigurationProperties(prefix = "alibaba.cloud.credentials")
public class AlibabaCloudConfig {
	public static final Set<HttpMethod> SUPPORTED_HTTP_METHODS = new HashSet<>(
			Arrays.asList(HttpMethod.GET, HttpMethod.POST, HttpMethod.DELETE,
					HttpMethod.PUT));

	private static final long EXPIRE_TIME = 3600L;

	private final AlibabaCloudCredentials credentials = new AlibabaCloudCredentials();

	private final AccessTokenRequest accessTokenRequest = new AccessTokenRequest();

	private String appSecret;

	public AlibabaCloudCredentials getCredentials() {
		return credentials;
	}

	public AccessTokenRequest getAccessTokenRequest() {
		return accessTokenRequest;
	}

	public String getAppSecret() {
		return appSecret;
	}

	public void setAppSecret(String appSecret) {
		this.appSecret = appSecret;
	}

	public static final class AlibabaCloudCredentials {
		private String appId;
		private String appSecret;
		private String region;
		private String accessKey;
		private String secretKey;

		private long ttl = EXPIRE_TIME;

		private long expireTime;

