#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <sstream>
#include <cstring>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_BUFFER_SIZE 1024

void print_usage() {
    std::cout << "Usage: ./chat_client <server_address> <server_port>" << std::endl;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        print_usage();
        return 1;
    }

    const char* server_address = argv[1];
    int server_port = atoi(argv[2]);

    // Create a socket
    int client_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (client_socket == -1) {
        std::cerr << "Error creating socket." << std::endl;
        return 1;
    }

    // Resolve the server address
    struct sockaddr_in server;
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_address, &server.sin_addr) == -1) {
        std::cerr << "Error resolving server address." << std::endl;
        return 1;
    }

    // Connect to the server
    if (connect(client_socket, (struct sockaddr*)&server, sizeof(server)) == -1) {
        std::cerr << "Error connecting to server." << std::endl;
        return 1;
    }

    std::vector<std::string> messages;
    std::cout << "Please enter your name: ";
    std::string name;
    std::cin >> name;

    // Receive and display messages
    char buffer[MAX_BUFFER_SIZE];
    int bytes_received;
    while ((bytes_received = recv(client_socket, buffer, MAX_BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        std::string message(buffer);
        if (message.find("History") != std::string::npos) {
            std::istringstream iss(message);
            std::string line;
            while (std::getline(iss, line)) {
                std::istringstream iss2(line);
                std::string sender, msg;
                std::getline(iss2, sender, ' ');
                std::getline(iss2, msg);
                messages.push_back(message);
                std::cout << sender << ": " << msg << std::endl;
            }
        } else if (message.find("HistoryEnd") != std::string::npos) {
            break;
        } else {
            std::cout << message << std::endl;
        }
    }

    // Send and receive messages
    while (true) {
        char buffer[MAX_BUFFER_SIZE];
        std::string message;
        std::getline(std::cin, message);

        if (message == "exit") {
            break;
        }

        std::string full_message = name + ": " + message + "\n";
        int bytes_sent = send(client_socket, full_message.c_str(), full_message.size(), 0);
        if (bytes_sent == -1) {
            std::cerr << "Error sending message." << std::endl;
            break;
        }

        message = name + ": " + message;
        messages.push_back(message);

        // Receive the server's response
        memset(buffer, 0, MAX_BUFFER_SIZE);
        int bytes_received = recv(client_socket, buffer, MAX_BUFFER_SIZE - 1, 0);
        if (bytes_received == -1) {
            std::cerr << "Error receiving message." << std::endl;
            break;
        }
        buffer[bytes_received] = '\0';
        std::cout << buffer << std::endl;
    }

    // Clean up
    close(client_socket);
    std::ofstream history_file("history.txt", std::ios::out | std::ios::app);
    for (const std::string& msg : messages) {
        history_file << msg << std::endl;
    }
    history_file.close();

    return 0;
}
