from qwen_cpp.client import QwenCppClient

# Modify the path according to your actual installation
model_path = "/path/to/qwen-7b-chat"

# Initialize the client
client = QwenCppClient(model_path)

# Start streaming
client.start_streaming()

# Chat with the model
while True:
    user_input = input("User: ")
    if user_input == "exit":
        break

    client.run(user_input)
    response = client.get_response()
    print("Assistant:", response)

# Stop streaming
client.stop_streaming()

# Clean up
client.destroy()
