class Solution {
public:
    int maxValue(vector<vector<int>>& grid) {
        int m=grid.size(),n=grid[0].size();
        vector<vector<int>> dp(m,vector<int>(n));
        for(int i=0;i<m;i++){
            for(int j=0;j<n;j++){
                dp[i][j]=grid[i][j];
                if(i>0)
                    dp[i][j]=max(dp[i][j]+dp[i-1][j],dp[i][j]);
                if(j>0)
                    dp[i][j]=max(dp[i][j]+dp[i][j-1],dp[i][j]);
            }
        }
        return dp[m-1][n-1];
    }
};
