const express = require('express');
const router = express.Router();
const Article = require('../models/Article');
const User = require('../models/User');
const { ensureAuthenticated } = require('../config/auth');

router.get('/add', ensureAuthenticated, async (req, res) => {
    try {
        const users = await User.find();
        res.render('articles/add', { users });
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

router.post('/add', ensureAuthenticated, async (req, res) => {
    try {
        const { title, content, author } = req.body;

        const newArticle = new Article({
            title,
            content,
            author,
            date: Date.now(),
        });

        await newArticle.save();
        req.flash('success_msg', 'Article added successfully');
        res.redirect('/articles');
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

router.get('/', async (req, res) => {
    try {
        const articles = await Article.find().sort({ date: -1 });
        res.render('articles/index', { articles });
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

router.get('/:id', async (req, res) => {
    try {
        const article = await Article.findById(req.params.id);
        if (!article) {
            return res.status(404).render('404');
        }
        res.render('articles/show', { article });
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

router.get('/edit/:id', ensureAuthenticated, async (req, res) => {
    try {
        const article = await Article.findById(req.params.id);
        if (!article) {
            return res.status(404).render('404');
        }

        if (req.user.id !== article.author.id) {
            return res.status(403).render('403');
        }

        const users = await User.find();
        res.render('articles/edit', { article, users });
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

router.put('/:id', ensureAuthenticated, async (req, res) => {
    try {
        const { title, content, author } = req.body;

        const article = await Article.findById(req.params.id);
        if (!article) {
            return res.status(404).render('404');
        }

        if (req.user.id !== article.author.id) {
            return res.status(403).render('403');
        }

        article.title = title;
        article.content = content;
        article.author = author;

        await article.save();
        req.flash('success_msg', 'Article updated successfully');
        res.redirect('/articles');
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

router.delete('/:id', ensureAuthenticated, async (req, res) => {
    try {
        const article = await Article.findById(req.params.id);
        if (!article) {
            return res.status(404).render('404');
        }

        if (req.user.id !== article.author.id) {
            return res.status(403).render('403');
        }

        await article.remove();
        req.flash('success_msg', 'Article removed successfully');
        res.redirect('/articles');
    } catch (err) {
        console.error(err);
        res.status(500).send('Server Error');
    }
});

