package com.qwen.ai.chain;

import com.qwen.ai.config.QwenConfig;
import com.qwen.ai.messages.ChatMessage;
import com.qwen.ai.messages.SystemMessage;
import com.qwen.ai.messages.UserMessage;
import com.qwen.ai.model.QwenModel;
import com.qwen.ai.model.QwenModelFactory;
import com.qwen.ai.model.QwenModelType;
import com.qwen.ai.model.QwenRequest;
import com.qwen.ai.model.QwenResponse;
import com.qwen.ai.service.QwenService;
import com.qwen.ai.util.StringUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.*;

@Slf4j
@Component
public class GPTChain {

    private final QwenService qwenService;
    private final QwenConfig qwenConfig;
    private final QwenModelFactory qwenModelFactory;

    @Autowired
    public GPTChain(QwenService qwenService, QwenConfig qwenConfig, QwenModelFactory qwenModelFactory) {
        this.qwenService = qwenService;
        this.qwenConfig = qwenConfig;
        this.qwenModelFactory = qwenModelFactory;
    }

    public String chat(String prompt, List<String> messages, String model) {
        QwenRequest request = new QwenRequest();
        request.setMessages(getMessages(prompt, messages));
        request.setModel(model);
        request.setTemperature(qwenConfig.getTemperature());
        request.setTopP(qwenConfig.getTopP());
        request.setTopK(qwenConfig.getTopK());
        request.setPresencePenalty(qwenConfig.getPresencePenalty());
        request.setFrequencyPenalty(qwenConfig.getFrequencyPenalty());
        request.setPrompt(prompt);
        request.setStop(qwenConfig.getStop());
        request.setUser(qwenConfig.getUser());
        QwenResponse response = qwenService.chat(request);
        return response.getAnswers().get(0);
    }

    private List<ChatMessage> getMessages(String prompt, List<String> messages) {
        List<ChatMessage> chatMessages = new ArrayList<>();
        if (Objects.nonNull(messages)) {
            for (String message : messages) {
                if (StringUtils.isEmpty(message)) {
                    continue;
                }
                if (message.startsWith("System:")) {
                    chatMessages.add(new SystemMessage(message.substring(7)));
                } else if (message.startsWith("User:")) {
                    chatMessages.add(new UserMessage(message.substring(5)));
                } else {
                    chatMessages.add(new UserMessage(message));
                }
            }
        }
        if (Objects.nonNull(prompt)) {
            chatMessages.add(new UserMessage(prompt));
        }
        return chatMessages;
    }

    public String chat(String prompt) {
        return chat(prompt, null, qwenConfig.getModel());
    }

    public String chat(String prompt, String model) {
        return chat(prompt, null, model);
    }

    public String chat(List<String> messages) {
        return chat(null, messages, qwenConfig.getModel());
    }

    public String chat(List<Strin<|fim_suffix|>g prompt, List<String> messages) {
        return chat(prompt, messages, qwenConfig.getModel());
    }

    public String chat(String prompt, List<String> messages, String model) {
        if (QwenModelType.Qwen7B.getName().equalsIgnoreCase(model)) {
            return chat7b(prompt, messages);
        } else {
            return chat(prompt, messages, model);
        }
    }

    public String chat7b(String prompt, List<String> messages) {
        QwenModel qwenModel = qwenModelFactory.getModel(QwenModelType.Qwen7B.getName());
        String model = qwenModel.getModel();
        List<ChatMessage> chatMessages = getMessages(prompt, messages);
        String input = getChatMessages(chatMessages);
        String output = qwenService.chat7b(input, model);
        return output;
    }

    private String getChatMessages(List<ChatMessage> chatMessages) {
        StringBuilder sb = new StringBuilder();
        for (ChatMessage message : chatMessages) {
            sb.append(message.toChatML());
        }
        return sb.toString();
    }

    public String chat7b(String prompt) {
        return chat7b(prompt, null);
    }

    public String chat7b(List<String> messages) {
        return chat7b(null, messages);
    }

    public String chat7b(List<String> messages, String model) {
        return chat7b(null, messages);
    }

    public String chat7b(String prompt, List<String> messages, String model) {
        return chat7b(prompt, messages);
    }
