package com.qwen.ai.model;

import com.alibaba.fastjson.JSONObject;
import lombok.Data;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Data
public class QwenRequest implements Serializable {
    private static final long serialVersionUID = 1L;

    private List<ChatMessage> messages;
    private String prompt;
    private String model;
    private Integer maxTokens;
    private Boolean stream;
    private Double temperature;
    private Double topP;
    private Integer topK;
    private Double presencePenalty;
    private Double frequencyPenalty;
    private List<String> stop;
    private String user;
    private String n;
    private Map<String, String> customParams;

    public static QwenRequest fromJSON(String json) {
        QwenRequest request = JSONObject.parseObject(json, QwenRequest.class);
        if (request.getCustomParams() == null || request.getCustomParams().isEmpty()) {
            return request;
        }
        Map<String, String> customParams = new HashMap<>();
        for (Map.Entry<String, String> entry : request.getCustomParams().entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue();
            if ("prompt".equals(key) && value.startsWith("[") && value.endsWith("]")) {
                value = value.substring(1, value.length() - 1);
                List<String> promptList = new ArrayList<>();
                for (String prompt : value.split(",")) {
                    promptList.add(prompt.trim());
                }
                request.setPrompt(promptList);
            } else if ("stop".equals(key) && value.startsWith("[") && value.endsWith("]")) {
                value = value.substring(1, value.length() - 1);
                List<String> stopList = new ArrayList<>();
                for (String stop : value.split(",")) {
                    stopList.add(stop.trim());
                }
                request.setStop(stopList);
            } else {
                customParams.put(key, value);
            }
        }
        request.setCustomParams(customParams);
        return request;
    }

    public JSONObject toJSON() {
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("messages", messages);
        jsonObject.put("prompt", prompt);
        jsonObject.put("model", model);
        jsonObject.put("maxTokens", maxTokens);
        jsonObject.put("stream", stream);
        jsonObject.put("temperature", temperature);
        jsonObject.put("topP", topP);
        jsonObject.put("topK", topK);
        jsonObject.put("presencePenalty", presencePenalty);
        jsonObject.put("frequencyPenalty", frequencyPenalty);
        jsonObject.put("stop", stop);
        jsonObject.put("user", user);
        jsonObject.put("n", n);
        jsonObject.put("customParams", customParams);
        return jsonObject;
    }

    public static void main(String[] args) {
        QwenRequest request = new QwenRequest();
        request.setModel("qwen-7b");
        request.setTemperature(0.7);
        request.setTopP(0.95);
        request.setTopK(40);
        request.setPresencePenalty(0.0);
        request.setFrequencyPenalty(0.0);
        request.setStop(Arrays.asList("用户:", "系统:", "Qwen:"));
        request.setPrompt("请列出五种日本料理，并简要描述它们的口味特点。");
        request.setUser("system");
        System.out.println(request);

        String json = "{\"messages\":[{\"role\":\"system\",\"content\":\"You are a helpful assistant.\"},{\"role\":\"user\",\"content\":\"Ping me.\"}],\"model\":\"qwen-7b\",\"prompt\":\"Please list five types of Japanese cuisine and briefly describe their flavor characteristics.\",\"maxTokens\":512,\"stream\":false,\"temperature\":0.7,\"topP\":0.95,\"topK\":40,\"presencePenalty\":0.0,\"frequencyPenalty\":0.0,\"stop\":[\"用户:\",\"系统:\",\"Qwen:\"],\"user\":\"system\"}";
        QwenRequest fromJSON = QwenRequest.fromJSON(json);
        System.out.println(fromJSON);
    }
}

