import java.util.*;

class Solution {
    public String[] solution(String[] orders, int[] course) {
        Map<String, Integer> counter = new HashMap<>();
        for (String order : orders) {
            char[] orderChars = order.toCharArray();
            Arrays.sort(orderChars);
            order = new String(orderChars);
            for (int i = 0; i < order.length(); i++) {
                Set<String> tmp = new HashSet<>();
                dfs(tmp, order, i, new StringBuilder());
                tmp.forEach(counter::merge);
            }
        }
        Map<Integer, Integer> maxCount = new HashMap<>();
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        for (Map.Entry<String, Integer> entry : counter.entrySet()) {
            int length = entry.getKey().length();
            int count = entry.getValue();
            maxCount.merge(length, count, (a, b) -> Math.max(a, b));
            min = Math.min(min, length);
            max = Math.max(max, length);
        }
        List<String> res = new ArrayList<>();
        for (int n : course) {
            if (!maxCount.containsKey(n)) continue;
            for (Map.Entry<String, Integer> entry : counter.entrySet()) {
                if (entry.getKey().length() == n && entry.getValue() == maxCount.get(n)) {
                    res.add(entry.getKey());
                }
            }
        }
        Collections.sort(res);
        return res.toArray(new String[]{});
    }

    private void dfs(Set<String> tmp, String order, int index, StringBuilder sb) {
        sb.append(order.charAt(index));
        tmp.add(sb.toString());
        for (int i = index + 1; i < order.length(); i++) {
            dfs(tmp, order, i, sb);
        }
        sb.deleteCharAt(sb.length() - 1);
    }
}

class Main {
    public static void main(String[] args) {
        Solution so = new Solution();
//        System.out.println(Arrays.toString(so.solution(new String[]{"ABCFG", "AC", "CDE", "ACDE", "BCFG", "ACDEH"}, new int[]{2, 3, 4})));
//        System.out.println(Arrays.toString(so.solution(new String[]{"ABCDE", "AB", "CD", "ADE", "XYZ", "XYZ", "ACD"}, new int[]{2, 3, 5})));
        System.out.println(Arrays.toString(so.solution(new String[]{"XYZ", "XWY", "WXA"}, new int[]{2, 3, 4})));
    }
}

