import java.util.*;

class Solution {
    public int[] solution(int[] progresses, int[] speeds) {
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < progresses.length; i++) {
            queue.offer((100 - progresses[i]) / speeds[i] + (100 - progresses[i]) % speeds[i] != 0 ? 1 : 0);
        }
        int size = queue.size();
        List<Integer> res = new ArrayList<>();
        int count = 0;
        while (!queue.isEmpty()) {
            int n = queue.poll();
            if (n == 0) {
                count++;
            } else if (count != 0) {
                res.add(count);
                count = 0;
            }
            queue.offer(n);
        }
        res.add(count);
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Main {
    public static void main(String[] args) {
        Solution so = new Solution();
        System.out.println(Arrays.toString(so.solution(new int[]{93, 30, 55}, new int[]{1, 30, 5})));
        System.out.println(Arrays.toString(so.solution(new int[]{95, 90, 99, 99, 80, 99}, new int[]{1, 1, 1, 1, 1, 1})));
    }
}

