#![allow(non_snake_case)]

mod bnb;
mod bfs;
mod bsp_kcore;
mod bfs_st;
mod bfs_knn;
mod bfs_knn_st;
mod bsp;
mod degree;
mod lpa;
mod pagerank;
mod sssp;
mod wcc;

use crate::algorithm::*;

use std::sync::Arc;

use crate::options::AlgorithmOptions;

pub fn run<T: Clone + Send>(alg: Algorithm, opts: AlgorithmOptions, graph: Arc<IrGraph<T>>) {
    match alg {
        Algorithm::BspKCore => bsp_kcore::run(graph, opts),
        Algorithm::Bfs => bfs::run(graph, opts),
        Algorithm::BfsSt => bfs_st::run(graph, opts),
        Algorithm::BfsKnn => bfs_knn::run(graph, opts),
        Algorithm::BfsKnnSt => bfs_knn_st::run(graph, opts),
        Algorithm::Bsp => bsp::run(graph, opts),
        Algorithm::Bnb => bnb::run(graph, opts),
        Algorithm::Degree => degree::run(graph, opts),
        Algorithm::Lpa => lpa::run(graph, opts),
        Algorithm::Pagerank => pagerank::run(graph, opts),
        Algorithm::Sssp => sssp::run(graph, opts),
        Algorithm::Wcc => wcc::run(graph, opts),
    }
}

pub fn run_with_output<T: Clone + Send>(
    alg: Algorithm,
    opts: AlgorithmOptions,
    graph: Arc<IrGraph<T>>,
) {
    match alg {
        Algorithm::Lpa => lpa::run_with_output(graph, opts),
        Algorithm::Pagerank => pagerank::run_with_output(graph, opts),
        _ => run(alg, opts, graph),
    }
}

