import { type LoadFunction } from '../../types'
import { fetch } from '../util/fetch'
import { type HostingOptions } from '../types'

/**
 * @experimental You can use this method but it may change without notice
 * @param hostname - The hostname of the proxy server
 * @param options - Options
 * @returns A load function that uses a proxy server
 */
export const proxy: (hostname: string, options?: HostingOptions) => LoadFunction =
  (hostname, options) => async (path) => {
    const url = new URL(path, hostname)

    if (options?.token) {
      url.searchParams.set('token', options.token)
    }

    return await fetch(url.href, {
      method: 'GET',
      headers: { 'user-agent': options?.userAgent },
    })
  }
