import { type HostingOptions } from '../types'
import { fetch } from '../util/fetch'

/**
 * @experimental You can use this method but it may change without notice
 * @param options - Options
 * @returns A load function for the OpenAI hosting
 */
export const openaiHosting = (options?: HostingOptions): LoadFunction => {
  const url = new URL('https://api.openai.com/v1/chat/completions')

  if (options?.token) {
    url.searchParams.set('Authorization', `Bearer ${options.token}`)
  }

  return async (path) => {
    const body = await fetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'User-Agent': options?.userAgent },
      body: JSON.stringify({
        model: 'gpt-3.5-turbo',
        messages: [{ role: 'user', content: `Read the following passage:
${path}` }],
      }),
    })

