import os
from flask import Flask, render_template, request
import openai
import hashlib
import requests
from config import *

app = Flask(__name__)


@app.route('/')
def index():
    return render_template('index.html')


@app.route('/generate', methods=['POST'])
def generate():
    prompt = request.form['prompt']
    response = openai.Image.create(
        prompt=prompt,
        n=1,
        size="256x256",
        response_format="b64_json"
    )
    image_data = response['data'][0]['b64_json']
    image_url = "data:image/png;base64," + image_data
    return render_template('result.html', image_url=image_url)


@app.route('/share', methods=['POST'])
def share():
    prompt = request.form['prompt']
    response = openai.Image.create(
        prompt=prompt,
        n=1,
        size="256x256",
        response_format="b64_json"
    )
    image_data = response['data'][0]['b64_json']
    image_url = "data:image/png;base64," + image_data
    url = request.url_root + "generate"
    payload = {
        'prompt': prompt,
        'image_data': image_data
    }
    headers = {'Content-Type': 'application/json'}
    response = requests.post(url, headers=headers, json=payload)
    if response.status_code == 200:
        return render_template('share.html', image_url=image_url, share_code=response.text)
    else:
        return render_template('error.html', message='Failed to share image')


if __name__ == '__main__':
    app.run(port=5000)
