import json
from typing import List

import requests


class AI:
    def __init__(self, api_key: str, api_secret: str, api_url: str):
        self.api_key = api_key
        self.api_secret = api_secret
        self.api_url = api_url

    @staticmethod
    def _token() -> str:
        return "Bearer " + json.loads(
            requests.post(
                "https://aip.baidubce.com/oauth/2.0/token",
                data={"grant_type": "client_credentials", "client_id": api_key, "client_secret": api_secret},
            ).text
        )["access_token"]

    @staticmethod
    def _headers() -> dict:
        return {"Content-Type": "application/json", "Accept": "application/json"}

    def query(self, text: str, type: str = "chat", history: List[str] = None) -> str:
        if history is None:
            history = []
        return json.loads(
            requests.post(
                self.api_url,
                data=json.dumps(
                    {"query": text, "type": type, "history": history},
                    ensure_ascii=False,
                ),
                headers={
                    **self._headers(),
                    "Authorization": self._token(),
                },
            ).text,
        )["response"]

    def chat(self, text: str, history: List[str] = None) -> str:
        return self.query(text, type="chat", history=history)

    def text_to_image(self, text: str, width: int = 512, height: int = 512, quality: int = 85) -> bytes:
        data = {"text": text, "width": width, "height": height, "quality": quality}
        return requests.post(
            self.api_url,
            data=json.dumps(data, ensure_ascii=False),
            headers={
                **self._headers(),
                "Authorization": self._token(),
                "Content-Type": "text/plain",
            },
        ).content

    def text_to_voice(
        self,
        text: str,
        speaker: int = 0,
