import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  isAuthenticated() {
    // Check if the user is authenticated based on your authentication logic
    // Replace this with your own logic to determine if the user is authenticated
    return localStorage.getItem('accessToken') !== null;
  }

  logout() {
    // Clear the authentication data whenever the user clicks the logout button
    localStorage.removeItem('accessToken');
  }
}

