func mergeLists(list1 []int, list2 []int) []int {
    mergedList := []int{}
    len1, len2 := len(list1), len(list2)
    i, j := 0, 0

    for i < len1 && j < len2 {
        if list1[i] < list2[j] {
            mergedList = append(mergedList, list1[i])
            i++
        } else {
            mergedList = append(mergedList, list2[j])
            j++
        }
    }

    for i < len1 {
        mergedList = append(mergedList, list1[i])
        i++
    }

    for j < len2 {
        mergedList = append(mergedList, list2[j])
        j++
    }

    return mergedList
}
