import os
import time
import base64
import requests
import hashlib
import hmac
import json
import random

from .config import API_KEY, API_SECRET, HOST

API_KEY = API_KEY
API_SECRET = API_SECRET
HOST = HOST
BASE_URL = HOST + '/v2/openapi'


def generate_timestamp():
    return str(int(time.time() * 1000))


def generate_nonce():
    return str(random.randint(10000, 99999))


def generate_signature(data):
    data = dict(sorted(data.items(), key=lambda e: e[0], reverse=False))
    message = '\n'.join(['='.join(map(str, item)) for item in data.items()])
    signature = hmac.new(
        API_SECRET.encode('utf-8'), msg=message.encode('utf-8'), digestmod=hashlib.sha256).hexdigest()
    return signature


def generate_access_token():
    nonce = generate_nonce()
    timestamp = generate_timestamp()
    data = {
        'apiKey': API_KEY,
        'nonce': nonce,
        'timestamp': timestamp
    }
    data['signature'] = generate_signature(data)
    return data


def get_content_type(prefix="json", suffix=""):
    return f"{prefix}/{suffix}"


def get_url(api_path, api_version):
    return f"{BASE_URL}/{api_version}/{api_path}"


def get(api_path, api_version, params):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
        "Content-Type": get_content_type("application", "json")
    }
    response = requests.get(get_url(api_path, api_version), params=params, headers=headers, timeout=3)
    return response.text


def post(api_path, api_version, params, data):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
        "Content-Type": get_content_type("application", "json")
    }
    response = requests.post(get_url(api_path, api_version), params=params, json=data, headers=headers, timeout=3)
    return response.text


def post_file(api_path, api_version, params, data):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
        "Content-Type": get_content_type("multipart", "form-data")
    }
    response = requests.post(get_url(api_path, api_version), params=params, files=data, headers=headers, timeout=3)
    return response.text


def post_file_with_url(api_path, api_version, params, data):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
        "Content-Type": get_content_type("multipart", "form-data")
    }
    response = requests.post(get_url(api_path, api_version), params=params, data=data, headers=headers, timeout=3)
    return response.text


def post_files(api_path, api_version, params, data, files=None):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
        "Content-Type": get_content_type("multipart", "form-data")
    }
    response = requests.post(get_url(api_path, api_version), params=params, files=files, data=data, headers=headers,
                             timeout=3)
    return response.text


def post_stream(api_path, api_version, params, data):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
        "Content-Type": get_content_type("application", "json")
    }
    response = requests.post(get_url(api_path, api_version), params=params, data=data, headers=headers, timeout=3,
                             stream=True)
    return response.text


def get_stream(api_path, api_version, params):
    headers = {
        "Authorization": f"Bearer {generate_access_token()['apiKey']}",
