import { createYield } from "typescript";
import { createClient } from "@supabase/supabase-js";
import { NextResponse } from "next/server";
import { type } from "os";

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY
);

export async function POST(req: Request) {
  const { messages, user } = await req.json();

  const prompt = messages[messages.length - 1].content;
  const timestamp = Date.now();
  const id = Math.random().toString(36).substr(2, 9);

  const res = await fetch(process.env.AI_URL ?? "", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      messages,
      prompt,
      system: messages[0].content,
      temperature: 0.3,
      top_p: 1,
      user,
      stream: true,
    }),
  });
  const stream = res.body;
  if (!stream) {
    return new NextResponse("stream is null", { status: 500 });
  }
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let result = "";
  let i = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    const chunk = decoder.decode(value, { stream: true });
    result += chunk;

    if (chunk.startsWith("data:")) {
      const data = chunk.slice(5);
      if (data === "[DONE]\n") {
        break;
      }
      const parsedData = JSON.parse(data);
      const token = parsedData.choices[0].delta.content;
      if (token) {
        await supabase.from("chat").insert({
          id,
          timestamp,
          user,
          token,
        });
      }
    }
  }

  await supabase
    .from("chat")
    .insert([
      { id, timestamp, user, token: "\n" },
      { id, timestamp, user: "system", token: "\n" },
    ]);
  return new NextResponse(result, { status: 200 });
}

export async function GET(req: Request) {
  const { user } = await req.json();

  const { data, error } = await supabase
    .from("chat")
    .select("*")
    .eq("user", user)
    .order("timestamp", { ascending: false })
    .limit(10000);

  if (error) {
    return new NextResponse(error.message, { status: 500 });
  }
  const userChat = data.filter((d) => d.user === user);
  const systemChat = data.filter((d) => d.user === "system");
  const result = userChat.map((d) => d.token).join("");
  const systemResult = systemChat.map((d) => d.token).join("");

  return new NextResponse(
    JSON.stringify({
      result,
      systemResult,
    }),
    { status: 200 }
  );
}

export async function DELETE(req: Request) {
  const { user } = await req.json();

  const { data, error } = await supabase
    .from("chat")
    .delete()
    .eq("user", user);

  if (error) {
    return new NextResponse(error.message, { status: 500 });
  }
  return new NextResponse(JSON.stringify({ data }), { status: 200 });
}

