const { openai } = require('../openai');
const { retrieve } = require('../retrieve');
const { query, deleteQuery, addQuery } = require('../redis');

const fs = require('fs');

const debug = require('debug')('chatbot:logs');
const debugError = require('debug')('chatbot:error');

const redisConfig = require('../config/redisConfig');
const redis = redisConfig.client;

const prompt = fs.readFileSync('prompt.txt', 'utf8');

const getResponse = async (req, res) => {
  try {
    if (req.query?.text != undefined && req.query?.text != '') {
      const text = req.query.text;

      // Query Redis for the response
      const response = await query(redis, text);

      // If response is not in Redis, call OpenAI API for a response
      if (response == null) {
        const completion = await openai.createChatCompletion({
          model: 'gpt-3.5-turbo',
          messages: [
            { role: 'system', content: prompt },
            { role: 'user', content: text },
          ],
          temperature: 0.7,
          stream: true,
        });

        // Process the stream of data from OpenAI
        const stream = completion.data;

        const chunks = [];
        for await (const chunk of stream) {
          const delta = chunk.choices[0].delta;
          if (delta.content) {
            chunks.push(delta.content);
          }
        }

        // Concatenate the chunks to form the complete response
        const result = chunks.join('');

        // Store the response in Redis with a timeout of 1 minute
        addQuery(redis, text, result);

        return res.status(200).send(result);
      } else {
        return res.status(200).send(response);
      }
    } else {
      return res.status(400).send({
        error: 'No text provided',
      });
    }
  } catch (error) {
    debugError(error);
    return res.status(500).send({
      error: error.message,
    });
  }
};

const deleteCache = async (req, res) => {
  try {
    const text = req.query.text;
    // Delete the cache associated with the text from Redis
    await deleteQuery(redis, text);

    return res.status(200).send({
      message: 'Cache deleted successfully',
    });
  } catch (error) {
    debugError(error);
    return res.status(500).send({
      error: error.message,
    });
  }
};

const deleteAllCache = async (req, res) => {
  try {
    // Delete all cache from Redis
    await deleteQuery(redis, '*');

    return res.status(200).send({
      message: 'All cache deleted successfully',
    });
  } catch (error) {
    debugError(error);
    return res.status(500).send({
      error: error.message,
    });
  }
};

