import datetime
from textwrap import dedent

import discord
from discord import app_commands
from discord.ext import commands

from utils import config
from utils import db


class Roleplay(commands.Cog):
    def __init__(self, bot: commands.Bot):
        self.bot = bot

    @commands.command()
    @commands.cooldown(1, 20, commands.BucketType.user)
    @commands.bot_has_permissions(attach_files=True)
    async def roleplay(self, ctx, user: discord.Member = None):
        if not user:
            return await ctx.reply(
                "Please provide a user to roleplay with.\n"
                "Example:\n"
                "`{prefix}roleplay @username`"
            )

        if user == ctx.author:
            return await ctx.reply("You can't roleplay with yourself.")

        if user.bot:
            return await ctx.reply("You can't roleplay with bots.")

        if user == self.bot.user:
            return await ctx.reply("You can't roleplay with me.")

        if user.status == discord.Status.offline:
            return await ctx.reply("The user is offline.")

        if user.status == discord.Status.invisible:
            return await ctx.reply("The user is invisible.")

        if ctx.guild and user not in ctx.guild.members:
            return await ctx.reply("The user is not in this server.")

        async with ctx.typing():
            async with db.pool.acquire() as conn:
                async with conn.transaction():
                    await db.insert(
                        conn,
                        "CREATE TABLE IF NOT EXISTS roleplay_logs (roleplay_id SERIAL PRIMARY KEY, guild_id BIGINT, channel_id BIGINT, author_id BIGINT, target_id BIGINT, roleplay_type VARCHAR(255), roleplay_context VARCHAR(255), roleplay_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP);",
                    )

                    roleplay_logs = await db.fetch(
                        conn,
                        "SELECT * FROM roleplay_logs WHERE guild_id = $1 AND author_id = $2 AND target_id = $3 AND roleplay_date >= NOW() - INTERVAL '1 day';",
                        ctx.guild.id,
                        ctx.author.id,
                        user.id
                    )

                    if len(roleplay_logs) >= 5:
                        return await ctx.reply(
                            "You can only have 5 roleplays in a day.\n"
                            "You can check your roleplay history by using `{prefix}roleplay history`."
                        )

                    roleplay_context = await self.generate_roleplay_context(ctx.author, user)
                    roleplay_type = await self.generate_roleplay_type(ctx.author, user)

                    await db.insert(
                        conn,
                        "INSERT INTO roleplay_logs (guild_id, channel_id, author_id, target_id, roleplay_type, roleplay_context) VALUES ($1, $2, $3, $4, $5, $6);",
                        ctx.guild.id,
                        ctx.channel.id,
                        ctx.author.id,
                        user.id,
                        roleplay_type,
                        roleplay_context,
                    )

                    roleplay_message = await ctx.send(
                        f"{ctx.author.mention} is roleplaying with {user.mention}."
                    )

                    await roleplay_message.add_reaction("✅")
                    await roleplay_message.add_reaction("❌")

                    def check(reaction, user):
                        return (
                            reaction.message.id == roleplay_message.id
                            and user == ctx.author
                        )

                    try:
                        reaction, user = await self.bot.wait_for(
                            "reaction_add", timeout=60, check=check
                        )

                        if reaction.emoji == "❌":
                            await roleplay_message.delete()
                            return await ctx.reply("Roleplay cancelled.")
                    except (discord.errors.TimeoutError, discord.errors.Forbidden):
                        return await ctx.reply("Roleplay cancelled.")

                    roleplay_data = {
                        "roleplay_type": roleplay_type,
                        "roleplay_context": roleplay_context
                    }

                    await self.generate_roleplay(ctx, user, roleplay_data)

    @commands.command()
    @commands.cooldown(1, 20, commands.BucketType.user)
    @commands.bot_has_permissions(attach_files=True)
    async def roleplayhistory(self, ctx, user: discord.Member = None):
        if not user:
            return await ctx.reply(
                "Please provide a user to view their roleplay history.\n"
                "Example:\n"
                "`{prefix}roleplayhistory @username`"
            )

        if user == ctx.author:
            return await ctx.reply("You can't view your own roleplay history.")

        if user.bot:
            return await ctx.reply("You can't view the roleplay history of bots.")

        if user == self.bot.user:
            return await ctx.reply("You can't view the roleplay history of me.")

        if ctx.guild and user not in ctx.guild.members:
            return await ctx.reply("The user is not in this server.")

        async with ctx.typing():
            async with db.pool.acquire() as conn:
                async with conn.transaction():
                    roleplay_logs = await db.fetch(
                        conn,
                        "SELECT * FROM roleplay_logs WHERE guild_id = $1 AND (author_id = $2 OR target_id = $2) ORDER BY roleplay_date DESC;",
                        ctx.guild.id,
                        user.id
                    )

                    if not roleplay_logs:
                        return await ctx.reply("The user has no roleplay history.")

                    roleplay_logs_data = []

                    for roleplay_log in roleplay_logs:
                        roleplay_author = self.bot.get_user(roleplay_log["author_id"])
                        roleplay_type = roleplay_log["roleplay_type"]
                        roleplay_context = roleplay_log["roleplay_context"]
                        roleplay_date = roleplay_log["roleplay_date"]

                        roleplay_logs_data.append({
                            "roleplay_author": roleplay_author,
                            "roleplay_type": roleplay_type,
                            "roleplay_context": roleplay_context,
                            "roleplay_date": roleplay_date,
                        })

                    roleplay_logs_embed = discord.Embed(
                        title=f"{user.display_name} Roleplay History",
                        description=f"Showing roleplay history for {user.mention} from the last 7 days.\n"
                                    f"Data is sorted by date in descending order.\n"
                                    f"Total roleplays: {len(roleplay_logs_data)}",
                        color=discord.Color.blue()
                    )

                    for roleplay_log in roleplay_logs_data:
                        roleplay_author = roleplay_log["roleplay_author"]
                        roleplay_type = roleplay_log["roleplay_type"]
                        roleplay_context = roleplay_log["roleplay_context"]
                        roleplay_date = roleplay_log["roleplay_date"]

                        roleplay_logs_embed.add_field(
                            name=f"{roleplay_author.display_name} {roleplay_type}",
                            value=f"Context: {roleplay_context}\n"
                                  f"Date: {roleplay_date}",
                            inline=False
                        )

                    return await ctx.reply(embed=roleplay_logs_embed)


