const fs = require('fs')
const path = require('path')
const shell = require('shelljs')

module.exports = {
  createFile,
  replaceInFile,
  copyFile,
  removeFile,
  isExist,
  isFile,
  cleanDir,
  isDir,
  isGitRepo,
  isDockerRepo,
  isNpmRepo,
  isYarnRepo,
  isPnpmRepo,
  getPackageManager,
  git
}

/**
 * 拷贝文件
 * @param source
 * @param target
 */
function copyFile(source, target) {
  shell.cp('-r', source, target)
}

/**
 * 删除文件
 * @param filepath
 */
function removeFile(filepath) {
  shell.rm('-rf', filepath)
}

/**
 * 创建文件
 * @param filepath
 * @param content
 */
function createFile(filepath, content) {
  fs.writeFileSync(filepath, content)
}

/**
 * 替换文件内容
 * @param filePath
 * @param source
 * @param target
 */
function replaceInFile(filePath, source, target) {
  let content = fs.readFileSync(filePath).toString()
  content = content.replace(source, target)
  fs.writeFileSync(filePath, content)
}

/**
 * 是否存在
 * @param path
 * @returns {boolean}
 */
function isExist(path) {
  return fs.existsSync(path)
}

/**
 * 是否是文件
 * @param filePath
 * @returns {boolean}
 */
function isFile(filePath) {
  return fs.statSync(filePath).isFile()
}

/**
 * 是否是目录
 * @param path
 * @returns {boolean}
 */
function isDir(path) {
  return fs.statSync(path).isDirectory()
}

/**
 * 清空目录
 * @param path
 */
function cleanDir(path) {
  if (isExist(path)) {
    fs.readdirSync(path).forEach((file) => {
      const curPath = path + '/' + file
      if (isDir(curPath)) {
        cleanDir(curPath)
      } else {
        fs.unlinkSync(curPath)
      }
    })
    fs.rmdirSync(path)
  }
}

/**
 * 是否是git仓库
 * @param path
 * @returns {boolean}
 */
function isGitRepo(path) {
  return fs.existsSync(path + '/.git')
}

/**
 * 是否是docker仓库
 * @param path
 * @returns {boolean}
 */
function isDockerRepo(path) {
  return fs.existsSync(path + '/.dockerignore')
}

/**
 * 是否是npm仓库
 * @param path
 * @returns {boolean}
 */
function isNpmRepo(path) {
  return fs.existsSync(path + '/package.json')
}

/**
 * 是否是yarn仓库
 * @param path
 * @returns {boolean}
 */
function isYarnRepo(path) {
  return fs.existsSync(path + '/yarn.lock')
}

/**
 * 是否是pnpm仓库
 * @param path
 * @returns {boolean}
 */
function isPnpmRepo(path) {
  return fs.existsSync(path + '/pnpm-lock.yaml')
}

/**
 * 获取仓库类型
 * @param path
 * @returns {string}
 */
function getPackageManager(path) {
  let packageManager = 'npm'
  if (isYarnRepo(path)) packageManager = 'yarn'
  if (isPnpmRepo(path)) packageManager = 'pnpm'
  return packageManager
}

/**
 * 执行git命令
 * @param args
 * @returns {string}
 */
function git(...args) {
  return shell.exec(`git ${args.join(' ')}`, { silent: true }).stdout
}
