const { readFileSync, writeFileSync } = require('fs')
const path = require('path')
const prettier = require('prettier')
const { isExist, createFile, replaceInFile, cleanDir } = require('./utils')

const JSON_FORMAT = 'json'
const TSJSON_FORMAT = 'tsjson'

function createModelFile(fileDir, fileName, format, model) {
  const fileContent = JSON.stringify(model, null, 2)

  let fileContentWithFormat
  if (format === JSON_FORMAT) {
    fileContentWithFormat = fileContent
  } else {
    fileContentWithFormat = `export default ${fileContent}`
  }

  const formattedFileContent = prettier.format(fileContentWithFormat, {
    parser: format === TSJSON_FORMAT ? 'typescript' : 'json'
  })

  createFile(path.join(fileDir, `${fileName}.${format === TSJSON_FORMAT ? 'ts' : 'json'}`), formattedFileContent)
}

