import requests


def get_internet_website(url):
    if url.startswith('https://') or url.startswith('http://'):
        response = requests.get(url)
        if response:
            html = response.text
            soup = BeautifulSoup(html, features="html.parser")
            return soup
        else:
            return None
    else:
        return None


