﻿const $ = require('jquery');
const axios = require('axios');
const { getUserName, isLogin, getUserInfo, getToken } = require('./util')
const { baseUrl } = require('./config');


// 请求头
const headers = {
  'Content-Type': 'application/json',
  'Authorization': getToken()
}

// 更换头像
function changeAvatar(file) {
  let formData = new FormData();
  formData.append('file', file)
  return axios.post(`${baseUrl}/User/changeAvatar`, formData, {
    headers: headers,
    withCredentials: true
  })
}

// 更换用户名
function changeUserName(username) {
  return axios.post(`${baseUrl}/User/changeUserName`, {
    username: username
  }, {
    headers: headers,
    withCredentials: true
  })
}

// 更换密码
function changePassword(oldPassword, newPassword) {
  return axios.post(`${baseUrl}/User/changePassword`, {
    oldPassword: oldPassword,
    newPassword: newPassword
  }, {
    headers: headers,
    withCredentials: true
  })
}

// 获取用户信息
function getUserInfo() {
  return axios.get(`${baseUrl}/User/getInfo`, {
    headers: headers,
    withCredentials: true
  })
}

// 获取用户列表
function getUserList(params) {
  return axios.get(`${baseUrl}/User/list`, {
    params: params,
    headers: headers,
    withCredentials: true
  })
}

// 禁用用户
function disableUser(userIdList) {
  return axios.post(`${baseUrl}/User/disable`, {
    userIdList: userIdList
  }, {
    headers: headers,
    withCredentials: true
  })
}

// 启用用户
function enableUser(userIdList) {
  return axios.post(`${baseUrl}/User/enable`, {
    userIdList: userIdList
  }, {
    headers: headers,
    withCredentials: true
  })
}

// 删除用户
function deleteUser(userIdList) {
  return axios.delete(`${baseUrl}/User/delete`, {
    data: {
      userIdList: userIdList
    },
    headers: headers,
    withCredentials: true
  })
}

// 获取用户评论
function getUserComment(params) {
  return axios.get(`${baseUrl}/User/comment`, {
    params: params,
    headers: headers,
    withCredentials: true
  })
}

