package com.qwen.java.utils;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class DateUtils {
    public static String formatDate(Date date, String pattern) {
        if (null == date) {
            return null;
        }
        if (null == pattern || "".equals(pattern.trim())) {
            pattern = "yyyy-MM-dd HH:mm:ss";
        }
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(pattern);
        return simpleDateFormat.format(date);
    }

    public static Date parseDate(String strDate, String pattern) {
        if (null == strDate || "".equals(strDate.trim())) {
            return null;
        }
        if (null == pattern || "".equals(pattern.trim())) {
            pattern = "yyyy-MM-dd HH:mm:ss";
        }
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(pattern);
        try {
            return simpleDateFormat.parse(strDate);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        return null;
    }

    public static String getNowDate(String pattern) {
        if (null == pattern || "".equals(pattern.trim())) {
            pattern = "yyyy-MM-dd HH:mm:ss";
        }
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(pattern);
        return simpleDateFormat.format(new Date());
    }

    public static String getNowDate() {
        return getNowDate("yyyy-MM-dd HH:mm:ss");
    }

    public static long getMillis(Date date) {
        if (null == date) {
            return 0;
        }
        return date.getTime();
    }

    public static long getMillis(String strDate, String pattern) {
        return getMillis(parseDate(strDate, pattern));
    }

    public static long getMillis(String strDate) {
        return getMillis(strDate, null);
    }

    public static long getMillisSinceEpoch() {
        return getMillis(new Date());
    }

    public static Date getNow() {
        return new Date();
    }

    public static Date addDays(Date date, int days) {
        if (null == date) {
            return null;
        }
        Date newDate = null;
        try {
            SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            // 毫秒数
            long time = simpleDateFormat.parse(simpleDateFormat.format(date)).getTime();
            time += days * 86400000;
            newDate = new Date(time);
        } catch (Exception e) {
            e.printStackTrace();
        }
        return newDate;
    }

    public static Date addDays(int days) {
        return addDays(getNow(), days);
    }

    public static Date addMonths(Date date, int months) {
        if (null == date) {
            return null;
        }
        Date newDate = null;
        try {
            SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            // 毫秒数
            long time = simpleDateFormat.parse(simpleDateFormat.format(date)).getTime();
            time += months * 2592000000L;
            newDate = new Date(time);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
        return newDate;
    }

    public static Date addMonths(int months) {
        return addMonths(getNow(), months);
    }

    public static String getToday() {
        return formatDate(getNow(), "yyyy-MM-dd");
    }

    public static String getYesterday() {
        return formatDate(addDays(-1), "yyyy-MM-dd");
    }

    public static String getTodayStart() {
        return formatDate(addDays(0), "yyyy-MM-dd") + " 00:00:00";
    }

    public static String getTodayEnd() {
        return formatDate(addDays(0), "yyyy-MM-dd") + " 23:59:59";
    }

    public static String getYesterdayStart() {
        return formatDate(addDays(-1), "yyyy-MM-dd") + " 00:00:00";
    }

    public static String getYesterdayEnd() {
        return formatDate(addDays(-1), "yyyy-MM-dd") + " 23:59:59";
    }

    public static String getTomorrowStart() {
        return formatDate(addDays(1), "yyyy-MM-dd") + " 00:00:00";
    }

    public static String getTomorrowEnd() {
        return formatDate(addDays(1), "yyyy-MM-dd") + " 23:59:59";
    }

    public static String getThisYearStart() {
        return formatDate(addMonths(0), "yyyy-01-01") + " 00:00:00";
    }

    public static String getThisYearEnd() {
        return getThisYearStart().substring(0, 4) + "-12-31 23:59:59";
    }

    public static String getThisWeekStart() {
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd");
        Calendar cal = Calendar.getInstance();
        cal.setTime(new Date());
        cal.setFirstDayOfWeek(Calendar.MONDAY);
        cal.set(Calendar.DAY_OF_WEEK, Calendar.MONDAY);

        String weekStart = simpleDateFormat.format(cal.getTime());
        return weekStart + " 00:00:00";
