const axios = require('axios');

// Importing the RedisClient class
const RedisClient = require('./RedisClient.js');

// Creating a new instance of RedisClient
const redisClient = new RedisClient();

// Accessing the redisClient instance's client property
const redis = redisClient.client;

// Creating a key and setting it to a value
const key1 = 'name';
const value1 = 'John';
redis.set(key1, value1);

// Creating another key and setting it to a value
const key2 = 'age';
const value2 = '30';
redis.set(key2, value2);

// Creating a third key and setting it to a value
const key3 = 'city';
const value3 = 'New York';
redis.set(key3, value3);

// Getting the value of a key
const keyToGet = 'name';
redis.get(keyToGet, (err, value) => {
  if (err) {
    console.error(err);
  } else {
    console.log(value);
  }
});

// Getting the values of multiple keys
const keysToGet = ['name', 'age', 'city'];
redis.mget(keysToGet, (err, values) => {
  if (err) {
    console.error(err);
  } else {
    console.log(values);
  }
});

// Setting multiple key-value pairs using mset
