redis.del(keyToDelete);

// Checking if the key was deleted
redis.exists(keyToDelete, (err, result) => {
  if (err) {
    console.error(err);
  } else {
    console.log(result);
  }
});

// Using incr to increment a numeric value
const numericKey = 'counter';
redis.incr(numericKey);

// Using incrby to increment a numeric value by a specified amount
