package gpt

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"os"
	"strings"
)

type CompletionRequest struct {
	Model              string  `json:"model"`
	Prompt             string  `json:"prompt"`
	MaxTokens          int     `json:"max_tokens"`
	Temperature        float64 `json:"temperature"`
	TopP               int     `json:"top_p"`
	FrequencyPenalty   float64 `json:"frequency_penalty"`
	PresencePenalty    float64 `json:"presence_penalty"`
	N                  int     `json:"n"`
	Stop               string  `json:"stop"`
	ReturnLogProbs     int     `json:"return_logprobs"`
	LogitBias          string  `json:"logit_bias"`
	User               string  `json:"user"`
}

type CompletionResponse struct {
	ID      string `json:"id"`
	Object  string `json:"object"`
	Created int    `json:"created"`
	Model   string `json:"model"`
	Choices []struct {
		Text         string `json:"text"`
		Index        int    `json:"index"`
		LogProbs     int    `json:"logprobs"`
		FinishReason string `json:"finish_reason"`
	} `json:"choices"`
	Usage struct {
		PromptTokens     int `json:"prompt_tokens"`
		CompletionTokens int `json:"completion_tokens"`
		TotalTokens      int `json:"total_tokens"`
	} `json:"usage"`
}

func CallGPT(req CompletionRequest) (CompletionResponse, error) {
	// 获取 GPT API 密钥
	apiKey := os.Getenv("OPENAI_API_KEY")

	if apiKey == "" {
		return CompletionResponse{}, fmt.Errorf("missing API key")
	}

	// 构建请求 URL
	baseURL := "https://api.openai.com/v1/engines/davinci/completions"

	// 构建请求头
	reqHeaders := http.Header{
		"Content-Type": {"application/json"},
		"Authorization": {"Bearer " + apiKey},
	}

	// 将请求体转换为 JSON
	reqBody, err := json.Marshal(req)
	if err != nil {
		return CompletionResponse{}, err
	}

	// 发送 POST 请求
	resp, err := http.Post(baseURL, "application/json", strings.NewReader(string(reqBody)))
	if err != nil {
		return CompletionResponse{}, err
	}
	defer resp.Body.Close()

	// 解析响应
	var res CompletionResponse
	err = json.NewDecoder(resp.Body).Decode(&res)
	if err != nil {
		return CompletionResponse{}, err
	}

	return res, nil
}

func HandleGPT(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Headers", "*")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE")
	w.Header().Set("Access-Control-Allow-Credentials", "true")

	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusOK)
		return
	}

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	// 解析请求参数
	params := r.URL.Query()
	prompt := params.Get("prompt")
	if prompt == "" {
		http.Error(w, "Missing prompt parameter", http.StatusBadRequest)
		return
	}

	// 构建请求体
	req := CompletionRequest{
		Model:            "text-davinci-003",
		Prompt:           prompt,
		MaxTokens:        100,
		Temperature:      0.7,
		TopP:             1,
		FrequencyPenalty: 0,
		PresencePenalty:  0,
		N:                1,
		Stop:             "",
		ReturnLogProbs:   0,
		LogitBias:        "",
		User:             "",
	}

	// 调用 GPT API
	res, err := CallGPT(req)
	if err != nil {
		http.Error(w, "Failed to call GPT API", http.StatusInternalServerError)
		return
	}

	// 构造响应
	response := map[string]interface{}{
		"prompt":     prompt,
		"completion": res.Choices[0].Text,
	}

	// 返回 JSON 响应
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

