import React from 'react';
import { shallow } from 'enzyme';
import { expect } from 'chai';
import { Provider } from 'react-redux';
import configureStore from 'redux-mock-store';
import { fetchQuestion } from '../actions/index';
import Question from '../components/Question';

const middlewares = [];
const mockStore = configureStore(middlewares);

describe('Question', () => {
  let question = null;
  const initialState = {
    question: {
      title: 'Why is the sky blue?',
      description: 'I do not know why.',
      answer: 'Because of the laws of physics.'
    },
    answer: {
      answer: 'Because of the laws of physics.'
    }
  };

  const store = mockStore(initialState);

  beforeEach(() => {
    question = shallow(<Provider store={store}><Question /></Provider>);
  });

  it('renders the title, description, and answer correctly', () => {
    expect(question.find('h3').text()).to.equal('Why is the sky blue?');
    expect(question.find('p').text()).to.equal('I do not know why.');
    expect(question.find('div').last().text()).to.equal('Because of the laws of physics.');
  });

  it('fetches a new question when asked', () => {
    const fetchSpy = sinon.spy(fetchQuestion);
    question.find('.new-question').simulate('click');
    expect(fetchSpy.calledOnce).to.be.true;
  });
});
