import { FETCH_QUESTION, FETCH_ANSWER } from './types';
import axios from 'axios';

export const fetchQuestion = () => dispatch => {
  return axios.get('http://qwen.alibaba.com/api/v1/question').then(response => {
    dispatch({
      type: FETCH_QUESTION,
      payload: response.data
    });
  });
};

export const fetchAnswer = questionId => dispatch => {
  return axios.get(`http://qwen.alibaba.com/api/v1/question/${questionId}/answer`).then(response => {
    dispatch({
      type: FETCH_ANSWER,
      payload: response.data
    });
  });
};
