package com.alibaba.openapi.client.req;

import cn.hutool.core.thread.ThreadUtil;
import com.alibaba.openapi.client.ApiClient;
import com.alibaba.openapi.client.ApiException;
import com.alibaba.openapi.client.ApiResponse;
import com.alibaba.openapi.client.model.PureGPTReq;
import com.alibaba.openapi.client.model.PureGPTResp;
import com.alibaba.openapi.client.util.SignatureUtils;
import org.junit.jupiter.api.Test;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * @author zhenghong@alibaba-inc.com
 */
public class ReqTest {
    private static final Logger logger = LoggerFactory.getLogger(ReqTest.class);

    private static final String APP_KEY = "";
    private static final String API_SECRET = "";
    private static final String API_URL = "http://localhost:8080/api/core/v1/chat/completions";
    private static final String API_VERSION = "2022-03-01";

    private static final int DEFAULT_TIMEOUT_MILLIS = 20000;

    @Test
    public void testReq() throws ApiException {
        try {
            ApiClient apiClient = new ApiClient(APP_KEY, API_SECRET, API_URL, API_VERSION, SignatureUtils.TYPE_HMACSHA256);
            apiClient.setReadTimeoutMs(DEFAULT_TIMEOUT_MILLIS);

            PureGPTReq req = new PureGPTReq();
            req.setModel("gpt-3.5-turbo");
            req.setMessages(new HashMap<String, Object>() {{
                put("role", "user");
                put("content", "你好！");
            }});
            req.setStream(false);

            ApiResponse resp = apiClient.call(req, PureGPTResp.class);
            logger.info("resp: {}", resp.toString());
            System.out.println(resp);
            ThreadUtil.sleep(ThreadUtil.ONE_SECOND_MILLIS);
            System.out.println(new String(resp.getContent(), StandardCharsets.UTF_8));
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testReqWithParam() throws ApiException {
        try {
            ApiClient apiClient = new ApiClient(APP_KEY, API_SECRET, API_URL, API_VERSION, SignatureUtils.TYPE_HMACSHA256);
            apiClient.setReadTimeoutMs(DEFAULT_TIMEOUT_MILLIS);

            PureGPTReq req = new PureGPTReq();
            req.setModel("gpt-3.5-turbo");
            req.setMessages(new HashMap<String, Object>() {{
                put("role", "user");
                put("content", "你好！");
            }});
            req.setStream(false);
            req.setTemperature(0.1);
            req.setTop_p(0.1);
            req.setMax_tokens(100);

            ApiResponse resp = apiClient.call(req, PureGPTResp.class);
            logger.info("resp: {}", resp.toString());
            System.out.println(resp);
            ThreadUtil.sleep(ThreadUtil.ONE_SECOND_MILLIS);
            System.out.println(new String(resp.getContent(), StandardCharsets.UTF_8));
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testReqWithStream() throws ApiException {
        try {
            ApiClient apiClient = new ApiClient(APP_KEY, API_SECRET, API_URL, API_VERSION, SignatureUtils.TYPE_HMACSHA256);
            apiClient.setReadTimeoutMs(DEFAULT_TIMEOUT_MILLIS);

            PureGPTReq req = new PureGPTReq();
            req.setModel("gpt-3.5-turbo");
            req.setMessages(new HashMap<String, Object>() {{
                put("role", "user");
                put("content", "你好！");
            }});
            req.setStream(true);

            ApiResponse resp = apiClient.call(req, PureGPTResp.class);
            logger.info("resp: {}", resp.toString());
