            System.out.println(new String(resp.getContent(), StandardCharsets.UTF_8));
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testReqWithCustomHeaders() throws ApiException {
        try {
            ApiClient apiClient = new ApiClient(APP_KEY, API_SECRET, API_URL, API_VERSION, SignatureUtils.TYPE_HMACSHA256);
            apiClient.setReadTimeoutMs(DEFAULT_TIMEOUT_MILLIS);

            PureGPTReq req = new PureGPTReq();
            req.setModel("gpt-3.5-turbo");
            req.setMessages(new HashMap<String, Object>() {{
                put("role", "user");
                put("content", "你好！");
            }});
