            Map<String, String> headMap = new HashMap<>();
            headMap.put("Custom-Header-Key", "Custom-Header-Value");
            ApiResponse resp = apiClient.call(req, PureGPTResp.class, headMap);
            logger.info("resp: {}", resp.toString());
            System.out.println(resp);
            ThreadUtil.sleep(ThreadUtil.ONE_SECOND_MILLIS);
            System.out.println(new String(resp.getContent(), StandardCharsets.UTF_8));
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
