def bisection(a, b):
    if f(a) * f(b) >= 0:
        print("No root found in the given interval")
        return None

    c = a
    while (b - a) >= 0.01:
        c = (a + b) / 2
        if f(c) == 0.0:
            break
        if f(c) * f(a) < 0:
            b = c
        else:
            a = c

    return c

