import React, { useEffect, useState } from 'react';
import { useHistory } from 'react-router-dom';
import axios from 'axios';
import useLocalStorage from '../useLocalStorage';
import '../styles/Gpt.css';

const Gpt = () => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [token, setToken] = useLocalStorage('token', '');
  const [userLang, setUserLang] = useLocalStorage('userLang', 'en');
  const history = useHistory();

  useEffect(() => {
    const userToken = localStorage.getItem('token');
    if (!userToken) {
      history.push('/login');
    } else {
      setToken(userToken);
    }
  }, [history]);

  const setLanguage = (selectedLang) => {
    localStorage.setItem('userLang', selectedLang);
    setUserLang(selectedLang);
  };

  const sendChat = async () => {
    if (loading) return;
    setLoading(true);
    try {
      const response = await axios.post(
        'https://api.openai.com/v1/chat/completions',
        {
          model: 'gpt-3.5-turbo',
          messages: [
            { role: 'system', content: `You are a language teacher for ${userLang}.` },
            ...messages,
            { role: 'user', content: message },
          ],
          max_tokens: 64,
        },
        {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${process.env.REACT_APP_OPENAI_API_KEY}`,
          },
        }
      );

      setMessages([
        ...messages,
        { role: 'user', content: message },
        { role: 'assistant', content: response.data.choices[0].message.content },
      ]);
      setMessage('');
      setLoading(false);
    } catch (error) {
      console.error(error);
      setLoading(false);
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        <h3>Speech to Text</h3>
        <button onClick={() => history.push('/chat')} className="switch-button">
          Chat to Speech
        </button>
      </div>
      <div className="chat-messages">
        {messages.map((msg, index) => (
          <div key={index} className={`message ${msg.role}`}>
            <span className="message-content">{msg.content}</span>
          </div>
        ))}
      </div>
      <div className="chat-input">
        <div className="input-container">
          <textarea
            rows="1"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendChat();
              }
            }}
          />
          <div className="send-button" onClick={sendChat}>
            {loading ? 'Loading...' : 'Send'}
          </div>
        </div>
      <|fim_suffix|>       <button className="lang-button" onClick={() => setLanguage('en')}>
            English
          </button>
          <button className="lang-button" onClick={() => setLanguage('ko')}>
            Korean
          </button>
        </div>
      </div>
    </div>
  );
};

export default Gpt;
