import com.qwen.ai.model.QwenRequest;
import com.qwen.ai.model.User;
import com.qwen.ai.utils.ObjectMapperUtil;
import okhttp3.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
