import java.util.Map;
import java.util.concurrent.TimeUnit;

@Service
public class ChatService {
    Logger logger = LoggerFactory.getLogger(ChatService.class);

    @Autowired
    private QwenConfig qwenConfig;

    @Autowired
    private AppConfig appConfig;

    public QwenResponse query(String prompt, User user) {
        if(StrUtil.isBlank(prompt)) {
            throw new IllegalArgumentException("Prompt is empty.");
        }
        if(user == null) {
            throw new IllegalArgumentException("User is empty.");
        }
        String userId = user.getId();
        if(userId == null) {
            throw new IllegalArgumentException("User ID is empty.");
        }
        String userApiKey = user.getApiKey();
        if(StrUtil.isBlank(userApiKey)) {
            throw new IllegalArgumentException("User API key is empty.");
        }

        Map<String, Object> requestMap = new HashMap<>();
        requestMap.put("prompt", prompt);
        requestMap.put("userId", userId);
        requestMap.put("userApiKey", userApiKey);
        requestMap.put("model", qwenConfig.getModel());
        requestMap.put("temperature", qwenConfig.getTemperature());
        requestMap.put("maxTokens", qwenConfig.getMaxTokens());
        requestMap.put("topP", qwenConfig.getTopP());
        requestMap.put("topK", qwenConfig.getTopK());
        requestMap.put("tfs", qwenConfig.getTfs());
        requestMap.put("typicalP", qwenConfig.getTypicalP());
        requestMap.put("repetitionPenalty", qwenConfig.getRepetitionPenalty());
        requestMap.put("presencePenalty", qwenConfig.getPresencePenalty());
        requestMap.put("frequencyPenalty", qwenConfig.getFrequencyPenalty());
        requestMap.put("stop", qwenConfig.getStop());
        requestMap.put("stream", false);
        requestMap.put("logitBias", qwenConfig.getLogitBias());
        requestMap.put("n", qwenConfig.getN());
        JSONObject data = new JSONObject(requestMap);

        MediaType json = MediaType.parse("application/json; charset=utf-8");
        OkHttpClient client = new OkHttpClient.Builder()
                .connectTimeout(5, TimeUnit.MINUTES)
                .readTimeout(5, TimeUnit.MINUTES)
                .build();
        Request request = new Request.Builder()
                .url(appConfig.getQwenUrl())
                .post(RequestBody.create(data.toJSONString(),json))
                .header("Authorization", "Bearer " + userApiKey)
                .build();
        logger.info("Request: {}", request);
        try (Response response = client.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new RuntimeException("Unexpected response: " + response);
            }
            String responseBody = response.body().string();
            if(StrUtil.isBlank(responseBody)) {
                throw new RuntimeException("Response body is empty.");
            }
            logger.info("Response: {}", responseBody);
            QwenResponse qwenResponse = ObjectMapperUtil.convertToObject(responseBody, QwenResponse.class);
            return qwenResponse;
        } catch (Exception e) {
            logger.error("An exception occurred while making a Qwen request: {}", e.getMessage());
            throw new RuntimeException("An exception occurred while making a Qwen request.", e);
        }
    }

    public List<ChatMessage> chat(String prompt, User user) {
        return chat(prompt, null, user);
    }

    public List<ChatMessage> chat(String prompt, List<ChatMessage> history, User user) {
        if(StrUtil.isBlank(prompt)) {
            throw new IllegalArgumentException("Prompt is empty.");
        }
        if(user == null) {
            throw new IllegalArgumentException("User is empty.");
        }
        String userId = user.getId();
        if(userId == null) {
            throw new IllegalArgumentException("User ID is empty.");
        }
        String userApiKey = user.getApiKey();
        if(StrUtil.isBlank(userApiKey)) {
            throw new IllegalArgumentException("User API key is empty.");
        }
        String model = qwenConfig.getModel();
        if(StrUtil.isBlank(model)) {
            model = QwenConfig.QWEN_7B_MODEL;
        }
        float temperature = qwenConfig.getTemperature();
        int maxTokens = qwenConfig.getMaxTokens();
        float topP = qwenConfig.getTopP();
        int topK = qwenConfig.getTopK();
        float tfs = qwenConfig.getTfs();
        float typicalP = qwenConfig.getTypicalP();
        float repetitionPenalty = qwenConfig.getRepetitionPenalty();
        float presencePenalty = qwenConfig.getPresencePenalty();
        float frequencyPenalty = qwenConfig.getFrequencyPenalty();
        String stop = qwenConfig.getStop();
        boolean stream = qwenConfig.isStream();
        Map<String, Object> logitBias = qwenConfig.getLogitBias();
        int n = qwenConfig.getN();

        List<ChatMessage> chatMessages = new ArrayList<>();
        if(history != null) {
            for (ChatMessage message : history) {
                String role = message.getRole();
                if (role.equals("system")) {
                    chatMessages.add(message);
                }
            }
        }
        chatMessages.add(new ChatMessage("user", prompt));

        if(!stream) {
            String userId = user.getId();
            if(userId == null) {
                throw new IllegalArgumentException("User ID is empty.");
            }
